  last_login_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_adminuser_sessions discussion_board_adminuser_sessions[]
  discussion_board_article_of_adminusers discussion_board_article_of_adminusers[]
  discussion_board_comment_of_adminusers discussion_board_comment_of_adminusers[]
  discussion_board_report_of_adminusers discussion_board_report_of_adminusers[]
  discussion_board_adminuser_notification_preferences discussion_board_adminuser_notification_preferences?

  @@unique([email])
  @@index([account_status, created_at])
