  adminUser discussion_board_adminusers @relation(fields: [discussion_board_adminuser_id], references: [id], onDelete: Cascade, map: "discussion_board_article_of_adminusers_discussion_boar_1d2b3c16")

  // spellchecker: ignore-next-line
  @@unique([discussion_board_article_id], map: "discussion_board_article_of_adminusers_discussion_boar_497946cd")
