  discussion_board_article_id String @db.Uuid

  /// Foreign key referencing the member user who liked the article. {@link
  /// discussion_board_memberusers.id}. Many likes can be created by the same
  /// member user.
  discussion_board_memberuser_id String @db.Uuid

  /// Timestamp when the like was created. Used for audit trails and ordering
  /// of engagement activity.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  article discussion_board_articles @relation(fields: [discussion_board_article_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  memberUser discussion_board_memberusers @relation(fields: [discussion_board_memberuser_id], references: [id], onDelete: Cascade, map: "discussion_board_article_likes_discussion_board_member_1e16ba80")

  // spellchecker: ignore-next-line
  @@unique([discussion_board_article_id, discussion_board_memberuser_id], map: "discussion_board_article_likes_discussion_board_articl_a0853f38")
  // spellchecker: ignore-next-line
  @@index([discussion_board_memberuser_id, created_at], map: "discussion_board_article_likes_discussion_board_member_21f81b89")
  // spellchecker: ignore-next-line
  @@index([discussion_board_article_id, created_at], map: "discussion_board_article_likes_discussion_board_articl_39b0a14e")
}

