import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

export async function test_api_guest_user_join_creates_new_placeholder_account(
  connection: api.IConnection,
) {
  // 1. Prepare a realistic anonymous token and optional context fields
  const anonymousToken: string = RandomGenerator.alphaNumeric(32);

  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const ip: string = RandomGenerator.alphaNumeric(3);

  const joinBody = {
    anonymous_token: anonymousToken,
    ip,
    href,
    referrer,
  } satisfies IDiscussionBoardGuestUser.IJoin;

  // 2. Call the guestUser join endpoint
  const authorizedGuest = await api.functional.auth.guestUser.join(connection, {
    body: joinBody,
  });

  // 3. Type-level validation of the response
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(authorizedGuest);

  // 4. Business and invariants validation
  // 4-1. Anonymous token must be echoed back exactly
  TestValidator.equals(
    "anonymous_token is echoed back",
    authorizedGuest.anonymous_token,
    anonymousToken,
  );

  // 4-2. deleted_at must be null or undefined for a fresh guest
  TestValidator.predicate(
    "deleted_at is null or undefined for new guest",
    () =>
      authorizedGuest.deleted_at === null ||
      authorizedGuest.deleted_at === undefined,
  );

  // 4-3. Token basics: access/refresh must be non-empty strings
  const token: IAuthorizationToken = authorizedGuest.token;

  TestValidator.predicate("access token is non-empty", token.access.length > 0);

  TestValidator.predicate(
    "refresh token is non-empty",
    token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

/**
 * Validate that guestUser join reuses an existing active guest record when
 * called multiple times with the same anonymous_token, while rotating JWT
 * tokens.
 *
 * Business rules under test:
 *
 * - Discussion_board_guestusers has a unique index on anonymous_token.
 * - POST /auth/guestUser/join either creates a new guest record or reuses an
 *   existing one when the same anonymous_token is presented and the record is
 *   still active (deleted_at is null).
 * - When reusing, the backend must:
 *
 *   - Preserve id and created_at.
 *   - Keep anonymous_token unchanged.
 *   - Maintain deleted_at as null/undefined (still active).
 *   - Update updated_at to reflect the latest join.
 *   - Issue a fresh pair of JWT tokens (access/refresh) for the guestUser actor
 *       role.
 *
 * Test flow:
 *
 * 1. Generate a stable anonymous_token T1.
 * 2. Call join with T1 and some session context (href/referrer/ip), capture the
 *    returned IDiscussionBoardGuestUser.IAuthorized as first.
 * 3. Call join again with the same T1 but different context values, capture the
 *    second IDiscussionBoardGuestUser.IAuthorized as second.
 * 4. Assert that:
 *
 *    - Second.id === first.id (same guest record reused).
 *    - Second.anonymous_token === first.anonymous_token === T1.
 *    - Second.created_at === first.created_at.
 *    - Deleted_at in both responses is null or undefined (still active).
 *    - Second.updated_at is greater than or equal to first.updated_at (monotonic
 *         last-updated timestamp).
 *    - Second.token.access !== first.token.access and second.token.refresh !==
 *         first.token.refresh (credentials rotated).
 */
export async function test_api_guest_user_join_reuses_existing_active_guest_record(
  connection: api.IConnection,
) {
  // Step 1: Generate a stable anonymous_token for this test scenario.
  const anonymousToken: string = RandomGenerator.alphaNumeric(32);

  // Prepare first join payload using IDiscussionBoardGuestUser.IJoin.
  const firstJoinBody = {
    anonymous_token: anonymousToken,
    href: "https://example.com/board/thread/1",
    referrer: "https://example.com/board",
    ip: "192.168.0.10",
  } satisfies IDiscussionBoardGuestUser.IJoin;

  // Step 2: First join call to materialize guest record.
  const first: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: firstJoinBody,
    });
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(first);

  // Capture first state snapshot.
  const firstId = first.id;
  const firstAnonymousToken = first.anonymous_token;
  const firstCreatedAt = first.created_at;
  const firstUpdatedAt = first.updated_at;
  const firstDeletedAt = first.deleted_at ?? null;
  const firstAccessToken = first.token.access;
  const firstRefreshToken = first.token.refresh;

  // Basic invariants on first response.
  TestValidator.equals(
    "first join anonymous_token echoes request",
    firstAnonymousToken,
    anonymousToken,
  );
  TestValidator.equals(
    "first join deleted_at is null or undefined",
    firstDeletedAt,
    null,
  );

  // Step 3: Second join with same anonymous_token but different context.
  const secondJoinBody = {
    anonymous_token: anonymousToken,
    href: "https://example.com/board/thread/2",
    referrer: "https://example.com/landing",
    ip: "10.0.0.5",
  } satisfies IDiscussionBoardGuestUser.IJoin;

  const second: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: secondJoinBody,
    });
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(second);

  const secondId = second.id;
  const secondAnonymousToken = second.anonymous_token;
  const secondCreatedAt = second.created_at;
  const secondUpdatedAt = second.updated_at;
  const secondDeletedAt = second.deleted_at ?? null;
  const secondAccessToken = second.token.access;
  const secondRefreshToken = second.token.refresh;

  // Step 4: Identity reuse assertions.
  TestValidator.equals("id must be reused on second join", secondId, firstId);
  TestValidator.equals(
    "anonymous_token must remain identical across joins",
    secondAnonymousToken,
    firstAnonymousToken,
  );
  TestValidator.equals(
    "anonymous_token must match original request token",
    secondAnonymousToken,
    anonymousToken,
  );
  TestValidator.equals(
    "created_at must remain unchanged when reusing guest record",
    secondCreatedAt,
    firstCreatedAt,
  );
  TestValidator.equals(
    "deleted_at remains null after repeated joins",
    secondDeletedAt,
    null,
  );

  // Step 5: updated_at monotonicity check.
  const firstUpdatedMillis = Date.parse(firstUpdatedAt);
  const secondUpdatedMillis = Date.parse(secondUpdatedAt);
  TestValidator.predicate(
    "second updated_at is greater than or equal to first updated_at",
    secondUpdatedMillis >= firstUpdatedMillis,
  );

  // Step 6: Token rotation checks.
  TestValidator.notEquals(
    "access token must be rotated on second join",
    secondAccessToken,
    firstAccessToken,
  );
  TestValidator.notEquals(
    "refresh token must be rotated on second join",
    secondRefreshToken,
    firstRefreshToken,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

/**
 * Validate guest join behavior when the same anonymous token is reused,
 * standing in for a logically deleted guest record scenario.
 *
 * Business context:
 *
 * - The backend manages discussion_board_guestusers with an anonymous_token
 *   unique index and a nullable deleted_at for logical deletion.
 * - From the public API surface we cannot force deleted_at to non-null or inspect
 *   database state, but we can validate how repeated joins with the same
 *   anonymous_token behave and ensure that the DTO contract is respected (no
 *   leaked internal fields).
 *
 * Scenario implemented (compilation/black-box friendly):
 *
 * 1. Generate a random but stable anonymous_token representing a browser
 *    fingerprint.
 * 2. Call POST /auth/guestUser/join with that token and a realistic href and
 *    referrer, receiving IDiscussionBoardGuestUser.IAuthorized.
 * 3. Assert that:
 *
 *    - Response shape matches IAuthorized (typia.assert)
 *    - Anonymous_token echoes the input token
 *    - Id is a UUID
 *    - Created_at and updated_at are valid date-time strings
 *    - Deleted_at is null or undefined for a fresh active guest
 *    - Token is a well-formed IAuthorizationToken
 * 4. Call join again with the same anonymous_token and similar context.
 * 5. Assert that:
 *
 *    - The second call also succeeds (no rejection on reuse)
 *    - Id is identical to the first call’s id (indicating reuse of the same guest
 *         record rather than a new one)
 *    - Anonymous_token matches the input
 *    - Created_at remains the same between calls
 *    - Updated_at in the second response is equal to or later than the first
 *         updated_at
 *    - Deleted_at remains null or undefined (still active)
 *    - Token structure is still valid; we do not require any specific difference
 *         between first and second token values, as that’s an implementation
 *         detail.
 */
export async function test_api_guest_user_join_handles_logically_deleted_guest_record(
  connection: api.IConnection,
) {
  // 1. Prepare a stable anonymous token and context URLs
  const anonymousToken: string = RandomGenerator.alphaNumeric(32);

  const href: string & tags.Format<"uri"> =
    "https://example.com/board/thread/123" as string & tags.Format<"uri">;
  const referrer: string & tags.Format<"uri"> =
    "https://example.com/board" as string & tags.Format<"uri">;

  // 2. First join call: simulate initial guest materialization
  const firstJoin: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: {
        anonymous_token: anonymousToken,
        href,
        referrer,
        ip: null,
      } satisfies IDiscussionBoardGuestUser.IJoin,
    });
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(firstJoin);

  // Basic DTO-level invariants for the first join
  TestValidator.equals(
    "first join anonymous_token round-trips",
    firstJoin.anonymous_token,
    anonymousToken,
  );

  // deleted_at should be null or undefined for an active guest
  TestValidator.predicate(
    "first join deleted_at is null or undefined",
    () => firstJoin.deleted_at === null || firstJoin.deleted_at === undefined,
  );

  // Token bundle presence is already type-guaranteed, but we ensure it’s
  // non-empty in a business sense (strings not empty)
  const firstToken: IAuthorizationToken = firstJoin.token;
  typia.assert<IAuthorizationToken>(firstToken);

  TestValidator.predicate(
    "first join access token is non-empty string",
    firstToken.access.length > 0,
  );
  TestValidator.predicate(
    "first join refresh token is non-empty string",
    firstToken.refresh.length > 0,
  );

  // 3. Second join call with the same anonymous token
  const secondJoin: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: {
        anonymous_token: anonymousToken,
        href,
        referrer,
        ip: null,
      } satisfies IDiscussionBoardGuestUser.IJoin,
    });
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(secondJoin);

  // 4. Cross-call consistency checks
  TestValidator.equals(
    "second join anonymous_token round-trips",
    secondJoin.anonymous_token,
    anonymousToken,
  );

  // We expect the same guest record to be reused, so ids should match
  TestValidator.equals(
    "guest id is stable across repeated joins",
    secondJoin.id,
    firstJoin.id,
  );

  // created_at should remain constant for the same record
  TestValidator.equals(
    "created_at remains unchanged across joins",
    secondJoin.created_at,
    firstJoin.created_at,
  );

  // updated_at should be the same or move forward in time
  TestValidator.predicate(
    "updated_at in second join is not earlier than first join",
    () =>
      new Date(secondJoin.updated_at).getTime() >=
      new Date(firstJoin.updated_at).getTime(),
  );

  // deleted_at should still be null or undefined (no logical deletion in between)
  TestValidator.predicate(
    "second join deleted_at is null or undefined",
    () => secondJoin.deleted_at === null || secondJoin.deleted_at === undefined,
  );

  const secondToken: IAuthorizationToken = secondJoin.token;
  typia.assert<IAuthorizationToken>(secondToken);

  TestValidator.predicate(
    "second join access token is non-empty string",
    secondToken.access.length > 0,
  );
  TestValidator.predicate(
    "second join refresh token is non-empty string",
    secondToken.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

/**
 * Validate that an active guestUser can refresh JWT tokens while preserving
 * identity.
 *
 * Business purpose:
 *
 * - Ensure that a guest, once materialized in discussion_board_guestusers via
 *   /auth/guestUser/join, can use the issued refresh token to obtain a new
 *   IDiscussionBoardGuestUser.IAuthorized via /auth/guestUser/refresh.
 * - Confirm that refresh does not change the underlying guest identity (id,
 *   anonymous_token) and that updated_at reflects recent activity.
 *
 * Test steps:
 *
 * 1. Prepare a realistic IDiscussionBoardGuestUser.IJoin payload:
 *
 *    - Anonymous_token: non-empty opaque string
 *    - Href/referrer: well-formed URI strings
 *    - Ip: either a string IP or null/undefined (we will send a concrete value)
 * 2. Call api.functional.auth.guestUser.join with the join payload and capture the
 *    IDiscussionBoardGuestUser.IAuthorized response as `joined`.
 *
 *    - Typia.assert(joined) to ensure schema conformity.
 * 3. Build an IDiscussionBoardGuestUser.IRefresh payload using
 *    joined.token.refresh:
 *
 *    - RefreshToken: joined.token.refresh
 *    - Href/referrer: realistic URIs (can reuse or vary from join request)
 *    - Ip: provide a concrete IP string to model client context.
 * 4. Call api.functional.auth.guestUser.refresh with the refresh payload and
 *    capture the IDiscussionBoardGuestUser.IAuthorized response as
 *    `refreshed`.
 *
 *    - Typia.assert(refreshed) to ensure schema conformity.
 * 5. Validate business invariants using TestValidator:
 *
 *    - `refreshed.id` equals `joined.id` (same guest record).
 *    - `refreshed.anonymous_token` equals `joined.anonymous_token`.
 *    - `refreshed.token.access` is different from `joined.token.access` to
 *         demonstrate access token rotation.
 *    - `refreshed.token.refresh` is a non-empty string (we do not constrain
 *         equality/inequality vs original, as implementation may rotate it or
 *         not).
 *    - `refreshed.updated_at` is greater than or equal to `joined.updated_at`.
 * 6. (Optional in scenario but skipped in implementation) We could exercise an
 *    additional guest-allowed endpoint to prove the new access token is usable.
 *    However, since no such endpoint is provided, we limit checks to the
 *    authorization DTO invariants and timestamps.
 */
export async function test_api_guest_user_refresh_issues_new_tokens_for_active_guest(
  connection: api.IConnection,
) {
  // 1. Prepare join payload with realistic context values
  const anonymousToken: string = RandomGenerator.alphaNumeric(32);
  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const ip: string = "203.0.113.10";

  const joinBody = {
    anonymous_token: anonymousToken,
    ip,
    href,
    referrer,
  } satisfies IDiscussionBoardGuestUser.IJoin;

  // 2. Call guestUser.join and validate response
  const joined: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // Basic invariants from join
  TestValidator.equals(
    "join: anonymous_token echoes input",
    joined.anonymous_token,
    anonymousToken,
  );

  // 3. Build refresh payload using the refresh token from join
  const refreshHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const refreshReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const refreshIp: string = "203.0.113.20";

  const refreshBody = {
    refreshToken: joined.token.refresh,
    ip: refreshIp,
    href: refreshHref,
    referrer: refreshReferrer,
  } satisfies IDiscussionBoardGuestUser.IRefresh;

  // 4. Call guestUser.refresh and validate response
  const refreshed: IDiscussionBoardGuestUser.IAuthorized =
    await api.functional.auth.guestUser.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshed);

  // 5. Business invariants
  // Identity continuity
  TestValidator.equals(
    "refresh: id must match original guest id",
    refreshed.id,
    joined.id,
  );
  TestValidator.equals(
    "refresh: anonymous_token must remain the same",
    refreshed.anonymous_token,
    joined.anonymous_token,
  );

  // Access token rotation
  TestValidator.notEquals(
    "refresh: access token should rotate",
    refreshed.token.access,
    joined.token.access,
  );

  // Refresh token presence and non-emptiness
  TestValidator.predicate(
    "refresh: refresh token must be non-empty string",
    refreshed.token.refresh.length > 0,
  );

  // updated_at monotonicity: refreshed.updated_at >= joined.updated_at
  const joinedUpdatedAt = new Date(joined.updated_at).getTime();
  const refreshedUpdatedAt = new Date(refreshed.updated_at).getTime();

  TestValidator.predicate(
    "refresh: updated_at should be greater than or equal to join.updated_at",
    refreshedUpdatedAt >= joinedUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

/**
 * Ensure guest refresh rejects tampered or malformed refresh tokens.
 *
 * Business intent:
 *
 * - A guest user first joins via /auth/guestUser/join and receives JWT tokens
 *   (access + refresh) encapsulated in
 *   IDiscussionBoardGuestUser.IAuthorized.token.
 * - The refresh endpoint /auth/guestUser/refresh must reject any refresh attempt
 *   where the refreshToken string has been altered or is structurally invalid,
 *   even though it is still a well-typed string.
 * - E2E tests should validate that such invalid inputs cause the call to fail
 *   (throw), without issuing a new IAuthorizationToken.
 *
 * Test steps:
 *
 * 1. Join as a guest user to obtain a valid refresh token.
 * 2. Derive multiple invalid refresh token variants:
 *
 *    - "tamperedMiddle": flip or replace a character in the middle of the valid
 *         refresh token while keeping it the same length.
 *    - "truncated": drop the last several characters of the valid refresh token to
 *         break its structure.
 *    - "random": generate a completely unrelated opaque token string using
 *         RandomGenerator.alphaNumeric.
 * 3. For each invalid token variant, build an IDiscussionBoardGuestUser.IRefresh
 *    body with required href/referrer fields set to valid URI strings and an
 *    optional ip field set to null (to exercise nullable handling).
 * 4. Call api.functional.auth.guestUser.refresh for each invalid token and assert
 *    that it throws using TestValidator.error. Do not inspect HttpError.status
 *    values or error messages – only that an error occurs.
 * 5. The test passes if every invalid token causes refresh to fail; if any variant
 *    unexpectedly succeeds, the test must fail.
 */
export async function test_api_guest_user_refresh_rejects_expired_or_tampered_token(
  connection: api.IConnection,
) {
  // 1. Join as a guest user to get an authorized payload with refresh token.
  const joinInput = {
    anonymous_token: RandomGenerator.alphaNumeric(32),
    ip: null,
    href: "https://example.com/join" as string & tags.Format<"uri">,
    referrer: "https://example.com/landing" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardGuestUser.IJoin;

  const authorized = await api.functional.auth.guestUser.join(connection, {
    body: joinInput,
  });
  typia.assert<IDiscussionBoardGuestUser.IAuthorized>(authorized);

  const baseRefreshToken: string = authorized.token.refresh;

  // Helper to safely tamper a token string.
  const makeTamperedMiddle = (token: string): string => {
    if (token.length <= 4) return token + "x"; // degenerate but still tampered
    const mid = Math.floor(token.length / 2);
    const replacementPool = [
      "A",
      "B",
      "C",
      "x",
      "y",
      "z",
      "0",
      "1",
      "2",
    ] as const;
    const replacement = RandomGenerator.pick(replacementPool);
    return token.slice(0, mid) + replacement + token.slice(mid + 1);
  };

  const makeTruncated = (token: string): string => {
    if (token.length <= 8) return token.slice(0, Math.max(1, token.length - 1));
    return token.slice(0, token.length - 5);
  };

  const invalidTokens: string[] = [
    makeTamperedMiddle(baseRefreshToken),
    makeTruncated(baseRefreshToken),
    RandomGenerator.alphaNumeric(64),
  ];

  // 3 & 4. For each invalid token, attempt refresh and assert it fails.
  for (const invalid of invalidTokens) {
    const refreshBody = {
      refreshToken: invalid,
      ip: null,
      href: "https://example.com/refresh" as string & tags.Format<"uri">,
      referrer: "https://example.com/context" as string & tags.Format<"uri">,
    } satisfies IDiscussionBoardGuestUser.IRefresh;

    await TestValidator.error(
      "guest refresh must reject invalid token",
      async () => {
        await api.functional.auth.guestUser.refresh(connection, {
          body: refreshBody,
        });
      },
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
