import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate successful member user login with valid credentials.
 *
 * Business flow:
 *
 * 1. Register a new member user via /auth/memberUser/join with unique email,
 *    password, displayName, and session context (href/referrer, optional ip).
 * 2. Immediately call /auth/memberUser/login with the same email/password and
 *    realistic href/referrer so that authentication succeeds.
 * 3. Assert that both responses conform to IDiscussionBoardMemberuser.IAuthorized.
 * 4. Verify that identity fields (id, email, display_name, bio, location) are
 *    consistent between join and login responses.
 * 5. Assert that the embedded token (IAuthorizationToken) has non-empty access and
 *    refresh strings, and valid date-time formatted expiration fields.
 * 6. Check that last_login_at in the login response is not null/undefined and is
 *    greater than or equal to created_at, and that lifecycle flags like
 *    account_status and closed_by_admin reflect an active, open account.
 */
export async function test_api_member_user_login_success_with_valid_credentials(
  connection: api.IConnection,
) {
  // 1. Register a new member user with unique email and password
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string = RandomGenerator.alphaNumeric(16);

  const joinBody = {
    email,
    password,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "203.0.113.10",
    href: "https://discussion.example.com/signup",
    referrer: "https://discussion.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const joined: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // Basic identity assertions on join result
  TestValidator.equals(
    "joined email should match request email",
    joined.email,
    email,
  );
  TestValidator.equals(
    "joined display_name should match request displayName",
    joined.display_name,
    joinBody.displayName,
  );

  // Lifecycle expectations for a freshly created account
  TestValidator.equals(
    "newly joined account must not be soft-deleted",
    joined.deleted_at,
    null,
  );
  TestValidator.equals(
    "newly joined account must not be closed",
    joined.closed_at,
    null,
  );
  TestValidator.equals(
    "newly joined account must not be closed by admin",
    joined.closed_by_admin,
    false,
  );

  // Token structure validation for join response
  typia.assert<IAuthorizationToken>(joined.token);
  TestValidator.predicate(
    "join token.access must be non-empty",
    joined.token.access.length > 0,
  );
  TestValidator.predicate(
    "join token.refresh must be non-empty",
    joined.token.refresh.length > 0,
  );

  // 2. Login using the same credentials
  const loginBody = {
    email,
    password,
    ip: "203.0.113.11",
    href: "https://discussion.example.com/login",
    referrer: "https://discussion.example.com/home",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const loggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedIn);

  // 3. Identity consistency between join and login
  TestValidator.equals("login id must equal join id", loggedIn.id, joined.id);
  TestValidator.equals(
    "login email must equal join email",
    loggedIn.email,
    joined.email,
  );
  TestValidator.equals(
    "login display_name must equal join display_name",
    loggedIn.display_name,
    joined.display_name,
  );
  TestValidator.equals(
    "login bio must equal join bio",
    loggedIn.bio ?? null,
    joined.bio ?? null,
  );
  TestValidator.equals(
    "login location must equal join location",
    loggedIn.location ?? null,
    joined.location ?? null,
  );

  // 4. Token validation for login response
  typia.assert<IAuthorizationToken>(loggedIn.token);
  TestValidator.predicate(
    "login token.access must be non-empty",
    loggedIn.token.access.length > 0,
  );
  TestValidator.predicate(
    "login token.refresh must be non-empty",
    loggedIn.token.refresh.length > 0,
  );

  // 5. Lifecycle and timestamp expectations
  TestValidator.equals(
    "account_status must remain consistent between join and login",
    loggedIn.account_status,
    joined.account_status,
  );
  TestValidator.equals(
    "closed_by_admin must remain false after login",
    loggedIn.closed_by_admin,
    false,
  );
  TestValidator.equals(
    "deleted_at must remain null after login",
    loggedIn.deleted_at,
    null,
  );
  TestValidator.equals(
    "closed_at must remain null after login",
    loggedIn.closed_at,
    null,
  );

  // last_login_at should be set (non-null) after a successful login
  TestValidator.predicate(
    "last_login_at must be present after successful login",
    loggedIn.last_login_at !== null && loggedIn.last_login_at !== undefined,
  );

  // Compare last_login_at and created_at as ISO date-time strings
  const createdAtMillis = Date.parse(joined.created_at);
  const lastLoginMillis =
    loggedIn.last_login_at !== null && loggedIn.last_login_at !== undefined
      ? Date.parse(loggedIn.last_login_at)
      : NaN;

  TestValidator.predicate(
    "last_login_at must be >= created_at",
    !Number.isNaN(createdAtMillis) &&
      !Number.isNaN(lastLoginMillis) &&
      lastLoginMillis >= createdAtMillis,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that member user login rejects an invalid password.
 *
 * Business goal:
 *
 * - Ensure that, for an existing discussion board member user, the login endpoint
 *   does not authenticate the user when an incorrect password is provided,
 *   while still allowing subsequent successful logins with the correct
 *   password.
 *
 * Scenario steps:
 *
 * 1. Register a new member user via POST /auth/memberUser/join with a known email
 *    and password.
 * 2. Attempt to log in using the same email but an incorrect password while
 *    providing valid href/referrer context.
 * 3. Verify that the login attempt fails (throws an error) and no
 *    IDiscussionBoardMemberuser.IAuthorized payload is returned.
 * 4. Perform a new login attempt with the correct password and verify it succeeds,
 *    demonstrating that failed attempts do not corrupt the account lifecycle or
 *    prevent future successful logins.
 */
export async function test_api_member_user_login_rejects_invalid_password(
  connection: api.IConnection,
) {
  // 1. Prepare deterministic but realistic test data
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const correctPassword: string = RandomGenerator.alphaNumeric(16);
  const wrongPassword: string = `${correctPassword}!`; // guaranteed different
  const displayName: string = RandomGenerator.name(2);
  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  // 2. Register a new member user (join)
  const joined: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: {
        email,
        password: correctPassword,
        displayName,
        bio: null,
        location: null,
        ip: null,
        href,
        referrer,
      } satisfies IDiscussionBoardMemberUserJoin.IRequest,
    });
  typia.assert(joined);

  // Capture baseline lifecycle and token information
  const originalToken: IAuthorizationToken = joined.token;
  typia.assert(originalToken);

  // 3. Attempt login with wrong password and expect failure
  await TestValidator.error(
    "member login rejects invalid password",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: {
          email,
          password: wrongPassword,
          ip: null,
          href,
          referrer,
        } satisfies IDiscussionBoardMemberUserLogin.IRequest,
      });
    },
  );

  // 4. Attempt login again with correct password; expect success
  const relogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: {
        email,
        password: correctPassword,
        ip: null,
        href,
        referrer,
      } satisfies IDiscussionBoardMemberUserLogin.IRequest,
    });
  typia.assert(relogin);
  typia.assert(relogin.token);

  // 4-1. Validate that identity fields remain consistent
  TestValidator.equals(
    "email remains consistent across join and relogin",
    relogin.email,
    joined.email,
  );
  TestValidator.equals(
    "account_status remains consistent across join and relogin",
    relogin.account_status,
    joined.account_status,
  );
  TestValidator.equals(
    "closed_by_admin remains consistent across join and relogin",
    relogin.closed_by_admin,
    joined.closed_by_admin,
  );

  // 4-2. Validate that a new access token has been issued after relogin
  TestValidator.notEquals(
    "relogin issues a different access token from original join",
    relogin.token.access,
    originalToken.access,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that member user login requires an existing account and does not
 * implicitly create new accounts.
 *
 * ## Business intent
 *
 * The discussion board exposes POST /auth/memberUser/login to authenticate
 * _existing_ member users in the `discussion_board_memberusers` table using
 * email and password. The endpoint must _not_ act as a registration shortcut:
 * if the provided email is not registered, the login attempt must fail, and no
 * new user record or token pair may be created as a side effect.
 *
 * Due to the constraints of this test harness, we only have the login SDK
 * function (no join/registration or member listing API). Therefore, we validate
 * the "requires existing account" and "no implicit creation" behavior
 * indirectly by repeatedly attempting to log in with a random, extremely
 * unlikely email and observing consistent failures.
 *
 * ## Scenario
 *
 * 1. Generate a random email address that is overwhelmingly unlikely to match any
 *    existing member record.
 * 2. Build a valid IDiscussionBoardMemberUserLogin.IRequest object using that
 *    email, a dummy password, and random-but-valid href/referrer URIs.
 * 3. Call api.functional.auth.memberUser.login with this body and expect the call
 *    to fail with an HTTP-level error (credentials invalid / account not
 *    found). Use TestValidator.error to assert that an error is thrown, but do
 *    not depend on any particular HTTP status code.
 * 4. Invoke the same login call again with exactly the same credentials and assert
 *    that it still fails. This guards against any unintended side-effect
 *    account creation behavior on first failure.
 * 5. As a control path, additionally perform a successful login using
 *    typia.random-generated input under simulation mode, when available, to
 *    validate that the success path yields a value compatible with
 *    IDiscussionBoardMemberuser.IAuthorized and that typia.assert accepts it.
 *    This does not depend on any particular business record state because
 *    simulation mode fabricates valid responses.
 */
export async function test_api_member_user_login_requires_existing_account(
  connection: api.IConnection,
) {
  // Helper to build a login request body with valid formats
  const buildLoginBody = (
    email: string & tags.Format<"email">,
  ): IDiscussionBoardMemberUserLogin.IRequest => {
    const href = "https://".concat(
      RandomGenerator.alphabets(10),
      ".example.com/login",
    );
    const referrer = "https://".concat(
      RandomGenerator.alphabets(10),
      ".example.com/",
    );

    const body: IDiscussionBoardMemberUserLogin.IRequest = {
      email,
      password: RandomGenerator.alphabets(16),
      ip: null,
      href,
      referrer,
    };
    return body;
  };

  // 1. Generate an email that is extremely unlikely to belong to a real user
  const rareEmail: string & tags.Format<"email"> = (RandomGenerator.alphabets(
    16,
  ) +
    "-nonexistent-" +
    RandomGenerator.alphabets(16) +
    "@example.invalid") as string & tags.Format<"email">;

  const firstBody = buildLoginBody(rareEmail);
  const secondBody = buildLoginBody(rareEmail);

  // 2. First login attempt with unknown email should fail
  await TestValidator.error(
    "login with non-existent member user must fail",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: firstBody,
      });
    },
  );

  // 3. Second login attempt with the same unknown email must also fail,
  //    demonstrating that login does not implicitly create the account.
  await TestValidator.error(
    "repeated login with same non-existent member user must still fail",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: secondBody,
      });
    },
  );

  // 4. Optional control: when simulation mode is enabled, verify that a
  //    successful login response conforms to IDiscussionBoardMemberuser.IAuthorized.
  if (connection.simulate === true) {
    const simulatedBody =
      typia.random<IDiscussionBoardMemberUserLogin.IRequest>();

    const authorized = await api.functional.auth.memberUser.login(connection, {
      body: simulatedBody,
    });
    typia.assert<IDiscussionBoardMemberuser.IAuthorized>(authorized);

    TestValidator.predicate(
      "simulated login should issue non-empty access token",
      () => authorized.token.access.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

export async function test_api_member_user_login_after_join_flow_end_to_end(
  connection: api.IConnection,
) {
  // 1. Prepare unique credentials and URLs for the flow
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string = RandomGenerator.alphaNumeric(16);

  const joinHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const joinReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const loginHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const loginReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const displayName: string = RandomGenerator.paragraph({ sentences: 2 });

  // 2. Perform join (registration) call
  const joinBody = {
    email,
    password,
    displayName,
    bio: null,
    location: null,
    ip: null,
    href: joinHref,
    referrer: joinReferrer,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const joined: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // Basic identity invariants from join
  TestValidator.predicate(
    "joined account_status should allow login (non-empty string)",
    joined.account_status.length > 0,
  );
  TestValidator.predicate(
    "joined account must not be closed by admin",
    joined.closed_by_admin === false,
  );
  TestValidator.predicate(
    "joined deleted_at should be null or undefined for active account",
    joined.deleted_at === null || joined.deleted_at === undefined,
  );

  // Capture join lifecycle/tokens for comparison
  const joinCreatedAt = joined.created_at;
  const joinUpdatedAt = joined.updated_at;
  const joinLastLoginAt = joined.last_login_at ?? null;
  const joinToken: IAuthorizationToken = joined.token;

  // 3. Simulate client-side logout: do not reuse token values explicitly
  // (No manipulation of connection.headers; SDK manages headers itself.)

  // 4. Perform login with the same credentials
  const loginBody = {
    email,
    password,
    ip: null,
    href: loginHref,
    referrer: loginReferrer,
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const loggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedIn);

  // 5. Validate core identity stability across join and login
  TestValidator.equals(
    "email must be identical between join and login",
    loggedIn.email,
    joined.email,
  );
  TestValidator.equals(
    "id must be identical between join and login",
    loggedIn.id,
    joined.id,
  );
  TestValidator.equals(
    "display_name should remain the same across join and login",
    loggedIn.display_name,
    joined.display_name,
  );
  TestValidator.equals(
    "account_status should remain unchanged across join and login",
    loggedIn.account_status,
    joined.account_status,
  );
  TestValidator.equals(
    "closed_by_admin must remain false after login",
    loggedIn.closed_by_admin,
    false,
  );

  // 6. Validate lifecycle timestamps
  TestValidator.equals(
    "created_at should be stable across join and login",
    loggedIn.created_at,
    joinCreatedAt,
  );

  // updated_at should be >= initial updated_at (lexicographic compare is safe on ISO strings)
  TestValidator.predicate(
    "updated_at after login should be greater than or equal to join updated_at",
    loggedIn.updated_at >= joinUpdatedAt,
  );

  // last_login_at should be non-null after login and >= previous last_login_at when it existed
  TestValidator.predicate(
    "last_login_at after login must not be null or undefined",
    loggedIn.last_login_at !== null && loggedIn.last_login_at !== undefined,
  );
  if (joinLastLoginAt !== null) {
    const loginLastLoginAt = typia.assert<string & tags.Format<"date-time">>(
      loggedIn.last_login_at!,
    );
    TestValidator.predicate(
      "last_login_at after login should be >= join last_login_at when previous value existed",
      loginLastLoginAt >= joinLastLoginAt,
    );
  }

  // 7. Validate token pair renewal semantics
  const loginToken: IAuthorizationToken = loggedIn.token;
  typia.assert(loginToken);

  const tokenChanged =
    loginToken.access !== joinToken.access ||
    loginToken.refresh !== joinToken.refresh ||
    loginToken.expired_at !== joinToken.expired_at ||
    loginToken.refreshable_until !== joinToken.refreshable_until;

  TestValidator.predicate(
    "at least one of the token fields (access/refresh/expired_at/refreshable_until) must change between join and login",
    tokenChanged,
  );
}

