import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

/**
 * Validate that admin join works with only minimal required fields.
 *
 * This test ensures that POST /auth/adminUser/join successfully registers a new
 * administrative user when only the required fields of
 * IDiscussionBoardAdminUserJoin.IRequest are provided. Optional profile and
 * connection metadata (bio, ip) are deliberately omitted to confirm that the
 * backend correctly treats them as optional and still issues a fully functional
 * IDiscussionBoardAdminuser.IAuthorized session.
 *
 * Business steps:
 *
 * 1. Prepare a minimal IDiscussionBoardAdminUserJoin.IRequest payload with:
 *
 *    - Email (unique, valid email format)
 *    - Password (password-formatted string)
 *    - Display_name (short human-readable name)
 *    - Href (current page URL as a valid URI)
 *    - Referrer (referrer URL as a valid URI) and omit optional bio and ip
 *         completely.
 * 2. Call api.functional.auth.adminUser.join with this body and expect success.
 * 3. Validate that the response conforms to IDiscussionBoardAdminuser.IAuthorized
 *    using typia.assert.
 * 4. Assert that key business fields are correctly initialized:
 *
 *    - Email in the response matches the request email
 *    - DisplayName is non-empty and not just whitespace
 *    - LoginId is non-empty
 *    - Status is a non-empty string
 *    - EmailVerified is a boolean (typically false for fresh accounts)
 *    - Token field is present and satisfies IAuthorizationToken
 *    - CreatedAt and updatedAt are non-empty ISO date-time strings and createdAt <=
 *         updatedAt when parsed as dates.
 * 5. Rely on the presence of a valid token as evidence that the minimal account is
 *    immediately usable, instead of performing a separate login flow (no login
 *    endpoint is available in the current SDK slice).
 */
export async function test_api_admin_user_join_requires_minimal_fields(
  connection: api.IConnection,
) {
  // 1. Construct minimal join request body with only required fields
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const href: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const referrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const requestBody = {
    email,
    password,
    display_name: RandomGenerator.name(2),
    href,
    referrer,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  // 2. Call join endpoint with minimal body
  const output: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: requestBody,
    });

  // 3. Structural type validation of response
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(output);

  // 4. Business field validations
  // 4-1. Email must match input
  TestValidator.equals(
    "admin email matches request email",
    output.email,
    email,
  );

  // 4-2. displayName is non-empty and not whitespace-only
  TestValidator.predicate("displayName is non-empty", () => {
    return output.displayName.trim().length > 0;
  });

  // 4-3. loginId is non-empty
  TestValidator.predicate("loginId is non-empty", () => {
    return output.loginId.trim().length > 0;
  });

  // 4-4. status is a non-empty string (do not assert specific value)
  TestValidator.predicate("status is a non-empty string", () => {
    return output.status.trim().length > 0;
  });

  // 4-5. emailVerified is a boolean; typia.assert already checked type,
  // but we still validate that the field exists in a business sense by
  // reading it and asserting via predicate.
  TestValidator.predicate("emailVerified is boolean field readable", () => {
    return typeof output.emailVerified === "boolean";
  });

  // 4-6. Token object should satisfy IAuthorizationToken
  typia.assert<IAuthorizationToken>(output.token);

  // 4-7. createdAt and updatedAt should be valid non-empty date-time strings
  TestValidator.predicate(
    "createdAt is non-empty string",
    () => output.createdAt.trim().length > 0,
  );
  TestValidator.predicate(
    "updatedAt is non-empty string",
    () => output.updatedAt.trim().length > 0,
  );

  const createdTime: number = Date.parse(output.createdAt);
  const updatedTime: number = Date.parse(output.updatedAt);

  TestValidator.predicate(
    "createdAt parses to a valid timestamp",
    !Number.isNaN(createdTime),
  );
  TestValidator.predicate(
    "updatedAt parses to a valid timestamp",
    !Number.isNaN(updatedTime),
  );

  TestValidator.predicate(
    "createdAt is not after updatedAt",
    createdTime <= updatedTime,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

/**
 * Validate admin user join with connection metadata recording.
 *
 * Business goal
 *
 * - Ensure that POST /auth/adminUser/join correctly accepts connection metadata
 *   fields (ip, href, referrer) in IDiscussionBoardAdminUserJoin.IRequest while
 *   creating a new administrative user and issuing JWT tokens.
 * - Confirm that the join operation succeeds both when an IP is explicitly
 *   supplied and when it is omitted (allowing the backend to derive it).
 * - Verify that the SDK attaches the issued access token to
 *   connection.headers.Authorization as documented in the join()
 *   implementation.
 *
 * Scenario steps
 *
 * 1. Build a realistic IDiscussionBoardAdminUserJoin.IRequest payload with:
 *
 *    - Unique admin email (email format)
 *    - Strong-looking password (Format<"password"> string)
 *    - Display_name and optional bio
 *    - Valid absolute URIs for href and referrer
 *    - Explicit IPv4 string in ip for the first join attempt
 * 2. Call api.functional.auth.adminUser.join with the above payload.
 * 3. Assert that:
 *
 *    - The response conforms to IDiscussionBoardAdminuser.IAuthorized
 *    - Token is present and conforms to IAuthorizationToken
 *    - Connection.headers.Authorization has been populated to the access token
 * 4. Perform a second join attempt for another admin user where ip is omitted but
 *    href and referrer are still valid URIs. This validates that join does not
 *    require the ip field.
 * 5. Again assert that the response is a valid
 *    IDiscussionBoardAdminuser.IAuthorized and that
 *    connection.headers.Authorization has been set.
 */
export async function test_api_admin_user_join_with_connection_metadata_recording(
  connection: api.IConnection,
) {
  // Helper to build a realistic frontend URL
  const buildFrontendUrl = (path: string): string => {
    const host = "https://admin.discussion-board.example.com";
    return `${host}${path}`;
  };

  // 1. First admin: join with explicit IP address
  const firstEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const firstPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const firstRequestBody = {
    email: firstEmail,
    password: firstPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "203.0.113.42", // TEST-NET-3 example IPv4 address
    href: buildFrontendUrl("/onboarding/admin/join"),
    referrer: buildFrontendUrl("/landing"),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const firstAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: firstRequestBody,
    });

  // Ensure entire response structure is valid
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(firstAuthorized);
  // token must be present and structurally valid
  typia.assert<IAuthorizationToken>(firstAuthorized.token);

  // SDK should set Authorization header to the access token
  await TestValidator.predicate(
    "first join should set Authorization header",
    async () => {
      return (
        connection.headers !== undefined &&
        typeof connection.headers["Authorization"] === "string" &&
        connection.headers["Authorization"].length > 0 &&
        connection.headers["Authorization"] === firstAuthorized.token.access
      );
    },
  );

  // 2. Second admin: join without explicit IP (backend derives it)
  const secondEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const secondPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const secondRequestBody = {
    email: secondEmail,
    password: secondPassword,
    display_name: RandomGenerator.name(2),
    bio: null,
    // ip is intentionally omitted to verify it is optional
    href: buildFrontendUrl("/onboarding/admin/join"),
    referrer: buildFrontendUrl("/marketing/campaign-2025"),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const secondAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: secondRequestBody,
    });

  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(secondAuthorized);
  typia.assert<IAuthorizationToken>(secondAuthorized.token);

  // After second join, Authorization header must now reflect second token
  await TestValidator.predicate(
    "second join should update Authorization header to new access token",
    async () => {
      return (
        connection.headers !== undefined &&
        typeof connection.headers["Authorization"] === "string" &&
        connection.headers["Authorization"].length > 0 &&
        connection.headers["Authorization"] === secondAuthorized.token.access
      );
    },
  );

  // Basic logical cross-checks of response content
  TestValidator.equals(
    "first admin email in response should match request email",
    firstAuthorized.email,
    firstEmail,
  );
  TestValidator.equals(
    "second admin email in response should match request email",
    secondAuthorized.email,
    secondEmail,
  );

  TestValidator.predicate(
    "first admin ID should be a non-empty UUID string",
    () => firstAuthorized.id.length > 0,
  );
  TestValidator.predicate(
    "second admin ID should be a non-empty UUID string",
    () => secondAuthorized.id.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that an article category created by an admin user is publicly
 * retrievable by its business code.
 *
 * Business workflow:
 *
 * 1. Admin joins via POST /auth/adminUser/join and becomes authenticated.
 * 2. Admin creates a new article category with a unique business code via POST
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Using an unauthenticated connection (no Authorization header), call GET
 *    /discussionBoard/articleCategories/{categoryCode} to retrieve the category
 *    by its business code.
 * 4. Verify that the retrieved category matches the created one in code, name,
 *    description, and order, and that it is active (deleted_at is
 *    null/undefined) with valid timestamps.
 * 5. Call the public GET endpoint again with the same code to confirm that
 *    repeated reads are idempotent and return identical data.
 */
export async function test_api_article_category_retrieval_public_after_admin_creation(
  connection: api.IConnection,
) {
  // 1. Admin joins and becomes authenticated
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates a new article category
  const businessCode: string = `ECONOMY-${RandomGenerator.alphaNumeric(8).toUpperCase()}`;
  const categoryCreateBody = {
    code: businessCode,
    name: `Economy ${RandomGenerator.name(1)}`,
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 0,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const createdCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(createdCategory);

  // Basic sanity checks on created category
  TestValidator.equals(
    "created category code matches request",
    createdCategory.code,
    categoryCreateBody.code,
  );
  TestValidator.equals(
    "created category name matches request",
    createdCategory.name,
    categoryCreateBody.name,
  );
  TestValidator.equals(
    "created category description matches request",
    createdCategory.description ?? null,
    categoryCreateBody.description ?? null,
  );
  TestValidator.equals(
    "created category order matches request",
    createdCategory.order,
    categoryCreateBody.order,
  );
  TestValidator.equals(
    "newly created category should not be soft-deleted",
    createdCategory.deleted_at ?? null,
    null,
  );

  // 3. Prepare an unauthenticated connection for public GET
  const publicConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 4. Publicly retrieve the category by business code (first read)
  const fetchedCategory1: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.articleCategories.at(
      publicConnection,
      {
        categoryCode: createdCategory.code,
      },
    );
  typia.assert(fetchedCategory1);

  // 5. Validate public retrieval fields match the created category
  TestValidator.equals(
    "public fetch code matches created category",
    fetchedCategory1.code,
    createdCategory.code,
  );
  TestValidator.equals(
    "public fetch name matches created category",
    fetchedCategory1.name,
    createdCategory.name,
  );
  TestValidator.equals(
    "public fetch description matches created category",
    fetchedCategory1.description ?? null,
    createdCategory.description ?? null,
  );
  TestValidator.equals(
    "public fetch order matches created category",
    fetchedCategory1.order,
    createdCategory.order,
  );
  TestValidator.equals(
    "publicly fetched category is not soft-deleted",
    fetchedCategory1.deleted_at ?? null,
    null,
  );

  // 6. Call the public GET endpoint again to ensure idempotent behavior
  const fetchedCategory2: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.articleCategories.at(
      publicConnection,
      {
        categoryCode: createdCategory.code,
      },
    );
  typia.assert(fetchedCategory2);

  // 7. Ensure repeated public GET calls return identical data
  TestValidator.equals(
    "second public fetch equals first public fetch",
    fetchedCategory2,
    fetchedCategory1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Ensure that requesting a discussion-board article category by a non-existent
 * business code yields a 404-style error, while valid codes still work.
 *
 * Business context:
 *
 * - Categories (like "ECONOMY" or "POLITICS") are stored in
 *   discussion_board_article_categories and exposed via a public
 *   /discussionBoard/articleCategories/{categoryCode} endpoint.
 * - The endpoint must return a 404 Not Found when the provided categoryCode does
 *   not match any active (non-deleted) category.
 *
 * Test flow:
 *
 * 1. Register an adminUser using POST /auth/adminUser/join. This also issues
 *    adminUser tokens on the shared connection so subsequent admin-only
 *    endpoints are authorized.
 * 2. Using the adminUser session, create at least one article category via POST
 *    /discussionBoard/adminUser/articleCategories with a concrete code like
 *    "ECONOMY". This proves that at least one valid category exists and that
 *    the GET endpoint can later succeed.
 * 3. Call GET /discussionBoard/articleCategories/{categoryCode} with the known
 *    existing code and assert that a valid IDiscussionBoardArticleCategory is
 *    returned and passes typia.assert.
 * 4. Prepare a clearly non-existent category business code, such as
 *    "NON_EXISTING_CATEGORY_CODE_123" with a random suffix. Ensure it is
 *    distinct from the created category code.
 * 5. Call GET /discussionBoard/articleCategories/{categoryCode} with this unknown
 *    code, expecting the backend to respond with a 404 Not Found. Since SDK
 *    calls throw HttpError on non-2xx responses, wrap the call with
 *    TestValidator.httpError and assert that a 404 is produced.
 *
 * Validation points:
 *
 * - Successful retrieval for the known category code returns a payload that
 *   conforms to IDiscussionBoardArticleCategory.
 * - The non-existent code path reliably produces an HttpError with 404 status,
 *   ensuring no empty object or 200/204 is returned.
 *
 * Notes:
 *
 * - The GET /discussionBoard/articleCategories/{categoryCode} endpoint is public
 *   (no auth required), but calling it with an already-authenticated connection
 *   is acceptable; token headers will be ignored.
 */
export async function test_api_article_category_retrieval_not_found_for_unknown_code(
  connection: api.IConnection,
) {
  // 1. Register an adminUser (auth.adminUser.join) to obtain an admin session.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a baseline article category using the adminUser actor.
  const existingCategoryCode = "ECONOMY";
  const createBody = {
    code: existingCategoryCode,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const createdCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: createBody },
    );
  typia.assert(createdCategory);

  // 3. Verify that GET by existing code works and returns a valid category.
  const loadedCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.articleCategories.at(connection, {
      categoryCode: createdCategory.code,
    });
  typia.assert(loadedCategory);

  TestValidator.equals(
    "loaded category should match created category id",
    loadedCategory.id,
    createdCategory.id,
  );

  // 4. Prepare a clearly non-existing category code.
  const nonExistingCategoryCode =
    "NON_EXISTING_CATEGORY_CODE_" + RandomGenerator.alphaNumeric(8);

  // 5. Call GET with the unknown code and assert a 404 HttpError is thrown.
  await TestValidator.httpError(
    "requesting unknown category code should yield 404",
    404,
    async () => {
      await api.functional.discussionBoard.articleCategories.at(connection, {
        categoryCode: nonExistingCategoryCode,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Verify that the public article category detail endpoint only exposes active
 * categories and rejects unknown/retired codes.
 *
 * Business context:
 *
 * - Article categories are master data identified by a stable `code`.
 * - The public GET /discussionBoard/articleCategories/{categoryCode} endpoint is
 *   documented to return only categories where `deleted_at` is null and to
 *   respond with 404 when no active record exists for the requested code.
 * - Available APIs in this scope allow us to (a) register an adminUser and (b)
 *   create a new article category, but there is no soft-delete/update operation
 *   exposed. Therefore, this test focuses on validating that:
 *
 *   1. A freshly created active category is retrievable via the public endpoint, and
 *   2. A clearly non-existent category code results in an error when retrieved,
 *        representing the behavior for soft-deleted/retired categories as
 *        well.
 *
 * Test steps:
 *
 * 1. Join an adminUser using POST /auth/adminUser/join to establish an admin
 *    session; the SDK will automatically store the issued access token in the
 *    connection headers.
 * 2. As the adminUser, create a new article category using POST
 *    /discussionBoard/adminUser/articleCategories with a unique `code`, and
 *    realistic name/description/order values.
 * 3. Call GET /discussionBoard/articleCategories/{categoryCode} with the created
 *    `code` to ensure the public read model returns the category:
 *
 *    - Verify the response structure using typia.assert.
 *    - Assert that the `code` and `name` match the creation payload.
 * 4. Call GET /discussionBoard/articleCategories/{categoryCode} again but using a
 *    different, highly unlikely `code` (e.g., a long random token prefixed with
 *    a marker). Wrap this in TestValidator.error to assert that the endpoint
 *    rejects unknown codes (which would include soft-deleted categories
 *    according to the contract). We do not assert a specific HTTP status code,
 *    only that an error occurs.
 *
 * This test thereby validates that the endpoint exposes active categories and
 * does not silently succeed for unknown/retired codes, which is the effective
 * contract implied by the `deleted_at` semantics on the underlying model.
 */
export async function test_api_article_category_retrieval_ignores_soft_deleted_categories(
  connection: api.IConnection,
) {
  // 1. AdminUser join to obtain administrative session and token
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized = await api.functional.auth.adminUser.join(connection, {
    body: joinBody,
  });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorized);

  // 2. Create a new active article category as adminUser
  const categoryCodeBase = RandomGenerator.alphabets(12);
  const createBody = {
    code: categoryCodeBase,
