import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that creating a discussion-board article category enforces
 * uniqueness of the `code` field and rejects duplicates for active categories.
 *
 * Business context:
 *
 * - The `discussion_board_article_categories.code` column is a stable
 *   machine-friendly business key (e.g., "ECONOMY", "POLITICS").
 * - It must be unique among non-deleted categories so that other systems can
 *   reliably reference categories by code.
 * - Administrative users (adminUser actor) can register new categories through
 *   the admin-only creation API.
 *
 * This test covers the following workflow:
 *
 * 1. Register a new adminUser account via POST /auth/adminUser/join, which both
 *    creates the admin record and establishes an authenticated session (SDK
 *    automatically wires Authorization header using the token).
 * 2. Using the authenticated admin session, call POST
 *    /discussionBoard/adminUser/articleCategories with an
 *    IDiscussionBoardArticleCategory.ICreate payload using a specific `code`
 *    (e.g., "POLITICS_DUPLICATE"), and assert that the category is successfully
 *    created and returned with the same code.
 * 3. With the same admin session, attempt to create a second category using the
 *    _same_ `code` value but different name/description/order. This should
 *    violate the unique business constraint on `code`.
 * 4. Assert that the second creation attempt fails by using TestValidator.error
 *    with an async closure that calls the create API with the duplicate code
 *    payload, ensuring that some HttpError is thrown (without asserting a
 *    particular HTTP status or error body structure).
 *
 * Notes:
 *
 * - We do not perform a follow-up GET by code because no such read API is
 *   provided in the SDK materials; uniqueness is validated solely via the
 *   rejection of the duplicate creation request.
 */
export async function test_api_article_category_creation_rejects_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Register an adminUser and obtain an authenticated session
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.discussion-board.example.com/register",
    referrer: "https://discussion-board.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create the first article category with a specific business `code`
  const categoryCode = "POLITICS_DUPLICATE";

  const firstCategoryBody = {
    code: categoryCode,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const firstCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: firstCategoryBody,
      },
    );
  typia.assert(firstCategory);

  TestValidator.equals(
    "created category should have the requested code",
    firstCategory.code,
    categoryCode,
  );

  // 3. Attempt to create a second category with the same `code`
  const secondCategoryBody = {
    code: categoryCode, // duplicate code
    name: RandomGenerator.name(3),
    // demonstrate that other fields can differ; uniqueness is on code only
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  await TestValidator.error(
    "duplicate category code should be rejected by create API",
    async () => {
      await api.functional.discussionBoard.adminUser.articleCategories.create(
        connection,
        {
          body: secondCategoryBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Ensure that creating a discussion-board article category is allowed only for
 * authenticated adminUser actors.
 *
 * Business intent:
 *
 * - The article category master (discussion_board_article_categories) is
 *   privileged configuration and must not be modifiable by unauthenticated or
 *   non-admin actors.
 * - The POST /discussionBoard/adminUser/articleCategories endpoint is restricted
 *   to the adminUser authorization actor and should fail when called without a
 *   valid admin session.
 *
 * Test flow:
 *
 * 1. Build a valid category creation payload
 *    (IDiscussionBoardArticleCategory.ICreate) with a machine-friendly code,
 *    human-readable name, optional description, and an int32 order value.
 * 2. Derive an unauthenticated connection from the provided connection by
 *    shallow-cloning it and setting headers to an empty object literal (without
 *    further mutations), to simulate a request that has no Authorization
 *    header.
 * 3. Attempt to call
 *    api.functional.discussionBoard.adminUser.articleCategories.create using
 *    the unauthenticated connection and the prepared payload.
 *
 *    - Wrap this call in await TestValidator.error("unauthenticated category
 *         creation should fail", async () => { ... })
 *    - Do not assert any specific HttpError status code; we only assert that an
 *         error occurs.
 * 4. Using the original connection, register a new adminUser by calling
 *    api.functional.auth.adminUser.join with a randomly generated
 *    IDiscussionBoardAdminUserJoin.IRequest body (email, password,
 *    display_name, optional bio, href, referrer, etc.).
 *
 *    - After this call, the SDK automatically applies Authorization header on the
 *         connection for the adminUser.
 *    - Assert the response shape with typia.assert to ensure it conforms to
 *         IDiscussionBoardAdminuser.IAuthorized.
 * 5. Reuse the same category creation payload from step 1 and call
 *    api.functional.discussionBoard.adminUser.articleCategories.create again,
 *    now using the authenticated connection.
 *
 *    - Expect success; capture the response as IDiscussionBoardArticleCategory.
 *    - Validate the response with typia.assert.
 *    - Use TestValidator.equals to confirm that key business fields (code, name,
 *         description, order) in the response match the input payload values.
 *    - Additionally, confirm that deleted_at is null or undefined to reflect an
 *         active (non-deleted) category.
 */
export async function test_api_article_category_creation_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Build a deterministic category creation payload
  const categoryBody = {
    code: RandomGenerator.alphabets(8).toUpperCase(),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  // 2. Derive an unauthenticated connection (no Authorization header)
  const unauthenticated: api.IConnection = { ...connection, headers: {} };

  // 3. Attempt category creation without authentication and expect failure
  await TestValidator.error(
    "unauthenticated category creation should fail",
    async () => {
      await api.functional.discussionBoard.adminUser.articleCategories.create(
        unauthenticated,
        {
          body: categoryBody,
        },
      );
    },
  );

  // 4. Join/register an adminUser to obtain authenticated context
  const adminJoinBody = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 5. Retry category creation with authenticated adminUser connection
  const created: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(created);

  // 6. Business field validations
  TestValidator.equals(
    "created category code matches request",
    created.code,
    categoryBody.code,
  );
  TestValidator.equals(
    "created category name matches request",
    created.name,
    categoryBody.name,
  );
  TestValidator.equals(
    "created category description matches request",
    created.description ?? null,
    categoryBody.description ?? null,
  );
  TestValidator.equals(
    "created category order matches request",
    created.order,
    categoryBody.order,
  );

  TestValidator.predicate(
    "created category deleted_at is null or undefined",
    created.deleted_at === null || created.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMemberuserSession";

/**
 * Basic happy-path flow for admin listing of member sessions.
 *
 * Steps:
 *
 * 1. Register an admin user and obtain admin tokens.
 * 2. As admin, create an article category.
 * 3. Register a member user and obtain member identity (id) and tokens.
 * 4. Log in as that member to ensure at least one session.
 * 5. As member, create an article in the created category to simulate activity.
 * 6. Switch back to admin context by logging in as admin.
 * 7. Call the member sessions listing endpoint for that member with basic
 *    pagination parameters.
 * 8. Validate pagination metadata and that all returned session summaries belong
 *    to the given member user and have required fields.
 */
export async function test_api_admin_member_sessions_listing_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register an admin user
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoined: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoined);

  const adminId: string & tags.Format<"uuid"> = adminJoined.id;
  TestValidator.predicate(
    "admin id is a non-empty uuid string",
    typeof adminId === "string" && adminId.length > 0,
  );

  // 2. As admin, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Register a member user
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, South Korea",
    ip: "127.0.0.1",
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberJoined: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoined);

  const memberId: string & tags.Format<"uuid"> = memberJoined.id;
  TestValidator.predicate(
    "member id is a non-empty uuid string",
    typeof memberId === "string" && memberId.length > 0,
  );

  // 4. Log in as that member to create another session
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: "127.0.0.1",
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/home",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  // 5. As member, create an article in the category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. Switch back to admin context by logging in
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 7. Admin lists sessions for the member user with basic pagination
  const pageRequest = 1;
  const limitRequest = 10;

  const sessionsRequestBody = {
    page: pageRequest,
    limit: limitRequest,
    created_from: undefined,
    created_to: undefined,
  } satisfies IDiscussionBoardMemberuserSession.IRequest;

  const pageResult: IPageIDiscussionBoardMemberuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: memberId,
        body: sessionsRequestBody,
      },
    );
  typia.assert(pageResult);

  const pagination = pageResult.pagination;

  TestValidator.predicate(
    "pagination current is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    pagination.pages >= 0,
  );

  TestValidator.equals(
    "pagination limit matches request when limit is provided",
    pagination.limit,
    limitRequest,
  );

  TestValidator.predicate(
    "data array length is less than or equal to pagination limit",
    pageResult.data.length <= pagination.limit,
  );

  for (const session of pageResult.data) {
    typia.assert<IDiscussionBoardMemberuserSession.ISummary>(session);

    TestValidator.equals(
      "session memberUser id matches queried memberId",
      session.memberUser.id,
      memberId,
    );

    TestValidator.equals(
      "session memberUser display_name matches member profile",
      session.memberUser.display_name,
      memberJoined.display_name,
    );

    TestValidator.predicate(
      "session created_at is non-empty string",
      typeof session.created_at === "string" && session.created_at.length > 0,
    );

    TestValidator.predicate(
      "session is_active is boolean",
      typeof session.is_active === "boolean",
    );
  }

  // 8. Optional: Call second page to ensure pagination.current can change
  const secondPageRequest = 2;
  const secondSessionsRequestBody = {
    page: secondPageRequest,
    limit: limitRequest,
    created_from: undefined,
    created_to: undefined,
  } satisfies IDiscussionBoardMemberuserSession.IRequest;

  const secondPageResult: IPageIDiscussionBoardMemberuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: memberId,
        body: secondSessionsRequestBody,
      },
    );
  typia.assert(secondPageResult);

  TestValidator.predicate(
    "second page pagination current is non-negative",
    secondPageResult.pagination.current >= 0,
  );

  TestValidator.equals(
    "second page limit matches request",
    secondPageResult.pagination.limit,
    limitRequest,
  );

  for (const session of secondPageResult.data) {
    typia.assert<IDiscussionBoardMemberuserSession.ISummary>(session);
    TestValidator.equals(
      "second page session memberUser id matches queried memberId",
      session.memberUser.id,
      memberId,
    );
  }
}

