  typia.assert(adminLoginAuthorized);

  // 6. Scenario 1: mismatched identifiers simulated by pairing the
  // memberUserId of member A with a random sessionId that is very unlikely to
  // belong to that user. We expect the call to fail with an error.
  const mismatchedSessionId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "admin cannot view session with mismatched memberUserId and sessionId",
    async () => {
      await api.functional.discussionBoard.adminUser.memberUsers.sessions.at(
        connection,
        {
          memberUserId: memberAId,
          sessionId: mismatchedSessionId,
        },
      );
    },
  );

  // 7. Scenario 2: use a random UUID as both memberUserId and sessionId where
  // there should be no corresponding member or session at all. This should
  // also result in a not-found style error.
  const unknownMemberId = typia.random<string & tags.Format<"uuid">>();
  const unknownSessionId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "admin cannot view session for completely unknown memberUser and sessionId",
    async () => {
      await api.functional.discussionBoard.adminUser.memberUsers.sessions.at(
        connection,
        {
          memberUserId: unknownMemberId,
          sessionId: unknownSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Public comment detail retrieval after authenticated creation.
 *
 * Business flow:
 *
 * 1. Register a new member user via POST /auth/memberUser/join to obtain an
 *    authenticated context.
 * 2. As that member user, create a new article via POST
 *    /discussionBoard/memberUser/articles using a valid random categoryId (UUID
 *    format) and realistic random text fields.
 * 3. As the same member user, create a new comment for that article via POST
 *    /discussionBoard/memberUser/articles/{articleId}/comments.
 * 4. Derive a public (unauthenticated) connection by cloning the original
 *    connection with an empty headers object, without further header
 *    manipulation.
 * 5. Using the public connection, call GET
 *    /discussionBoard/articles/{articleId}/comments/{commentId}.
 * 6. Validate that the returned comment:
 *
 *    - Conforms to IDiscussionBoardComment (typia.assert).
 *    - Has the same id and body as the created comment.
 *    - Embeds an article summary whose id, title, and category.id match the created
 *         article.
 *    - Has a non-empty status string equal to the status from the created comment
 *         response.
 *    - Has deleted_at === null for this freshly created visible comment.
 */
export async function test_api_comment_detail_public_access(
  connection: api.IConnection,
) {
  // 1. Register member user and obtain authenticated context
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://example.com/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const member: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(member);

  // 2. Create article as the authenticated member user
  const articleCreate = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreate,
      },
    );
  typia.assert(article);

  // 3. Create comment for the article as the same member user
  const commentCreate = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const createdComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreate,
      },
    );
  typia.assert(createdComment);

  // 4. Build a public (unauthenticated) connection by clearing headers
  const publicConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 5. Publicly fetch the comment detail
  const publicComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.articles.comments.at(
      publicConnection,
      {
        articleId: article.id,
        commentId: createdComment.id,
      },
    );
  typia.assert(publicComment);

  // 6. Validate logical consistency between created and public comment
  TestValidator.equals(
    "public comment id matches created comment id",
    publicComment.id,
    createdComment.id,
  );

  TestValidator.equals(
    "public comment body matches created comment body",
    publicComment.body,
    createdComment.body,
  );

  TestValidator.equals(
    "public comment status matches created comment status",
    publicComment.status,
    createdComment.status,
  );

  TestValidator.equals(
    "public comment article id matches created article id",
    publicComment.article.id,
    article.id,
  );

  TestValidator.equals(
    "public comment article title matches created article title",
    publicComment.article.title,
    article.title,
  );

  TestValidator.equals(
    "public comment article category id matches created article category id",
    publicComment.article.category.id,
    article.category.id,
  );

  TestValidator.equals(
    "public comment deleted_at is null for fresh comment",
    publicComment.deleted_at,
    null,
  );

  TestValidator.predicate(
    "public comment status is non-empty string",
    publicComment.status.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

export async function test_api_comment_detail_visibility_and_not_found_cases(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    // Optional fields can be null or omitted; use realistic sample values where convenient
    bio: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    location: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 3,
      wordMax: 8,
    }),
    ip: null,
    href: "https://example.com/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const member: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2. Create a new article as this member
  const articleCreateBody = typia.random<IDiscussionBoardArticle.ICreate>();

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 3. Create two comments on this article
  const firstCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 4, wordMin: 3, wordMax: 10 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const firstComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: firstCommentBody,
      },
    );
  typia.assert(firstComment);

  const secondCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 5, wordMin: 3, wordMax: 10 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const secondComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: secondCommentBody,
      },
    );
  typia.assert(secondComment);

  // 4. Prepare an unauthenticated connection for public access
  const publicConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 5. Publicly get comment detail for the first comment
  const publicFirst: IDiscussionBoardComment =
    await api.functional.discussionBoard.articles.comments.at(
      publicConnection,
      {
        articleId: article.id,
        commentId: firstComment.id,
      },
    );
  typia.assert(publicFirst);

  TestValidator.equals(
    "public fetch of first comment returns same id",
    publicFirst.id,
    firstComment.id,
  );
  TestValidator.equals(
    "public fetch of first comment belongs to same article",
    publicFirst.article.id,
    article.id,
  );

  // 6. Publicly get comment detail for the second comment
  const publicSecond: IDiscussionBoardComment =
    await api.functional.discussionBoard.articles.comments.at(
      publicConnection,
      {
        articleId: article.id,
        commentId: secondComment.id,
      },
    );
  typia.assert(publicSecond);

  TestValidator.equals(
    "public fetch of second comment returns same id",
    publicSecond.id,
    secondComment.id,
  );
  TestValidator.equals(
    "public fetch of second comment belongs to same article",
    publicSecond.article.id,
    article.id,
  );

  // 7. Cross-article mismatch should not be found
  const secondArticleBody = typia.random<IDiscussionBoardArticle.ICreate>();
  const secondArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: secondArticleBody,
      },
    );
  typia.assert(secondArticle);

  const crossCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 10 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const crossArticleComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: secondArticle.id,
        body: crossCommentBody,
      },
    );
  typia.assert(crossArticleComment);

  await TestValidator.error(
    "cross-article articleId/commentId pair should not be retrievable",
    async () => {
      await api.functional.discussionBoard.articles.comments.at(
        publicConnection,
        {
          articleId: article.id,
          commentId: crossArticleComment.id,
        },
      );
    },
  );

  // 8. Random non-existing UUIDs should also result in error
  const randomArticleId = typia.random<string & tags.Format<"uuid">>();
  const randomCommentId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "random non-existing articleId/commentId should result in error",
    async () => {
      await api.functional.discussionBoard.articles.comments.at(
        publicConnection,
        {
          articleId: randomArticleId,
          commentId: randomCommentId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that a member user can create an article and then post a comment on
 * it.
 *
 * Business flow covered by this test:
 *
 * 1. Register a new discussion board member user via /auth/memberUser/join.
 * 2. As that authenticated member, create an article via
 *    /discussionBoard/memberUser/articles.
 * 3. As the same member, create a comment for the article via
 *    /discussionBoard/memberUser/articles/{articleId}/comments.
 * 4. Verify that the created comment reflects the request payload and is linked to
 *    the correct article summary.
 * 5. Verify that attempting to create a comment without authentication fails.
 */
export async function test_api_article_comment_creation_by_member(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authorized session
  const joinRequest = typia.random<IDiscussionBoardMemberUserJoin.IRequest>();

  const member: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(member);

  // 2. Create a new article as the authenticated member user
  const articleRequest = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    // In a real environment this should reference an existing category.
    // Here we use a random UUID; backend fixtures/config must ensure validity.
    categoryId: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleRequest,
      },
    );
  typia.assert(article);

  // Basic sanity checks on the created article
  TestValidator.equals(
    "article title should match request",
    article.title,
    articleRequest.title,
  );
  TestValidator.equals(
    "article body should match request",
    article.body,
    articleRequest.body,
  );

  // 3. Create a comment on the article as the same member user
  const commentRequest = {
    body: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentRequest,
      },
    );
  typia.assert(comment);

  // 4. Validate the created comment
  TestValidator.equals(
    "comment body should match request body",
    comment.body,
    commentRequest.body,
  );

  // Ensure the comment is linked to the correct article summary
  TestValidator.equals(
    "comment.article.id should match parent article id",
    comment.article.id,
    article.id,
  );

  // author_type should be a non-empty string, but we don't rely on a specific enum
  TestValidator.predicate(
    "comment author_type should be a non-empty string",
    typeof comment.author_type === "string" && comment.author_type.length > 0,
  );

  // Timestamps should be present; typia.assert has already validated date-time format
  TestValidator.predicate(
    "comment.created_at should be a non-empty string",
    typeof comment.created_at === "string" && comment.created_at.length > 0,
  );
  TestValidator.predicate(
    "comment.updated_at should be a non-empty string",
    typeof comment.updated_at === "string" && comment.updated_at.length > 0,
  );

  // 5. Negative test: creating a comment without authentication must fail
  const anonymousConnection: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated comment creation should fail",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.comments.create(
        anonymousConnection,
        {
          articleId: article.id,
          body: commentRequest,
        },
      );
    },
  );
}

