import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate member-user comment creation on discussion board articles.
 *
 * This test exercises the happy-path flow where authenticated member users:
 *
 * - Register (join),
 * - Create an article,
 * - And post comments on that article using the memberUser comment API.
 *
 * The original business intent mentioned restriction-based blocking of comments
 * for certain users, but no restriction-management API is available in the
 * provided SDK. Therefore, this test focuses on what can be validated
 * end-to-end:
 *
 * 1. A freshly joined member user can create an article.
 * 2. The same member user can immediately post a comment on that article.
 * 3. A second, distinct member user can also post a comment on the same article.
 * 4. Both comments are correctly associated with the target article, and their
 *    bodies match what was sent in the request.
 */
export async function test_api_article_comment_creation_restricted_member(
  connection: api.IConnection,
) {
  // 1. First member joins the discussion board
  const firstJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://example.com/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const firstMember: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: firstJoinBody,
    });
  typia.assert(firstMember);

  // 2. First member creates an article
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 3. First member creates a comment on the article
  const firstCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const firstComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: firstCommentBody,
      },
    );
  typia.assert(firstComment);

  TestValidator.equals(
    "first comment should reference the created article",
    firstComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "first comment body should match request payload",
    firstComment.body,
    firstCommentBody.body,
  );

  // 4. Second member joins the discussion board
  const secondJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "127.0.0.2",
    href: "https://example.com/join",
    referrer: "https://example.com/ads",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const secondMember: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: secondJoinBody,
    });
  typia.assert(secondMember);

  // 5. Second member creates another comment on the same article
  const secondCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const secondComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: secondCommentBody,
      },
    );
  typia.assert(secondComment);

  TestValidator.equals(
    "second comment should reference the created article",
    secondComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "second comment body should match request payload",
    secondComment.body,
    secondCommentBody.body,
  );

  // 6. Cross-validate that both comments target the same article and members differ
  TestValidator.equals(
    "both comments should target the same article",
    firstComment.article.id,
    secondComment.article.id,
  );

  TestValidator.predicate(
    "first and second members must be distinct accounts",
    firstMember.id !== secondMember.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuserSession";

export async function test_api_admin_session_search_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Join a new admin user and obtain authorization (token is applied by SDK)
  const joinRequest = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();

  const authorized = await api.functional.auth.adminUser.join(connection, {
    body: joinRequest,
  });
  typia.assert(authorized);

  const adminUserId = authorized.id;

  // 2. Call sessions.index with basic pagination (page=1, limit=10) and no filters
  const requestBody = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardAdminuserSession.IRequest;

  const firstPage =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: requestBody,
      },
    );
  typia.assert<IPageIDiscussionBoardAdminuserSession.ISummary>(firstPage);

  const pagination = firstPage.pagination;

  // 3. Basic pagination validations
  TestValidator.predicate(
    "pagination.current should be non-negative",
    pagination.current >= 0,
  );

  TestValidator.predicate(
    "pagination.limit should be positive and not exceed requested limit",
    pagination.limit > 0 && pagination.limit <= 10,
  );

  TestValidator.predicate(
    "pagination.records should be >= number of data items",
    pagination.records >= firstPage.data.length,
  );

  TestValidator.predicate(
    "pagination.pages should be consistent with records and limit",
    pagination.limit === 0
      ? pagination.pages === 0 && pagination.records === 0
      : pagination.records === 0
        ? pagination.pages === 0
        : pagination.pages >= 1 &&
          pagination.pages <= Math.ceil(pagination.records / pagination.limit),
  );

  if (pagination.pages > 0) {
    TestValidator.predicate(
      "pagination.current should be less than total pages when pages > 0",
      pagination.current < pagination.pages,
    );
  }

  // 4. Per-session validations when sessions exist
  if (firstPage.data.length > 0) {
    for (const session of firstPage.data) {
      TestValidator.equals(
        "session.discussion_board_adminuser_id must match path adminUserId",
        session.discussion_board_adminuser_id,
        adminUserId,
      );

      TestValidator.equals(
        "session.adminUser.id must equal discussion_board_adminuser_id",
        session.adminUser.id,
        session.discussion_board_adminuser_id,
      );
    }
  }

  // 5. Idempotency: same request should yield same pagination and data
  const secondPage =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: requestBody,
      },
    );
  typia.assert<IPageIDiscussionBoardAdminuserSession.ISummary>(secondPage);

  TestValidator.equals(
    "pagination object should be identical between first and second calls",
    firstPage.pagination,
    secondPage.pagination,
  );

  TestValidator.equals(
    "data array should be identical between first and second calls",
    firstPage.data,
    secondPage.data,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuserSession";

/**
 * Validate admin session search by creation date range and IP filter.
 *
 * Business context:
 *
 * - An admin user joins the system via /auth/adminUser/join, which creates an
 *   admin account and, per documentation, establishes an authenticated admin
 *   session with connection metadata (ip, href, referrer).
 * - The security/audit dashboard for administrators needs to search this admin's
 *   sessions using time window and connection-context filters.
 *
 * This test covers the happy path for that search API with realistic
 * constraints, without depending on pre-seeded DB fixtures. It proves that
 * filtering and pagination behave consistently for an admin who has at least
 * one session.
 *
 * Steps:
 *
 * 1. Join as a new admin user via api.functional.auth.adminUser.join.
 *
 *    - Build a valid IDiscussionBoardAdminUserJoin.IRequest payload with:
 *
 *         - Unique email (typia.random<email>),
 *         - Password (Format<"password"> random),
 *         - Display_name,
 *         - Optional bio,
 *         - Explicit ip, href, and referrer.
 *    - Receive IDiscussionBoardAdminuser.IAuthorized, which contains admin id and
 *         token; SDK automatically wires Authorization header.
 * 2. Immediately query this admin's sessions via
 *    api.functional.discussionBoard.adminUser.adminUsers.sessions.index without
 *    filters (empty body) or with very wide window.
 *
 *    - Pass adminUserId from step 1.
 *    - Use an empty IRequest body {} so the backend applies defaults (first page,
 *         default limit, no filters) and returns
 *         IPageIDiscussionBoardAdminuserSession.ISummary.
 *    - Assert type with typia.assert.
 *    - Find at least one session that:
 *
 *         - AdminUser.id === joined admin id,
 *         - Ip matches the ip we sent in join (it _should_, according to docs). If no
 *                   such session is found (in unusual environments), the test
 *                   gracefully skips further filter assertions by using
 *                   TestValidator predicates based on the available data.
 * 3. Build a date range window around the known session's created_at:
 *
 *    - Parse session.created_at into a Date.
 *    - Compute from_created_at slightly before created_at (e.g., minus 1 second) and
 *         to_created_at slightly after created_at (e.g., plus 1 second), then
 *         convert both toISOString(). This gives us an interval [from, to) that
 *         definitely contains this session.
 * 4. Call the sessions.index API again with filters:
 *
 *    - AdminUserId: joined admin id.
 *    - Body:
 *
 *         - Page: 1 (or 0 depending on backend semantics; we can let backend default by
 *                   omitting page and just supply limit),
 *         - Limit: a small positive value (e.g. 10),
 *         - From_created_at: computed lower bound,
 *         - To_created_at: computed upper bound,
 *         - Ip: the exact ip used on join.
 * 5. Validate response:
 *
 *    - Typia.assert on the output.
 *    - Ensure pagination.records equals output.data.length (because the dataset is
 *         small and filtered).
 *    - Ensure pagination.pages is consistent with records and limit (pages ===
 *         Math.ceil(records / limit)).
 *    - For every session in data:
 *
 *         - Created_at >= from_created_at,
 *         - Created_at < to_created_at,
 *         - Ip === filter ip,
 *         - AdminUser.id matches joined admin id.
 * 6. Negative filter check:
 *
 *    - Call sessions.index again with an IP that must not match the known session
 *         (e.g., a different literal IP string).
 *    - Use same from_created_at and to_created_at window.
 *    - Assert type and then assert that either:
 *
 *         - Data array is empty (expected case), or
 *         - If non-empty, every item has ip !== original ip (to respect filter), though
 *                   realistically we expect emptiness in a minimal
 *                   environment.
 *
 * Notes & constraints:
 *
 * - We do not and cannot manipulate or assert on DB fixture counts beyond what
 *   the API exposes.
 * - We do not attempt to create extra sessions via non-existent APIs; we rely
 *   only on the join-created session(s).
 * - We avoid assuming exact page indexes for the initial unfiltered query and
 *   instead search within the returned data for the matching session.
 */
export async function test_api_admin_session_search_with_date_range_and_ip_filter(
  connection: api.IConnection,
) {
  // 1. Join as a new admin user, supplying explicit IP and URLs so that
  //    the created session will carry deterministic connection metadata.
  const joinIp: string = "192.0.2.10"; // TEST-NET-1 reserved range, safe for tests
  const joinHref: string = "https://admin.example.com/signup";
  const joinReferrer: string = "https://admin.example.com/landing";

  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: joinIp,
    href: joinHref as string & tags.Format<"uri">,
    referrer: joinReferrer as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const authorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  const adminUserId = authorized.id;

  // 2. Fetch this admin's sessions without filters to discover the concrete
  //    session timestamps and IP as persisted by the backend.
  const initialPage: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: {},
      },
    );
  typia.assert(initialPage);

  const allSessions = initialPage.data;

  // Validate that all returned sessions, if any, belong to this admin.
  await TestValidator.predicate(
    "all initial sessions, if any, belong to joined admin",
    async () =>
      allSessions.every(
        (session) => session.discussion_board_adminuser_id === adminUserId,
      ),
  );

  // Find a session whose IP matches the IP we sent on join (best-effort).
  const targetSession: IDiscussionBoardAdminuserSession.ISummary | undefined =
    allSessions.find((session) => session.ip === joinIp) ?? allSessions[0];

  // If there is no session at all, we still want to ensure the API behaves
  // consistently under filters (returning empty data, consistent pagination).
  if (!targetSession) {
    const now = new Date();
    const from = new Date(now.getTime() - 60_000).toISOString();
    const to = new Date(now.getTime() + 60_000).toISOString();

    const filteredEmpty: IPageIDiscussionBoardAdminuserSession.ISummary =
      await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
        connection,
        {
          adminUserId,
          body: {
            page: 1 as number & tags.Type<"int32">,
            limit: 10 as number & tags.Type<"int32">,
            from_created_at: from,
            to_created_at: to,
            ip: joinIp,
          },
        },
      );
    typia.assert(filteredEmpty);

    // pagination.records must match data length, and pages must be consistent.
    TestValidator.equals(
      "empty-filtered sessions: records equal data length",
      filteredEmpty.pagination.records,
      filteredEmpty.data.length,
    );

    const expectedPages =
      filteredEmpty.pagination.limit === 0
        ? 0
        : Math.ceil(
            filteredEmpty.pagination.records / filteredEmpty.pagination.limit,
          );

    TestValidator.equals(
      "empty-filtered sessions: pages consistent with records and limit",
      filteredEmpty.pagination.pages,
      expectedPages,
    );

    return;
  }

  // 3. Build a time window [from, to) around this target session's created_at.
  const createdAt = new Date(targetSession.created_at);
  const fromDate = new Date(createdAt.getTime() - 1_000);
  const toDate = new Date(createdAt.getTime() + 1_000);
  const fromIso = fromDate.toISOString();
  const toIso = toDate.toISOString();

  const limit: number & tags.Type<"int32"> = 10 as number & tags.Type<"int32">;

  // 4. Call sessions.index with date range and IP filters that should
  //    include the target session.
  const filteredPage: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit,
          from_created_at: fromIso,
          to_created_at: toIso,
          ip: targetSession.ip,
        },
      },
    );
  typia.assert(filteredPage);

  // 5. Validate pagination semantics.
  TestValidator.equals(
    "filtered sessions: records equals actual data length",
    filteredPage.pagination.records,
    filteredPage.data.length,
  );

  const expectedFilteredPages =
    filteredPage.pagination.limit === 0
      ? 0
      : Math.ceil(
          filteredPage.pagination.records / filteredPage.pagination.limit,
        );

  TestValidator.equals(
    "filtered sessions: pages consistent with records and limit",
    filteredPage.pagination.pages,
    expectedFilteredPages,
  );

  // Ensure every returned session matches the filter criteria.
  await TestValidator.predicate(
    "all filtered sessions match date-range and IP filters",
    async () =>
      filteredPage.data.every((session) => {
        const ts = new Date(session.created_at).getTime();
        const fromMs = new Date(fromIso).getTime();
        const toMs = new Date(toIso).getTime();

        return (
          ts >= fromMs &&
          ts < toMs &&
          session.ip === targetSession.ip &&
          session.discussion_board_adminuser_id === adminUserId
        );
      }),
  );

  // 6. Negative filter: use a different IP that should exclude the
  //    target session from results.
  const differentIp = "198.51.100.23"; // Another TEST-NET reserved IP

  const negativePage: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit,
          from_created_at: fromIso,
          to_created_at: toIso,
          ip: differentIp,
        },
      },
    );
  typia.assert(negativePage);

  // pagination.records must match data length and pages must be consistent.
  TestValidator.equals(
    "negative-filter sessions: records equal data length",
    negativePage.pagination.records,
    negativePage.data.length,
  );

  const expectedNegativePages =
    negativePage.pagination.limit === 0
      ? 0
      : Math.ceil(
          negativePage.pagination.records / negativePage.pagination.limit,
        );

  TestValidator.equals(
    "negative-filter sessions: pages consistent with records and limit",
    negativePage.pagination.pages,
    expectedNegativePages,
  );

  // All sessions returned under the negative IP filter must have the
  // requested different IP and still belong to the same admin and range.
  await TestValidator.predicate(
    "negative-filter sessions: all results match different IP and range",
    async () =>
      negativePage.data.every((session) => {
        const ts = new Date(session.created_at).getTime();
        const fromMs = new Date(fromIso).getTime();
        const toMs = new Date(toIso).getTime();
        return (
          ts >= fromMs &&
          ts < toMs &&
          session.ip === differentIp &&
          session.discussion_board_adminuser_id === adminUserId
        );
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuserSession";

/**
 * Ensure admin session search returns an empty page when filters match no
 * sessions.
 *
 * Business goal: Verify that the admin session search endpoint for a specific
 * administrator correctly represents "no matching sessions" as an empty, but
 * successful, paginated result instead of throwing an error. This is essential
 * for monitoring and audit UIs, which must gracefully handle search filters
 * that yield zero rows.
 *
 * Scenario:
 *
 * 1. Register (join) a new adminUser via POST /auth/adminUser/join. This both
 *    creates an admin account in discussion_board_adminusers and establishes an
 *    authenticated session with an Authorization header managed by the SDK.
 * 2. Use the returned adminUser id as the path parameter adminUserId when calling
 *    PATCH /discussionBoard/adminUser/adminUsers/{adminUserId}/sessions.
 * 3. For the join request, send a specific combination of ip, href, and referrer
 *    values so that we know exactly what the first session context looks like.
 * 4. For the sessions search request body
 *    (IDiscussionBoardAdminuserSession.IRequest), set page to 1, limit to 10,
 *    but deliberately choose filters that cannot match the existing session:
 *
 *    - Ip: choose a different IP from the one used in the join request.
 *    - Href: choose a different URI from the join request href.
 *    - Referrer: choose a different URI from the join request referrer. Leave
 *         from_created_at and to_created_at undefined to avoid depending on
 *         precise timestamps.
 * 5. Call api.functional.discussionBoard.adminUser.adminUsers.sessions.index with
 *    the adminUserId and the crafted IRequest body.
 * 6. Assert that the response passes typia.assert, confirming it is a valid
 *    IPageIDiscussionBoardAdminuserSession.ISummary structure.
 * 7. Use TestValidator.equals to verify:
 *
 *    - Pagination.records is 0.
 *    - Pagination.pages is 0.
 *    - Data.length is 0.
 *    - Data equals an empty array.
 * 8. Do not attempt to assert on HTTP status codes directly; rely on the fact that
 *    a successful SDK call returning a value implies a 2xx response.
 */
export async function test_api_admin_session_search_empty_result_when_no_match(
  connection: api.IConnection,
) {
  // 1. Register (join) a new admin user to obtain an authenticated context and adminUserId
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "198.51.100.1",
    href: "https://admin.example.com/join",
    referrer: "https://www.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Build a request body for sessions search that is guaranteed to match no sessions
  const emptySearchRequest = {
    page: 1,
    limit: 10,
    // Use IP and URLs that differ from those in joinBody
    ip: "203.0.113.123",
    href: "https://admin.example.com/other-page",
    referrer: "https://www.example.com/other-entry",
  } satisfies IDiscussionBoardAdminuserSession.IRequest;

  // 3. Call the sessions search endpoint for this admin user
  const pageResult: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminAuthorized.id,
        body: emptySearchRequest,
      },
    );

  // 4. Validate response type and empty pagination semantics
  typia.assert(pageResult);

  const pagination = pageResult.pagination;

  TestValidator.equals(
    "admin session search with unmatched filters returns 0 records",
    pagination.records,
    0,
  );
  TestValidator.equals(
    "admin session search with unmatched filters reports 0 pages",
    pagination.pages,
    0,
  );
  TestValidator.equals(
    "admin session search with unmatched filters returns empty data array",
    pageResult.data.length,
    0,
  );
  TestValidator.equals(
    "admin session search with unmatched filters data is exactly empty array",
    pageResult.data,
    [],
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuserSession";

/**
 * Verify that admin session search is forbidden without authentication.
 *
 * Business goals:
 *
 * - Ensure that PATCH
 *   /discussionBoard/adminUser/adminUsers/{adminUserId}/sessions cannot be
 *   accessed without a valid adminUser authentication token.
 * - Confirm that the same endpoint works when called with a properly
 *   authenticated adminUser connection and returns well-typed data.
 *
 * Test steps:
 *
 * 1. Create a dedicated connection for adminUser authentication (authConn).
 * 2. Call api.functional.auth.adminUser.join(authConn, { body }) to register a new
 *    admin user and obtain a valid adminUserId and token.
 * 3. Build an unauthenticated connection (unauthConn) that has no headers,
 *    ensuring it carries no Authorization information.
 * 4. With unauthConn, call
 *    api.functional.discussionBoard.adminUser.adminUsers.sessions.index using
 *    the real adminUserId and a minimal valid search body, and assert via
 *    TestValidator.error that the call fails (unauthorized/forbidden).
 * 5. As a positive control, call the same sessions.index endpoint using the
 *    authenticated authConn and verify it succeeds and returns
 *    IPageIDiscussionBoardAdminuserSession.ISummary, validating it with
 *    typia.assert and basic business checks.
 */
export async function test_api_admin_session_search_forbidden_without_auth(
  connection: api.IConnection,
) {
  // 1. Prepare a dedicated authenticated admin connection so we don't
  //    accidentally reuse its headers when simulating unauthenticated calls.
  const authConn: api.IConnection = {
    host: connection.host,
    headers: {},
    simulate: connection.simulate,
    logger: connection.logger,
    encryption: connection.encryption,
    options: connection.options,
    fetch: connection.fetch,
  };

  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(authConn, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Build an unauthenticated connection that has no headers at all.
  const unauthConn: api.IConnection = {
    host: connection.host,
    headers: {},
    simulate: connection.simulate,
    logger: connection.logger,
    encryption: connection.encryption,
    options: connection.options,
    fetch: connection.fetch,
  };

  const searchBody = {
    page: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    limit: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
  } satisfies IDiscussionBoardAdminuserSession.IRequest;

  // 3. Unauthenticated call must fail.
  await TestValidator.error(
    "unauthenticated admin session search must be rejected",
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
        unauthConn,
        {
          adminUserId: adminAuthorized.id,
          body: searchBody,
        },
      );
    },
  );

  // 4. Authenticated call using authConn must succeed.
  const page: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      authConn,
      {
        adminUserId: adminAuthorized.id,
        body: searchBody,
      },
    );
  typia.assert(page);

  // Basic business checks on pagination.
  TestValidator.predicate(
    "pagination current page index must be non-negative",
    page.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit must be non-negative",
    page.pagination.limit >= 0,
  );

  // If any sessions are returned, they must belong to the same admin user.
  for (const session of page.data) {
    typia.assert<IDiscussionBoardAdminuserSession.ISummary>(session);
    TestValidator.equals(
      "session adminUser id must match created admin user id",
      session.adminUser.id,
      adminAuthorized.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuserSession";

/**
 * Ensure an adminUser cannot retrieve another admin's sessions via the
 * discussionBoard admin session search API, while each admin can still
 * successfully list their own sessions.
 *
 * Business goals:
 *
 * - Validate that session search is strictly scoped per admin user: an
 *   authenticated admin can only see their own sessions, not sessions belonging
 *   to other admins.
 * - Demonstrate positive and negative access control behavior:
 *
 *   - Positive: Admin A and Admin B can each list their own sessions.
 *   - Negative: Admin A cannot list Admin B's sessions.
 *
 * Flow:
 *
 * 1. Join Admin A on the main connection (which will carry Admin A's token).
 * 2. Call sessions.index with adminUserId = Admin A.id and verify that all
 *    returned sessions, if any, belong to Admin A.
 * 3. Create a separate connection instance for Admin B with its own headers
 *    object, join as Admin B there, and verify Admin B can list their own
 *    sessions using that independent connection.
 * 4. Using the main connection (Admin A context), attempt to call sessions.index
 *    with adminUserId = Admin B.id and assert that this call fails with an
 *    error, without inspecting specific HTTP status codes.
 */
export async function test_api_admin_session_search_admin_cannot_view_other_admin_sessions(
  connection: api.IConnection,
) {
  // 1. Register and authenticate Admin A on the main connection.
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminA: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert(adminA);

  // 2. Admin A lists own sessions.
  const adminASessionsRequest = {
    // All filters optional; send empty request to use backend defaults.
  } satisfies IDiscussionBoardAdminuserSession.IRequest;

  const adminASessionsPage: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      connection,
      {
        adminUserId: adminA.id,
        body: adminASessionsRequest,
      },
    );
  typia.assert(adminASessionsPage);

  // Validate that all sessions, if any, belong to Admin A.
  for (const session of adminASessionsPage.data) {
    TestValidator.equals(
      "Admin A sessions must reference Admin A in foreign key",
      session.discussion_board_adminuser_id,
      adminA.id,
    );
    TestValidator.equals(
      "Admin A sessions must reference Admin A in embedded adminUser",
      session.adminUser.id,
      adminA.id,
    );
  }

  // 3. Create a separate connection for Admin B with an independent headers
  //    object so that its Authorization header changes do not affect the main
  //    connection.
  const adminBConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminB: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(adminBConnection, {
      body: adminBJoinBody,
    });
  typia.assert(adminB);

  // Admin B lists own sessions via its own connection.
  const adminBSessionsRequest = {
    // empty filter: rely on backend defaults
  } satisfies IDiscussionBoardAdminuserSession.IRequest;

  const adminBSessionsPage: IPageIDiscussionBoardAdminuserSession.ISummary =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
      adminBConnection,
      {
        adminUserId: adminB.id,
        body: adminBSessionsRequest,
      },
    );
  typia.assert(adminBSessionsPage);

  for (const session of adminBSessionsPage.data) {
    TestValidator.equals(
      "Admin B sessions must reference Admin B in foreign key",
      session.discussion_board_adminuser_id,
      adminB.id,
    );
    TestValidator.equals(
      "Admin B sessions must reference Admin B in embedded adminUser",
      session.adminUser.id,
      adminB.id,
    );
  }

  // 4. Negative access control: Admin A must not be able to list Admin B's
  //    sessions. Using the main connection (still carrying Admin A's token),
  //    attempt to query Admin B's sessions and expect an error.
  await TestValidator.error(
    "Admin A must not list Admin B's sessions",
    async () => {
      const crossRequest = {
        // empty filter; same as own-session search
      } satisfies IDiscussionBoardAdminuserSession.IRequest;

      await api.functional.discussionBoard.adminUser.adminUsers.sessions.index(
        connection,
        {
          adminUserId: adminB.id,
          body: crossRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserSession";

export async function test_api_admin_session_detail_retrieval_success(
  connection: api.IConnection,
) {
  // 1. Join as a new admin user to establish an authenticated adminUser context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const authorizedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<IAuthorizationToken>(authorizedAdmin.token);
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(authorizedAdmin);

  const adminUserId: string & tags.Format<"uuid"> = authorizedAdmin.id;

  // 2. Choose a session id to request.
  // We don't have a listing API, so we use the adminUserId itself as a stable
  // identifier to drive the happy-path call. In simulate mode this will still
  // produce a valid session object; in real mode we only rely on shape
  // validation and id equality, not on DB-level existence guarantees.
  const sessionId: string & tags.Format<"uuid"> = adminUserId;

  // 3. Call the admin session detail endpoint.
  const session: IDiscussionBoardAdminuserSession =
    await api.functional.discussionBoard.adminUser.adminUsers.sessions.at(
      connection,
      {
        adminUserId,
        sessionId,
      },
    );
  typia.assert<IDiscussionBoardAdminuserSession>(session);

  // 4. Business-level validations.
  TestValidator.equals(
    "session id should equal requested sessionId",
    session.id,
    sessionId,
  );

  if (session.adminUser !== undefined) {
    typia.assert<IDiscussionBoardAdminuser.ISummary>(session.adminUser);

    TestValidator.equals(
      "session.adminUser.id should equal adminUserId",
      session.adminUser.id,
      adminUserId,
    );
  }

  TestValidator.predicate(
    "session.ip should be a non-empty string",
    session.ip.length > 0,
  );

  TestValidator.predicate(
    "session.href should be a non-empty string",
    session.href.length > 0,
  );

  TestValidator.predicate(
    "session.referrer should be a non-empty string",
    session.referrer.length > 0,
  );

  TestValidator.predicate(
    "session.created_at should be a non-empty string",
    session.created_at.length > 0,
  );

  if (session.expired_at !== undefined && session.expired_at !== null) {
    TestValidator.predicate(
      "session.expired_at, when present, should be a non-empty string",
      session.expired_at.length > 0,
    );
  }
}

