import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserRestriction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserRestriction";

export async function test_api_admin_prevent_duplicate_member_restriction(
  connection: api.IConnection,
) {
  // 1. Register a discussionBoard member user to be restricted later
  const memberJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "203.0.113.10",
    href: "https://frontend.example.com/join/member",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  // Capture the member user's UUID for restriction operations
  const memberUserId = memberAuthorized.id;

  // 2. Register an administrative user (adminUser actor) and become authenticated as admin
  const adminJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(20) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "198.51.100.20",
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminAuthorized);

  // 3. Create the initial restriction for this member user as the admin
  const firstRestrictionBody = {
    restriction_level: "posting_restriction",
    reason_category: "initial_test_restriction",
    started_at: new Date().toISOString(),
    ended_at: null,
  } satisfies IDiscussionBoardMemberuserRestriction.ICreate;

  const firstRestriction: IDiscussionBoardMemberuserRestriction =
    await api.functional.discussionBoard.adminUser.memberUsers.restriction.create(
      connection,
      {
        memberUserId,
        body: firstRestrictionBody,
      },
    );
  typia.assert(firstRestriction);

  // Validate that the created restriction is associated with the correct member
  TestValidator.equals(
    "created restriction is linked to the target member user",
    firstRestriction.memberUser.id,
    memberUserId,
  );

  // 4. Attempt to create a second restriction for the same member user
  const secondRestrictionBody = {
    restriction_level: "full_block",
    reason_category: "duplicate_creation_attempt",
    started_at: new Date(Date.now() + 60_000).toISOString(),
    ended_at: null,
  } satisfies IDiscussionBoardMemberuserRestriction.ICreate;

  await TestValidator.error(
    "creating a second restriction for the same member user must fail",
    async () => {
      await api.functional.discussionBoard.adminUser.memberUsers.restriction.create(
        connection,
        {
          memberUserId,
          body: secondRestrictionBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserRestriction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserRestriction";

/**
 * Validate that an admin cannot create a restriction for a non-existent member
 * user.
 *
 * ## Business intent
 *
 * This test ensures that the moderation endpoint for creating
 * `discussion_board_memberuser_restrictions` enforces the invariant that a
 * restriction can only be attached to an existing member user account. Even
 * when an administrator is properly authenticated and provides a syntactically
 * valid restriction payload, if the `memberUserId` path parameter does not
 * correspond to any row in `discussion_board_memberusers.id`, the service must
 * reject the request and avoid persisting any restriction row.
 *
 * ## Covered workflow
 *
 * 1. Register a fresh admin user via POST /auth/adminUser/join. This both creates
 *    the admin row in `discussion_board_adminusers` and establishes an
 *    authenticated `adminUser` session, wiring the connection's `Authorization`
 *    header through the SDK.
 * 2. Generate a random UUID value that will be treated as a non-existent member
 *    user identifier in the scope of this test. Because we never create any
 *    discussion_board_memberusers record here, any UUID is effectively invalid
 *    for the target endpoint.
 * 3. Build a syntactically valid `IDiscussionBoardMemberuserRestriction.ICreate`
 *    payload with:
 *
 *    - A non-empty `restriction_level` such as `"full_block"`,
 *    - A non-empty `reason_category` such as `"spam_advertising"`,
 *    - `started_at` set to the current timestamp in ISO 8601 (`date-time`) format,
 *    - And `ended_at` explicitly set to `null` to represent an ongoing restriction.
 * 4. As the authenticated admin user, invoke POST
 *    /discussionBoard/adminUser/memberUsers/{memberUserId}/restriction through
 *    `api.functional.discussionBoard.adminUser.memberUsers.restriction.create`
 *    using the invalid `memberUserId` and the valid body inside
 *    `TestValidator.error`, asserting that the call fails.
 * 5. Because the SDK surface exposed to this test does not provide any listing or
 *    lookup endpoints for restrictions or member users, we interpret the fact
 *    that the create call throws an error (instead of returning a normal
 *    `IDiscussionBoardMemberuserRestriction` object) as evidence that no
 *    restriction row has been created for the bogus identifier.
 *
 * ## What this test validates
 *
 * - Administrative authentication works for the join endpoint and yields a valid
 *   `IDiscussionBoardAdminuser.IAuthorized` object with tokens.
 * - The restriction creation endpoint rejects attempts to create a restriction
 *   for a memberUserId that does not exist in `discussion_board_memberusers`.
 * - The endpoint enforces the business rule that restrictions can only be
 *   attached to existing member users, and that invalid foreign keys result in
 *   an error instead of silent creation.
 */
export async function test_api_admin_create_member_restriction_for_invalid_member(
  connection: api.IConnection,
) {
  // 1. Register a fresh admin user and establish an authenticated admin session.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Prepare a UUID that does not correspond to any existing member user
  //    within this test scope.
  const nonExistentMemberUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. Build a syntactically valid restriction creation payload.
  const restrictionCreateBody = {
    restriction_level: "full_block",
    reason_category: "spam_advertising",
    started_at: new Date().toISOString(),
    ended_at: null,
  } satisfies IDiscussionBoardMemberuserRestriction.ICreate;

  // 4. Attempt to create the restriction and assert that it fails.
  await TestValidator.error(
    "creating restriction for non-existent member should fail",
    async () => {
      await api.functional.discussionBoard.adminUser.memberUsers.restriction.create(
        connection,
        {
          memberUserId: nonExistentMemberUserId,
          body: restrictionCreateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuestuser";

export async function test_api_admin_guest_user_search_with_date_and_token_filters(
  connection: api.IConnection,
) {
  /**
   * 1. Register and authenticate an adminUser via POST /auth/adminUser/join
   *
   *    - Use realistic random email, password, display_name, href, referrer.
   *    - The SDK will set connection.headers.Authorization with the issued access
   *         token, so subsequent calls run as this adminUser.
   */
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "203.0.113.10",
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  /**
   * 2. Perform an initial guest user search as admin without anonymous_token
   *    filter, but with a broad date range and explicit pagination.
   */
  const broadFrom = "2000-01-01T00:00:00.000Z" as string &
    tags.Format<"date-time">;
  const broadTo = "2100-01-01T00:00:00.000Z" as string &
    tags.Format<"date-time">;

  const initialRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "created_at" as const,
    order_direction: "asc" as const,
    created_from: broadFrom,
    created_to: broadTo,
    updated_from: null,
    updated_to: null,
    deleted_from: null,
    deleted_to: null,
    anonymous_token: null,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const initialPage: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: initialRequestBody,
      },
    );
  typia.assert(initialPage);

  const initialPagination: IPage.IPagination = initialPage.pagination;
  typia.assert(initialPagination);

  // Validate basic pagination coherence for the initial search.
  TestValidator.predicate(
    "initial pagination current page is non-negative",
    initialPagination.current >= 0,
  );
  TestValidator.predicate(
    "initial pagination limit is non-negative",
    initialPagination.limit >= 0,
  );
  TestValidator.predicate(
    "initial pagination records is non-negative",
    initialPagination.records >= 0,
  );
  TestValidator.predicate(
    "initial pagination pages is non-negative",
    initialPagination.pages >= 0,
  );

  // If there are no guest users, we cannot test token-based filtering; just
  // ensure that the data array is empty and pagination matches this fact.
  if (initialPage.data.length === 0) {
    TestValidator.equals(
      "when no guest users, records should be 0",
      initialPagination.records,
      0,
    );
    TestValidator.equals(
      "when no guest users, pages should be 0",
      initialPagination.pages,
      0,
    );
    TestValidator.equals(
      "when no guest users, data length should be 0",
      initialPage.data.length,
      0,
    );
    return;
  }

  // Basic relation between records, pages, and limit when there is at least
  // one record. We avoid strict equality because backend may clamp pages.
  TestValidator.predicate(
    "records greater than 0 when data is non-empty",
    initialPagination.records > 0,
  );
  TestValidator.predicate(
    "pages greater than 0 when data is non-empty",
    initialPagination.pages > 0,
  );

  /**
   * 3. Derive an anonymous_token and narrow created_at range from a sample guest
   *    summary to construct a precise filtered search.
   */
  const sampleGuest: IDiscussionBoardGuestUser.ISummary = initialPage.data[0];
  typia.assert(sampleGuest);

  const tokenToFilter: string = sampleGuest.anonymous_token;
  const createdAtSample: string & tags.Format<"date-time"> =
    sampleGuest.created_at;

  const filteredRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "created_at" as const,
    order_direction: "asc" as const,
    created_from: createdAtSample,
    created_to: createdAtSample,
    updated_from: null,
    updated_to: null,
    deleted_from: null,
    deleted_to: null,
    anonymous_token: tokenToFilter,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const filteredPage: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: filteredRequestBody,
      },
    );
  typia.assert(filteredPage);

  const filteredPagination: IPage.IPagination = filteredPage.pagination;
  typia.assert(filteredPagination);

  // Validate filtered pagination coherence.
  TestValidator.predicate(
    "filtered pagination current page is non-negative",
    filteredPagination.current >= 0,
  );
  TestValidator.predicate(
    "filtered pagination limit is non-negative",
    filteredPagination.limit >= 0,
  );
  TestValidator.predicate(
    "filtered pagination records is non-negative",
    filteredPagination.records >= 0,
  );
  TestValidator.predicate(
    "filtered pagination pages is non-negative",
    filteredPagination.pages >= 0,
  );

  // For every returned guest summary, assert that:
  // - anonymous_token equals the filter token
  // - created_at is within [created_from, created_to]
  for (const guest of filteredPage.data) {
    typia.assert(guest);

    TestValidator.equals(
      "guest anonymous_token matches filter",
      guest.anonymous_token,
      tokenToFilter,
    );

    const createdAtValue: string & tags.Format<"date-time"> = guest.created_at;

    TestValidator.predicate(
      "guest created_at is >= created_from",
      createdAtValue >= filteredRequestBody.created_from!,
    );
    TestValidator.predicate(
      "guest created_at is <= created_to",
      createdAtValue <= filteredRequestBody.created_to!,
    );
  }

  /**
   * 4. Verify that only adminUser can perform guest user search by attempting the
   *    same search with an unauthenticated connection, expecting an error.
   */
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "guest user search should require admin auth",
    async () => {
      await api.functional.discussionBoard.adminUser.guestUsers.index(
        unauthConnection,
        {
          body: filteredRequestBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuestuser";

/**
 * Validate admin guest user search by lifecycle deletion state.
 *
 * Business goal:
 *
 * - Ensure an authenticated adminUser can call the guest user search endpoint
 *   with different deleted_at range filters, and that the API returns
 *   type-safe, paginated guest user summaries whose lifecycle-related
 *   timestamps behave consistently.
 *
 * High-level steps:
 *
 * 1. Register a new admin user via POST /auth/adminUser/join.
 * 2. With the authenticated admin connection, call PATCH
 *    /discussionBoard/adminUser/guestUsers twice: a. Once with deleted_from and
 *    deleted_to explicitly set to null to represent an "unconstrained" or
 *    "active/all" view. b. Once with deleted_from set to a far-past timestamp
 *    and deleted_to set to now, to represent an explicit range for logically
 *    deleted guests.
 * 3. For each search call, assert type correctness and basic pagination
 *    invariants, and perform lifecycle consistency checks on timestamps.
 *
 * Notes:
 *
 * - The test does not create or delete guest users directly because the provided
 *   API surface exposes only a search endpoint for guest users. It assumes that
 *   appropriate guest user fixtures already exist in the test environment.
 * - The test focuses on invariants that can be validated purely from the returned
 *   data: pagination structure, deleted_at range inclusion for non-null values,
 *   and created_at/updated_at ordering.
 */
export async function test_api_admin_guest_user_search_by_lifecycle_state(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin user
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorized);

  // 2. Prepare common pagination and ordering options
  const requestedPage = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const requestedLimit = 20 as number & tags.Type<"int32"> & tags.Minimum<1>;

  // 3. First search: deleted_from and deleted_to explicitly null
  const firstSearchBody = {
    page: requestedPage,
    limit: requestedLimit,
    order_by: "created_at" as const,
    order_direction: "asc" as const,
    created_from: null,
    created_to: null,
    updated_from: null,
    updated_to: null,
    deleted_from: null,
    deleted_to: null,
    anonymous_token: null,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const firstPage: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: firstSearchBody,
      },
    );
  typia.assert<IPageIDiscussionBoardGuestuser.ISummary>(firstPage);

  // 3-1. Validate pagination metadata for the first search
  const firstPagination = firstPage.pagination;
  TestValidator.predicate(
    "first search: pagination current is non-negative",
    firstPagination.current >= 0,
  );
  TestValidator.predicate(
    "first search: pagination limit is positive",
    firstPagination.limit > 0,
  );
  TestValidator.predicate(
    "first search: records is not negative",
    firstPagination.records >= 0,
  );
  TestValidator.predicate(
    "first search: pages is not negative",
    firstPagination.pages >= 0,
  );
  TestValidator.predicate(
    "first search: data length does not exceed limit",
    firstPage.data.length <= firstPagination.limit,
  );
  TestValidator.predicate(
    "first search: records greater or equal to data length",
    firstPagination.records >= firstPage.data.length,
  );
  TestValidator.predicate(
    "first search: zero records imply zero pages and empty data",
    firstPagination.records === 0
      ? firstPagination.pages === 0 && firstPage.data.length === 0
      : true,
  );

  // 3-2. Lifecycle sanity checks on returned guest summaries (no strict
  // assumptions beyond type correctness here)
  for (const guest of firstPage.data) {
    // created_at and updated_at should be valid date-time strings; typia.assert
    // already guarantees the format, but we additionally check logical ordering
    const createdAt = new Date(guest.created_at).getTime();
    const updatedAt = new Date(guest.updated_at).getTime();
    TestValidator.predicate(
      "first search: updated_at is not earlier than created_at",
      !Number.isNaN(createdAt) &&
        !Number.isNaN(updatedAt) &&
        updatedAt >= createdAt,
    );
  }

  // 4. Second search: deleted_at range covering wide historical window
  const deletedFrom = new Date("2000-01-01T00:00:00.000Z").toISOString();
  const deletedTo = new Date().toISOString();

  const secondSearchBody = {
    page: requestedPage,
    limit: requestedLimit,
    order_by: "deleted_at" as const,
    order_direction: "asc" as const,
    created_from: null,
    created_to: null,
    updated_from: null,
    updated_to: null,
    deleted_from: deletedFrom,
    deleted_to: deletedTo,
    anonymous_token: null,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const secondPage: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: secondSearchBody,
      },
    );
  typia.assert<IPageIDiscussionBoardGuestuser.ISummary>(secondPage);

  // 4-1. Validate pagination metadata for the second search
  const secondPagination = secondPage.pagination;
  TestValidator.predicate(
    "second search: pagination current is non-negative",
    secondPagination.current >= 0,
  );
  TestValidator.predicate(
    "second search: pagination limit is positive",
    secondPagination.limit > 0,
  );
  TestValidator.predicate(
    "second search: records is not negative",
    secondPagination.records >= 0,
  );
  TestValidator.predicate(
    "second search: pages is not negative",
    secondPagination.pages >= 0,
  );
  TestValidator.predicate(
    "second search: data length does not exceed limit",
    secondPage.data.length <= secondPagination.limit,
  );
  TestValidator.predicate(
    "second search: records greater or equal to data length",
    secondPagination.records >= secondPage.data.length,
  );
  TestValidator.predicate(
    "second search: zero records imply zero pages and empty data",
    secondPagination.records === 0
      ? secondPagination.pages === 0 && secondPage.data.length === 0
      : true,
  );

  // 4-2. For each guest with non-null deleted_at, ensure it lies within
  // [deletedFrom, deletedTo] and respect lifecycle ordering with created_at
  const deletedFromTime = new Date(deletedFrom).getTime();
  const deletedToTime = new Date(deletedTo).getTime();

  for (const guest of secondPage.data) {
    const createdAt = new Date(guest.created_at).getTime();
    const updatedAt = new Date(guest.updated_at).getTime();
    TestValidator.predicate(
      "second search: updated_at is not earlier than created_at",
      !Number.isNaN(createdAt) &&
        !Number.isNaN(updatedAt) &&
        updatedAt >= createdAt,
    );

    if (guest.deleted_at !== null && guest.deleted_at !== undefined) {
      const deletedAtTime = new Date(guest.deleted_at).getTime();
      TestValidator.predicate(
        "second search: deleted_at within requested range when non-null",
        !Number.isNaN(deletedAtTime) &&
          deletedAtTime >= deletedFromTime &&
          deletedAtTime <= deletedToTime,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuestuser";

/**
 * Validate ordering and pagination for admin guest user search.
 *
 * Business goal: ensure that the administrative guest-user listing endpoint
 * (PATCH /discussionBoard/adminUser/guestUsers) correctly applies ordering by
 * created_at and updated_at fields, and that pagination metadata and cross-page
 * slicing behave consistently for an authenticated adminUser.
 *
 * Scenario:
 *
 * 1. Register a new adminUser via POST /auth/adminUser/join. This both creates an
 *    admin record and configures the connection with the Authorization header
 *    via the SDK side-effect.
 * 2. Using the authenticated connection, call the guestUsers.index endpoint twice
 *    with identical filter criteria but different page indices:
 *
 *    - First request: order_by = "created_at", order_direction = "asc", page = 1,
 *         limit = 10.
 *    - Second request: same order_by/order_direction/limit but page = 2.
 * 3. For each response, assert type correctness with typia.assert and inspect
 *    pagination metadata:
 *
 *    - Pagination.current is zero-based and should reflect the resolved page index;
 *         when requesting page = 1 and page = 2, we at least verify that
 *         `current` is stable and within [0, pages-1].
 *    - Pagination.limit matches the effective page size and is > 0 when data exist.
 *    - Pagination.records and pagination.pages are non-negative and consistent:
 *         records === 0 implies pages === 0, otherwise pages >= 1.
 * 4. Validate in-page ordering for created_at asc: iterate over each page’s data
 *    array and check created_at[i] <= created_at[i+1]. Use
 *    TestValidator.predicate with descriptive titles.
 * 5. If page1 and page2 both contain at least one record, assert cross-page
 *    continuity and non-overlap:
 *
 *    - The last record of page1 should not be identical (by id) to the first record
 *         of page2.
 *    - When records across both pages are more than one page limit, we expect that
 *         sorting by created_at asc means created_at(last of page1) <=
 *         created_at(first of page2).
 * 6. Repeat steps 2–5 using ordering by updated_at desc instead of created_at asc,
 *    adjusting sort predicates accordingly (updated_at[i] >= updated_at[i+1]).
 *    Cross-page continuity then checks updated_at(last of page1) >=
 *    updated_at(first of page2) when both pages have data.
 *
 * Notes and simplifications:
 *
 * - We rely on existing seed data in discussion_board_guestusers; we do not
 *   create guest users in this test because no write APIs are provided.
 * - When the total record count is too small to populate both pages, the test
 *   will still validate single-page ordering and basic pagination metadata, but
 *   will skip cross-page continuity assertions with clear predicates.
 */
export async function test_api_admin_guest_user_search_ordering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an adminUser
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // Helper to validate pagination metadata consistency
  const assertPagination = (title: string, pagination: IPage.IPagination) => {
    TestValidator.predicate(
      `${title} - current is non-negative`,
      pagination.current >= 0,
    );
    TestValidator.predicate(
      `${title} - pages is non-negative`,
      pagination.pages >= 0,
    );
    TestValidator.predicate(
      `${title} - records is non-negative`,
      pagination.records >= 0,
    );
    if (pagination.records === 0) {
      TestValidator.equals(
        `${title} - zero records implies zero pages`,
        pagination.pages,
        0,
      );
    } else {
      TestValidator.predicate(
        `${title} - positive records imply at least one page`,
        pagination.pages >= 1,
      );
    }
  };

  // Helper to assert ascending ordering by a date-time field
  const assertAscending = (
    title: string,
    rows: IDiscussionBoardGuestUser.ISummary[],
    selector: (row: IDiscussionBoardGuestUser.ISummary) => string,
  ) => {
    for (let i = 0; i + 1 < rows.length; i++) {
      const a = selector(rows[i]);
      const b = selector(rows[i + 1]);
      TestValidator.predicate(`${title} - ascending at index ${i}`, a <= b);
    }
  };

  // Helper to assert descending ordering by a date-time field
  const assertDescending = (
    title: string,
    rows: IDiscussionBoardGuestUser.ISummary[],
    selector: (row: IDiscussionBoardGuestUser.ISummary) => string,
  ) => {
    for (let i = 0; i + 1 < rows.length; i++) {
      const a = selector(rows[i]);
      const b = selector(rows[i + 1]);
      TestValidator.predicate(`${title} - descending at index ${i}`, a >= b);
    }
  };

  // Scenario A: order_by = created_at, order_direction = asc
  const requestCreatedPage1 = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "created_at" as const,
    order_direction: "asc" as const,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const createdPage1: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: requestCreatedPage1,
      },
    );
  typia.assert(createdPage1);

  assertPagination("created_at asc - page 1", createdPage1.pagination);
  assertAscending(
    "created_at asc - page 1 data",
    createdPage1.data,
    (row) => row.created_at,
  );

  const requestCreatedPage2 = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "created_at" as const,
    order_direction: "asc" as const,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const createdPage2: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: requestCreatedPage2,
      },
    );
  typia.assert(createdPage2);

  assertPagination("created_at asc - page 2", createdPage2.pagination);
  assertAscending(
    "created_at asc - page 2 data",
    createdPage2.data,
    (row) => row.created_at,
  );

  if (createdPage1.data.length > 0 && createdPage2.data.length > 0) {
    const lastOfPage1 = createdPage1.data[createdPage1.data.length - 1];
    const firstOfPage2 = createdPage2.data[0];

    TestValidator.predicate(
      "created_at asc - cross page ids are not identical",
      lastOfPage1.id !== firstOfPage2.id,
    );
    TestValidator.predicate(
      "created_at asc - cross page created_at continuity",
      lastOfPage1.created_at <= firstOfPage2.created_at,
    );
  }

  // Scenario B: order_by = updated_at, order_direction = desc
  const requestUpdatedPage1 = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "updated_at" as const,
    order_direction: "desc" as const,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const updatedPage1: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: requestUpdatedPage1,
      },
    );
  typia.assert(updatedPage1);

  assertPagination("updated_at desc - page 1", updatedPage1.pagination);
  assertDescending(
    "updated_at desc - page 1 data",
    updatedPage1.data,
    (row) => row.updated_at,
  );

  const requestUpdatedPage2 = {
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    order_by: "updated_at" as const,
    order_direction: "desc" as const,
  } satisfies IDiscussionBoardGuestUser.IRequest;

  const updatedPage2: IPageIDiscussionBoardGuestuser.ISummary =
    await api.functional.discussionBoard.adminUser.guestUsers.index(
      connection,
      {
        body: requestUpdatedPage2,
      },
    );
  typia.assert(updatedPage2);

  assertPagination("updated_at desc - page 2", updatedPage2.pagination);
  assertDescending(
    "updated_at desc - page 2 data",
    updatedPage2.data,
    (row) => row.updated_at,
  );

  if (updatedPage1.data.length > 0 && updatedPage2.data.length > 0) {
    const lastOfPage1 = updatedPage1.data[updatedPage1.data.length - 1];
    const firstOfPage2 = updatedPage2.data[0];

    TestValidator.predicate(
      "updated_at desc - cross page ids are not identical",
      lastOfPage1.id !== firstOfPage2.id,
    );
    TestValidator.predicate(
      "updated_at desc - cross page updated_at continuity",
      lastOfPage1.updated_at >= firstOfPage2.updated_at,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate admin-only access and basic structure of guest user detail retrieval
 * after a member-driven article/comment/report workflow.
 *
 * Business context:
 *
 * - The discussion board supports member users, admin users, articles, comments,
 *   reports, and guest user placeholders.
 * - Admins can inspect guest user placeholder accounts via GET
 *   /discussionBoard/adminUser/guestUsers/{guestUserId}.
 * - Member users can create articles, comment on them, and file reports.
 *
 * This test performs a realistic multi-actor flow:
 *
 * 1. Admin joins (auto-authenticated via SDK) and creates an article category.
 * 2. Member joins (auto-authenticated) and creates an article in that category.
 * 3. Member creates a comment on the article.
 * 4. Member files a report targeting that comment.
 * 5. Admin logs in again to ensure admin context.
 * 6. Admin fetches a guest user placeholder via
 *    api.functional.discussionBoard.adminUser.guestUsers.at.
 * 7. The test asserts that the returned guest user matches the
 *    IDiscussionBoardGuestUser contract and that only admins can access this
 *    endpoint (member access is rejected).
 *
 * Note:
 *
 * - The provided APIs and DTOs do not expose how guest users are created or tied
 *   to reports. Therefore, this test does not attempt to assert a concrete link
 *   between a specific report and a specific guest user. Instead it validates
 *   the happy-path admin retrieval and the authorization boundary.
 */
export async function test_api_admin_guest_user_detail_after_article_comment_report(
  connection: api.IConnection,
) {
  // 1. Admin joins and becomes authenticated as adminUser.
  const adminJoinEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminJoinEmail,
    password: "Admin!234", // any string, schema only requires string & Format<"password">
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorizedFromJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  const adminId: string & tags.Format<"uuid"> = adminAuthorizedFromJoin.id;

  // 2. Admin creates an article category.
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Member joins and becomes authenticated as memberUser.
  const memberJoinEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberJoinEmail,
    password: "Member!234",
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  const memberId: string & tags.Format<"uuid"> = memberAuthorizedFromJoin.id;

  // 4. Member creates an article in the created category.
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  TestValidator.equals(
    "article should reference created category",
    article.category.id,
    category.id,
  );

  // 5. Member creates a comment on the article.
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);

  TestValidator.equals(
    "comment should be attached to the article",
    comment.article.id,
    article.id,
  );

  // 6. Member files a report targeting the comment.
  const reportCreateBody = {
    category: "hate_abuse",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: undefined,
    target_comment_id: comment.id,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);

  TestValidator.equals(
    "report target type should be comment in business terms",
    report.target_type,
    report.target_type,
  );

  // 7. Prepare a candidate guestUserId. In real E2E this would come from
  // seed data or a prior admin listing; here we just generate a UUID that
  // must be acceptable by the API contract.
  const guestUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 8. Switch back to admin context via login.
  const adminLoginBody = {
    email: adminJoinEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedFromLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  TestValidator.equals(
    "admin id after login should match id after join",
    adminAuthorizedFromLogin.id,
    adminId,
  );

  // 9. As admin, fetch guest user placeholder detail.
  const guestUser: IDiscussionBoardGuestUser =
    await api.functional.discussionBoard.adminUser.guestUsers.at(connection, {
      guestUserId,
    });
  typia.assert(guestUser);

  TestValidator.predicate(
    "guest user anonymous_token should be non-empty string",
    typeof guestUser.anonymous_token === "string" &&
      guestUser.anonymous_token.length > 0,
  );

  TestValidator.predicate(
    "guest user created_at and updated_at should be non-empty strings",
    typeof guestUser.created_at === "string" &&
      guestUser.created_at.length > 0 &&
      typeof guestUser.updated_at === "string" &&
      guestUser.updated_at.length > 0,
  );

  // 10. Verify that memberUser cannot access the admin guest user detail
  // endpoint by re-authenticating as member and expecting an error.
  const memberLoginBody = {
    email: memberJoinEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  TestValidator.equals(
    "member id after login should match id after join",
    memberAuthorizedFromLogin.id,
    memberId,
  );

  // Member should not be allowed to call admin guestUsers.at.
  await TestValidator.error(
    "member cannot access admin guestUsers.at",
    async () => {
      await api.functional.discussionBoard.adminUser.guestUsers.at(connection, {
        guestUserId,
      });
    },
  );

  // Switch back to admin at the end to ensure subsequent tests, if any,
  // execute under a privileged context.
  const adminRelogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminRelogin);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";

/**
 * Validate that admin guest user detail endpoint returns an error when queried
 * with a non-existent guestUserId.
 *
 * Business context:
 *
 * - Only authenticated adminUser actors may access
 *   /discussionBoard/adminUser/guestUsers/{guestUserId}.
 * - When the provided guestUserId does not correspond to any
 *   discussion_board_guestusers.id, the endpoint must not return a guest user
 *   record and must surface an error via the HTTP error handling layer.
 *
 * Scenario steps:
 *
 * 1. Register an adminUser via POST /auth/adminUser/join, which authenticates the
 *    connection and issues JWT tokens.
 * 2. Generate a random UUID to act as a non-existent guestUserId.
 * 3. Call GET /discussionBoard/adminUser/guestUsers/{guestUserId} with that UUID
 *    and verify that an error is thrown using TestValidator.error, ensuring
 *    that no IDiscussionBoardGuestUser object is returned for unknown IDs.
 */
export async function test_api_admin_guest_user_detail_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Arrange: create and authenticate an admin user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Act: generate a random, presumably non-existent guestUserId
  const unknownGuestUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. Assert: calling guestUsers.at with unknown ID should result in an error
  await TestValidator.error(
    "unknown guest user id should produce an error",
    async () => {
      await api.functional.discussionBoard.adminUser.guestUsers.at(connection, {
        guestUserId: unknownGuestUserId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Verify admin guest user detail retrieval stability after an
 * attachment-related report workflow.
 *
 * Business goal:
 *
 * - Exercise the typical moderation-related workflow up to the point of creating
 *   a report targeting an attachment.
 * - Then validate that the admin-only guest user detail API can be called and
 *   returns a stable, schema-conform guest placeholder for a given
 *   guestUserId.
 *
 * Scenario implemented (within available APIs):
 *
 * 1. Admin registers via /auth/adminUser/join and becomes authenticated as
 *    adminUser.
 * 2. Member registers via /auth/memberUser/join and becomes authenticated as
 *    memberUser.
 * 3. Switch back to admin and create an article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Switch to member and create an article in that category via
 *    /discussionBoard/memberUser/articles.
 * 5. As the same member, attach a file to the article via
 *    /discussionBoard/memberUser/articles/{articleId}/attachments.
 * 6. As the same member, create a report whose target_attachment_id is the
 *    attachment id via /discussionBoard/memberUser/reports.
 * 7. Switch to admin again and call
 *    /discussionBoard/adminUser/guestUsers/{guestUserId} twice, using a
 *    deterministic UUID guestUserId for this test.
 * 8. Assert that both calls return structurally valid IDiscussionBoardGuestUser
 *    objects and that their id and anonymous_token fields remain stable across
 *    calls.
 */
export async function test_api_admin_guest_user_detail_after_attachment_report(
  connection: api.IConnection,
) {
  // 1. Admin registration (join) and authentication
  const adminJoinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "AdminPassword!123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
