import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

export async function test_api_admin_user_login_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin user via join endpoint
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  // password must satisfy Format<"password">, use random string
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    // use realistic URLs for href and referrer
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const joinedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(joinedAdmin);

  // 2. Login using same email and password
  const loginBody = {
    email,
    password,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const loggedInAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(loggedInAdmin);

  // 3. Basic identity consistency checks
  TestValidator.equals(
    "admin id must be consistent between join and first login",
    joinedAdmin.id,
    loggedInAdmin.id,
  );
  TestValidator.equals(
    "admin email must match input email on join",
    joinedAdmin.email,
    email,
  );
  TestValidator.equals(
    "admin email must be consistent between join and first login",
    loggedInAdmin.email,
    joinedAdmin.email,
  );
  TestValidator.equals(
    "display name must be consistent between join and first login",
    loggedInAdmin.displayName,
    joinedAdmin.displayName,
  );
  TestValidator.equals(
    "status must be consistent between join and first login",
    loggedInAdmin.status,
    joinedAdmin.status,
  );
  TestValidator.equals(
    "role must be consistent between join and first login",
    loggedInAdmin.role,
    joinedAdmin.role,
  );
  TestValidator.equals(
    "emailVerified flag must be consistent between join and first login",
    loggedInAdmin.emailVerified,
    joinedAdmin.emailVerified,
  );

  // 4. Token-level validations for join and first login
  const joinedToken: IAuthorizationToken = joinedAdmin.token;
  const loggedInToken: IAuthorizationToken = loggedInAdmin.token;

  TestValidator.predicate(
    "joined access token must be non-empty",
    joinedToken.access.length > 0,
  );
  TestValidator.predicate(
    "joined refresh token must be non-empty",
    joinedToken.refresh.length > 0,
  );
  TestValidator.predicate(
    "login access token must be non-empty",
    loggedInToken.access.length > 0,
  );
  TestValidator.predicate(
    "login refresh token must be non-empty",
    loggedInToken.refresh.length > 0,
  );

  // Expect new tokens on login vs join
  TestValidator.notEquals(
    "access token from login should differ from join access token",
    loggedInToken.access,
    joinedToken.access,
  );
  TestValidator.notEquals(
    "refresh token from login should differ from join refresh token",
    loggedInToken.refresh,
    joinedToken.refresh,
  );

  // 5. Re-login to confirm repeated logins continue to work and issue fresh tokens
  const loginBody2 = {
    email,
    password,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const loggedInAdmin2: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody2,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(loggedInAdmin2);

  const loggedInToken2: IAuthorizationToken = loggedInAdmin2.token;

  // Identity consistency across all three responses
  TestValidator.equals(
    "admin id must be consistent across join and both logins",
    loggedInAdmin2.id,
    joinedAdmin.id,
  );
  TestValidator.equals(
    "admin email must be consistent across join and both logins",
    loggedInAdmin2.email,
    joinedAdmin.email,
  );
  TestValidator.equals(
    "display name must be consistent across join and both logins",
    loggedInAdmin2.displayName,
    joinedAdmin.displayName,
  );

  // Token rotation expectations
  TestValidator.notEquals(
    "second login access token should differ from first login access token",
    loggedInToken2.access,
    loggedInToken.access,
  );
  TestValidator.notEquals(
    "second login access token should differ from join access token",
    loggedInToken2.access,
    joinedToken.access,
  );

  // Optional check: refresh tokens should also rotate
  TestValidator.notEquals(
    "second login refresh token should differ from first login refresh token",
    loggedInToken2.refresh,
    loggedInToken.refresh,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

/**
 * Validate admin login failure on wrong password while preserving account
 * usability.
 *
 * Business goal:
 *
 * - Ensure that when an administrator attempts to log in with an incorrect
 *   password, authentication fails cleanly without returning any authorized
 *   payload, and that a subsequent login with the correct password still
 *   succeeds (no lockout behavior after a single failure).
 *
 * Test steps:
 *
 * 1. Register a new admin via /auth/adminUser/join and remember its email and
 *    password. This both provisions the account and authenticates the
 *    connection as that admin (per SDK behavior).
 * 2. Build an independent, unauthenticated connection object so that the login
 *    behavior is not affected by the join-issued token.
 * 3. Call /auth/adminUser/login with the same email but a clearly different wrong
 *    password using the unauthenticated connection, and assert that the call
 *    fails using TestValidator.error.
 *
 *    - Do NOT attempt to read any IDiscussionBoardAdminuser.IAuthorized payload from
 *         this failure.
 *    - Do NOT inspect HTTP status codes or error messages; only existence of an
 *         error matters.
 * 4. Using the same unauthenticated connection, perform a login with the correct
 *    password and assert that it succeeds and returns a valid
 *    IDiscussionBoardAdminuser.IAuthorized payload.
 * 5. Confirm that the email field of the authorized admin matches the one used
 *    during registration.
 */
export async function test_api_admin_user_login_with_wrong_password(
  connection: api.IConnection,
) {
  // 1. Register a new admin via join
  const joinEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const joinPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email: joinEmail,
    password: joinPassword,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const joinedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joinedAdmin);

  // 2. Create an unauthenticated connection by cloning without headers
  const unauthenticated: api.IConnection = { ...connection, headers: {} };

  // 3. Attempt login with wrong password and expect failure
  const wrongPassword: string = `${joinPassword}wrong`;

  await TestValidator.error(
    "admin login must fail with wrong password",
    async () => {
      await api.functional.auth.adminUser.login(unauthenticated, {
        body: {
          email: joinEmail,
          password: wrongPassword,
          ip: null,
          href: "https://admin.example.com/login" as string &
            tags.Format<"uri">,
          referrer: "https://admin.example.com/referrer" as string &
            tags.Format<"uri">,
        } satisfies IDiscussionBoardAdminUserLogin.IRequest,
      });
    },
  );

  // 4. Perform successful login with correct password
  const authorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(unauthenticated, {
      body: {
        email: joinEmail,
        password: joinPassword,
        ip: null,
        href: "https://admin.example.com/login" as string & tags.Format<"uri">,
        referrer: "https://admin.example.com/referrer" as string &
          tags.Format<"uri">,
      } satisfies IDiscussionBoardAdminUserLogin.IRequest,
    });
  typia.assert(authorized);

  // 5. Verify that the authorized admin email matches the registration email
  TestValidator.equals(
    "authorized admin email must equal joined email",
    authorized.email,
    joinEmail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

export async function test_api_admin_user_login_nonexistent_email(
  connection: api.IConnection,
) {
  // 1. Prepare base and unauthenticated connections
  const baseConnection: api.IConnection = connection;
  const unauthenticatedForNegative: api.IConnection = {
    ...baseConnection,
    headers: {},
  };

  // 2. Generate two distinct admin emails
  const existingEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const nonexistentEmail: string & tags.Format<"email"> = (() => {
    let email: string & tags.Format<"email">;
    while (true) {
      const candidate = typia.random<string & tags.Format<"email">>();
      if (candidate !== existingEmail) {
        email = candidate;
        break;
      }
    }
    return email;
  })();

  // 3. Create a control admin account with a different email
  const joinRequestForExisting = {
    ...typia.random<IDiscussionBoardAdminUserJoin.IRequest>(),
    email: existingEmail,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const existingAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(baseConnection, {
      body: joinRequestForExisting,
    });
  typia.assert(existingAdmin);

  // 4. Attempt login with non-existent email on unauthenticated connection
  //    Expect authentication failure (some error), but do not inspect status code
  const randomPasswordForNegative: string = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 8,
    wordMax: 16,
  });

  await TestValidator.error(
    "login with non-existent admin email should fail",
    async () => {
      const loginRequestForNonexistent = {
        email: nonexistentEmail,
        password: randomPasswordForNegative,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IDiscussionBoardAdminUserLogin.IRequest;

      await api.functional.auth.adminUser.login(unauthenticatedForNegative, {
        body: loginRequestForNonexistent,
      });
    },
  );

  // 5. Create an admin using the previously non-existent email
  const joinPasswordForNonexistent: string & tags.Format<"password"> =
    typia.random<string & tags.Format<"password">>();

  const joinRequestForNonexistent = {
    ...typia.random<IDiscussionBoardAdminUserJoin.IRequest>(),
    email: nonexistentEmail,
    password: joinPasswordForNonexistent,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const newlyCreatedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(baseConnection, {
      body: joinRequestForNonexistent,
    });
  typia.assert(newlyCreatedAdmin);

  // 6. Attempt login again with the now-existing email and correct password
  const unauthenticatedForPositive: api.IConnection = {
    ...baseConnection,
    headers: {},
  };

  const loginRequestForExistingNow = {
    email: nonexistentEmail,
    password: joinPasswordForNonexistent,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const loginResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(unauthenticatedForPositive, {
      body: loginRequestForExistingNow,
    });
  typia.assert(loginResult);

  // 7. Verify that the successful login corresponds to the expected email
  TestValidator.equals(
    "successful admin login should return profile for the requested email",
    loginResult.email,
    nonexistentEmail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

export async function test_api_admin_user_login_multiple_successive_logins(
  connection: api.IConnection,
) {
  // 1. Register a new administrative user who will perform multiple logins.
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  // Use a deterministic but strong-looking password string. It must satisfy
  // Format<"password">, but we don't need to randomize it.
  const password: string & tags.Format<"password"> =
    "Adm1n!Passw0rd" as string & tags.Format<"password">;

  const joinHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const joinReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const joinRequestBody = {
    email,
    password,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "203.0.113.10",
    href: joinHref,
    referrer: joinReferrer,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const joinedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinRequestBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(joinedAdmin);

  // 2. First login with the same credentials and connection metadata.
  const loginHref1: string & tags.Format<"uri"> = joinHref;
  const loginReferrer1: string & tags.Format<"uri"> = joinReferrer;

  const loginBody1 = {
    email,
    password,
    ip: "203.0.113.10",
    href: loginHref1,
    referrer: loginReferrer1,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const login1: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody1,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(login1);

  // 3. Second login immediately with the same credentials and connection metadata.
  const loginBody2 = {
    email,
    password,
    ip: "203.0.113.10",
    href: loginHref1,
    referrer: loginReferrer1,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const login2: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody2,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(login2);

  // 4. Verify that core identity/profile fields remain identical.
  const titleStableProfile1 =
    "admin profile should remain stable across successive logins";

  TestValidator.equals(titleStableProfile1, login1.id, login2.id);
  TestValidator.equals(titleStableProfile1, login1.loginId, login2.loginId);
  TestValidator.equals(
    titleStableProfile1,
    login1.displayName,
    login2.displayName,
  );
  TestValidator.equals(titleStableProfile1, login1.email, login2.email);
  TestValidator.equals(titleStableProfile1, login1.status, login2.status);
  TestValidator.equals(titleStableProfile1, login1.role, login2.role);
  TestValidator.equals(
    "emailVerified flag should stay consistent across logins",
    login1.emailVerified,
    login2.emailVerified,
  );
  TestValidator.equals(
    "createdAt should be the same across repeated logins",
    login1.createdAt,
    login2.createdAt,
  );
  TestValidator.equals(
    "updatedAt should not regress across repeated logins",
    login1.updatedAt,
    login2.updatedAt,
  );

  // 5. Compare token behavior between login1 and login2.
  const token1: IAuthorizationToken = login1.token;
  const token2: IAuthorizationToken = login2.token;

  // At minimum, ensure structure and basic invariants via typia.
  typia.assert<IAuthorizationToken>(token1);
  typia.assert<IAuthorizationToken>(token2);

  // Access token should generally be refreshed on each login. If
  // implementation chooses to reuse it, this assertion will highlight it.
  TestValidator.notEquals(
    "access token should change on successive logins",
    token1.access,
    token2.access,
  );

  // Refresh tokens may or may not rotate; we don't strictly require
  // them to differ, but we can at least assert that expiration windows
  // do not regress.
  TestValidator.predicate(
    "access token expiration of second login should not be earlier than first",
    new Date(token2.expired_at).getTime() >=
      new Date(token1.expired_at).getTime(),
  );
  TestValidator.predicate(
    "refresh token expiration of second login should not be earlier than first",
    new Date(token2.refreshable_until).getTime() >=
      new Date(token1.refreshable_until).getTime(),
  );

  // 6. Third login with different connection metadata (ip, href, referrer).
  const loginHref3: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
