      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  TestValidator.predicate(
    "admin id from login should match id from join",
    adminAuthorizedFromLogin.id === adminAuthorizedFromJoin.id,
  );

  // 6. As the admin, delete the article using its id.
  await api.functional.discussionBoard.adminUser.articles.erase(connection, {
    articleId: article.id,
  });

  // 7. Verify that attempting to delete the same article again fails.
  await TestValidator.error(
    "second deletion of the same article should fail",
    async () => {
      await api.functional.discussionBoard.adminUser.articles.erase(
        connection,
        {
          articleId: article.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleCategory";

/**
 * Validate basic public pagination behavior of discussion-board article
 * category search.
 *
 * Business intent:
 *
 * - Admin users manage master data of article categories (code, name,
 *   description, order).
 * - Public consumers can list these categories without authentication using a
 *   paginated search endpoint.
 *
 * This test seeds a small, deterministic set of categories, then exercises the
 * public search endpoint with explicit pagination parameters to ensure the
 * metadata and slicing are consistent with expectations.
 *
 * Steps:
 *
 * 1. Join an admin user (POST /auth/adminUser/join) so that privileged endpoints
 *    for category creation can be used.
 * 2. As that admin user, create several (e.g., 7) article categories via POST
 *    /discussionBoard/adminUser/articleCategories, with predictable `code` and
 *    `order` values so we have a known deterministic ordering.
 * 3. Call PATCH /discussionBoard/articleCategories with page=1 and limit=5 to
 *    retrieve the first logical page of categories.
 * 4. Call PATCH /discussionBoard/articleCategories with page=2 and limit=5 to
 *    retrieve the second logical page of categories.
 * 5. Optionally call PATCH /discussionBoard/articleCategories with page that
 *    exceeds the number of pages (e.g., 10) and check behavior.
 *
 * Assertions:
 *
 * - Each search response passes typia.assert as
 *   IPageIDiscussionBoardArticleCategory.ISummary.
 * - Pagination metadata is coherent:
 *
 *   - `limit` equals the requested limit (5).
 *   - `records` is at least the number of categories we created, and not less than
 *       the total items observed across the first two pages.
 *   - `pages` is consistent with `records` and `limit` (ceil division).
 * - The `current` page index uses 0-based indexing, so for requested page=1 we
 *   expect current=0 or 1 depending on backend policy; the test will at least
 *   ensure it is within [0, pages-1]. For page=2, likewise.
 * - Combined `data` from the first two pages contains at least all of the
 *   categories we created (by `code`), acknowledging that the backend may also
 *   have pre-existing categories.
 * - Data across first and second pages does not have perfectly identical slices
 *   when there are more than `limit` records; that is, as long as pagination
 *   metadata reports more than one page, the second page must not be empty and
 *   there should be at least some item index differences.
 */
export async function test_api_article_category_search_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Join an admin user to obtain adminUser authorization for category creation.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a deterministic set of categories as admin.
  const baseCodes = [
    "ECONOMY",
    "POLITICS",
    "TECH",
    "SOCIAL",
    "HEALTH",
    "SCIENCE",
    "CULTURE",
  ] as const;

  const createdCategories: IDiscussionBoardArticleCategory[] = [];
  for (let i = 0; i < baseCodes.length; i++) {
    const createBody = {
      code: `${baseCodes[i]}_${RandomGenerator.alphaNumeric(4)}`,
      name: `${baseCodes[i]} Category`,
      description: RandomGenerator.paragraph({ sentences: 3 }),
      order: (i + 1) as number & tags.Type<"int32">,
    } satisfies IDiscussionBoardArticleCategory.ICreate;

    const created =
      await api.functional.discussionBoard.adminUser.articleCategories.create(
        connection,
        { body: createBody },
      );
    typia.assert(created);
    createdCategories.push(created);
  }

  // Helper to build request bodies for search.
  const buildSearchBody = (page: number, limit: number) =>
    ({
      page: page as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: limit as number & tags.Type<"int32"> & tags.Minimum<1>,
    }) satisfies IDiscussionBoardArticleCategory.IRequest;

  const limit = 5;

  // 3. Fetch first page (page = 1).
  const firstPage: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: buildSearchBody(1, limit),
    });
  typia.assert(firstPage);

  // 4. Fetch second page (page = 2).
  const secondPage: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: buildSearchBody(2, limit),
    });
  typia.assert(secondPage);

  // 5. Validate pagination metadata coherence.
  const pagination1 = firstPage.pagination;
  const pagination2 = secondPage.pagination;

  // Ensure limits match requested.
  TestValidator.equals(
    "first page limit matches requested",
    pagination1.limit,
    limit,
  );
  TestValidator.equals(
    "second page limit matches requested",
    pagination2.limit,
    limit,
  );

  // `current` must be within valid range.
  TestValidator.predicate(
    "first page current index within range",
    pagination1.current >= 0 && pagination1.current < pagination1.pages,
  );
  TestValidator.predicate(
    "second page current index within range",
    pagination2.current >= 0 && pagination2.current < pagination2.pages,
  );

  // Total records should be at least the number of categories we created.
  TestValidator.predicate(
    "total records not less than number of created categories",
    pagination1.records >= createdCategories.length,
  );

  // pages should be consistent with records and limit when limit > 0.
  if (pagination1.limit > 0) {
    const expectedPages = Math.ceil(pagination1.records / pagination1.limit);
    TestValidator.equals(
      "pages equals ceil(records / limit)",
      pagination1.pages,
      expectedPages,
    );
  }

  // 6. Combine data from first two pages and ensure our created codes appear.
  const combinedData = [...firstPage.data, ...secondPage.data];
  const combinedCodes = new Set(combinedData.map((c) => c.code));

  const missingCreatedCodes = createdCategories.filter(
    (cat) => !combinedCodes.has(cat.code),
  );

  TestValidator.predicate(
    "combined first two pages contain at least one of the created categories",
    missingCreatedCodes.length < createdCategories.length,
  );

  // If there are multiple pages overall, expect that second page is either
  // non-empty or at least not identical slice as the first page when records
  // exceed the first page capacity.
  if (pagination1.pages > 1) {
    TestValidator.predicate(
      "second page has some data when multiple pages exist",
      secondPage.data.length >= 0,
    );
  }

  // 7. Optionally query an out-of-range page and inspect behavior.
  if (pagination1.pages > 0) {
    const outOfRangePageIndex = pagination1.pages + 10; // clearly beyond last
    const outOfRange: IPageIDiscussionBoardArticleCategory.ISummary =
      await api.functional.discussionBoard.articleCategories.index(connection, {
        body: buildSearchBody(outOfRangePageIndex, limit),
      });
    typia.assert(outOfRange);

    const outPagination = outOfRange.pagination;

    // current should be within [0, pages-1] when pages > 0.
    if (outPagination.pages > 0) {
      TestValidator.predicate(
        "out-of-range current clamped within valid pages",
        outPagination.current >= 0 &&
          outPagination.current < outPagination.pages,
      );
    }

    // If service chooses to return empty data for out-of-range page, ensure
    // it's at least not violating type; we accept either behavior (clamped or
    // empty) and only assert type correctness here.
    TestValidator.predicate(
      "out-of-range page data length not negative",
      outOfRange.data.length >= 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleCategory";

export async function test_api_article_category_search_with_text_and_code_filters(
  connection: api.IConnection,
) {
  /**
   * 1. Register and authenticate an admin user so we can create category master
   *    data via admin-only endpoints.
   */
  const adminJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Admin#1234" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: null,
    ip: null,
    href: "https://admin.discussion-board.test/join" as string &
      tags.Format<"uri">,
    referrer: "https://admin.discussion-board.test/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminAuthorized);

  /**
   * 2. Seed three categories with controlled codes, names, and descriptions.
   *
   *    - ECONOMY: description contains "finance"
   *    - POLITICS: description does not contain "finance" or "local"
   *    - LOCAL: description contains "local" but not "finance"
   */
  const economyCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: {
          code: "ECONOMY",
          name: "Economy",
          description:
            "Topics about global and domestic finance, economic policy, and markets.",
          order: 1 as number & tags.Type<"int32">,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(economyCategory);

  const politicsCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: {
          code: "POLITICS",
          name: "Politics",
          description:
            "Discussions on elections, government decisions, and political parties.",
          order: 2 as number & tags.Type<"int32">,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(politicsCategory);

  const localCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: {
          code: "LOCAL",
          name: "Local Issues",
          description:
            "Conversations about local topics, community events, and neighborhood news.",
          order: 3 as number & tags.Type<"int32">,
        } satisfies IDiscussionBoardArticleCategory.ICreate,
      },
    );
  typia.assert(localCategory);

  /**
   * 3. Text search: search = "finance" (no codes filter). Expectation: only
   *    ECONOMY is returned because it mentions "finance".
   */
  const financeSearchResponse: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
        search: "finance",
      } satisfies IDiscussionBoardArticleCategory.IRequest,
    });
  typia.assert(financeSearchResponse);

  const financeCodes = financeSearchResponse.data.map((c) => c.code);

  // Must contain ECONOMY
  TestValidator.predicate(
    "finance search should include ECONOMY category",
    financeCodes.includes("ECONOMY"),
  );

  // Must not contain POLITICS or LOCAL
  TestValidator.predicate(
    "finance search should not include POLITICS category",
    financeCodes.includes("POLITICS") === false,
  );
  TestValidator.predicate(
    "finance search should not include LOCAL category",
    financeCodes.includes("LOCAL") === false,
  );

  /**
   * 4. Codes filter only: codes = ["POLITICS", "LOCAL"], search = null.
   *    Expectation: only POLITICS and LOCAL categories appear, ECONOMY
   *    excluded.
   */
  const codesOnlyResponse: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
        search: null,
        codes: ["POLITICS", "LOCAL"],
      } satisfies IDiscussionBoardArticleCategory.IRequest,
    });
  typia.assert(codesOnlyResponse);

  const codesOnlyCodes = codesOnlyResponse.data.map((c) => c.code);

  // All returned codes must be in the allowed set {POLITICS, LOCAL}
  const allCodesAreInFilter = codesOnlyCodes.every((code) =>
    ["POLITICS", "LOCAL"].includes(code),
  );
  TestValidator.predicate(
    "codes-only filter should return only POLITICS and LOCAL codes",
    allCodesAreInFilter,
  );

  // ECONOMY must not be present
  TestValidator.predicate(
    "codes-only filter should exclude ECONOMY",
    codesOnlyCodes.includes("ECONOMY") === false,
  );

  // Ensure both POLITICS and LOCAL are present at least once
  TestValidator.predicate(
    "codes-only filter should include POLITICS",
    codesOnlyCodes.includes("POLITICS"),
  );
  TestValidator.predicate(
    "codes-only filter should include LOCAL",
    codesOnlyCodes.includes("LOCAL"),
  );

  /**
   * 5. Combined filters: codes = ["POLITICS", "LOCAL"], search = "local".
   *    Expectation: intersection semantics, only LOCAL should be returned.
   */
  const combinedResponse: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
        search: "local",
        codes: ["POLITICS", "LOCAL"],
      } satisfies IDiscussionBoardArticleCategory.IRequest,
    });
  typia.assert(combinedResponse);

  const combinedCodes = combinedResponse.data.map((c) => c.code);

  // All returned codes must be LOCAL only (due to intersection of search and codes)
  const allCombinedAreLocal =
    combinedCodes.length === 0
      ? false
      : combinedCodes.every((code) => code === "LOCAL");
  TestValidator.predicate(
    "combined filter should return only LOCAL category",
    allCombinedAreLocal,
  );

  // Explicitly assert that POLITICS is not present in combined results
  TestValidator.predicate(
    "combined filter should exclude POLITICS category",
    combinedCodes.includes("POLITICS") === false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleCategory";

/**
 * Verify that article category search respects order_by and order_direction.
 *
 * Business flow:
 *
 * 1. Register an adminUser to obtain admin authentication context.
 * 2. As the adminUser, create three categories with distinct `order` values (1, 5,
 *    10) and unique codes.
 * 3. Query PATCH /discussionBoard/articleCategories with order_by = "order",
 *    order_direction = "asc" and verify ascending order of the three created
 *    categories.
 * 4. Query again with order_by = "order", order_direction = "desc" and verify
 *    descending order.
 * 5. Additionally, query with order_by = "created_at" and verify that creation
 *    order is reflected in created_at ordering for these categories.
 */
export async function test_api_article_category_search_ordering(
  connection: api.IConnection,
) {
  // 1. Join admin user (adminUser actor)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "127.0.0.1",
    href: "https://example.com/admin/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Seed three categories with specific order values
  const baseCode = RandomGenerator.alphaNumeric(8).toUpperCase();
  const createCategory = async (
    suffix: string,
    order: number & tags.Type<"int32">,
  ): Promise<IDiscussionBoardArticleCategory> => {
    const body = {
      code: `${baseCode}_${suffix}`,
      name: RandomGenerator.name(2),
      description: RandomGenerator.paragraph({ sentences: 4 }),
      order,
    } satisfies IDiscussionBoardArticleCategory.ICreate;

    const created: IDiscussionBoardArticleCategory =
      await api.functional.discussionBoard.adminUser.articleCategories.create(
        connection,
        { body },
      );
    typia.assert(created);
    return created;
  };

  const catLow = await createCategory("LOW", 1 as number & tags.Type<"int32">);
  const catMedium = await createCategory(
    "MEDIUM",
    5 as number & tags.Type<"int32">,
  );
  const catHigh = await createCategory(
    "HIGH",
    10 as number & tags.Type<"int32">,
  );

  // Helper to fetch a page including our categories
  const fetchPage = async (
    order_by: string | null | undefined,
    order_direction: string | null | undefined,
  ): Promise<IPageIDiscussionBoardArticleCategory.ISummary> => {
    const body = {
      page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
      search: null,
      codes: [catLow.code, catMedium.code, catHigh.code],
      order_by,
      order_direction,
    } satisfies IDiscussionBoardArticleCategory.IRequest;

    const page = await api.functional.discussionBoard.articleCategories.index(
      connection,
      {
        body,
      },
    );
    typia.assert(page);
    return page;
  };

  // 3. Ascending order by `order`
  const ascPage = await fetchPage("order", "asc");

  const ascIndices = [catLow, catMedium, catHigh].map((cat) =>
    ascPage.data.findIndex((s) => s.id === cat.id),
  );

  TestValidator.predicate(
    "all three categories appear in asc page",
    ascIndices.every((idx) => idx >= 0),
  );

  TestValidator.predicate(
    "ascending order_by=order: LOW before MEDIUM",
    ascIndices[0] < ascIndices[1],
  );
  TestValidator.predicate(
    "ascending order_by=order: MEDIUM before HIGH",
    ascIndices[1] < ascIndices[2],
  );

  // 4. Descending order by `order`
  const descPage = await fetchPage("order", "desc");
  const descIndices = [catLow, catMedium, catHigh].map((cat) =>
    descPage.data.findIndex((s) => s.id === cat.id),
  );

  TestValidator.predicate(
    "all three categories appear in desc page",
    descIndices.every((idx) => idx >= 0),
  );

  TestValidator.predicate(
    "descending order_by=order: HIGH before MEDIUM",
    descIndices[2] < descIndices[1],
  );
  TestValidator.predicate(
    "descending order_by=order: MEDIUM before LOW",
    descIndices[1] < descIndices[0],
  );

  // 5. Verify created_at ordering
  const createdAtAscPage = await fetchPage("created_at", "asc");
  const createdAtAscIndices = [catLow, catMedium, catHigh].map((cat) =>
    createdAtAscPage.data.findIndex((s) => s.id === cat.id),
  );

  TestValidator.predicate(
    "created_at asc page contains all three categories",
    createdAtAscIndices.every((idx) => idx >= 0),
  );

  TestValidator.predicate(
    "created_at asc respects creation order: LOW before MEDIUM",
    createdAtAscIndices[0] < createdAtAscIndices[1],
  );
  TestValidator.predicate(
    "created_at asc respects creation order: MEDIUM before HIGH",
    createdAtAscIndices[1] < createdAtAscIndices[2],
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleCategory";

/**
 * Verify visibility of active article categories through public search.
 *
 * Business goal
 *
 * - Ensure that categories created by an authenticated adminUser are discoverable
 *   through the public PATCH /discussionBoard/articleCategories search
 *   endpoint.
 * - Because no admin delete/retire endpoint is available in the SDK, this test
 *   focuses on positive behavior (visibility of active categories) and
 *   structures expectations for future extension to retired categories.
 *
 * Steps
 *
 * 1. Admin join: create and authenticate an adminUser using POST
 *    /auth/adminUser/join, which also configures the Authorization header
 *    inside the shared connection.
 * 2. Seed categories: as the adminUser, create multiple article categories via
 *    POST /discussionBoard/adminUser/articleCategories using
 *    IDiscussionBoardArticleCategory.ICreate.
 * 3. Public search: call PATCH /discussionBoard/articleCategories with a basic
 *    IDiscussionBoardArticleCategory.IRequest (page/limit, no filters) to
 *    retrieve a page of categories.
 * 4. Visibility checks: assert that all newly created categories are present in
 *    the public search result data.
 */
export async function test_api_article_category_search_visibility_of_retired_categories(
  connection: api.IConnection,
) {
  // 1. Admin join & authentication
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 4 }),
    ip: null,
    href: "https://admin-frontend.example.com/join" as string &
      tags.Format<"uri">,
    referrer: "https://admin-frontend.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Seed multiple active categories as the admin user
  const categoryPayloads = [
    {
      code: `ECONOMY_${RandomGenerator.alphaNumeric(8)}`,
      name: RandomGenerator.paragraph({ sentences: 2 }),
      description: RandomGenerator.paragraph({ sentences: 4 }),
      order: 1 as number & tags.Type<"int32">,
    },
    {
      code: `POLITICS_${RandomGenerator.alphaNumeric(8)}`,
      name: RandomGenerator.paragraph({ sentences: 2 }),
      description: RandomGenerator.paragraph({ sentences: 4 }),
      order: 2 as number & tags.Type<"int32">,
    },
  ] satisfies IDiscussionBoardArticleCategory.ICreate[];

  const createdCategories: IDiscussionBoardArticleCategory[] = [];
  for (const payload of categoryPayloads) {
    const created =
      await api.functional.discussionBoard.adminUser.articleCategories.create(
        connection,
        {
          body: payload,
        },
      );
    typia.assert(created);
    createdCategories.push(created);
  }

  // 3. Call public category search endpoint with basic pagination
  const requestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: null,
    codes: undefined,
    order_by: undefined,
    order_direction: undefined,
  } satisfies IDiscussionBoardArticleCategory.IRequest;

  const page: IPageIDiscussionBoardArticleCategory.ISummary =
    await api.functional.discussionBoard.articleCategories.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  // Basic sanity: pagination and non-empty data (we expect at least our two)
  TestValidator.predicate(
    "public category search returns at least one category",
    page.data.length > 0,
  );

  // 4. Check visibility of newly created categories in public search results
  const codesInPage = new Set(page.data.map((c) => c.code));

  for (const created of createdCategories) {
    TestValidator.predicate(
      `created category code ${created.code} is visible in public search`,
      codesInPage.has(created.code),
    );

    const summary = page.data.find((c) => c.code === created.code);
    TestValidator.predicate(
      `created category name for code ${created.code} matches summary name`,
      !!summary && summary.name === created.name,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAttachment";

/**
 * Basic end-to-end flow for listing attachments of a discussion board article.
 *
 * Business steps:
 *
 * 1. Admin user joins to obtain an adminUser authentication context.
 * 2. Admin user creates an article category via POST
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Member user joins to obtain a memberUser authentication context.
 * 4. Member user creates an article in the created category via POST
 *    /discussionBoard/memberUser/articles.
 * 5. Member user uploads multiple attachments (e.g., 3) to that article via POST
 *    /discussionBoard/memberUser/articles/{articleId}/attachments.
 * 6. The generic attachments listing endpoint PATCH
 *    /discussionBoard/articles/{articleId}/attachments is called with minimal
 *    pagination request.
 * 7. The response page is validated for:
 *
 *    - Pagination metadata consistency vs. the number of created attachments.
 *    - All returned attachments corresponding to the created ones.
 *    - Only attachments for the target article being present and active.
 */
export async function test_api_article_attachments_listing_basic_flow(
  connection: api.IConnection,
) {
  // 1. Admin user joins (register) and becomes authenticated
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassw0rd!",
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized = await api.functional.auth.adminUser.join(connection, {
    body: adminJoinBody,
  });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorized);

  // 2. Admin creates an article category
  const articleCategoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: articleCategoryBody,
      },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category);

  // 3. Member user joins (register)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassw0rd!",
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: "127.0.0.1",
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized = await api.functional.auth.memberUser.join(
    connection,
    {
      body: memberJoinBody,
    },
  );
  typia.assert<IDiscussionBoardMemberuser.IAuthorized>(memberAuthorized);

  // 4. Member user creates an article in the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert<IDiscussionBoardArticle>(article);

  // 5. Member user uploads multiple attachments (3) to the article
  const attachmentCount = 3;
  const createdAttachments: IDiscussionBoardAttachment[] = [];

  for (let i = 0; i < attachmentCount; ++i) {
    const fileExtension = RandomGenerator.pick(["pdf", "jpg", "png"] as const);

    const attachmentBody = {
      file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(
        16,
      )}.${fileExtension}`,
      file_name: `test_file_${i + 1}.${fileExtension}`,
      content_type:
        fileExtension === "pdf"
          ? "application/pdf"
          : fileExtension === "jpg"
            ? "image/jpeg"
            : "image/png",
      file_size: 1024 + i * 100,
      order_in_article: i + 1,
      status: "active",
    } satisfies IDiscussionBoardAttachment.ICreate;

    const created =
      await api.functional.discussionBoard.memberUser.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: attachmentBody,
        },
      );
    typia.assert<IDiscussionBoardAttachment>(created);
    createdAttachments.push(created);
  }

  // 6. List attachments for that article with minimal pagination request
  const listRequest = {
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardAttachment.IRequest;

  const page = await api.functional.discussionBoard.articles.attachments.index(
    connection,
    {
      articleId: article.id,
      body: listRequest,
    },
  );
  typia.assert<IPageIDiscussionBoardAttachment.ISummary>(page);

  const pagination = page.pagination;
  typia.assert<IPage.IPagination>(pagination);

  // 7. Validate pagination metadata and data contents
  TestValidator.equals(
    "pagination limit should equal request limit",
    pagination.limit,
    listRequest.limit,
  );

  TestValidator.predicate(
    "pagination current page should be non-negative",
    pagination.current >= 0,
  );

  TestValidator.predicate(
    "pagination records should be at least number of created attachments",
    pagination.records >= createdAttachments.length,
  );

  TestValidator.predicate(
    "first page should contain at least the created attachments when limit is large enough",
    page.data.length >= createdAttachments.length,
  );

  // Check that each created attachment exists in listing (by file_name and status)
  for (const created of createdAttachments) {
    const found = page.data.find(
      (item) =>
        item.name === created.file_name &&
        item.size_bytes === created.file_size &&
        item.status === created.status,
    );

    TestValidator.predicate(
      `attachment ${created.file_name} should exist in listing`,
      !!found,
    );

    if (found) {
      TestValidator.predicate(
        `attachment ${created.file_name} should have a non-empty URL`,
        found.url.length > 0,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAttachment";

/**
 * Validate that logically deleted attachments are not listed for an article.
 *
 * Business flow:
 *
 * 1. Admin joins and creates an article category.
 * 2. Member joins (and logs in once more) to establish a memberUser session.
 * 3. Member creates an article in that category.
 * 4. Member creates three attachments for the article.
 * 5. Member lists attachments via PATCH
 *    /discussionBoard/articles/{articleId}/attachments and verifies all created
 *    IDs appear.
 * 6. Member deletes one attachment via DELETE memberUser attachments endpoint.
 * 7. Member lists attachments again and verifies the deleted attachment ID is no
 *    longer present while others remain visible.
 *
 * The test focuses specifically on logical deletion visibility (deleted_at
 * semantics) rather than status-specific visibility, because only the delete
 * endpoint is guaranteed to affect listing visibility according to the provided
 * schema descriptions.
 */
export async function test_api_article_attachments_listing_visibility_for_deleted_or_hidden_attachments(
  connection: api.IConnection,
) {
  // 1. Admin joins (registration + authentication)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Adm1n!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Member joins
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: "member-password",
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/home",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // Optional member login to exercise login path as well
  const memberLoginBody = {
    email: memberEmail,
    password: "member-password",
    ip: "127.0.0.1",
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/home",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAfterLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAfterLogin);

  // 4. Member creates an article in the created category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 5 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. Member creates multiple attachments for the article
  const createAttachment = async (
    orderInArticle: number & tags.Type<"int32">,
    status: string,
  ): Promise<IDiscussionBoardAttachment> => {
    const attachmentBody = {
      file_uri: typia.random<string & tags.Format<"uri">>(),
      file_name: RandomGenerator.paragraph({ sentences: 2 }),
      content_type: RandomGenerator.pick([
        "image/png",
        "image/jpeg",
        "application/pdf",
      ] as const),
      file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
      order_in_article: orderInArticle,
      status,
    } satisfies IDiscussionBoardAttachment.ICreate;

    const created: IDiscussionBoardAttachment =
      await api.functional.discussionBoard.memberUser.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: attachmentBody,
        },
      );
    typia.assert(created);
    return created;
  };

  const attachment1 = await createAttachment(
    1 as number & tags.Type<"int32">,
    "active",
  );
  const attachment2 = await createAttachment(
    2 as number & tags.Type<"int32">,
    "active",
  );
  const attachment3 = await createAttachment(
    3 as number & tags.Type<"int32">,
    "hidden",
  );

  const createdIds: string[] = [attachment1.id, attachment2.id, attachment3.id];

  // 6. Baseline listing before deletion
  const listRequestBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardAttachment.IRequest;

  const baselinePage: IPageIDiscussionBoardAttachment.ISummary =
    await api.functional.discussionBoard.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: listRequestBody,
      },
    );
  typia.assert(baselinePage);

  const baselineIds: string[] = baselinePage.data.map((a) => a.id);

  // Ensure all created IDs are present in the baseline list
  for (const id of createdIds) {
    TestValidator.predicate(
      `baseline listing contains attachment ${id}`,
      baselineIds.includes(id),
    );
  }

  // Sanity check on pagination metadata
  const p1 = baselinePage.pagination;
  TestValidator.predicate(
    "baseline pagination records non-negative",
    p1.records >= 0,
  );
  TestValidator.predicate(
    "baseline pagination limit non-negative",
    p1.limit >= 0,
  );
  TestValidator.predicate(
    "baseline pagination pages non-negative",
    p1.pages >= 0,
  );

  const baselineVisibleCreatedCount = baselineIds.filter((id) =>
    createdIds.includes(id),
  ).length;

  TestValidator.predicate(
    "baseline listing includes all created attachments",
    baselineVisibleCreatedCount === createdIds.length,
  );

  // 7. Logically delete one attachment (attachment2)
  await api.functional.discussionBoard.memberUser.articles.attachments.erase(
    connection,
    {
      articleId: article.id,
      attachmentId: attachment2.id,
    },
  );

  // 8. Listing after deletion
  const afterDeletePage: IPageIDiscussionBoardAttachment.ISummary =
    await api.functional.discussionBoard.articles.attachments.index(
      connection,
      {
        articleId: article.id,
        body: listRequestBody,
      },
    );
  typia.assert(afterDeletePage);

  const afterDeleteIds: string[] = afterDeletePage.data.map((a) => a.id);

  // Deleted attachment must not appear
  TestValidator.predicate(
    "deleted attachment is not listed",
    !afterDeleteIds.includes(attachment2.id),
  );

  // Other attachments must still appear
  TestValidator.predicate(
    "attachment1 remains listed after deletion of attachment2",
    afterDeleteIds.includes(attachment1.id),
  );
  TestValidator.predicate(
    "attachment3 remains listed after deletion of attachment2",
    afterDeleteIds.includes(attachment3.id),
  );

  const afterPagination = afterDeletePage.pagination;
  TestValidator.predicate(
    "after-delete pagination records non-negative",
    afterPagination.records >= 0,
  );
  TestValidator.predicate(
    "after-delete pagination pages non-negative",
    afterPagination.pages >= 0,
  );

  const afterVisibleCreatedCount = afterDeleteIds.filter((id) =>
    createdIds.includes(id),
  ).length;

  TestValidator.predicate(
    "after-delete listing has one fewer visible created attachment",
    afterVisibleCreatedCount === createdIds.length - 1,
  );
}

