import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleOfMemberusersMemberAuthor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleOfMemberusersMemberAuthor";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate member author resolution behavior for existing vs. missing articles.
 *
 * Business context:
 *
 * - Articles can be authored by member users via the memberUser actor.
 * - The `GET /discussionBoard/articles/{articleId}/memberAuthor` endpoint returns
 *   a public projection of the member user who authored the article when the
 *   article exists and is linked to a member author via
 *   `discussion_board_article_of_memberusers`.
 * - When the article does not exist at all, the endpoint is expected to fail
 *   without returning any author DTO, providing clear consumer-facing semantics
 *   that the article context is invalid.
 *
 * This test sets up a realistic board environment with both admin and member
 * actors, creates required category master data, then verifies both the
 * successful and error-path behaviors of the member author endpoint.
 *
 * Steps:
 *
 * 1. Register an adminUser and rely on automatic authentication to obtain an admin
 *    session.
 * 2. As adminUser, create a discussion board article category that can be used for
 *    member-authored articles.
 * 3. Register a memberUser account and rely on automatic authentication to obtain
 *    a member session.
 * 4. As memberUser, create a control article assigned to the created category
 *    using POST /discussionBoard/memberUser/articles.
 * 5. Call GET /discussionBoard/articles/{articleId}/memberAuthor with the control
 *    article id and verify that:
 *
 *    - The call succeeds and returns an
 *         IDiscussionBoardArticleOfMemberusersMemberAuthor DTO.
 *    - The author.id matches the member user's id.
 *    - The author.displayName matches the member user's display_name field.
 * 6. Generate a random UUID that does not correspond to any existing article
 *    (overwhelmingly likely when using typia.random<uuid>()), and call the same
 *    memberAuthor endpoint with that non-existent articleId, wrapped in
 *    TestValidator.error to assert that an error is thrown and no author DTO is
 *    returned.
 *
 * This test does not verify detailed HTTP status codes or internal moderation
 * state transitions; instead, it focuses on externally observable behavior: a
 * valid member author is resolved for a real article, and no author information
 * is exposed when the article context is invalid or missing.
 */
export async function test_api_discussion_board_member_author_behavior_when_article_missing_or_removed(
  connection: api.IConnection,
) {
  // 1. Register an adminUser (automatic admin authentication via SDK)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As adminUser, create an article category
  const categoryCreateBody = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(category);

  // 3. Register a memberUser (automatic member authentication via SDK)
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword = RandomGenerator.alphaNumeric(16);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(1),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // Optionally, explicitly login again as memberUser to confirm login flow
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // Ensure the same member account is represented in both responses
  TestValidator.equals(
    "member id from join and login must match",
    memberAuthorizedFromLogin.id,
    memberAuthorizedFromJoin.id,
  );

  // 4. As memberUser, create a control article
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody },
    );
  typia.assert(article);

  // 5. Successful member author resolution for existing article
  const memberAuthor: IDiscussionBoardArticleOfMemberusersMemberAuthor =
    await api.functional.discussionBoard.articles.memberAuthor.at(connection, {
      articleId: article.id,
    });
  typia.assert(memberAuthor);

  // Validate that member author info matches the member user's identity
  TestValidator.equals(
    "member author id must equal member user id",
    memberAuthor.id,
    memberAuthorizedFromLogin.id,
  );
  TestValidator.equals(
    "member author displayName must equal member user's display_name",
    memberAuthor.displayName,
    memberAuthorizedFromLogin.display_name,
  );

  // 6. Error behavior when articleId does not exist
  let missingArticleId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // Extremely unlikely, but avoid accidentally reusing the real article id
  if (missingArticleId === article.id) {
    missingArticleId = typia.random<string & tags.Format<"uuid">>();
  }

  await TestValidator.error(
    "member author lookup must fail for non-existent article id",
    async () => {
      await api.functional.discussionBoard.articles.memberAuthor.at(
        connection,
        {
          articleId: missingArticleId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleOfAdminusersAdminAuthor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleOfAdminusersAdminAuthor";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate retrieval of admin author metadata for a discussion board article.
 *
 * Business context:
 *
 * - Some discussion board articles are authored by administrators. For such
 *   articles, the public-facing API exposes admin author metadata via GET
 *   /discussionBoard/articles/{articleId}/adminAuthor.
 * - The endpoint returns a trimmed DTO,
 *   IDiscussionBoardArticleOfAdminusersAdminAuthor, containing only fields that
 *   are safe and meaningful for public display (id, displayName, roleLabel).
 * - The endpoint itself is read-only and is expected to be publicly accessible,
 *   because admin author labels are typically shown alongside articles for all
 *   visitors.
 *
 * Test workflow:
 *
 * 1. Register an adminUser via POST /auth/adminUser/join to establish an
 *    administrative actor and session.
 * 2. As that adminUser, create a new article category via POST
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Register a memberUser via POST /auth/memberUser/join to represent a
 *    front-facing discussion participant, then keep their authenticated session
 *    active.
 * 4. As the memberUser, create a new discussion article via POST
 *    /discussionBoard/memberUser/articles using the admin-created category so
 *    that a valid articleId exists in discussion_board_articles.
 * 5. Call GET /discussionBoard/articles/{articleId}/adminAuthor using the
 *    articleId from step 4, without performing any manual header handling,
 *    relying on the SDK connection state.
 * 6. Validate that the response is a valid
 *    IDiscussionBoardArticleOfAdminusersAdminAuthor instance via typia.assert,
 *    and perform simple business assertions that displayName and roleLabel are
 *    non-empty strings.
 *
 * Notes and constraints:
 *
 * - The concrete mapping between an article and an admin author is driven by the
 *   internal discussion_board_article_of_adminusers relationship. Because we do
 *   not have an explicit public API to bind an article to a specific admin,
 *   this test focuses on validating the endpoint behavior and DTO shape for a
 *   real articleId but does not try to assert that the admin returned is
 *   exactly the adminUser created in step 1.
 * - The test avoids any negative or error-path scenarios, status-code assertions,
 *   or deliberate type errors. It strictly validates the happy path and type
 *   safety.
 */
export async function test_api_discussion_board_admin_author_retrieval_for_admin_authored_article(
  connection: api.IConnection,
) {
  // 1. AdminUser registration (join) to establish an administrative actor
  const adminJoinRequest =
    typia.random<IDiscussionBoardAdminUserJoin.IRequest>();

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminAuthorized);

  // 2. Create an article category as the authenticated adminUser
  const categoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. MemberUser registration (join) to represent a front-facing user
  const memberJoinRequest =
    typia.random<IDiscussionBoardMemberUserJoin.IRequest>();

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  // 4. Create a discussion article as the memberUser using the category id
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. Retrieve admin author information for the created article
  const adminAuthor: IDiscussionBoardArticleOfAdminusersAdminAuthor =
    await api.functional.discussionBoard.articles.adminAuthor.at(connection, {
      articleId: article.id,
    });
  typia.assert(adminAuthor);

  // 6. Business-level assertions on the returned admin author metadata
  TestValidator.predicate(
    "admin author displayName must be a non-empty string",
    typeof adminAuthor.displayName === "string" &&
      adminAuthor.displayName.length > 0,
  );

  TestValidator.predicate(
    "admin author roleLabel must be a non-empty string",
    typeof adminAuthor.roleLabel === "string" &&
      adminAuthor.roleLabel.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleOfAdminusersAdminAuthor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleOfAdminusersAdminAuthor";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that admin author lookup fails for member-authored articles.
 *
 * Business intent:
 *
 * - Articles written by regular member users must not expose any admin author
 *   information through the adminAuthor endpoint.
 * - Clients should be able to distinguish between "article has no admin author"
 *   and generic article-not-found conditions. In this test we focus on the
 *   former by ensuring that looking up an admin author for a member-authored
 *   article yields an error instead of returning an
 *   IDiscussionBoardArticleOfAdminusersAdminAuthor payload.
 *
 * End-to-end flow:
 *
 * 1. Register an adminUser account via /auth/adminUser/join and obtain
 *    authenticated admin context.
 * 2. As this adminUser, create a valid article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Register a memberUser account via /auth/memberUser/join and obtain an
 *    authenticated member context.
 * 4. As this memberUser, create a new article via
 *    /discussionBoard/memberUser/articles, using the previously created
 *    category id, guaranteeing that the resulting article is authored by a
 *    member, not an admin.
 * 5. Create an unauthenticated connection clone (no Authorization header).
 * 6. From that unauthenticated connection, call
 *    /discussionBoard/articles/{articleId}/adminAuthor for the member-authored
 *    article id.
 * 7. Assert that the call results in an error via TestValidator.error, which
 *    semantically represents "no admin author for this article" in this
 *    backend, rather than returning any admin author DTO.
 */
export async function test_api_discussion_board_admin_author_not_found_for_member_authored_article(
  connection: api.IConnection,
) {
  // 1. Admin user joins to get admin context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://example.com/admin/join",
    referrer: "https://example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryCreateBody = {
    code: `CAT-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Member user joins to get member context
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://example.com/member/join",
    referrer: "https://example.com/member/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates an article using the created category
  const createArticleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: createArticleBody,
      },
    );
  typia.assert(article);

  TestValidator.equals(
    "created article should reference the chosen category",
    article.category.id,
    category.id,
  );

  // 5. Create an unauthenticated connection (no Authorization header)
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 6-7. Calling adminAuthor for a member-authored article should fail
  await TestValidator.error(
    "admin author lookup must fail for member-authored article",
    async () => {
      await api.functional.discussionBoard.articles.adminAuthor.at(
        unauthenticated,
        {
          articleId: article.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleOfAdminusersAdminAuthor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleOfAdminusersAdminAuthor";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate admin author resolution behavior for existing vs. missing articles.
 *
 * ## Business intent
 *
 * The endpoint GET /discussionBoard/articles/{articleId}/adminAuthor exposes
 * public-facing information about the administrator account that authored a
 * specific article. It should only succeed when all of the following are true:
 *
 * - The target article row exists in discussion_board_articles.
 * - That article is linked to an admin author via
 *   discussion_board_article_of_adminusers.
 * - Moderation / visibility rules consider the article resolvable.
 *
 * In contrast, when the article does not exist at all, or when it is not
 * associated with any admin authorship record (for example because it is a
 * member-authored article or has been removed/hidden), the endpoint must not
 * leak any admin profile information and should fail with an appropriate
 * error.
 *
 * ## Available APIs and constraints
 *
 * - Admin authentication
 *
 *   - POST /auth/adminUser/join -> api.functional.auth.adminUser.join
 *
 *       - Body: IDiscussionBoardAdminUserJoin.IRequest
 *       - Response: IDiscussionBoardAdminuser.IAuthorized (also sets Authorization
 *               header)
 *   - POST /auth/adminUser/login -> api.functional.auth.adminUser.login
 *
 *       - Body: IDiscussionBoardAdminUserLogin.IRequest
 *       - Response: IDiscussionBoardAdminuser.IAuthorized (sets Authorization)
 * - Member authentication
 *
 *   - POST /auth/memberUser/join -> api.functional.auth.memberUser.join
 *
 *       - Body: IDiscussionBoardMemberUserJoin.IRequest
 *       - Response: IDiscussionBoardMemberuser.IAuthorized
 *   - POST /auth/memberUser/login -> api.functional.auth.memberUser.login
 *
 *       - Body: IDiscussionBoardMemberUserLogin.IRequest
 *       - Response: IDiscussionBoardMemberuser.IAuthorized
 * - Board configuration
 *
 *   - POST /discussionBoard/adminUser/articleCategories ->
 *       api.functional.discussionBoard.adminUser.articleCategories.create
 *
 *       - Body: IDiscussionBoardArticleCategory.ICreate
 *       - Response: IDiscussionBoardArticleCategory
 * - Member-authored articles
 *
 *   - POST /discussionBoard/memberUser/articles ->
 *       api.functional.discussionBoard.memberUser.articles.create
 *
 *       - Body: IDiscussionBoardArticle.ICreate
 *       - Response: IDiscussionBoardArticle
 * - Admin-author lookup target
 *
 *   - GET /discussionBoard/articles/{articleId}/adminAuthor ->
 *       api.functional.discussionBoard.articles.adminAuthor.at
 *
 *       - Props: { articleId: string }
 *       - Response: IDiscussionBoardArticleOfAdminusersAdminAuthor
 *
 * Even though the endpoint is described around admin-authored articles, we do
 * not have explicit APIs here to create such admin-authored articles or to
 * soft-delete / hide them. Therefore, this test focuses on behaviors the
 * current SDK can exercise safely:
 *
 * - A success control path calling adminAuthor.at() with a syntactically valid
 *   article id that the backend considers admin-authored (in simulation mode,
 *   typia.random is used by SDK, but in real environment this call may fail if
 *   no such article exists). We just assert the type of the response when the
 *   call succeeds.
 * - Error paths where articleId clearly does not map to any article or admin
 *   authorship, using TestValidator.error to ensure the endpoint fails and
 *   therefore does not return an author DTO.
 *
 * ## Test workflow
 *
 * 1. Register an adminUser via auth.adminUser.join and assert the token and
 *    profile structure. This both validates the join API and configures the
 *    `connection` Authorization header for admin-only endpoints.
 * 2. Using the admin session, create a discussion board article category via
 *    discussionBoard.adminUser.articleCategories.create with realistic random
 *    data. This ensures that subsequent article creation has a valid category
 *    to reference.
 * 3. Register a memberUser via auth.memberUser.join and assert the authorized
 *    structure. This switches Authorization to the member actor.
 * 4. As the memberUser, create a normal article via
 *    discussionBoard.memberUser.articles.create using the category id from step
 *    2. This gives us a real article id that is _not_ admin-authored in a
 *    typical deployment, but from the SDK perspective it is just a valid UUID
 *    in discussion_board_articles.
 * 5. Attempt to resolve admin author information for a clearly non-existent
 *    article by generating a fresh random UUID that should not correspond to
 *    any persisted article id in the test database. Wrap the call to
 *    discussionBoard.articles.adminAuthor.at in TestValidator.error to assert
 *    that the operation fails and therefore does not leak any
 *    IDiscussionBoardArticleOfAdminusersAdminAuthor payload.
 * 6. Attempt to resolve admin author information for the valid member-authored
 *    article id created in step 4. Depending on implementation details, this
 *    may either:
 *
 *    - Fail with a not-found or similar error because there is no admin-authorship
 *         record, or
 *    - In some implementations, still resolve authorship if the system treats all
 *         articles as potentially admin-authored. Therefore, this test uses a
 *         defensive pattern:
 *
 *         - First, try calling adminAuthor.at(article.id). If it succeeds, simply
 *                   typia.assert() the returned DTO to validate that the
 *                   payload matches
 *                   IDiscussionBoardArticleOfAdminusersAdminAuthor and stop
 *                   there.
 *         - If it fails, use TestValidator.error to confirm that failure is consistently
 *                   reported, and that in such cases no DTO is exposed.
 * 7. Finally, call adminAuthor.at() again with another fresh random UUID to
 *    reinforce the missing-article behavior and ensure we have coverage for
 *    multiple independent non-existent identifiers.
 *
 * ## Assertions and guarantees
 *
 * - All successful responses from join, category creation, article creation, and
 *   (if it succeeds) adminAuthor.at() are validated via typia.assert(),
 *   ensuring perfect runtime type conformity.
 * - TestValidator.error is used with descriptive titles wherever we expect the
 *   adminAuthor endpoint to fail (non-existent article ids or
 *   non-admin-authored articles in the failure branch).
 * - No attempt is made to inspect HTTP status codes or internal error payloads;
 *   we only assert that an error is thrown vs. not thrown, which is sufficient
 *   to guarantee that no IDiscussionBoardArticleOfAdminusersAdminAuthor DTO is
 *   returned in these negative scenarios.
 */
export async function test_api_discussion_board_admin_author_behavior_when_article_missing_or_removed(
  connection: api.IConnection,
) {
  // 1. Admin join - prepare an administrator actor and admin session
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.discussion-board.test/join",
    referrer: "https://admin.discussion-board.test/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create a category as admin for articles
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Member join - prepare a member actor and session
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://discussion-board.test/join",
    referrer: "https://discussion-board.test/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates a normal article under the configured category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const memberArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody },
    );
  typia.assert(memberArticle);

  // 5. Call adminAuthor for a clearly non-existent article id
  const nonExistentArticleId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "adminAuthor should fail for a non-existent article id",
    async () => {
      await api.functional.discussionBoard.articles.adminAuthor.at(connection, {
        articleId: nonExistentArticleId,
      });
    },
  );

  // 6. Call adminAuthor for an existing member-authored article id.
  //    Depending on backend, this may either succeed (admin-authored) or fail
  //    (no admin authorship). We handle both outcomes defensively.
  try {
    const adminAuthor: IDiscussionBoardArticleOfAdminusersAdminAuthor =
      await api.functional.discussionBoard.articles.adminAuthor.at(connection, {
        articleId: memberArticle.id,
      });
    typia.assert(adminAuthor);

    // Basic sanity check on returned admin author DTO when it does succeed.
    TestValidator.predicate(
      "adminAuthor id must be a non-empty string when returned",
      adminAuthor.id.length > 0,
    );
    TestValidator.predicate(
      "adminAuthor displayName must be a non-empty string when returned",
      adminAuthor.displayName.length > 0,
    );
    TestValidator.predicate(
      "adminAuthor roleLabel must be a non-empty string when returned",
      adminAuthor.roleLabel.length > 0,
    );
  } catch {
    await TestValidator.error(
      "adminAuthor should fail when no admin authorship exists for member article",
      async () => {
        await api.functional.discussionBoard.articles.adminAuthor.at(
          connection,
          { articleId: memberArticle.id },
        );
      },
    );
  }

  // 7. Re-assert missing behavior with another fresh random UUID
  const anotherMissingId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "adminAuthor must fail consistently for another non-existent article id",
    async () => {
      await api.functional.discussionBoard.articles.adminAuthor.at(connection, {
        articleId: anotherMissingId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleLike";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Basic flow for a member user listing their liked articles.
 *
 * Business workflow:
 *
 * 1. Register a new member user (join) and capture the member id and
 *    email/password.
 * 2. Register a new admin user (join) so that we can create an article category.
 * 3. As admin, create a concrete article category via
 *    discussionBoard.adminUser.articleCategories.create.
 * 4. Log back in as the member user to restore member context.
 * 5. As the member, create at least two articles in the created category.
 * 6. Like exactly one of the created articles.
 * 7. Call memberUser.members.likedArticles.index for that member with an article
 *    request body (page/limit/categoryId).
 * 8. Verify that:
 *
 *    - The liked article appears in the result list and its category matches.
 *    - The non-liked article does not appear.
 *    - Pagination metadata is consistent with a single liked article.
 * 9. Optionally re-query with a different limit and verify stable ordering when
 *    only one liked article exists.
 */
export async function test_api_member_liked_articles_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register member user
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = RandomGenerator.alphabets(12);

  const memberJoinRequest = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://frontend.example.com/join/member",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  const memberId = memberAuthorized.id;

  // 2. Register admin user
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinRequest = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinRequest,
    });
  typia.assert(adminAuthorized);

  // 3. As admin, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 1 }),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(category);

  // 4. Log back in as member user to ensure member context
  const memberLoginRequest = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://frontend.example.com/login/member",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorizedAgain: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginRequest,
    });
  typia.assert(memberAuthorizedAgain);

  // 5. Member creates at least two articles under the category
  const articleCreateBody1 = {
    title: RandomGenerator.paragraph({ sentences: 1 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article1: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody1 },
    );
  typia.assert(article1);

  const articleCreateBody2 = {
    title: RandomGenerator.paragraph({ sentences: 1 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article2: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody2 },
    );
  typia.assert(article2);

  // 6. Like exactly one article (article1)
  const likeCreateBody = {} satisfies IDiscussionBoardArticleLike.ICreate;

  const likeResult: IDiscussionBoardArticleLike =
    await api.functional.discussionBoard.memberUser.articles.likes.create(
      connection,
      {
        articleId: article1.id,
        body: likeCreateBody,
      },
    );
  typia.assert(likeResult);

  TestValidator.equals(
    "liked article in likeResult matches article1",
    likeResult.article.id,
    article1.id,
  );

  // 7. Query liked articles for this member with pagination and filters
  const likedArticlesRequestBody = {
    page: 1,
    limit: 10,
    search: undefined,
    categoryId: category.id,
    moderationState: undefined,
    createdFrom: undefined,
    createdTo: undefined,
    orderBy: "createdAt",
    orderDirection: "desc",
  } satisfies IDiscussionBoardArticle.IRequest;

  const likedPage: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: likedArticlesRequestBody,
      },
    );
  typia.assert(likedPage);

  const pagination: IPage.IPagination = likedPage.pagination;
  typia.assert(pagination);

  TestValidator.predicate(
    "liked articles pagination has at least one record",
    pagination.records >= 1,
  );
  TestValidator.predicate(
    "liked articles pagination pages is at least 1",
    pagination.pages >= 1,
  );

  const likedSummaries = likedPage.data;

  TestValidator.predicate(
    "at least one liked article summary is returned",
    likedSummaries.length >= 1,
  );

  const likedSummaryForArticle1 = likedSummaries.find(
    (summary) => summary.id === article1.id,
  );

  TestValidator.predicate(
    "liked article1 appears in liked articles list",
    likedSummaryForArticle1 !== undefined,
  );

  if (likedSummaryForArticle1 !== undefined) {
    TestValidator.equals(
      "liked article1 category matches created category",
      likedSummaryForArticle1.category.id,
      category.id,
    );
  }

  const summaryForArticle2 = likedSummaries.find(
    (summary) => summary.id === article2.id,
  );

  TestValidator.predicate(
    "unliked article2 does not appear in liked articles list",
    summaryForArticle2 === undefined,
  );

  // 8. Optional: re-query with different limit to ensure stable result when only one liked article exists
  const likedArticlesRequestBodyLimit1 = {
    page: 1,
    limit: 1,
    search: undefined,
    categoryId: category.id,
    moderationState: undefined,
    createdFrom: undefined,
    createdTo: undefined,
    orderBy: "createdAt",
    orderDirection: "desc",
  } satisfies IDiscussionBoardArticle.IRequest;

  const likedPageLimit1: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: likedArticlesRequestBodyLimit1,
      },
    );
  typia.assert(likedPageLimit1);

  if (likedPageLimit1.data.length > 0) {
    const firstSummary = likedPageLimit1.data[0];
    TestValidator.equals(
      "first liked article with limit 1 is article1",
      firstSummary.id,
      article1.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleLike";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

export async function test_api_member_liked_articles_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create member user (join)
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/join",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberId = memberAuthorized.id;

  // 2. Create admin user (join) to manage categories
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}-admin@example.com`,
    password: RandomGenerator.alphabets(16),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/admin/join",
    referrer: "https://frontend.local/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Create two article categories as admin
  const categoryABody = {
    code: `CAT_A_${RandomGenerator.alphabets(4)}`,
    name: "Category A",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;
  const categoryA: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryABody,
      },
    );
  typia.assert(categoryA);

  const categoryBBody = {
    code: `CAT_B_${RandomGenerator.alphabets(4)}`,
    name: "Category B",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 2,
  } satisfies IDiscussionBoardArticleCategory.ICreate;
  const categoryB: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBBody,
      },
    );
  typia.assert(categoryB);

  // 4. Switch to member user context via login (even though join already set token)
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);
  TestValidator.equals(
    "logged-in member id should match joined member id",
    memberLogin.id,
    memberId,
  );

  // 5. Create multiple articles as member across categories
  const targetPerCategory = 7;
  const otherPerCategory = 5;
  const createdCategoryA: IDiscussionBoardArticle[] = [];
  const createdCategoryB: IDiscussionBoardArticle[] = [];

  // Helper to create one article in a given category
  const createArticle = async (
    categoryId: string & tags.Format<"uuid">,
  ): Promise<IDiscussionBoardArticle> => {
    const body = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      body: RandomGenerator.content({ paragraphs: 2 }),
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId,
    } satisfies IDiscussionBoardArticle.ICreate;

    const article =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        {
          body,
        },
      );
    typia.assert(article);
    return article;
  };

  // Create articles in category A (enough to span 2 pages when liked)
  for (let i = 0; i < targetPerCategory; i += 1) {
    const article = await createArticle(categoryA.id);
    createdCategoryA.push(article);
  }

  // Create articles in category B
  for (let i = 0; i < otherPerCategory; i += 1) {
    const article = await createArticle(categoryB.id);
    createdCategoryB.push(article);
  }

  // 6. Like every created article as the same member
  const likeArticle = async (
    article: IDiscussionBoardArticle,
  ): Promise<void> => {
    const body = {} satisfies IDiscussionBoardArticleLike.ICreate;
    const like: IDiscussionBoardArticleLike =
      await api.functional.discussionBoard.memberUser.articles.likes.create(
        connection,
        {
          articleId: article.id,
          body,
        },
      );
    typia.assert(like);
    TestValidator.equals(
      "liked article summary id should match target article id",
      like.article.id,
      article.id,
    );
  };

  for (const article of [...createdCategoryA, ...createdCategoryB]) {
    await likeArticle(article);
  }

  // 7. Call likedArticles.index with category filter and pagination (page 1)
  const limit = 5;

  const requestPage1 = {
    page: 1,
    limit,
    categoryId: categoryA.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const page1: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: requestPage1,
      },
    );
  typia.assert(page1);

  TestValidator.predicate(
    "page1.data length must not exceed limit",
    page1.data.length <= limit,
  );

  for (const summary of page1.data) {
    TestValidator.equals(
      "page1 article category should match filter category",
      summary.category.id,
      categoryA.id,
    );
  }

  // 8. Call likedArticles.index for page 2 with same filter
  const requestPage2 = {
    page: 2,
    limit,
    categoryId: categoryA.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const page2: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: requestPage2,
      },
    );
  typia.assert(page2);

  TestValidator.predicate(
    "page2.data length must not exceed limit",
    page2.data.length <= limit,
  );

  for (const summary of page2.data) {
    TestValidator.equals(
      "page2 article category should match filter category",
      summary.category.id,
      categoryA.id,
    );
  }

  // Combine ids and ensure no overlap between page1 and page2 results
  const page1Ids = page1.data.map((s) => s.id);
  const page2Ids = page2.data.map((s) => s.id);

  for (const id of page1Ids) {
    TestValidator.predicate(
      "no overlap between page1 and page2 article ids",
      page2Ids.includes(id) === false,
    );
  }

  // Ensure returned ids are subset of created+liked category A articles
  const createdCategoryAIds = createdCategoryA.map((a) => a.id);
  const combinedIds = [...page1Ids, ...page2Ids];

  for (const id of combinedIds) {
    TestValidator.predicate(
      "returned liked article must be created in this test for category A",
      createdCategoryAIds.includes(id),
    );
  }

  // Validate pagination metadata consistency against expected total liked count in category A
  const expectedTotal = createdCategoryA.length;

  TestValidator.equals(
    "pagination.records should equal total liked articles in category A",
    page1.pagination.records,
    expectedTotal,
  );

  TestValidator.equals(
    "pagination.pages should be ceil(total/limit)",
    page1.pagination.pages,
    Math.ceil(expectedTotal / limit),
  );

  TestValidator.equals(
    "pagination limit should equal requested limit",
    page1.pagination.limit,
    limit,
  );

  TestValidator.predicate(
    "pagination.current for page1 should be within valid range (0-based)",
    page1.pagination.current >= 0 &&
      page1.pagination.current < page1.pagination.pages,
  );

  TestValidator.predicate(
    "pagination.current for page2 should be within valid range (0-based)",
    page2.pagination.current >= 0 &&
      page2.pagination.current < page2.pagination.pages,
  );

  // 9. Optional additional filter usage: ensure moderationState filter does not break contract
  const filterWithModerationState = {
    page: 1,
    limit,
    categoryId: categoryA.id,
    moderationState: page1.data[0]?.category.name ? undefined : undefined,
  } satisfies IDiscussionBoardArticle.IRequest;

  const pageWithModerationState: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: filterWithModerationState,
      },
    );
  typia.assert(pageWithModerationState);

  for (const summary of pageWithModerationState.data) {
    TestValidator.equals(
      "moderationState-filtered article category should match filter category",
      summary.category.id,
      categoryA.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardArticleLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleLike";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Verify that a member user's liked-articles listing only returns articles that
 * are both liked by the member and match the current visibility filters, and
 * that pagination metadata reflects only this visible subset.
 *
 * Business flow (adapted to available APIs):
 *
 * 1. Admin joins and becomes authenticated.
 * 2. Admin creates two categories (e.g., ECONOMY and POLITICS).
 * 3. A member user joins and becomes authenticated.
 * 4. The member creates three articles: two in ECONOMY, one in POLITICS.
 * 5. The member likes all three articles.
 * 6. The member calls the liked-articles index without filters and sees all three
 *    liked articles.
 * 7. The member calls liked-articles index filtered by the ECONOMY categoryId and
 *    sees only the two ECONOMY articles; the POLITICS article is effectively
 *    hidden by the filter.
 * 8. The member calls liked-articles index with a createdFrom filter in the future
 *    and gets an empty page; pagination metadata reports zero records.
 *
 * This simulates the visibility rules by using category- and date-based filters
 * instead of direct moderation/deletion toggles, which are not available in the
 * exposed SDK.
 */
export async function test_api_member_liked_articles_visibility_rules(
  connection: api.IConnection,
) {
  // 1. Admin joins
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@admin.test.com`,
    password: "AdminPw#123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.test.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.test.com/" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates two categories
  const economyCategoryBody = {
    code: `ECON_${RandomGenerator.alphaNumeric(4)}`,
    name: "Economy",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const politicsCategoryBody = {
    code: `POL_${RandomGenerator.alphaNumeric(4)}`,
    name: "Politics",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 2 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const economyCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: economyCategoryBody },
    );
  typia.assert(economyCategory);

  const politicsCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: politicsCategoryBody },
    );
  typia.assert(politicsCategory);

  // 3. Member joins
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@member.test.com` as string &
      tags.Format<"email">,
    password: "MemberPw#123",
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: null,
    href: "https://member.test.com/join" as string & tags.Format<"uri">,
    referrer: "https://member.test.com/" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberId = memberAuthorized.id;

  // 4. Member creates three articles
  const articleABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: economyCategory.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleBBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: economyCategory.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleCBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: politicsCategory.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleA: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleABody },
    );
  typia.assert(articleA);

  const articleB: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBBody },
    );
  typia.assert(articleB);

  const articleC: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCBody },
    );
  typia.assert(articleC);

  // 5. Member likes all three articles
  const likeABody = {} satisfies IDiscussionBoardArticleLike.ICreate;
  const likeBBody = {} satisfies IDiscussionBoardArticleLike.ICreate;
  const likeCBody = {} satisfies IDiscussionBoardArticleLike.ICreate;

  const likeA: IDiscussionBoardArticleLike =
    await api.functional.discussionBoard.memberUser.articles.likes.create(
      connection,
      { articleId: articleA.id, body: likeABody },
    );
  typia.assert(likeA);

  const likeB: IDiscussionBoardArticleLike =
    await api.functional.discussionBoard.memberUser.articles.likes.create(
      connection,
      { articleId: articleB.id, body: likeBBody },
    );
  typia.assert(likeB);

  const likeC: IDiscussionBoardArticleLike =
    await api.functional.discussionBoard.memberUser.articles.likes.create(
      connection,
      { articleId: articleC.id, body: likeCBody },
    );
  typia.assert(likeC);

  // 6. Liked articles without filters
  const likedAllBody = {} satisfies IDiscussionBoardArticle.IRequest;

  const likedAllPage: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: likedAllBody,
      },
    );
  typia.assert(likedAllPage);

  const likedAllIds = likedAllPage.data.map((s) => s.id);

  TestValidator.predicate(
    "liked-articles index without filters returns all liked articles",
    likedAllIds.includes(articleA.id) &&
      likedAllIds.includes(articleB.id) &&
      likedAllIds.includes(articleC.id),
  );

  TestValidator.equals(
    "pagination.records should equal number of liked articles (3)",
    likedAllPage.pagination.records,
    3,
  );

  // 7. Liked articles filtered by ECONOMY category
  const likedEconomyBody = {
    categoryId: economyCategory.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const likedEconomyPage: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: likedEconomyBody,
      },
    );
  typia.assert(likedEconomyPage);

  const likedEconomyIds = likedEconomyPage.data.map((s) => s.id);

  TestValidator.predicate(
    "economy-filtered liked-articles contains A and B",
    likedEconomyIds.includes(articleA.id) &&
      likedEconomyIds.includes(articleB.id),
  );

  TestValidator.predicate(
    "economy-filtered liked-articles excludes C (different category)",
    likedEconomyIds.includes(articleC.id) === false,
  );

  TestValidator.equals(
    "economy-filtered pagination.records equals 2",
    likedEconomyPage.pagination.records,
    2,
  );

  // 8. Liked articles filtered by future createdFrom so that no articles match
  const futureFrom = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString();
  const likedFutureBody = {
    createdFrom: futureFrom,
  } satisfies IDiscussionBoardArticle.IRequest;

  const likedFuturePage: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.memberUser.members.likedArticles.index(
      connection,
      {
        memberUserId: memberId,
        body: likedFutureBody,
      },
    );
  typia.assert(likedFuturePage);

  TestValidator.equals(
    "future-filtered liked-articles should have empty data",
    likedFuturePage.data.length,
    0,
  );

  TestValidator.equals(
    "future-filtered pagination.records should be 0",
    likedFuturePage.pagination.records,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

export async function test_api_article_comments_basic_listing(
  connection: api.IConnection,
) {
  // 1. Admin setup: register an adminUser (auto-authenticated via SDK)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 3. Member setup: register memberUser (auto-authenticated via SDK)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: null,
    href: "https://board.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://board.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates a primary article under the category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  // 5. Member creates several comments on the primary article
  const createdComments: IDiscussionBoardComment[] = [];
  const commentCount = 3;

  for (let i = 0; i < commentCount; ++i) {
    const commentBody = {
      body: RandomGenerator.paragraph({ sentences: 4 }),
    } satisfies IDiscussionBoardComment.ICreate;

    const comment: IDiscussionBoardComment =
      await api.functional.discussionBoard.memberUser.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: commentBody,
        },
      );
    typia.assert(comment);
    createdComments.push(comment);
  }

  // 6. Create another article and one comment to ensure isolation
  const otherArticleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 1 }),
    summary: RandomGenerator.paragraph({ sentences: 1 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const otherArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: otherArticleBody,
      },
    );
  typia.assert(otherArticle);

  const otherCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const otherComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: otherArticle.id,
        body: otherCommentBody,
      },
    );
  typia.assert(otherComment);

  // 7. Invoke listing API for the primary article
  const listRequestBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    orderBy: "created_at",
    orderDirection: "asc",
  } satisfies IDiscussionBoardComment.IRequest;

  const page: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: listRequestBody,
    });
  typia.assert(page);

  const pagination = page.pagination;
  const summaries = page.data;

  // 8. Validate pagination metadata
  TestValidator.predicate(
    "pagination.limit should be at least created comment count",
    pagination.limit >= createdComments.length,
  );
  TestValidator.predicate(
    "pagination.records should be at least created comment count",
    pagination.records >= createdComments.length,
  );
  TestValidator.predicate(
    "pagination.pages should be at least 1 when comments exist",
    pagination.pages >= 1,
  );

  // 9. Validate that all returned summaries belong to the primary article
  for (const summary of summaries) {
    TestValidator.equals(
      "each summary.article.id must match primary article id",
      summary.article.id,
      article.id,
    );
  }

  // 10. Validate that all createdComments are included in the listing
  for (const created of createdComments) {
    const found = summaries.some((s) => s.id === created.id);
    TestValidator.predicate(
      "created comment must be present in listing",
      found,
    );
  }

  // 11. Ensure comments from other article are not included
  const otherFound = summaries.some((s) => s.article.id === otherArticle.id);
  TestValidator.predicate(
    "comments from other articles must not be present in listing",
    otherFound === false,
  );

  // 12. Validate ordering by createdAt ascending
  const sortedByCreatedAt = [...summaries].sort((a, b) =>
    a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : 0,
  );

  TestValidator.equals(
    "listing should be ordered by createdAt ascending",
    summaries,
    sortedByCreatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

/**
 * Validate pagination and sorting of comments on a busy article.
 *
 * Business scenario:
 *
 * - An admin user defines an article category for the board.
 * - A member user joins the discussion board and creates a single article under
 *   that category.
 * - The member then posts many comments on that article so that multiple pages of
 *   comments are required when listing.
 * - The listing endpoint PATCH /discussionBoard/articles/{articleId}/comments is
 *   invoked with different pagination and sorting options to verify that it
 *   slices and orders comments correctly.
 *
 * Steps:
 *
 * 1. Register an admin user (join) and let the SDK attach its token.
 * 2. As admin, create a discussion-board article category.
 * 3. Register a member user (join) to get a member session.
 * 4. As member, create one article under the created category.
 * 5. As member, create N comments (e.g., 17) on that article, capturing their IDs
 *    and createdAt timestamps using typia.assert on each
 *    IDiscussionBoardComment response.
 * 6. Call the comments index endpoint for page=1, limit=10, orderBy="created_at",
 *    orderDirection="asc" and assert:
 *
 *    - Pagination.current === 0 (first page, zero-based)
 *    - Pagination.limit === 10
 *    - Pagination.records === N
 *    - Pagination.pages === Math.ceil(N / 10)
 *    - Data.length === Math.min(10, N)
 *    - Data is sorted by createdAt ascending
 * 7. Call the comments index endpoint for page=2 with same sorting and assert:
 *
 *    - Pagination.current === 1
 *    - Data contains the remaining comments (N - 10 items)
 *    - No overlap of IDs between page 1 and page 2
 * 8. Call the index endpoint again with page=1 but orderDirection="desc" and
 *    assert:
 *
 *    - Data is sorted by createdAt descending
 *    - Data[0] has a createdAt greater than or equal to all other comments returned
 *         in this page
 * 9. Cross-check that the union of IDs from asc pages equals the set of IDs
 *    observed when creating comments.
 */
export async function test_api_article_comments_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register an admin user (join)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassword123!",
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 3. Register a member user (join)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "MemberPassword123!";

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: null,
    href: "https://member.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://member.example.com/" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As member, create one article under the created category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  // 5. As member, create N comments on that article
  const commentCount = 17;
  const createdComments: IDiscussionBoardComment[] = [];

  for (let i = 0; i < commentCount; i++) {
    const commentBody = {
      body: `Comment #${i + 1}: ${RandomGenerator.paragraph({
        sentences: 3,
      })}`,
    } satisfies IDiscussionBoardComment.ICreate;

    const created: IDiscussionBoardComment =
      await api.functional.discussionBoard.memberUser.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: commentBody,
        },
      );
    typia.assert(created);
    createdComments.push(created);
  }

  // Sort local copies by created_at to have a ground truth ordering
  const ascByCreatedAt = [...createdComments].sort((a, b) =>
    a.created_at.localeCompare(b.created_at),
  );

  // 6. Call comments index for page=1, limit=10, asc
  const page1AscRequest = {
    page: 1,
    limit: 10,
    orderBy: "created_at",
    orderDirection: "asc",
  } satisfies IDiscussionBoardComment.IRequest;

  const page1Asc: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: page1AscRequest,
    });
  typia.assert(page1Asc);

  const pagination1 = page1Asc.pagination;
  const data1 = page1Asc.data;

  // pagination assertions
  TestValidator.equals(
    "page1 current should be 0 (zero-based)",
    pagination1.current,
    0,
  );
  TestValidator.equals("page1 limit should be 10", pagination1.limit, 10);
  TestValidator.equals(
    "pagination.records should equal total commentCount",
    pagination1.records,
    commentCount,
  );

  const expectedPages = Math.ceil(commentCount / 10);
  TestValidator.equals(
    "pagination.pages should match ceil(commentCount/limit)",
    pagination1.pages,
    expectedPages,
  );

  TestValidator.equals(
    "page1 data length should be min(limit, commentCount)",
    data1.length,
    Math.min(10, commentCount),
  );

  // data1 should correspond to earliest 10 comments in ascByCreatedAt
  const expectedPage1Ids = ascByCreatedAt.slice(0, 10).map((c) => c.id);
  const actualPage1Ids = data1.map((s) => s.id);

  TestValidator.equals(
    "page1 IDs should equal earliest 10 comment IDs in asc order",
    actualPage1Ids,
    expectedPage1Ids,
  );

  // ensure data1 sorted by createdAt ascending
  for (let i = 1; i < data1.length; i++) {
    const prev = data1[i - 1].createdAt;
    const curr = data1[i].createdAt;
    TestValidator.predicate(
      `page1 ascending order at index ${i}`,
      prev <= curr,
    );
  }

  // 7. Call comments index for page=2, same sorting
  const page2AscRequest = {
    page: 2,
    limit: 10,
    orderBy: "created_at",
    orderDirection: "asc",
  } satisfies IDiscussionBoardComment.IRequest;

  const page2Asc: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: page2AscRequest,
    });
  typia.assert(page2Asc);

  const pagination2 = page2Asc.pagination;
  const data2 = page2Asc.data;

  TestValidator.equals(
    "page2 current should be 1 (zero-based)",
    pagination2.current,
    1,
  );
  TestValidator.equals("page2 limit should be 10", pagination2.limit, 10);
  TestValidator.equals(
    "page2 records should equal total commentCount",
    pagination2.records,
    commentCount,
  );

  const expectedPage2Length = Math.max(commentCount - 10, 0);
  TestValidator.equals(
    "page2 data length should be remaining comments",
    data2.length,
    expectedPage2Length,
  );

  const expectedPage2Ids = ascByCreatedAt.slice(10).map((c) => c.id);
  const actualPage2Ids = data2.map((s) => s.id);

  TestValidator.equals(
    "page2 IDs should equal remaining comment IDs in asc order",
    actualPage2Ids,
    expectedPage2Ids,
  );

  // Ensure no overlap between page1 and page2 IDs
  const page1IdSet = new Set(actualPage1Ids);
  const hasOverlap = actualPage2Ids.some((id) => page1IdSet.has(id));
  TestValidator.predicate(
    "page1 and page2 should have no overlapping IDs",
    hasOverlap === false,
  );

  // 8. Call index with desc ordering on page=1
  const page1DescRequest = {
    page: 1,
    limit: 10,
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies IDiscussionBoardComment.IRequest;

  const page1Desc: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: page1DescRequest,
    });
  typia.assert(page1Desc);

  const dataDesc = page1Desc.data;
  TestValidator.equals(
    "desc page1 data length should be min(limit, commentCount)",
    dataDesc.length,
    Math.min(10, commentCount),
  );

  // Ensure dataDesc sorted by createdAt descending
  for (let i = 1; i < dataDesc.length; i++) {
    const prev = dataDesc[i - 1].createdAt;
    const curr = dataDesc[i].createdAt;
    TestValidator.predicate(
      `page1 descending order at index ${i}`,
      prev >= curr,
    );
  }

  // 9. Cross-check that union of IDs from asc pages equals created comment IDs
  const allAscIds = [...actualPage1Ids, ...actualPage2Ids];
  const allAscIdSet = new Set(allAscIds);
  const createdIdSet = new Set(createdComments.map((c) => c.id));

  TestValidator.equals(
    "union of asc page IDs should cover all created comment IDs",
    allAscIdSet.size,
    createdIdSet.size,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";

/**
 * Validate search and status filtering behavior of article comments listing.
 *
 * Business flow:
 *
 * 1. Register an admin user and a member user, relying on SDK auth helpers to
 *    attach tokens.
 * 2. As admin, create an article category.
 * 3. As member user, create an article in that category.
 * 4. As the same member user, create multiple comments on that article with bodies
 *    containing different keywords (some with "economy" and others with
 *    "politics").
 * 5. Call the comments listing endpoint with a search term "economy" and no status
 *    filter and verify that only comments whose body contains the keyword are
 *    returned, scoped to the correct article, and that pagination metadata is
 *    consistent with the result size.
 * 6. Discover one or more status values from the created comments via an
 *    unfiltered listing call; pick one status value.
 * 7. Call the listing endpoint again with search omitted and status set to the
 *    chosen value, verifying that all returned comments have that status and
 *    belong to the article, and that pagination is self-consistent.
 * 8. If a second distinct status exists, call the endpoint once more with that
 *    other status and verify that the resulting comment ids differ from the
 *    first status-filtered set, demonstrating that status filtering changes the
 *    view.
 * 9. In all listing calls, request orderBy="created_at" and orderDirection="asc"
 *    and verify that the resulting comments are non-decreasing by createdAt.
 */
export async function test_api_article_comments_search_and_status_filtering(
  connection: api.IConnection,
) {
  // 1. Register admin user (join) - token automatically stored in connection.headers
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassword!1" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create an article category
  const categoryBody = {
    code: `ECONOMY_${RandomGenerator.alphaNumeric(8)}`,
    name: "Economy Category",
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Register member user
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassword!1",
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://member.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://member.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As member user, create an article in the created category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 4 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. Create multiple comments (with and without the keyword "economy")
  const keyword = "economy";

  const economyBodies: string[] = ArrayUtil.repeat(3, () => {
    const prefix = RandomGenerator.paragraph({ sentences: 2 });
    const suffix = RandomGenerator.paragraph({ sentences: 2 });
    return `${prefix} ${keyword} ${suffix}`;
  });

  const politicsBodies: string[] = ArrayUtil.repeat(3, () => {
    const prefix = RandomGenerator.paragraph({ sentences: 2 });
    const suffix = RandomGenerator.paragraph({ sentences: 2 });
    return `${prefix} politics ${suffix}`;
  });

  const allBodies: string[] = [...economyBodies, ...politicsBodies];

  const createdComments: IDiscussionBoardComment[] = await ArrayUtil.asyncMap(
    allBodies,
    async (bodyText, index) => {
      const createBody = {
        body: bodyText,
      } satisfies IDiscussionBoardComment.ICreate;

      const comment: IDiscussionBoardComment =
        await api.functional.discussionBoard.memberUser.articles.comments.create(
          connection,
          {
            articleId: article.id,
            body: createBody,
          },
        );
      typia.assert(comment);

      TestValidator.equals(
        `created comment belongs to correct article [index=${index}]`,
        comment.article.id,
        article.id,
      );

      return comment;
    },
  );

  // 6. Initial unfiltered listing to discover statuses and verify scoping
  const initialList: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 50 as number & tags.Type<"int32">,
        orderBy: "created_at",
        orderDirection: "asc",
        search: undefined,
        status: undefined,
      },
    });
  typia.assert(initialList);

  const paginationInitial: IPage.IPagination = initialList.pagination;
  TestValidator.predicate(
    "initial listing pagination has non-negative records",
    paginationInitial.records >= 0,
  );

  // Verify all comments belong to the same article and ordering by createdAt asc
  const initialData = initialList.data;
  for (let i = 0; i < initialData.length; i++) {
    const summary = initialData[i];
    TestValidator.equals(
      `initial listing comment belongs to target article [index=${i}]`,
      summary.article.id,
      article.id,
    );
  }
  for (let i = 1; i < initialData.length; i++) {
    const prev = initialData[i - 1];
    const curr = initialData[i];
    TestValidator.predicate(
      `initial listing is ordered by createdAt asc [index=${i}]`,
      prev.createdAt <= curr.createdAt,
    );
  }

  // Collect distinct status values from the fully created comments
  const statusById = new Map<string, string>();
  for (const comment of createdComments) {
    statusById.set(comment.id, comment.status);
  }

  const distinctStatuses: string[] = [];
  for (const comment of createdComments) {
    const status = comment.status;
    if (!distinctStatuses.includes(status)) distinctStatuses.push(status);
  }

  TestValidator.predicate(
    "at least one status value discovered",
    distinctStatuses.length >= 1,
  );

  const primaryStatus: string = distinctStatuses[0];
  const secondaryStatus: string | undefined =
    distinctStatuses.length > 1 ? distinctStatuses[1] : undefined;

  // 7. Search filtering: search="economy" without status
  const searchList: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 50 as number & tags.Type<"int32">,
        orderBy: "created_at",
        orderDirection: "asc",
        search: keyword,
        status: undefined,
      },
    });
  typia.assert(searchList);

  const searchPagination: IPage.IPagination = searchList.pagination;
  const searchData = searchList.data;

  TestValidator.equals(
    "search listing records equals data length (single page)",
    searchPagination.records,
    searchData.length,
  );

  for (let i = 0; i < searchData.length; i++) {
    const summary = searchData[i];
    TestValidator.equals(
      `search listing comment belongs to target article [index=${i}]`,
      summary.article.id,
      article.id,
    );
    TestValidator.predicate(
      `search listing comment body contains keyword '${keyword}' [index=${i}]`,
      createdComments.some(
        (c) => c.id === summary.id && c.body.includes(keyword),
      ),
    );
  }

  for (let i = 1; i < searchData.length; i++) {
    const prev = searchData[i - 1];
    const curr = searchData[i];
    TestValidator.predicate(
      `search listing is ordered by createdAt asc [index=${i}]`,
      prev.createdAt <= curr.createdAt,
    );
  }

  // 8. Status-only filtering with primaryStatus (no search)
  const statusList: IPageIDiscussionBoardComment.ISummary =
    await api.functional.discussionBoard.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 50 as number & tags.Type<"int32">,
        orderBy: "created_at",
        orderDirection: "asc",
        search: undefined,
        status: primaryStatus,
      },
    });
  typia.assert(statusList);

  const statusPagination: IPage.IPagination = statusList.pagination;
  const statusData = statusList.data;

  TestValidator.equals(
    "status listing records equals data length (single page) for primary status",
    statusPagination.records,
    statusData.length,
  );

  for (let i = 0; i < statusData.length; i++) {
    const summary = statusData[i];
    TestValidator.equals(
      `status listing (primary) belongs to target article [index=${i}]`,
      summary.article.id,
      article.id,
    );
    TestValidator.equals(
      `status listing (primary) has expected status [index=${i}]`,
      statusById.get(summary.id),
      primaryStatus,
    );
  }

  for (let i = 1; i < statusData.length; i++) {
    const prev = statusData[i - 1];
    const curr = statusData[i];
    TestValidator.predicate(
      `status listing (primary) ordered by createdAt asc [index=${i}]`,
      prev.createdAt <= curr.createdAt,
    );
  }

  // 9. If a secondary status exists, verify that filtering by it yields a different set
  if (secondaryStatus !== undefined) {
    const secondaryList: IPageIDiscussionBoardComment.ISummary =
      await api.functional.discussionBoard.articles.comments.index(connection, {
        articleId: article.id,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 50 as number & tags.Type<"int32">,
          orderBy: "created_at",
          orderDirection: "asc",
          search: undefined,
          status: secondaryStatus,
        },
      });
    typia.assert(secondaryList);

    const secondaryData = secondaryList.data;

    for (let i = 0; i < secondaryData.length; i++) {
      const summary = secondaryData[i];
      TestValidator.equals(
        `status listing (secondary) belongs to target article [index=${i}]`,
        summary.article.id,
        article.id,
      );
      TestValidator.equals(
        `status listing (secondary) has expected secondary status [index=${i}]`,
        statusById.get(summary.id),
        secondaryStatus,
      );
    }

    // Ensure that the set of ids for secondary status does not overlap with primary status ids
    const primaryIds = statusData.map((s) => s.id);
    const secondaryIds = secondaryData.map((s) => s.id);
    const hasOverlap = secondaryIds.some((id) => primaryIds.includes(id));

    TestValidator.predicate(
      "primary and secondary status result sets should be disjoint",
      hasOverlap === false,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserNotificationPreference";

/**
 * Validate initial setup of member notification preferences after registration
 * and first article creation.
 *
 * Business context: A new discussion board member typically goes through
 * onboarding where they:
 *
 * - Register an account
 * - The platform has at least one category configured by an admin
 * - They post at least one article
 * - Then they configure notification preferences (activity, digest, marketing)
 *
 * This test validates that a freshly registered member user can configure their
 * own notification preferences through the dedicated endpoint after having
 * created an article, and that the server stores and returns those preferences
 * consistently, including idempotent behavior for repeated PUT calls.
 *
 * Steps:
 *
 * 1. Register member user via /auth/memberUser/join, capturing the credential
 *    information (email/password) for later re-login.
 * 2. Register admin user via /auth/adminUser/join.
 * 3. (Optional) Re-login as admin via /auth/adminUser/login to demonstrate token
 *    switching is safe; SDK will update Authorization header accordingly.
 * 4. As admin, create an article category via
 *    /discussionBoard/adminUser/articleCategories with a unique `code`, plus
 *    name/description/order.
 * 5. Switch authentication back to the member user via /auth/memberUser/login
 *    using the original member credentials.
 * 6. As the member, create a discussion article via
 *    /discussionBoard/memberUser/articles using IDiscussionBoardArticle.ICreate
 *    with the categoryId from step 4.
 * 7. Call PUT /discussionBoard/memberUser/notifications/memberUser/preferences
 *    with IDiscussionBoardMemberuserNotificationPreference.IUpdate, setting:
 *
 *    - Activity_notifications_enabled = true
 *    - Digest_notifications_enabled = true
 *    - Marketing_notifications_enabled = false
 * 8. Assert that the returned IDiscussionBoardMemberuserNotificationPreference has
 *    flags matching the request and a coherent created_at/updated_at ordering.
 * 9. Call the same PUT again with the identical payload and verify:
 *
 *    - Flags remain the same
 *    - Updated_at is not earlier than the first response's updated_at
 */
export async function test_api_member_notification_preferences_initial_setup_after_registration(
  connection: api.IConnection,
) {
  // 1. Register member user
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register admin user
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. (Optional) Re-login as admin using explicit login endpoint
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 4. Create article category as admin
  const categoryCodeBase = "ECONOMY";
  const categoryCode = `${categoryCodeBase}_${RandomGenerator.alphaNumeric(8)}`;

  const categoryCreateBody = {
    code: categoryCode,
    name: "Economy & Markets",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  TestValidator.equals(
    "article category code should match request",
    category.code,
    categoryCreateBody.code,
  );

  // 5. Switch back to member user via login to ensure current actor is member
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoginAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 6. Create an article as the member user using the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  TestValidator.equals(
    "article category id should match assigned category",
    article.category.id,
    category.id,
  );

  // 7. First notification preference update as member user
  const preferenceUpdateBody = {
    activity_notifications_enabled: true,
    digest_notifications_enabled: true,
    marketing_notifications_enabled: false,
  } satisfies IDiscussionBoardMemberuserNotificationPreference.IUpdate;

  const preference1: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.update(
      connection,
      {
        body: preferenceUpdateBody,
      },
    );
  typia.assert(preference1);

  TestValidator.equals(
    "activity flag should match first update payload",
    preference1.activity_notifications_enabled,
    preferenceUpdateBody.activity_notifications_enabled,
  );
  TestValidator.equals(
    "digest flag should match first update payload",
    preference1.digest_notifications_enabled,
    preferenceUpdateBody.digest_notifications_enabled,
  );
  TestValidator.equals(
    "marketing flag should match first update payload",
    preference1.marketing_notifications_enabled,
    preferenceUpdateBody.marketing_notifications_enabled,
  );

  // created_at should not be after updated_at (created_at <= updated_at)
  TestValidator.predicate("created_at should be <= updated_at", () => {
    const created = new Date(preference1.created_at).getTime();
    const updated = new Date(preference1.updated_at).getTime();
    return created <= updated;
  });

  // 8. Second call for idempotency check
  const preference2: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.update(
      connection,
      {
        body: preferenceUpdateBody,
      },
    );
  typia.assert(preference2);

  // Flags must remain identical
  TestValidator.equals(
    "activity flag should remain identical on second update",
    preference2.activity_notifications_enabled,
    preferenceUpdateBody.activity_notifications_enabled,
  );
  TestValidator.equals(
    "digest flag should remain identical on second update",
    preference2.digest_notifications_enabled,
    preferenceUpdateBody.digest_notifications_enabled,
  );
  TestValidator.equals(
    "marketing flag should remain identical on second update",
    preference2.marketing_notifications_enabled,
    preferenceUpdateBody.marketing_notifications_enabled,
  );

  // updated_at on second response should be >= first updated_at
  TestValidator.predicate(
    "second updated_at should be >= first updated_at for idempotent update",
    () => {
      const updated1 = new Date(preference1.updated_at).getTime();
      const updated2 = new Date(preference2.updated_at).getTime();
      return updated2 >= updated1;
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
