import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardAdminuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserNotificationPreference";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that admin notification preferences read endpoint reflects the
 * latest state after updates.
 *
 * Business context:
 *
 * - Admin users in the discussion board have a 1:1 notification preference record
 *   controlling three categories of notifications: activity, digest, and
 *   marketing.
 * - The UI typically loads preferences via GET
 *   `/discussionBoard/adminUser/notifications/adminUser/preferences` and
 *   persists changes via PUT on the same path.
 *
 * This test ensures that:
 *
 * 1. After an admin updates their notification preferences via PUT, the subsequent
 *    GET returns those exact flag values.
 * 2. Repeating updates with different combinations of flags always results in the
 *    GET endpoint reflecting the latest persisted state.
 * 3. The same underlying preference record (id) is reused across updates, and
 *    updated_at is refreshed after changes.
 *
 * High-level steps:
 *
 * 1. Join as a new adminUser using POST /auth/adminUser/join.
 * 2. As that adminUser, create an article category to sanity-check admin context
 *    using POST /discussionBoard/adminUser/articleCategories.
 * 3. Perform a first preferences update with a specific boolean combination
 *    (activity=true, digest=true, marketing=false).
 * 4. GET the preferences and assert flag equality and type validity.
 * 5. Perform a second preferences update with a different combination
 *    (activity=false, digest=true, marketing=true).
 * 6. GET the preferences again and assert that the latest flags are reflected, id
 *    is stable, and updated_at has changed.
 */
export async function test_api_admin_notification_preferences_after_external_change(
  connection: api.IConnection,
) {
  // 1. Register a new admin user (join) and get authorized session
  const joinBody = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create an article category as this admin to sanity-check
  //    admin-only capabilities and context
  const categoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. First update of notification preferences
  const firstUpdateBody: IDiscussionBoardAdminuserNotificationPreference.IUpdate =
    {
      activity_notifications_enabled: true,
      digest_notifications_enabled: true,
      marketing_notifications_enabled: false,
    };

  const afterFirstUpdate: IDiscussionBoardAdminuserNotificationPreference =
    await api.functional.discussionBoard.adminUser.notifications.adminUser.preferences.update(
      connection,
      {
        body: firstUpdateBody,
      },
    );
  typia.assert(afterFirstUpdate);

  // Capture baseline id and updated_at for later comparison
  const basePreferenceId = afterFirstUpdate.id;
  const baseUpdatedAt = afterFirstUpdate.updated_at;

  // 4. Read preferences immediately after first update
  const afterFirstGet: IDiscussionBoardAdminuserNotificationPreference =
    await api.functional.discussionBoard.adminUser.notifications.adminUser.preferences.at(
      connection,
    );
  typia.assert(afterFirstGet);

  // Validate that GET matches the first update payload and id is stable
  TestValidator.equals(
    "id should remain stable after first update/get",
    afterFirstGet.id,
    basePreferenceId,
  );
  TestValidator.equals(
    "activity flag should match first update",
    afterFirstGet.activity_notifications_enabled,
    firstUpdateBody.activity_notifications_enabled,
  );
  TestValidator.equals(
    "digest flag should match first update",
    afterFirstGet.digest_notifications_enabled,
    firstUpdateBody.digest_notifications_enabled,
  );
  TestValidator.equals(
    "marketing flag should match first update",
    afterFirstGet.marketing_notifications_enabled,
    firstUpdateBody.marketing_notifications_enabled,
  );

  // 5. Second update with a different combination of flags
  const secondUpdateBody: IDiscussionBoardAdminuserNotificationPreference.IUpdate =
    {
      activity_notifications_enabled: false,
      digest_notifications_enabled: true,
      marketing_notifications_enabled: true,
    };

  const afterSecondUpdate: IDiscussionBoardAdminuserNotificationPreference =
    await api.functional.discussionBoard.adminUser.notifications.adminUser.preferences.update(
      connection,
      {
        body: secondUpdateBody,
      },
    );
  typia.assert(afterSecondUpdate);

  // Ensure id is still the same preference record
  TestValidator.equals(
    "id should remain the same across updates",
    afterSecondUpdate.id,
    basePreferenceId,
  );

  // 6. Read preferences again after second update
  const afterSecondGet: IDiscussionBoardAdminuserNotificationPreference =
    await api.functional.discussionBoard.adminUser.notifications.adminUser.preferences.at(
      connection,
    );
  typia.assert(afterSecondGet);

  // Validate that GET reflects the second update flags
  TestValidator.equals(
    "activity flag should match second update",
    afterSecondGet.activity_notifications_enabled,
    secondUpdateBody.activity_notifications_enabled,
  );
  TestValidator.equals(
    "digest flag should match second update",
    afterSecondGet.digest_notifications_enabled,
    secondUpdateBody.digest_notifications_enabled,
  );
  TestValidator.equals(
    "marketing flag should match second update",
    afterSecondGet.marketing_notifications_enabled,
    secondUpdateBody.marketing_notifications_enabled,
  );

  // Confirm preference id stability after second GET
  TestValidator.equals(
    "id should remain stable after second update/get",
    afterSecondGet.id,
    basePreferenceId,
  );

  // Optional: updated_at should have advanced at least once compared
  // to the baseline captured after the first update. We only check
  // inequality to avoid assumptions on exact time ordering format.
  TestValidator.notEquals(
    "updated_at should change after at least one subsequent update",
    afterSecondGet.updated_at,
    baseUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

export async function test_api_discussion_board_articles_list_basic_browsing(
  connection: api.IConnection,
) {
  // 1. Admin user join (also authenticates as adminUser)
  const adminJoinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinInput,
    });
  typia.assert(adminAuthorized);

  // 2. Create an article category as admin
  const categoryCode = `CAT_${RandomGenerator.alphaNumeric(8)}`;
  const categoryCreateBody = {
    code: categoryCode,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Member user join (also authenticates as memberUser)
  const memberJoinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinInput,
    });
  typia.assert(memberAuthorized);

  // 4. Create multiple articles as the member user in that category
  const articleCount = 3;
  const createdArticles: IDiscussionBoardArticle[] = [];

  for (let i = 0; i < articleCount; i++) {
    const createBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      body: RandomGenerator.content({ paragraphs: 2 }),
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId: category.id,
    } satisfies IDiscussionBoardArticle.ICreate;

    const article: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        {
          body: createBody,
        },
      );
    typia.assert(article);
    createdArticles.push(article);
  }

  // 5. Browse articles via PATCH /discussionBoard/articles with simple pagination
  const pageRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
  } satisfies IDiscussionBoardArticle.IRequest;

  const page: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: pageRequest,
    });
  typia.assert(page);

  const pagination: IPage.IPagination = page.pagination;
  typia.assert(pagination);

  // 6. Validate pagination coherence: page index, limit, page count
  TestValidator.equals(
    "pagination current index should be 0-based first page when requesting page 1",
    pagination.current,
    0,
  );
  TestValidator.equals(
    "pagination limit should match requested limit",
    pagination.limit,
    10,
  );

  TestValidator.predicate(
    "pagination.records should be at least the number of created articles",
    pagination.records >= createdArticles.length,
  );
  TestValidator.predicate(
    "pagination.pages should be >= 1 when there are records",
    pagination.records === 0 ? pagination.pages === 0 : pagination.pages >= 1,
  );

  // 7. Ensure that at least one created article appears in the first page data
  const summaries = page.data;
  const summaryIds = summaries.map((s) => s.id);

  const missingIds = createdArticles
    .map((a) => a.id)
    .filter((id) => !summaryIds.includes(id));

  TestValidator.predicate(
    "at least one created article should be present in the first page of summaries",
    missingIds.length < createdArticles.length,
  );

  // 8. Validate summary fields for created articles that appear in the page
  for (const article of createdArticles) {
    const summary = summaries.find((s) => s.id === article.id);
    if (!summary) continue;

    typia.assert(summary);

    // Check basic fields
    TestValidator.equals(
      "summary title matches article title",
      summary.title,
      article.title,
    );

    // Category consistency
    TestValidator.equals(
      "summary category id matches created category id",
      summary.category.id,
      category.id,
    );
    TestValidator.equals(
      "summary category code matches created category code",
      summary.category.code,
      category.code,
    );
    TestValidator.equals(
      "summary category name matches created category name",
      summary.category.name,
      category.name,
    );

    // Author polymorphic union: ensure it has required summary shape
    const author = summary.author;
    typia.assert<
      IDiscussionBoardMemberuser.ISummary | IDiscussionBoardAdminuser.ISummary
    >(author);

    TestValidator.predicate(
      "author id is non-empty string",
      typeof author.id === "string" && author.id.length > 0,
    );

    // Counts are non-negative
    TestValidator.predicate(
      "likeCount is non-negative",
      summary.likeCount >= 0,
    );
    TestValidator.predicate(
      "commentCount is non-negative",
      summary.commentCount >= 0,
    );
  }

  // 9. Validate default ordering: newest first among our created articles that appear in the page
  const summariesForCreated = summaries.filter((s) =>
    createdArticles.some((a) => a.id === s.id),
  );

  if (summariesForCreated.length >= 2) {
    const sortedByCreatedAtDesc = [...summariesForCreated].sort((a, b) =>
      a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : 0,
    );

    TestValidator.equals(
      "summaries for created articles should be sorted by createdAt descending by default",
      summariesForCreated.map((s) => s.id),
      sortedByCreatedAtDesc.map((s) => s.id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Validate category-based filtering in the public article listing endpoint.
 *
 * ## Business context
 *
 * The discussion board provides a generic article listing/search endpoint
 * `PATCH /discussionBoard/articles` that supports multiple filters, including
 * `categoryId`. Articles are created by member users under specific categories
 * that administrators manage. This test ensures that when `categoryId` is
 * provided, the endpoint returns only articles that belong to that category,
 * and that pagination metadata reflects only the filtered subset. It also
 * covers symmetric behavior across multiple categories and the empty-result
 * case for a category with no articles.
 *
 * ## Steps
 *
 * 1. Join as an admin user (adminUser actor) to obtain an admin session.
 * 2. As adminUser, create two distinct article categories (A and B).
 * 3. Join as a member user (memberUser actor) to obtain a member session.
 * 4. As memberUser, create several articles in category A and category B.
 * 5. Call `PATCH /discussionBoard/articles` filtered by category A and assert
 *    that:
 *
 *    - All returned article summaries belong to category A.
 *    - No article from category B appears.
 *    - Pagination metadata reflects the number of category A articles.
 * 6. Repeat step 5 for category B (symmetric behavior).
 * 7. Create a third category C with no articles and verify that filtering by C
 *    returns an empty data array with coherent pagination fields.
 */
export async function test_api_discussion_board_articles_list_filter_by_category(
  connection: api.IConnection,
) {
  // 1. Join as admin user to seed categories
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: "https://example.com/admin/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorized);

  // 2. Create two categories A and B as adminUser
  const categoryABody = {
    code: `ECONOMY_${RandomGenerator.alphaNumeric(6)}`,
    name: "Economy",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const categoryA: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryABody },
    );
  typia.assert<IDiscussionBoardArticleCategory>(categoryA);

  const categoryBBody = {
    code: `POLITICS_${RandomGenerator.alphaNumeric(6)}`,
    name: "Politics",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 2,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const categoryB: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBBody },
    );
  typia.assert<IDiscussionBoardArticleCategory>(categoryB);

  // 7. Prepare third category C for empty-case later
  const categoryCBody = {
    code: `EMPTY_${RandomGenerator.alphaNumeric(6)}`,
    name: "Empty Category",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 3,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const categoryC: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCBody },
    );
  typia.assert<IDiscussionBoardArticleCategory>(categoryC);

  // 3. Join as member user
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://example.com/member/join",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<IDiscussionBoardMemberuser.IAuthorized>(memberAuthorized);

  // 4. Create articles in categories A and B
  const numArticlesA = 3;
  const numArticlesB = 2;

  const createdArticlesA: IDiscussionBoardArticle[] = [];
  const createdArticlesB: IDiscussionBoardArticle[] = [];

  for (let i = 0; i < numArticlesA; i++) {
    const bodyA = {
      title: RandomGenerator.paragraph({ sentences: 1 }),
      body: RandomGenerator.content({ paragraphs: 2 }),
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId: categoryA.id,
    } satisfies IDiscussionBoardArticle.ICreate;

    const articleA: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        { body: bodyA },
      );
    typia.assert<IDiscussionBoardArticle>(articleA);
    createdArticlesA.push(articleA);
  }

  for (let i = 0; i < numArticlesB; i++) {
    const bodyB = {
      title: RandomGenerator.paragraph({ sentences: 1 }),
      body: RandomGenerator.content({ paragraphs: 2 }),
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId: categoryB.id,
    } satisfies IDiscussionBoardArticle.ICreate;

    const articleB: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        { body: bodyB },
      );
    typia.assert<IDiscussionBoardArticle>(articleB);
    createdArticlesB.push(articleB);
  }

  const idsA = createdArticlesA.map((a) => a.id);
  const idsB = createdArticlesB.map((a) => a.id);

  // 5. Filter by category A
  const requestA = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    categoryId: categoryA.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const pageA: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: requestA,
    });
  typia.assert<IPageIDiscussionBoardArticle.ISummary>(pageA);

  // Pagination expectations for A
  TestValidator.equals(
    "pagination.records should equal number of category A articles",
    pageA.pagination.records,
    numArticlesA,
  );
  TestValidator.equals(
    "pagination.limit should equal requested limit",
    pageA.pagination.limit,
    requestA.limit,
  );
  TestValidator.predicate(
    "pagination.current should be non-negative",
    pageA.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination.pages should be at least 1 when there are records",
    pageA.pagination.records > 0 ? pageA.pagination.pages >= 1 : true,
  );

  // All returned articles should belong to category A and not B
  for (const summary of pageA.data) {
    // category id match
    TestValidator.equals(
      "summary.category.id must equal category A id",
      summary.category.id,
      categoryA.id,
    );

    // When codes are unique, match by code as well
    TestValidator.equals(
      "summary.category.code must match category A code",
      summary.category.code,
      categoryA.code,
    );

    // Ensure no B articles leak into A filter
    TestValidator.predicate(
      "no category B article id should appear when filtering by category A",
      idsB.includes(summary.id) === false,
    );

    // Ensure the summary corresponds to one of the created A articles
    TestValidator.predicate(
      "summary.id must belong to set of created A article ids",
      idsA.includes(summary.id),
    );
  }

  // 6. Filter by category B (symmetric behavior)
  const requestB = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    categoryId: categoryB.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const pageB: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: requestB,
    });
  typia.assert<IPageIDiscussionBoardArticle.ISummary>(pageB);

  TestValidator.equals(
    "pagination.records for category B should equal number of category B articles",
    pageB.pagination.records,
    numArticlesB,
  );
  TestValidator.equals(
    "pagination.limit for category B should equal requested limit",
    pageB.pagination.limit,
    requestB.limit,
  );
  TestValidator.predicate(
    "pagination.current for category B should be non-negative",
    pageB.pagination.current >= 0,
  );

  for (const summary of pageB.data) {
    TestValidator.equals(
      "summary.category.id must equal category B id",
      summary.category.id,
      categoryB.id,
    );
    TestValidator.equals(
      "summary.category.code must match category B code",
      summary.category.code,
      categoryB.code,
    );
    TestValidator.predicate(
      "no category A article id should appear when filtering by category B",
      idsA.includes(summary.id) === false,
    );
    TestValidator.predicate(
      "summary.id must belong to set of created B article ids",
      idsB.includes(summary.id),
    );
  }

  // 7. Filter by category C which has no articles
  const requestC = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    categoryId: categoryC.id,
  } satisfies IDiscussionBoardArticle.IRequest;

  const pageC: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: requestC,
    });
  typia.assert<IPageIDiscussionBoardArticle.ISummary>(pageC);

  TestValidator.equals(
    "records should be zero for category with no articles",
    pageC.pagination.records,
    0,
  );
  TestValidator.equals(
    "data array should be empty for category with no articles",
    pageC.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticle";

/**
 * Test combined text search and createdAt date range filtering for article
 * listing.
 *
 * Business scenario:
 *
 * - An admin user defines a single article category for economic/political
 *   topics.
 * - A member user publishes multiple articles, some containing a distinctive
 *   keyword (e.g. "inflation") and others without it.
 * - The global listing endpoint PATCH /discussionBoard/articles is used to
 *   retrieve articles filtered by a text search term and a createdAt date
 *   range.
 *
 * Validation goals:
 *
 * 1. Only articles whose text matches the search term are returned.
 * 2. Among matching articles, only those whose createdAt is within the
 *    [createdFrom, createdTo] range are included.
 * 3. Articles outside the date range or without the keyword are excluded.
 * 4. Pagination metadata (records, pages, current, limit) is consistent with the
 *    controlled test dataset.
 * 5. An invalid date range (createdFrom > createdTo) is treated as returning an
 *    empty result set.
 */
export async function test_api_discussion_board_articles_list_search_and_date_range(
  connection: api.IConnection,
) {
  // 1. Prepare admin user via join
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "Admin#" + RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.discussion-board.test/join",
    referrer: "https://admin.discussion-board.test/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create single article category as admin
  const categoryCreateBody = {
    code: "ECONOMY_" + RandomGenerator.alphaNumeric(6),
    name: "Economy",
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Prepare member user via join
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: "Member#" + RandomGenerator.alphaNumeric(10),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://discussion-board.test/join",
    referrer: "https://discussion-board.test/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As member user, create multiple articles with and without the keyword
  const keyword = "inflation";

  const createArticle = async (title: string, body: string) => {
    const createBody = {
      title,
      body,
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId: category.id,
    } satisfies IDiscussionBoardArticle.ICreate;

    const article: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        {
          body: createBody,
        },
      );
    typia.assert(article);
    return article;
  };

  const keywordArticles: IDiscussionBoardArticle[] = [];
  const nonKeywordArticles: IDiscussionBoardArticle[] = [];

  keywordArticles.push(
    await createArticle(
      `${RandomGenerator.paragraph({ sentences: 1 })} ${keyword} early`,
      `${keyword} impact on economy: ` +
        RandomGenerator.content({ paragraphs: 2 }),
    ),
  );

  nonKeywordArticles.push(
    await createArticle(
      "General market news",
      RandomGenerator.content({ paragraphs: 2 }),
    ),
  );

  keywordArticles.push(
    await createArticle(
      `Debate about ${keyword} policy`,
      RandomGenerator.content({ paragraphs: 3 }) + ` ${keyword} `,
    ),
  );

  nonKeywordArticles.push(
    await createArticle(
      "Local community updates",
      RandomGenerator.content({ paragraphs: 1 }),
    ),
  );

  keywordArticles.push(
    await createArticle(
      `${keyword} expectations in future markets`,
      RandomGenerator.content({ paragraphs: 2 }),
    ),
  );

  // Sort keyword articles by createdAt to derive boundaries
  const sortedKeywordArticles = [...keywordArticles].sort((a, b) => {
    return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
  });

  const earliestKeyword = sortedKeywordArticles[0];
  const middleKeyword = sortedKeywordArticles[1];
  const latestKeyword = sortedKeywordArticles[2];

  const createdFrom = earliestKeyword.createdAt;
  const createdTo = latestKeyword.createdAt;

  // 5. Call PATCH /discussionBoard/articles with search + date range
  const listRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: keyword,
    categoryId: category.id,
    createdFrom,
    createdTo,
    moderationState: undefined,
    orderBy: "createdAt",
    orderDirection: "asc",
  } satisfies IDiscussionBoardArticle.IRequest;

  const pageResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: listRequestBody,
    });
  typia.assert(pageResult);

  const page = pageResult.pagination;
  const items = pageResult.data;

  TestValidator.predicate(
    "pagination current is non-negative",
    page.current >= 0,
  );
  TestValidator.predicate("pagination limit is positive", page.limit > 0);
  TestValidator.predicate("records count is non-negative", page.records >= 0);
  TestValidator.predicate("pages count is non-negative", page.pages >= 0);

  TestValidator.equals(
    "records equals returned item count in controlled test",
    items.length,
    page.records,
  );

  for (const article of items) {
    const createdTime = new Date(article.createdAt).getTime();
    const fromTime = new Date(createdFrom).getTime();
    const toTime = new Date(createdTo).getTime();

    TestValidator.predicate(
      "article createdAt within requested range",
      createdTime >= fromTime && createdTime <= toTime,
    );

    const textPool = `${article.title} ${article.excerpt ?? ""}`.toLowerCase();
    TestValidator.predicate(
      "article text contains keyword",
      textPool.includes(keyword.toLowerCase()),
    );
  }

  // Narrowed range around the middle keyword article
  const narrowedFrom = middleKeyword.createdAt;
  const narrowedTo = middleKeyword.createdAt;

  const narrowedRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: keyword,
    categoryId: category.id,
    createdFrom: narrowedFrom,
    createdTo: narrowedTo,
    moderationState: undefined,
    orderBy: "createdAt",
    orderDirection: "asc",
  } satisfies IDiscussionBoardArticle.IRequest;

  const narrowedResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: narrowedRequestBody,
    });
  typia.assert(narrowedResult);

  for (const article of narrowedResult.data) {
    TestValidator.equals(
      "narrowed range article createdAt matches middle keyword createdAt",
      article.createdAt,
      middleKeyword.createdAt,
    );
  }

  // 6. Invalid date range scenario: createdFrom after createdTo
  const invalidRangeRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    search: keyword,
    categoryId: category.id,
    createdFrom: createdTo,
    createdTo: createdFrom,
    moderationState: undefined,
    orderBy: "createdAt",
    orderDirection: "asc",
  } satisfies IDiscussionBoardArticle.IRequest;

  const invalidResult: IPageIDiscussionBoardArticle.ISummary =
    await api.functional.discussionBoard.articles.index(connection, {
      body: invalidRangeRequestBody,
    });
  typia.assert(invalidResult);

  TestValidator.equals(
    "invalid range returns no data (treated as empty result)",
    invalidResult.data.length,
    0,
  );
}

