    ip: "127.0.0.1",
    href: "https://frontend.example.com/join",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register admin user (auto-authenticated, overwriting auth headers)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Create article category as admin
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 4. Switch back to member user via login to ensure memberUser auth
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.example.com/login",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoginAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 5. Create article as member
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 6. Create first attachment with order_in_article = 1
  const attachmentBody1 = {
    file_uri: typia.random<string & tags.Format<"uri">>(),
    file_name: `file_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/plain",
    file_size: 1024 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment1: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody1,
      },
    );
  typia.assert(attachment1);

  TestValidator.equals(
    "first attachment article id matches article",
    attachment1.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "first attachment order_in_article should be 1",
    attachment1.order_in_article,
    1,
  );

  // 7. Attempt second attachment with the same order_in_article = 1
  const attachmentBody2 = {
    file_uri: typia.random<string & tags.Format<"uri">>(),
    file_name: `file_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/plain",
    file_size: 2048 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const createdAttachments: IDiscussionBoardAttachment[] = [attachment1];

  let secondSucceeded = false;
  try {
    const attachment2: IDiscussionBoardAttachment =
      await api.functional.discussionBoard.memberUser.articles.attachments.create(
        connection,
        {
          articleId: article.id,
          body: attachmentBody2,
        },
      );
    typia.assert(attachment2);

    secondSucceeded = true;
    createdAttachments.push(attachment2);

    TestValidator.equals(
      "second attachment article id matches article",
      attachment2.discussion_board_article_id,
      article.id,
    );
  } catch (error) {
    // If the second creation fails, we expect it to be due to uniqueness
    // enforcement. Use TestValidator.error to assert that calling the API
    // throws an error when repeated.
    await TestValidator.error(
      "second attachment with duplicate order should fail or already failed",
      async () => {
        await api.functional.discussionBoard.memberUser.articles.attachments.create(
          connection,
          {
            articleId: article.id,
            body: attachmentBody2,
          },
        );
      },
    );
  }

  // 8. Validate uniqueness of order_in_article among successfully created attachments
  const orders = createdAttachments.map((a) => a.order_in_article);

  TestValidator.predicate(
    "order_in_article values of created attachments must be unique",
    () => {
      const seen = new Set<number>();
      for (const value of orders) {
        if (seen.has(value)) return false;
        seen.add(value);
      }
      return true;
    },
  );

  // Sanity check on scenario outcome
  TestValidator.predicate(
    "either only first attachment exists or second succeeded with adjusted order",
    () =>
      (secondSucceeded && createdAttachments.length === 2) ||
      (!secondSucceeded && createdAttachments.length === 1),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Verify that a member user can update mutable metadata of an attachment on
 * their own article.
 *
 * Business flow:
 *
 * 1. Register a member user (join) and get an authenticated member session.
 * 2. Register an admin user (join) and get an authenticated admin session.
 * 3. As the admin, create an article category.
 * 4. As the member user, create an article in that category.
 * 5. As the member, create an attachment for the article with initial metadata.
 * 6. As the same member, update the attachment via PUT
 *    /discussionBoard/memberUser/articles/{articleId}/attachments/{attachmentId}
 *    using IDiscussionBoardAttachment.IUpdate to change file_name and
 *    order_in_article.
 * 7. Validate that:
 *
 *    - Id stays the same.
 *    - Discussion_board_article_id still points to the original article.id.
 *    - File_name and order_in_article are updated to new values.
 *    - File_uri, file_size, content_type, status are preserved.
 *    - Updated_at is changed (and is later than or different from original
 *         updated_at).
 *    - Deleted_at remains null/undefined.
 */
export async function test_api_article_attachment_update_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register member user (join) -> auto-sets Authorization header for memberUser
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(1),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/join",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // Keep member email/password for later login (actor switching)
  const memberEmail: string & tags.Format<"email"> = memberJoinBody.email;
  const memberPassword: string = memberJoinBody.password;

  // 2. Register admin user (join) -> becomes current actor (adminUser)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(1),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.2",
    href: "https://frontend.local/admin/join",
    referrer: "https://frontend.local/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Create article category as admin
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Switch back to member user via login
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: "127.0.0.3",
    href: "https://frontend.local/login",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorized2: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorized2);

  // 5. Create article in the created category as member
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. Create an attachment for the article as member
  const attachmentCreateBody = {
    file_uri: "https://cdn.local/files/" + RandomGenerator.alphaNumeric(12),
    file_name: "initial_file_name.txt",
    content_type: "text/plain",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const originalAttachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(originalAttachment);

  // 7. Prepare update payload modifying file_name and order_in_article
  const updatedFileName = "updated_file_name.txt";
  const updatedOrder: number & tags.Type<"int32"> & tags.Minimum<0> =
    2 as number & tags.Type<"int32"> & tags.Minimum<0>;

  const updateBody = {
    file_name: updatedFileName,
    order_in_article: updatedOrder,
  } satisfies IDiscussionBoardAttachment.IUpdate;

  const updatedAttachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.update(
      connection,
      {
        articleId: article.id,
        attachmentId: originalAttachment.id,
        body: updateBody,
      },
    );
  typia.assert(updatedAttachment);

  // 8. Validate identity and ownership fields
  TestValidator.equals(
    "attachment id remains unchanged after update",
    updatedAttachment.id,
    originalAttachment.id,
  );
  TestValidator.equals(
    "attachment still belongs to the original article",
    updatedAttachment.discussion_board_article_id,
    article.id,
  );

  // 9. Validate updated fields
  TestValidator.equals(
    "file_name is updated to new value",
    updatedAttachment.file_name,
    updatedFileName,
  );
  TestValidator.equals(
    "order_in_article is updated to new value",
    updatedAttachment.order_in_article,
    updatedOrder,
  );

  // 10. Validate preserved fields (file_uri, file_size, content_type, status)
  TestValidator.equals(
    "file_uri is preserved after update",
    updatedAttachment.file_uri,
    originalAttachment.file_uri,
  );
  TestValidator.equals(
    "file_size is preserved after update",
    updatedAttachment.file_size,
    originalAttachment.file_size,
  );
  TestValidator.equals(
    "content_type is preserved after update",
    updatedAttachment.content_type,
    originalAttachment.content_type,
  );
  TestValidator.equals(
    "status is preserved when not changed in update",
    updatedAttachment.status,
    originalAttachment.status,
  );

  // 11. Validate timestamps and deleted_at
  TestValidator.notEquals(
    "updated_at should change after update",
    updatedAttachment.updated_at,
    originalAttachment.updated_at,
  );

  TestValidator.predicate(
    "updated_at is equal or later than created_at",
    new Date(updatedAttachment.updated_at).getTime() >=
      new Date(updatedAttachment.created_at).getTime(),
  );

  TestValidator.equals(
    "deleted_at remains null or undefined after a normal update",
    updatedAttachment.deleted_at ?? null,
    originalAttachment.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate updating an attachment's order within an article.
 *
 * Business workflow:
 *
 * 1. Admin joins and creates an article category.
 * 2. Member joins.
 * 3. Member creates an article in that category.
 * 4. Member creates two attachments (A: order 1, B: order 2) for the article.
 * 5. Member updates attachment B setting order_in_article to 1 using PUT.
 * 6. Test checks that the update succeeds and that the updated attachment still
 *    belongs to the same article and has the new order value.
 */
export async function test_api_article_attachment_update_order_reordering(
  connection: api.IConnection,
) {
  // 1. Admin joins
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Member joins
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates an article in that category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. Member creates two attachments A (order 1) and B (order 2)
  const baseUri = "https://cdn.example.com/files";

  const attachmentABody = {
    file_uri: `${baseUri}/${RandomGenerator.alphaNumeric(16)}.pdf`,
    file_name: "attachment-a.pdf",
    content_type: "application/pdf",
    file_size: 1024 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachmentA: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentABody,
      },
    );
  typia.assert(attachmentA);

  const attachmentBBody = {
    file_uri: `${baseUri}/${RandomGenerator.alphaNumeric(16)}.pdf`,
    file_name: "attachment-b.pdf",
    content_type: "application/pdf",
    file_size: 2048 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 2 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachmentB: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBBody,
      },
    );
  typia.assert(attachmentB);

  TestValidator.equals(
    "initial attachment A order is 1",
    attachmentA.order_in_article,
    1 as number,
  );
  TestValidator.equals(
    "initial attachment B order is 2",
    attachmentB.order_in_article,
    2 as number,
  );

  // 6. Update attachment B to conflict order (1)
  const updateBody = {
    order_in_article: 1 as number & tags.Type<"int32"> & tags.Minimum<0>,
  } satisfies IDiscussionBoardAttachment.IUpdate;

  const updatedB: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.update(
      connection,
      {
        articleId: article.id,
        attachmentId: attachmentB.id,
        body: updateBody,
      },
    );
  typia.assert(updatedB);

  // Validate updated attachment still belongs to same article and has new order
  TestValidator.equals(
    "updated attachment B belongs to same article",
    updatedB.discussion_board_article_id,
    article.id,
  );
  TestValidator.equals(
    "updated attachment B has new order 1",
    updatedB.order_in_article,
    1 as number,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Verify authorization and ownership rules when updating article attachments.
 *
 * Business goal:
 *
 * - Only the article-owning member user can update an attachment through the
 *   memberUser endpoint.
 * - Authenticated non-owners must be rejected when attempting to update an
 *   attachment on someone else's article.
 * - Unauthenticated requests must also be rejected.
 * - A legitimate owner update must succeed so we know the endpoint works
 *   correctly when properly authorized.
 *
 * High-level flow:
 *
 * 1. Join member user A and implicitly authenticate them.
 * 2. Join admin user and create an article category.
 * 3. Switch to member A and create an article in that category.
 * 4. Member A creates an attachment for that article.
 * 5. Join member user B so that Authorization reflects a different user.
 * 6. As member B, attempt to update the attachment belonging to A's article and
 *    expect an authorization/permission error.
 * 7. Switch back to member A and perform a successful update of the same
 *    attachment, asserting that:
 *
 *    - The call succeeds.
 *    - The attachment id and article id remain the same.
 *    - The editable metadata fields are updated as requested.
 * 8. Finally, attempt to update the attachment using an unauthenticated connection
 *    (no Authorization header) and assert that this also fails.
 */
export async function test_api_article_attachment_update_authorization_and_ownership(
  connection: api.IConnection,
) {
  // 1. Register member user A (owner) via join and authenticate
  const memberAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberAJoinBody = {
    email: memberAEmail,
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/join/memberA",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberA: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberA);

  // 2. Register admin user and authenticate
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.2",
    href: "https://frontend.local/admin/join",
    referrer: "https://frontend.local/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Create an article category as admin
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Switch back to member A (ensure Authorization for member A)
  const memberALoginBody = {
    email: memberAEmail,
    password: memberAJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login/memberA",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberALogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALogin);

  // 5. Member A creates an article in the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. Member A creates an attachment for the article
  const attachmentCreateBody = {
    file_uri: typia.random<string & tags.Format<"uri">>(),
    file_name: `file_${RandomGenerator.alphaNumeric(8)}.txt`,
    content_type: "text/plain",
    file_size: 1024 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 0 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachment);

  // 7. Join member user B and authenticate as B
  const memberBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberBJoinBody = {
    email: memberBEmail,
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "127.0.0.3",
    href: "https://frontend.local/join/memberB",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberB: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberB);

  // 8. As member B, attempt to update A's attachment and expect failure
  const unauthorizedUpdateBodyByB = {
    file_name: `unauthorized_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/markdown",
    order_in_article: 1 as number & tags.Type<"int32"> & tags.Minimum<0>,
    status: "hidden",
  } satisfies IDiscussionBoardAttachment.IUpdate;

  await TestValidator.error(
    "unauthorized member B cannot update attachment owned by member A",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.update(
        connection,
        {
          articleId: article.id,
          attachmentId: attachment.id,
          body: unauthorizedUpdateBodyByB,
        },
      );
    },
  );

  // 9. Switch back to member A and perform a successful update
  const memberALoginAgainBody = {
    email: memberAEmail,
    password: memberAJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login/memberA/again",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberALoginAgain: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginAgainBody,
    });
  typia.assert(memberALoginAgain);

  const ownerUpdateBody = {
    file_name: `owner_updated_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/plain",
    order_in_article: 2 as number & tags.Type<"int32"> & tags.Minimum<0>,
    status: "active",
  } satisfies IDiscussionBoardAttachment.IUpdate;

  const updatedByOwner: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.update(
      connection,
      {
        articleId: article.id,
        attachmentId: attachment.id,
        body: ownerUpdateBody,
      },
    );
  typia.assert(updatedByOwner);

  // Validate that core identity fields remain stable
  TestValidator.equals(
    "attachment id remains unchanged after owner update",
    updatedByOwner.id,
    attachment.id,
  );
  TestValidator.equals(
    "attachment's article id remains unchanged after owner update",
    updatedByOwner.discussion_board_article_id,
    attachment.discussion_board_article_id,
  );

  // Validate that editable fields reflect the owner's update request
  TestValidator.equals(
    "file_name updated by owner",
    updatedByOwner.file_name,
    ownerUpdateBody.file_name,
  );
  TestValidator.equals(
    "content_type updated by owner",
    updatedByOwner.content_type,
    ownerUpdateBody.content_type,
  );
  TestValidator.equals(
    "order_in_article updated by owner",
    updatedByOwner.order_in_article,
    ownerUpdateBody.order_in_article,
  );
  TestValidator.equals(
    "status updated by owner",
    updatedByOwner.status,
    ownerUpdateBody.status,
  );

  // 10. Attempt to update attachment without authentication and expect failure
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  const unauthenticatedUpdateBody = {
    file_name: `unauthenticated_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/plain",
    order_in_article: 3 as number & tags.Type<"int32"> & tags.Minimum<0>,
    status: "hidden",
  } satisfies IDiscussionBoardAttachment.IUpdate;

  await TestValidator.error(
    "unauthenticated client cannot update attachment",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.update(
        unauthenticatedConnection,
        {
          articleId: article.id,
          attachmentId: attachment.id,
          body: unauthenticatedUpdateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that an admin user can update a member-authored comment on an
 * article.
 *
 * Business flow:
 *
 * 1. Admin user joins and obtains an authenticated admin session.
 * 2. Admin creates a discussion-board article category.
 * 3. Member user joins and obtains an authenticated member session.
 * 4. Member creates an article under the created category.
 * 5. Member posts a comment on that article.
 * 6. Admin logs in again (switching actor back to adminUser).
 * 7. Admin updates the member-authored comment via PUT
 *    /discussionBoard/adminUser/articles/{articleId}/comments/{commentId}.
 * 8. The test asserts that:
 *
 *    - Comment id is unchanged.
 *    - Comment remains scoped to the same article.
 *    - Body text is updated to the new value and differs from the original.
 *    - Created_at is preserved, and updated_at moves forward (or at least does not
 *         go backwards).
 */
export async function test_api_admin_comment_update_on_member_comment(
  connection: api.IConnection,
) {
  // 1. Admin joins (registration + initial authenticated session)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Member joins
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberJoinBody = {
    email: memberEmail,
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates an article under the category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. Member creates a comment on the article
  const originalCommentBodyText: string = RandomGenerator.paragraph({
    sentences: 4,
  });
  const commentCreateBody = {
    body: originalCommentBodyText,
  } satisfies IDiscussionBoardComment.ICreate;

  const createdComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(createdComment);

  // Basic sanity checks on created comment
  TestValidator.equals(
    "created comment is associated with the correct article",
    createdComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "created comment body equals request body",
    createdComment.body,
    originalCommentBodyText,
  );

  const originalCreatedAt = new Date(createdComment.created_at).getTime();
  const originalUpdatedAt = new Date(createdComment.updated_at).getTime();

  // 6. Switch back to admin via login (ensures current session is admin)
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 7. Admin updates the member-authored comment
  const updatedBodyText: string = RandomGenerator.paragraph({ sentences: 5 });
  const commentUpdateBody = {
    body: updatedBodyText,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.adminUser.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: createdComment.id,
        body: commentUpdateBody,
      },
    );
  typia.assert(updatedComment);

  // 8. Business validations

  // 8.1 ID immutability
  TestValidator.equals(
    "comment id remains unchanged after admin update",
    updatedComment.id,
    createdComment.id,
  );

  // 8.2 Article scoping remains consistent
  TestValidator.equals(
    "updated comment remains associated with the same article",
    updatedComment.article.id,
    article.id,
  );

  // 8.3 Body updated to new content
  TestValidator.equals(
    "comment body is updated to new text",
    updatedComment.body,
    updatedBodyText,
  );

  // 8.4 Body differs from the original
  TestValidator.notEquals(
    "comment body after update differs from original body",
    updatedComment.body,
    createdComment.body,
  );

  // 8.5 created_at is immutable (not later than original)
  const updatedCreatedAt = new Date(updatedComment.created_at).getTime();
  TestValidator.equals(
    "created_at is preserved on admin comment update",
    updatedCreatedAt,
    originalCreatedAt,
  );

  // 8.6 updated_at is moved forward or at least not earlier
  const updatedUpdatedAt = new Date(updatedComment.updated_at).getTime();
  TestValidator.predicate(
    "updated_at is greater than or equal to original updated_at after update",
    updatedUpdatedAt >= originalUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that an admin user can update their own admin-authored comment on an
 * article.
 *
 * Business context:
 *
 * - Articles are created by authenticated member users under specific categories.
 * - Admin users can author comments on those articles through admin-scoped
 *   endpoints.
 * - Admin users must be able to update the body of their own comments without
 *   changing identity, article linkage, or moderation status.
 *
 * Scenario steps:
 *
 * 1. Register a memberUser and implicitly authenticate them via
 *    /auth/memberUser/join.
 * 2. Register an adminUser and implicitly authenticate them via
 *    /auth/adminUser/join.
 * 3. As the adminUser, create an article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Switch authentication to the memberUser and create an article under that
 *    category via /discussionBoard/memberUser/articles.
 * 5. Switch authentication back to the adminUser and create a comment on that
 *    article via /discussionBoard/adminUser/articles/{articleId}/comments.
 * 6. Update the admin-authored comment using PUT
 *    /discussionBoard/adminUser/articles/{articleId}/comments/{commentId} and
 *    change only the comment body.
 * 7. Assert that the update succeeded and core invariants hold:
 *
 *    - Comment id is unchanged.
 *    - Comment article.id matches the original article id.
 *    - Author_type is unchanged and still represents an admin author.
 *    - Status is unchanged.
 *    - Deleted_at remains unchanged (and usually null).
 *    - Body has actually changed and matches the update payload.
 *    - Updated_at is greater than or equal to both original created_at and original
 *         updated_at.
 */
export async function test_api_admin_comment_update_on_admin_comment(
  connection: api.IConnection,
) {
  // 1. Register a member user (join also authenticates as that member).
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = RandomGenerator.alphaNumeric(16);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(1),
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register an admin user (join also authenticates as that admin).
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> =
    RandomGenerator.alphaNumeric(20) as string & tags.Format<"password">;

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(1),
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As the adminUser, create an article category.
  const categoryBody = {
    code: `CAT-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 4. Switch to memberUser and create an article under that category.
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    href: "https://member.example.com/login",
    referrer: "https://member.example.com/articles/new",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);

  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. Switch back to adminUser and create an admin-authored comment.
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/comments/new",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  const createCommentBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const originalComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.adminUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: createCommentBody,
      },
    );
  typia.assert(originalComment);

  // Sanity checks on initial comment.
  TestValidator.equals(
    "created comment is linked to the correct article",
    originalComment.article.id,
    article.id,
  );

  const originalCreatedAt = new Date(originalComment.created_at);
  const originalUpdatedAt = new Date(originalComment.updated_at);

  // 6. Update the admin-authored comment body via admin endpoint.
  const updatedBodyText = RandomGenerator.paragraph({ sentences: 5 });

  const updateCommentBody = {
    body: updatedBodyText,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.adminUser.articles.comments.update(
      connection,
      {
        articleId: originalComment.article.id,
        commentId: originalComment.id,
        body: updateCommentBody,
      },
    );
  typia.assert(updatedComment);

  // 7. Assert invariants after update.

  // Identity invariants.
  TestValidator.equals(
    "comment id must remain unchanged after update",
    updatedComment.id,
    originalComment.id,
  );
  TestValidator.equals(
    "article id in comment.article must remain unchanged",
    updatedComment.article.id,
    originalComment.article.id,
  );
  TestValidator.equals(
    "updated comment remains linked to the original article",
    updatedComment.article.id,
    article.id,
  );

  // Author type and status invariants.
  TestValidator.equals(
    "author_type should remain unchanged for admin-authored comment",
    updatedComment.author_type,
    originalComment.author_type,
  );
  TestValidator.equals(
    "comment status should not change after body update",
    updatedComment.status,
    originalComment.status,
  );

  // Deleted_at invariant.
  TestValidator.equals(
    "deleted_at should remain unchanged (typically null) after update",
    updatedComment.deleted_at,
    originalComment.deleted_at,
  );

  // Body must change and match payload.
  TestValidator.notEquals(
    "comment body must actually change after update",
    updatedComment.body,
    originalComment.body,
  );
  TestValidator.equals(
    "updated body must reflect the update payload",
    updatedComment.body,
    updatedBodyText,
  );

  // Temporal invariants.
  const updatedUpdatedAt = new Date(updatedComment.updated_at);

  TestValidator.predicate(
    "updated_at should be no earlier than created_at after update",
    updatedUpdatedAt.getTime() >= originalCreatedAt.getTime(),
  );
  TestValidator.predicate(
    "updated_at should be no earlier than original updated_at after update",
    updatedUpdatedAt.getTime() >= originalUpdatedAt.getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that an admin cannot update a non-existent comment under an existing
 * article.
 *
 * Business intent:
 *
 * - When an adminUser targets a commentId that does not exist (for a valid
 *   articleId), the comments.update endpoint must fail instead of creating or
 *   upserting a comment.
 * - The test focuses on error semantics (operation must throw) rather than
 *   specific HTTP status codes.
 *
 * Test steps:
 *
 * 1. Register an admin user using /auth/adminUser/join to obtain adminUser
 *    context.
 * 2. Register a member user using /auth/memberUser/join to act as an article
 *    author.
 * 3. As the admin user, create an article category via
 *    /discussionBoard/adminUser/articleCategories to get a valid categoryId.
 * 4. Switch to the memberUser context (login) if necessary and create an article
 *    via /discussionBoard/memberUser/articles using the category from step 3.
 * 5. Generate a random UUID for commentId that is extremely unlikely to correspond
 *    to any real comment under that article.
 * 6. Switch back to adminUser context (login) to call the admin-only
 *    comments.update endpoint.
 * 7. Invoke PUT
 *    /discussionBoard/adminUser/articles/{articleId}/comments/{commentId} via
 *    api.functional.discussionBoard.adminUser.articles.comments.update, passing
 *    the existing article.id and the random commentId with a valid
 *    IDiscussionBoardComment.IUpdate body.
 * 8. Wrap this call in TestValidator.error to assert that the operation fails
 *    (throws), thereby confirming that the endpoint does not upsert when a
 *    non-existent commentId is provided.
 *
 * Notes:
 *
 * - We do not verify a specific HTTP status (like 404) because HTTP status code
 *   assertions are out of scope for these tests.
 * - We also cannot explicitly assert that no comment was created, because no
 *   comment listing or lookup functions are available in this scope; instead,
 *   we rely on the error behavior as the observable contract.
 */
export async function test_api_admin_comment_update_not_found(
