import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Verify that an author member user can update their own discussion board
 * article and reclassify it to a different category.
 *
 * Business flow:
 *
 * 1. Register a member user (author) and capture their credentials.
 * 2. Register an admin user who can manage article categories.
 * 3. As admin, create an initial category (Category A).
 * 4. As member, create an article in Category A.
 * 5. As admin, create a second category (Category B).
 * 6. As member, update the article: change title, body, summary and move it to
 *    Category B via PUT /discussionBoard/memberUser/articles/{articleId}.
 * 7. Assert that core identity fields (id, createdAt) are stable, content fields
 *    are updated, category summary points to Category B, and updatedAt is
 *    refreshed.
 */
export async function test_api_article_update_by_author_member(
  connection: api.IConnection,
) {
  // 1. Register member user (author)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://example.com/join/member",
    referrer: "https://example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoin);

  // 2. Register admin user
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://example.com/join/admin",
    referrer: "https://example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoin);

  // 3. As admin, create Category A
  const categoryABody = {
    code: `CAT_A_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const categoryA: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryABody,
      },
    );
  typia.assert(categoryA);

  // 4. Switch to member context explicitly via login
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://example.com/login/member",
    referrer: "https://example.com/join/member/complete",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);

  // 5. As member, create an article under Category A
  const originalTitle = RandomGenerator.paragraph({ sentences: 3 });
  const originalBody = RandomGenerator.content({ paragraphs: 2 });
  const originalSummary = RandomGenerator.paragraph({ sentences: 2 });

  const articleCreateBody = {
    title: originalTitle,
    body: originalBody,
    summary: originalSummary,
    categoryId: categoryA.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const originalArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(originalArticle);

  // 6. Switch back to admin and create Category B
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://example.com/login/admin",
    referrer: "https://example.com/join/admin/complete",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  const categoryBBody = {
    code: `CAT_B_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 2 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const categoryB: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBBody,
      },
    );
  typia.assert(categoryB);

  // 7. Switch back to member and update the article
  const memberLoginAgain: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAgain);

  const updatedTitle = RandomGenerator.paragraph({ sentences: 3 });
  const updatedBody = RandomGenerator.content({ paragraphs: 3 });
  const updatedSummary = RandomGenerator.paragraph({ sentences: 2 });

  const articleUpdateBody = {
    title: updatedTitle,
    body: updatedBody,
    summary: updatedSummary,
    discussion_board_article_category_id: categoryB.id,
  } satisfies IDiscussionBoardArticle.IUpdate;

  const updatedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.update(
      connection,
      {
        articleId: originalArticle.id,
        body: articleUpdateBody,
      },
    );
  typia.assert(updatedArticle);

  // 8. Business assertions
  // Identity invariants
  TestValidator.equals(
    "article id should remain unchanged after update",
    updatedArticle.id,
    originalArticle.id,
  );

  TestValidator.equals(
    "createdAt should remain unchanged after update",
    updatedArticle.createdAt,
    originalArticle.createdAt,
  );

  // updatedAt must change and be later or at least not equal; since both are
  // ISO date-time strings, we compare by Date.
  const originalUpdatedAtTime = new Date(originalArticle.updatedAt).getTime();
  const updatedUpdatedAtTime = new Date(updatedArticle.updatedAt).getTime();

  TestValidator.predicate(
    "updatedAt should be refreshed after article update",
    updatedUpdatedAtTime >= originalUpdatedAtTime &&
      updatedArticle.updatedAt !== originalArticle.updatedAt,
  );

  // Content should reflect updated values
  TestValidator.equals(
    "title should be updated",
    updatedArticle.title,
    updatedTitle,
  );

  TestValidator.equals(
    "body should be updated",
    updatedArticle.body,
    updatedBody,
  );

  TestValidator.equals(
    "summary should be updated (including null handling)",
    updatedArticle.summary ?? null,
    updatedSummary,
  );

  // Category summary should now point to Category B
  TestValidator.equals(
    "category id should point to Category B after update",
    updatedArticle.category.id,
    categoryB.id,
  );

  TestValidator.equals(
    "category code should match Category B",
    updatedArticle.category.code,
    categoryB.code,
  );

  TestValidator.equals(
    "category name should match Category B",
    updatedArticle.category.name,
    categoryB.name,
  );

  TestValidator.equals(
    "category description should match Category B",
    updatedArticle.category.description ?? null,
    categoryB.description ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that non-author member cannot update another member's article.
 *
 * Business flow:
 *
 * 1. Join Member A and keep its credentials.
 * 2. Join Member B and keep its credentials (non-author actor).
 * 3. Join an admin user.
 * 4. As admin, create an article category.
 * 5. Switch to Member A and create an article in the created category.
 * 6. Switch to Member B and attempt to update Member A's article via memberUser
 *    update API.
 * 7. Assert that the update attempt fails (authorization/ownership check).
 * 8. Fetch the article via public GET and confirm that all core content fields
 *    remain unchanged.
 */
export async function test_api_article_update_rejected_for_non_author_member(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberAHref: string = "https://example.com/member-a/join";
  const memberAReferrer: string = "https://example.com/landing";
  const memberAEmail: string = typia.random<string & tags.Format<"email">>();
  const memberAPassword: string = RandomGenerator.alphabets(12);

  const memberAJoinBody = {
    email: memberAEmail,
    password: memberAPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "203.0.113.10",
    href: memberAHref,
    referrer: memberAReferrer,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAJoin);

  // keep Member A credentials for later login

  // 2. Register Member B
  const memberBHref: string = "https://example.com/member-b/join";
  const memberBReferrer: string = "https://example.com/landing";
  const memberBEmail: string = typia.random<string & tags.Format<"email">>();
  const memberBPassword: string = RandomGenerator.alphabets(12);

  const memberBJoinBody = {
    email: memberBEmail,
    password: memberBPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "203.0.113.11",
    href: memberBHref,
    referrer: memberBReferrer,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberBJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBJoin);

  // 3. Register an admin user
  const adminHref: string = "https://example.com/admin/join";
  const adminReferrer: string = "https://example.com/admin/landing";
  const adminEmail: string = typia.random<string & tags.Format<"email">>();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphabets(16) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "198.51.100.5",
    href: adminHref,
    referrer: adminReferrer,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoin);

  // 4. As admin, create an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 1 }),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 5. Switch to Member A and create an article
  const memberALoginBody = {
    email: memberAEmail,
    password: memberAPassword,
    ip: "203.0.113.10",
    href: "https://example.com/member-a/login",
    referrer: memberAHref,
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberALogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALogin);

  const createArticleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const originalArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: createArticleBody,
      },
    );
  typia.assert(originalArticle);

  // Keep a snapshot of original content for later comparison
  const originalSnapshot = {
    title: originalArticle.title,
    body: originalArticle.body,
    summary: originalArticle.summary ?? null,
    categoryId: originalArticle.category.id,
    moderationState: originalArticle.moderationState,
    createdAt: originalArticle.createdAt,
    updatedAt: originalArticle.updatedAt,
  };

  // 6. Switch to Member B and attempt to update Member A's article
  const memberBLoginBody = {
    email: memberBEmail,
    password: memberBPassword,
    ip: "203.0.113.11",
    href: "https://example.com/member-b/login",
    referrer: memberBHref,
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberBLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberBLoginBody,
    });
  typia.assert(memberBLogin);

  const updateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.content({ paragraphs: 3 }),
    summary: RandomGenerator.paragraph({ sentences: 1 }),
    discussion_board_article_category_id: category.id,
  } satisfies IDiscussionBoardArticle.IUpdate;

  await TestValidator.error(
    "non-author member update must be rejected",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.update(
        connection,
        {
          articleId: originalArticle.id,
          body: updateBody,
        },
      );
    },
  );

  // 7. Fetch article again to verify it is unchanged
  const reloaded: IDiscussionBoardArticle =
    await api.functional.discussionBoard.articles.at(connection, {
      articleId: originalArticle.id,
    });
  typia.assert(reloaded);

  TestValidator.equals(
    "article title remains unchanged after rejected update",
    reloaded.title,
    originalSnapshot.title,
  );
  TestValidator.equals(
    "article body remains unchanged after rejected update",
    reloaded.body,
    originalSnapshot.body,
  );
  TestValidator.equals(
    "article summary remains unchanged after rejected update",
    reloaded.summary ?? null,
    originalSnapshot.summary,
  );
  TestValidator.equals(
    "article category remains unchanged after rejected update",
    reloaded.category.id,
    originalSnapshot.categoryId,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that member article update is rejected after administrative
 * deletion.
 *
 * Business scenario:
 *
 * - A regular member creates an article under a valid category.
 * - An administrator hard-deletes that article using the admin-only erase API.
 * - The member then attempts to update the previously created article via the
 *   member update endpoint.
 *
 * Expectations:
 *
 * 1. Member join/login and admin join/login succeed and yield valid sessions.
 * 2. Admin can create a valid article category that member can use.
 * 3. Member can successfully create an article in that category.
 * 4. Admin can successfully erase (hard-delete) that article by id.
 * 5. Any subsequent attempt by the member to update that article must fail,
 *    producing an HTTP error (e.g., not-found or deletion-related) rather than
 *    reviving or modifying the deleted resource.
 *
 * Steps:
 *
 * 1. Register member user via /auth/memberUser/join.
 * 2. Register admin user via /auth/adminUser/join.
 * 3. As admin, create article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Switch to member and create article via /discussionBoard/memberUser/articles.
 * 5. Switch to admin and erase article via
 *    /discussionBoard/adminUser/articles/{articleId}.
 * 6. Switch back to member and attempt to update article via
 *    /discussionBoard/memberUser/articles/{articleId}.
 * 7. Assert that the update call throws an error using TestValidator.error.
 */
export async function test_api_article_update_rejected_for_deleted_article(
  connection: api.IConnection,
) {
  // 1. Register member user (join immediately authenticates and sets token)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://frontend.example.com/join/member",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register admin user (join authenticates and sets admin token)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://frontend.example.com/join/admin",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As admin, create a category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 4. Switch to member session via login (overwrites Authorization header)
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://frontend.example.com/login/member",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoginResult: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginResult);

  // 5. Member creates an article in that category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. Switch back to admin session by logging in as admin
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://frontend.example.com/login/admin",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginResult);

  // 7. Admin hard-deletes the article
  await api.functional.discussionBoard.adminUser.articles.erase(connection, {
    articleId: article.id,
  });

  // 8. Switch again to member session
  const memberLoginResultAfterDeletion: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginResultAfterDeletion);

  // 9. Attempt to update the deleted article and assert that it fails
  const updateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.content({ paragraphs: 1 }),
    summary: RandomGenerator.paragraph({ sentences: 1 }),
    discussion_board_article_category_id: category.id,
  } satisfies IDiscussionBoardArticle.IUpdate;

  await TestValidator.error(
    "member cannot update article after admin hard deletion",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.update(
        connection,
        {
          articleId: article.id,
          body: updateBody,
        },
      );
    },
  );
}

