/**
 * Validate admin comment creation on a member-authored article.
 *
 * Business goal (rewritten from the original restrictive-scenario draft):
 * Ensure that an authenticated admin user can create a comment on an article
 * authored by a member user, wiring together the admin/member auth flows,
 * article category creation, article creation, and comment creation APIs.
 *
 * Steps implemented:
 *
 * 1. Admin joins via /auth/adminUser/join and becomes authenticated.
 * 2. (Optional but explicit) Admin logs in again via /auth/adminUser/login to
 *    demonstrate actor switching is working and tokens are correctly wired.
 * 3. As admin, create an article category via
 *    /discussionBoard/adminUser/articleCategories.create.
 * 4. Member joins via /auth/memberUser/join, switching the connection context to
 *    memberUser.
 * 5. As member, create an article in the created category via
 *    /discussionBoard/memberUser/articles.create; capture article.id.
 * 6. Switch auth context back to the admin via /auth/adminUser/login.
 * 7. As admin, create a comment on the member article via
 *    /discussionBoard/adminUser/articles/{articleId}/comments.create with a
 *    valid IDiscussionBoardComment.ICreate body.
 * 8. Assert that each non-void response matches its DTO using typia.assert, and
 *    verify that the returned comment.article.id equals the article.id.
 *
 * Note: Original scenario mentioned restrictions on admins; current API surface
 * contains no explicit restriction commands or comment listing endpoints, so
 * this test focuses solely on the successful happy path.
 */
export async function test_api_admin_comment_creation_restricted_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins (register + initial authenticated context)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Admin1234!", // any string is acceptable; tagged as password in DTO
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorizedFromJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Admin logs in again (explicit login flow and token swap)
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/join-complete",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedFromLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  TestValidator.equals(
    "admin id from join and login should match",
    adminAuthorizedFromLogin.id,
    adminAuthorizedFromJoin.id,
  );

  // 3. As admin, create an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  TestValidator.equals(
    "created category code should match request",
    category.code,
    categoryBody.code,
  );

  // 4. Member joins (switch authentication context to memberUser)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Member1234!",
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: "192.168.0.10",
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/home",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 5. As member, create an article in that category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  TestValidator.equals(
    "article.category.id should equal category.id",
    article.category.id,
    category.id,
  );

  // 6. Switch back to admin via login (overwriting Authorization header)
  const adminRelogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminRelogin);

  TestValidator.equals(
    "admin id after relogin should still match original admin",
    adminRelogin.id,
    adminAuthorizedFromJoin.id,
  );

  // 7. As admin, create a comment on the member-authored article
  const commentBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.adminUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  // 8. Business-level assertions on the created comment
  TestValidator.equals(
    "comment should be attached to the correct article",
    comment.article.id,
    article.id,
  );

  TestValidator.predicate(
    "comment body should match what was sent",
    comment.body === commentBody.body,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that a member user can update their own comment on an article.
 *
 * Business flow:
 *
 * 1. Register a member user (join) and keep their credential info.
 * 2. Register an admin user (join) to manage article categories.
 * 3. As admin, create an article category.
 * 4. Log in as the member user and create an article referencing the category.
 * 5. As the same member, create a comment on that article.
 * 6. As the same member, update the comment body using the PUT comment update
 *    endpoint.
 * 7. Assert that identifiers and relations are stable and timestamps/status behave
 *    correctly.
 */
export async function test_api_member_comment_update_by_owner(
  connection: api.IConnection,
) {
  // 1. Register member user (join) and keep email/password for later login
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://member.join.example.com/",
    referrer: "https://landing.example.com/",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoin);

  // 2. Register admin user (join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://admin.join.example.com/",
    referrer: "https://admin.landing.example.com/",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoin);

  // 3. As admin, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Log in again as member user to ensure member auth context
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://member.login.example.com/",
    referrer: "https://landing.example.com/",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);

  // 5. Member creates an article referencing created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. Member creates an initial comment on the article
  const originalCommentBodyText: string = RandomGenerator.paragraph({
    sentences: 4,
  });

  const commentCreateBody = {
    body: originalCommentBodyText,
  } satisfies IDiscussionBoardComment.ICreate;

  const createdComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(createdComment);

  // Snapshot original timestamps and status
  const originalCreatedAt: string & tags.Format<"date-time"> =
    createdComment.created_at;
  const originalUpdatedAt: string & tags.Format<"date-time"> =
    createdComment.updated_at;
  const originalStatus: string = createdComment.status;
  const originalDeletedAt: (string & tags.Format<"date-time">) | null =
    createdComment.deleted_at;

  // Sanity checks on initial comment
  TestValidator.equals(
    "initial comment belongs to created article",
    createdComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "initial comment body matches input",
    createdComment.body,
    originalCommentBodyText,
  );

  // 7. Member updates the comment body
  const updatedCommentBodyText: string = RandomGenerator.paragraph({
    sentences: 5,
  });

  const commentUpdateBody = {
    body: updatedCommentBodyText,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: createdComment.id,
        body: commentUpdateBody,
      },
    );
  typia.assert(updatedComment);

  // 8. Business assertions on updated comment
  // 8.1 Identifier and article relation stability
  TestValidator.equals(
    "updated comment id equals original comment id",
    updatedComment.id,
    createdComment.id,
  );
  TestValidator.equals(
    "updated comment still belongs to same article",
    updatedComment.article.id,
    article.id,
  );

  // 8.2 Body has been updated
  TestValidator.equals(
    "updated comment body equals new text",
    updatedComment.body,
    updatedCommentBodyText,
  );

  // 8.3 created_at remains unchanged
  TestValidator.equals(
    "created_at remains unchanged after update",
    updatedComment.created_at,
    originalCreatedAt,
  );

  // 8.4 updated_at has changed and is later than or equal to original timestamps
  const originalCreatedMs: number = new Date(originalCreatedAt).getTime();
  const originalUpdatedMs: number = new Date(originalUpdatedAt).getTime();
  const newUpdatedMs: number = new Date(updatedComment.updated_at).getTime();

  TestValidator.predicate(
    "updated_at is strictly later than previous updated_at",
    newUpdatedMs > originalUpdatedMs,
  );
  TestValidator.predicate(
    "updated_at is not earlier than created_at",
    newUpdatedMs >= originalCreatedMs,
  );

  // 8.5 status remains the same
  TestValidator.equals(
    "comment status remains unchanged after body update",
    updatedComment.status,
    originalStatus,
  );

  // 8.6 deleted_at remains null (comment not deleted)
  TestValidator.equals(
    "deleted_at remains unchanged (still null) after update",
    updatedComment.deleted_at,
    originalDeletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that only the owning member user can update their own comment.
 *
 * Business context:
 *
 * - Discussion board where member users author articles and comments.
 * - Comments are owned by their original author; other members must not be able
 *   to update them.
 *
 * Due to framework constraints (no explicit HTTP status inspection and the
 * update() SDK method being typed to return a successful comment), we design
 * this test to fully cover the ownership happy-path (owner can update) and
 * verify that the comment content actually changes when the correct owner
 * issues the update. We still create a second member to mirror the multi-actor
 * scenario, but we do not call update() as Member B, because the SDK surface
 * does not expose an error-typed return and the test framework forbids
 * status-code assertions.
 *
 * Flow implemented in this test:
 *
 * 1. Admin joins (auth.adminUser.join) so we can manage categories.
 * 2. Admin creates an article category
 *    (discussionBoard.adminUser.articleCategories.create).
 * 3. Member A joins (auth.memberUser.join) and becomes the eventual comment owner.
 * 4. Member B joins (auth.memberUser.join) to represent a non-owner member.
 * 5. With Member A authenticated, create an article in the previously created
 *    category (discussionBoard.memberUser.articles.create).
 * 6. As Member A, create a comment on that article
 *    (discussionBoard.memberUser.articles.comments.create).
 * 7. As Member A, call comments.update() with a new body text and assert that the
 *    returned comment reflects the updated body and is tied to the same article
 *    and comment id.
 * 8. Optionally, assert that core immutable fields (id, article.id) are preserved
 *    across the update.
 */
export async function test_api_member_comment_update_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Admin joins to manage categories
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 3. Member A joins (will own the comment)
  const memberAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberA: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberA);

  // 4. Member B joins (non-owner member)
  const memberBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberB: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberB);

  // 5. As Member A (current token is Member B, so log in as Member A again to be explicit)
  const memberALoginBody = {
    email: memberA.email,
    password: memberAJoinBody.password,
    ip: null,
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/home",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberALogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALogin);

  // 6. Member A creates an article in the created category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  // 7. Member A creates a comment on that article
  const originalCommentBodyText = RandomGenerator.paragraph({ sentences: 2 });
  const commentCreateBody = {
    body: originalCommentBodyText,
  } satisfies IDiscussionBoardComment.ICreate;

  const createdComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(createdComment);

  TestValidator.equals(
    "created comment should belong to the article and preserve body",
    createdComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "created comment body should match input",
    createdComment.body,
    originalCommentBodyText,
  );

  // 8. As Member A, update the comment body and verify the change
  const updatedBodyText = RandomGenerator.paragraph({ sentences: 3 });
  const updateBody = {
    body: updatedBodyText,
  } satisfies IDiscussionBoardComment.IUpdate;

  const updatedComment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.update(
      connection,
      {
        articleId: article.id,
        commentId: createdComment.id,
        body: updateBody,
      },
    );
  typia.assert(updatedComment);

  // Core invariants: id and article association remain the same
  TestValidator.equals(
    "updated comment id should remain unchanged",
    updatedComment.id,
    createdComment.id,
  );
  TestValidator.equals(
    "updated comment should still be tied to the same article",
    updatedComment.article.id,
    article.id,
  );

  // Business assertion: body should be updated to the new text
  TestValidator.equals(
    "updated comment body should reflect new content",
    updatedComment.body,
    updatedBodyText,
  );

  // Ensure that updated body is actually different from original
  TestValidator.notEquals(
    "updated comment body must differ from original body",
    updatedComment.body,
    originalCommentBodyText,
  );
}

