import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

export async function test_api_admin_user_profile_update_with_email_change(
  connection: api.IConnection,
) {
  // 1. Register first admin (admin A)
  const adminARequest = {
    email: `admin.a+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "AdminA!234",
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 4 }),
    ip: "203.0.113.10",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminA = await api.functional.auth.adminUser.join(connection, {
    body: adminARequest,
  });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminA);

  // 2. Register second admin (admin B) whose profile will be updated
  const adminBRequest = {
    email: `admin.b+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "AdminB!234",
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "203.0.113.11",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminB = await api.functional.auth.adminUser.join(connection, {
    body: adminBRequest,
  });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminB);

  // Basic sanity checks for authorized payloads
  TestValidator.predicate(
    "admin A and admin B must have different ids",
    adminA.id !== adminB.id,
  );
  TestValidator.predicate(
    "admin A and admin B must have different emails",
    adminA.email !== adminB.email,
  );

  // 3. Use admin B token to create an article category (admin-only endpoint)
  const categoryRequest = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryRequest },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category);

  // 4. Update admin B profile with a new unique email and changed display name
  const newEmail = `admin.b.updated+${RandomGenerator.alphaNumeric(8)}@example.com`;
  TestValidator.predicate(
    "new email must differ from both original admin emails",
    newEmail !== adminA.email && newEmail !== adminB.email,
  );

  const updateBody = {
    email: newEmail,
    displayName: RandomGenerator.name(),
  } satisfies IDiscussionBoardAdminuser.IUpdate;

  const updated: IDiscussionBoardAdminuser =
    await api.functional.discussionBoard.adminUser.adminUsers.update(
      connection,
      {
        adminUserId: adminB.id,
        body: updateBody,
      },
    );
  typia.assert<IDiscussionBoardAdminuser>(updated);

  // 5. Validate that profile fields have been updated as requested
  TestValidator.equals(
    "updated admin id must remain the same as admin B id",
    updated.id,
    adminB.id,
  );
  TestValidator.equals(
    "updated email must match the requested new email",
    updated.email,
    newEmail,
  );
  TestValidator.equals(
    "updated displayName must match the requested displayName",
    updated.displayName,
    updateBody.displayName,
  );

  // Additional sanity check: admin status and emailVerified are present and of expected primitive types.
  TestValidator.predicate(
    "accountStatus must be a non-empty string",
    typeof updated.accountStatus === "string" &&
      updated.accountStatus.length > 0,
  );
  TestValidator.predicate(
    "emailVerified must be a boolean",
    typeof updated.emailVerified === "boolean",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that updating an admin user's email to one already used by another
 * admin fails due to the unique email constraint and does not succeed as a
 * normal update.
 *
 * Business flow:
 *
 * 1. Join admin A with a unique emailA.
 * 2. Join admin B with a different unique emailB.
 * 3. While authenticated as admin B (token managed by SDK), create an article
 *    category to confirm admin-only access works.
 * 4. Attempt to update admin B's profile email to emailA via adminUsers.update.
 * 5. Assert that this conflicting update throws an error (uniqueness violation)
 *    using TestValidator.error.
 */
export async function test_api_admin_user_profile_update_email_uniqueness_violation(
  connection: api.IConnection,
) {
  // 1. Create admin A with a unique emailA
  const emailA: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const joinBodyA = {
    email: emailA,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminA = await api.functional.auth.adminUser.join(connection, {
    body: joinBodyA,
  });
  typia.assert(adminA);

  TestValidator.equals(
    "joined admin A email should equal emailA",
    adminA.email,
    emailA,
  );

  // 2. Create admin B with a different unique emailB
  let emailB: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  // Ensure emailB is different from emailA (loop for absolute safety)
  while (emailB === emailA) {
    emailB = typia.random<string & tags.Format<"email">>();
  }

  const joinBodyB = {
    email: emailB,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminB = await api.functional.auth.adminUser.join(connection, {
    body: joinBodyB,
  });
  typia.assert(adminB);

  TestValidator.equals(
    "joined admin B email should equal emailB",
    adminB.email,
    emailB,
  );

  // 3. As admin B, create an article category to confirm admin privileges work
  const categoryBody = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph(),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 4. Attempt to update admin B's email to the already-used emailA
  await TestValidator.error(
    "updating admin B email to admin A email must fail due to uniqueness constraint",
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.update(
        connection,
        {
          adminUserId: adminB.id,
          body: {
            email: adminA.email,
          } satisfies IDiscussionBoardAdminuser.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate updating lifecycle flags of an admin user profile.
 *
 * Business goal
 *
 * - Ensure that an authenticated adminUser can update another admin's
 *   lifecycle-related flags (accountStatus, emailVerified) and profile fields
 *   through the admin profile update endpoint.
 * - Confirm that the update response reflects the new values and that the admin
 *   context is able to perform other privileged operations.
 *
 * High-level flow
 *
 * 1. Register a first admin (controller) via POST /auth/adminUser/join.
 * 2. Register a second admin (managed target) via POST /auth/adminUser/join.
 * 3. Under the current admin context, create an article category via POST
 *    /discussionBoard/adminUser/articleCategories to prove privileged access.
 * 4. Call PUT /discussionBoard/adminUser/adminUsers/{adminUserId} for the managed
 *    admin using IDiscussionBoardAdminuser.IUpdate, updating accountStatus and
 *    emailVerified along with some profile metadata.
 * 5. Assert that the returned IDiscussionBoardAdminuser reflects the requested
 *    lifecycle flags and updated profile.
 */
export async function test_api_admin_user_profile_update_account_status_and_restrictions(
  connection: api.IConnection,
) {
  // 1. Join the first admin (controller).
  const controllerJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const controllerAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: controllerJoinRequest,
    });
  typia.assert(controllerAuthorized);

  // 2. Join the second admin (managed target).
  const managedJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const managedAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: managedJoinRequest,
    });
  typia.assert(managedAuthorized);

  // 3. Create an article category under the current admin context.
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const createdCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(createdCategory);

  // 4. Update the managed admin's lifecycle flags and profile.
  const newStatus = "suspended";
  const newEmailVerified = !managedAuthorized.emailVerified;
  const newDisplayName = `${managedAuthorized.displayName} (updated)`;

  const updateBody = {
    accountStatus: newStatus,
    emailVerified: newEmailVerified,
    displayName: newDisplayName,
  } satisfies IDiscussionBoardAdminuser.IUpdate;

  const updatedAdmin: IDiscussionBoardAdminuser =
    await api.functional.discussionBoard.adminUser.adminUsers.update(
      connection,
      {
        adminUserId: managedAuthorized.id,
        body: updateBody,
      },
    );
  typia.assert(updatedAdmin);

  // 5. Validate that lifecycle flags and profile were updated as requested.
  TestValidator.equals(
    "updated admin accountStatus should match requested value",
    updatedAdmin.accountStatus,
    newStatus,
  );

  TestValidator.equals(
    "updated admin emailVerified should match requested value",
    updatedAdmin.emailVerified,
    newEmailVerified,
  );

  TestValidator.equals(
    "updated admin displayName should match requested value",
    updatedAdmin.displayName,
    newDisplayName,
  );

  TestValidator.equals(
    "managed admin id should remain stable after update",
    updatedAdmin.id,
    managedAuthorized.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Verify that admin user profile update is rejected without proper admin
 * authentication.
 *
 * Business intent:
 *
 * - Ensure that the PUT /discussionBoard/adminUser/adminUsers/{adminUserId}
 *   endpoint enforces the `adminUser` authorization actor and cannot be invoked
 *   successfully by unauthenticated callers.
 * - Confirm that, when a valid admin session is present, other admin-only
 *   endpoints such as article category creation behave normally so we know the
 *   admin setup is correct.
 *
 * Scenario steps:
 *
 * 1. Call POST /auth/adminUser/join to create an admin account, which also
 *    establishes an authenticated `adminUser` session on the base connection.
 * 2. As that admin, call POST /discussionBoard/adminUser/articleCategories with a
 *    valid IDiscussionBoardArticleCategory.ICreate payload to verify that
 *    admin-only operations succeed under proper authentication.
 * 3. Create an unauthenticated connection by shallow-cloning the incoming
 *    connection but setting `headers` to an empty object, so no Authorization
 *    header is present.
 * 4. Using this unauthenticated connection, attempt to call PUT
 *    /discussionBoard/adminUser/adminUsers/{adminUserId} with a valid
 *    IDiscussionBoardAdminuser.IUpdate payload and expect the call to fail with
 *    an HttpError via TestValidator.httpError.
 * 5. Throughout, ensure that the base authenticated connection remains intact and
 *    is not mutated in a way that could affect other tests.
 */
export async function test_api_admin_user_profile_update_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Join as an admin user to obtain a valid admin session and id
  const joinBody = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const authorizedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorizedAdmin);

  // 2. As this admin, create an article category to verify admin-only access works
  const categoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();
  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(category);

  // 3. Prepare an update payload for the admin profile
  const updateBody = typia.random<IDiscussionBoardAdminuser.IUpdate>();

  // 4. Build an unauthenticated connection by clearing headers on a clone
  const unauthConn: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 5. Attempt to update admin profile without any Authorization header
  await TestValidator.httpError(
    "admin profile update without auth must fail",
    [401, 403],
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.update(
        unauthConn,
        {
          adminUserId: authorizedAdmin.id,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Verify that a privileged adminUser can hard delete another admin account and
 * that subsequent operations reflect the deletion semantics.
 *
 * Business flow under test:
 *
 * 1. Create a controlling adminUser via POST /auth/adminUser/join.
 * 2. As that admin, successfully perform an admin-only operation by creating a
 *    discussion-board article category.
 * 3. Create a second adminUser (the deletion target) via another join call, using
 *    a separate connection so tokens do not overwrite the controlling admin
 *    session.
 * 4. As the controlling admin (via its dedicated connection), hard delete the
 *    target admin via DELETE
 *    /discussionBoard/adminUser/adminUsers/{adminUserId}.
 * 5. Attempt a second delete on the same id and expect an error, proving the
 *    record is no longer deletable/found.
 * 6. Perform another admin-only category creation to confirm the controlling admin
 *    remains fully functional after deleting the target admin.
 */
export async function test_api_admin_user_hard_delete_success(
  connection: api.IConnection,
) {
  // Use a dedicated connection object for the controlling admin so that its
  // Authorization header is not overwritten when creating the target admin.
  const controllingConnection: api.IConnection = { ...connection };

  // 1. Create controlling admin via join
  const controllingJoinRequest =
    typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const controllingAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(controllingConnection, {
      body: controllingJoinRequest,
    });
  typia.assert(controllingAdmin);

  // 2. Admin-only operation: create an article category as controlling admin
  const firstCategoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();
  const firstCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      controllingConnection,
      { body: firstCategoryCreateBody },
    );
  typia.assert(firstCategory);

  // 3. Create target admin to be deleted, using a separate connection so that
  //    the controlling admin's Authorization token remains intact.
  const targetConnection: api.IConnection = { ...connection };
  const targetJoinRequest =
    typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const targetAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(targetConnection, {
      body: targetJoinRequest,
    });
  typia.assert(targetAdmin);

  // Sanity check: controlling admin and target admin must be different users.
  TestValidator.notEquals(
    "controlling admin and target admin must have different ids",
    controllingAdmin.id,
    targetAdmin.id,
  );

  // 4. Hard delete the target admin as the controlling admin
  await api.functional.discussionBoard.adminUser.adminUsers.erase(
    controllingConnection,
    {
      adminUserId: targetAdmin.id,
    },
  );

  // 5. Second delete should fail (target already deleted)
  await TestValidator.error(
    "second deletion of the same adminUserId should result in error",
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.erase(
        controllingConnection,
        { adminUserId: targetAdmin.id },
      );
    },
  );

  // 6. Controlling admin still can perform admin-only operations after deletion
  const secondCategoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();
  const secondCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      controllingConnection,
      { body: secondCategoryCreateBody },
    );
  typia.assert(secondCategory);

  TestValidator.notEquals(
    "distinct categories should have different ids",
    firstCategory.id,
    secondCategory.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Ensure that a self/primary admin account cannot be hard-deleted and remains
 * functional.
 *
 * Business goals:
 *
 * - Verify that DELETE /discussionBoard/adminUser/adminUsers/{adminUserId}
 *   rejects attempts to delete the currently authenticated admin (self-deletion
 *   / protected account).
 * - Prove that the admin remains operational after the failed deletion attempt by
 *   successfully executing another privileged operation.
 *
 * Steps:
 *
 * 1. Join a new adminUser via POST /auth/adminUser/join and capture its id.
 * 2. Using the issued admin token, create an article category to prove admin
 *    privileges work.
 * 3. Attempt DELETE /discussionBoard/adminUser/adminUsers/{adminUserId} with the
 *    same admin's id and assert that the call fails.
 * 4. Create another article category afterwards and assert success, demonstrating
 *    that the admin account/session still functions and was not deleted.
 */
export async function test_api_admin_user_hard_delete_protected_account(
  connection: api.IConnection,
) {
  // 1. Register a primary admin user (bootstrap/self account)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // Sanity check: admin email echoes back correctly
  TestValidator.equals(
    "joined admin email should match input email",
    admin.email,
    joinBody.email,
  );

  // 2. Create an article category as this admin to confirm privileges
  const firstCategoryBody = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const firstCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: firstCategoryBody,
      },
    );
  typia.assert(firstCategory);

  TestValidator.equals(
    "first category code should echo request",
    firstCategory.code,
    firstCategoryBody.code,
  );
  TestValidator.equals(
    "first category name should echo request",
    firstCategory.name,
    firstCategoryBody.name,
  );

  // 3. Try to hard delete the same admin account; this should be rejected
  await TestValidator.error(
    "self admin hard delete must be rejected",
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.erase(
        connection,
        {
          adminUserId: admin.id,
        },
      );
    },
  );

  // 4. After the failed deletion, verify that the admin is still functional
  //    by creating another category successfully.
  const secondCategoryBody = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 2 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const secondCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: secondCategoryBody,
      },
    );
  typia.assert(secondCategory);

  TestValidator.equals(
    "second category code should echo request after failed delete",
    secondCategory.code,
    secondCategoryBody.code,
  );
  TestValidator.equals(
    "second category name should echo request after failed delete",
    secondCategory.name,
    secondCategoryBody.name,
  );

  TestValidator.predicate(
    "admin performed privileged operations before and after delete attempt",
    firstCategory.id !== undefined && secondCategory.id !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
