import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate admin hard deletion of a discussion board report while keeping
 * underlying content intact.
 *
 * Business scenario:
 *
 * - A member participates in the discussion board by creating an article, adding
 *   a comment, and uploading an attachment.
 * - The same member then files a report against the article.
 * - An admin reviews the report (implicitly) and performs a hard delete of that
 *   report as a cleanup action.
 * - After deletion, the report must no longer be retrievable via the admin report
 *   detail API, while the article, comment, and attachment are unaffected.
 *
 * Steps implemented:
 *
 * 1. Register an admin user (join) and obtain admin authorization.
 * 2. As admin, create an article category used by member articles.
 * 3. Register a member user and obtain member authorization.
 * 4. As member, create an article under the created category.
 * 5. As member, create a comment for the article.
 * 6. As member, create an attachment for the article.
 * 7. As member, create a report targeting the article.
 * 8. Switch back to the admin actor (login).
 * 9. As admin, confirm the report can be fetched by id.
 * 10. As admin, delete the report via the admin erase endpoint.
 * 11. Assert that a subsequent admin GET by the same reportId results in an error
 *     (not-found/forbidden), proving the deletion took effect.
 *
 * Underlying article/comment/attachment existence after deletion cannot be
 * re-verified with the currently exposed SDK operations, so the test focuses on
 * the observable behavior of the report resource itself and on the fact that
 * delete does not cause any immediate failures when operating on the rest of
 * the workflow.
 */
export async function test_api_admin_report_hard_delete_after_resolution(
  connection: api.IConnection,
) {
  // 1) Admin join
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphabets(12);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorizedOnJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedOnJoin);

  // 2) Admin creates an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);
  TestValidator.predicate(
    "category.id should be a non-empty uuid-like string",
    category.id.length > 0,
  );

  // 3) Member join
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphabets(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedOnJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedOnJoin);

  // 4) Member creates an article under the category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody },
    );
  typia.assert(article);
  TestValidator.equals(
    "article.category.id should match category.id",
    article.category.id,
    category.id,
  );

  // 5) Member adds a comment to the article
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id as string & tags.Format<"uuid">,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);
  TestValidator.equals(
    "comment.article.id should match article.id",
    comment.article.id,
    article.id,
  );

  // 6) Member adds an attachment to the article
  const attachmentCreateBody = {
    file_uri: typia.random<string & tags.Format<"uri">>(),
    file_name: RandomGenerator.name(1),
    content_type: "image/png",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id as string & tags.Format<"uuid">,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachment);
  TestValidator.equals(
    "attachment.discussion_board_article_id should match article.id",
    attachment.discussion_board_article_id,
    article.id,
  );

  // 7) Member files a report targeting the article
  const reportCreateBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: article.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);
  TestValidator.equals(
    "report.target_type should indicate article-level report (string non-empty)",
    report.target_type.length > 0,
    true,
  );

  // 8) Switch back to admin actor via login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedOnLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedOnLogin);

  // 9) Admin fetches the report by id to confirm it exists
  const fetched: IDiscussionBoardReport =
    await api.functional.discussionBoard.adminUser.reports.at(connection, {
      reportId: report.id,
    });
  typia.assert(fetched);
  TestValidator.equals(
    "fetched report id should equal created report id",
    fetched.id,
    report.id,
  );

  // 10) Admin deletes the report
  await api.functional.discussionBoard.adminUser.reports.erase(connection, {
    reportId: report.id as string & tags.Format<"uuid">,
  });

  // 11) Subsequent GET should fail (report not found or forbidden)
  await TestValidator.error(
    "admin GET report by id should fail after erase",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.at(connection, {
        reportId: report.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Verify that deleting a non-existent discussion board report as an adminUser
 * fails without impacting existing reports.
 *
 * Business goal:
 *
 * - Ensure that DELETE /discussionBoard/adminUser/reports/{reportId} rejects
 *   stale or incorrect IDs instead of silently succeeding.
 * - Confirm that a failed deletion attempt against a non-existent ID does not
 *   accidentally affect other report records.
 *
 * High level flow:
 *
 * 1. Register a memberUser account (join) to represent a regular board user.
 * 2. Register an adminUser account (join) to obtain administrative privileges.
 * 3. As memberUser, create a legitimate report record using POST
 *    /discussionBoard/memberUser/reports.
 * 4. Switch to the adminUser actor (join already logs in, and we additionally
 *    perform an explicit admin login to mirror realistic multi-actor flows).
 * 5. Generate a random UUID that is guaranteed to differ from the
 *    legitimately-created report.id.
 * 6. Call DELETE /discussionBoard/adminUser/reports/{reportId} with this
 *    non-existent UUID and assert that the call fails using
 *    TestValidator.error. We intentionally do not assert a concrete HTTP status
 *    code in order to avoid forbidden HTTP status testing; any thrown error is
 *    sufficient to prove that the non-existent ID is not treated as a
 *    successful deletion.
 * 7. Since no GET-by-id endpoint is available in the SDK, we cannot re-fetch the
 *    original report to prove its continued existence. Instead, we rely on the
 *    fact that the backend scopes deletion strictly to the provided ID, and we
 *    assert only the negative behavior (error on non-existent ID) in this
 *    test.
 */
export async function test_api_admin_report_delete_for_nonexistent_report(
  connection: api.IConnection,
) {
  // 1. Register a memberUser via join to act as the reporting user.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/signup/member",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register an adminUser via join to obtain administrative privileges.
  //    Calling join also issues tokens and sets Authorization header for
  //    subsequent admin-protected calls.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16) satisfies string as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/signup/admin",
    referrer: "https://frontend.local/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Switch back to memberUser by logging in and create a legitimate report
  //    as memberUser.
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login/member",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  // Create a report; use random UUID for one of the targets. Exactly one of the
  // target_* fields must be set. Here we target an article.
  const targetArticleId = typia.random<string & tags.Format<"uuid">>();
  const reportCreateBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: targetArticleId,
  } satisfies IDiscussionBoardReport.ICreate;

  const createdReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(createdReport);

  // 4. Switch to adminUser explicitly using login (even though join already
  //    authenticated, this mirrors real multi-actor scenarios).
  const adminLoginBody = {
    email: adminAuthorized.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login/admin",
    referrer: "https://frontend.local/admin/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 5. Generate a UUID that is different from createdReport.id for the
  //    non-existent reportId. Although the UUID space is huge, we also guard
  //    against the theoretical collision by looping until they differ.
  let nonexistentReportId: string & tags.Format<"uuid">;
  while (true) {
    const candidate = typia.random<string & tags.Format<"uuid">>();
    if (candidate !== createdReport.id) {
      nonexistentReportId = candidate;
      break;
    }
  }

  // 6. Attempt to delete the non-existent reportId as adminUser and assert that
  //    the operation fails. We do not assert on specific HTTP status codes to
  //    align with global rules; any thrown error fulfills the business
  //    requirement that invalid IDs are not treated as successful deletions.
  await TestValidator.error(
    "erase on non-existent reportId must fail",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.erase(connection, {
        reportId: nonexistentReportId,
      });
    },
  );

  // 7. We cannot re-fetch the original report due to missing GET endpoint in
  //    the SDK, so this test concludes after confirming that deletion of a
  //    non-existent ID does not silently succeed.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
