    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. Member files a report targeting the created article
  const reportCreateBody = {
    category: "hate_abuse",
    reason: RandomGenerator.paragraph({ sentences: 4 }),
    target_article_id: article.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);

  // 6. Switch back to adminUser by logging in
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinRequest.password,
    ip: adminJoinRequest.ip ?? null,
    href: adminJoinRequest.href,
    referrer: adminJoinRequest.referrer,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginOutput: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginOutput);

  // 7. Admin retrieves the article-targeting report detail
  const detail: IDiscussionBoardReportOfArticle =
    await api.functional.discussionBoard.adminUser.reports.article.at(
      connection,
      {
        reportId: report.id,
      },
    );
  typia.assert(detail);

  // 8. Validate core relationships and consistency
  // 8-1. Report basics
  TestValidator.equals(
    "report id should match created report",
    detail.report.id,
    report.id,
  );

  TestValidator.equals(
    "report target_type should be article",
    detail.report.target_type,
    "article",
  );

  TestValidator.equals(
    "report reason_code should match category used in creation",
    detail.report.reason_code,
    reportCreateBody.category,
  );

  TestValidator.equals(
    "report description should match reason used in creation",
    detail.report.description ?? null,
    reportCreateBody.reason,
  );

  TestValidator.predicate(
    "report reporter_type should be a non-empty string",
    typeof detail.report.reporter_type === "string" &&
      detail.report.reporter_type.length > 0,
  );

  // 8-2. Article summary linkage
  TestValidator.equals(
    "linked article id should match created article",
    detail.article.id,
    article.id,
  );

  TestValidator.equals(
    "linked article category id should match created category",
    detail.article.category.id,
    category.id,
  );

  TestValidator.equals(
    "linked article category code should match created category",
    detail.article.category.code,
    category.code,
  );

  TestValidator.equals(
    "linked article category name should match created category",
    detail.article.category.name,
    category.name,
  );

  TestValidator.predicate(
    "article summary should have non-empty title",
    typeof detail.article.title === "string" && detail.article.title.length > 0,
  );

  TestValidator.predicate(
    "article summary author id should be non-empty",
    typeof detail.article.author.id === "string" &&
      detail.article.author.id.length > 0,
  );

  // 8-3. Link created_at sanity
  TestValidator.predicate(
    "link created_at should be a non-empty date-time string",
    typeof detail.created_at === "string" && detail.created_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfArticle";

/**
 * Validate not-found behavior for article-targeting report detail lookup.
 *
 * Business purpose: When an administrator reviews abuse reports, they
 * frequently open the detailed view for a specific report targeting an article.
 * If a client accidentally or maliciously sends an unknown reportId, the admin
 * endpoint GET /discussionBoard/adminUser/reports/{reportId}/article must
 * respond with a not-found style error instead of returning a misleading or
 * unrelated record.
 *
 * This test covers both sides:
 *
 * 1. Happy path sanity check – ensure that an existing article report can be
 *    retrieved successfully by an authenticated admin.
 * 2. Negative path – ensure that a random, non-existent reportId produces an error
 *    and does not return a normal IDiscussionBoardReportOfArticle payload.
 *
 * High-level steps
 *
 * 1. Create and authenticate a memberUser actor.
 * 2. As that memberUser, create an article.
 * 3. As that memberUser, file a report targeting that article.
 * 4. Create and authenticate an adminUser actor.
 * 5. As the adminUser, successfully fetch the article-targeting report detail by
 *    the real report id and validate the payload.
 * 6. Generate a random UUID that should not match any existing report.
 * 7. As the adminUser, attempt to fetch article report detail with this
 *    non-existent reportId and assert that the call fails via
 *    TestValidator.error.
 */
export async function test_api_admin_article_report_detail_not_found(
  connection: api.IConnection,
) {
  // 1) Create and authenticate a memberUser actor via join (auto-login)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://frontend.example.com/join",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2) As that memberUser, create an article.
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    // Use a random UUID for categoryId as we do not have category listing APIs.
    categoryId: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 3) As that memberUser, file a report targeting that article.
  const reportCreateBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 4 }),
    target_article_id: article.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);

  // 4) Create and authenticate an adminUser actor via join (auto-login)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(2),
    bio: null,
    ip: null,
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 5) Happy-path sanity: fetch existing article report detail as admin.
  const existingDetail: IDiscussionBoardReportOfArticle =
    await api.functional.discussionBoard.adminUser.reports.article.at(
      connection,
      {
        reportId: report.id,
      },
    );
  typia.assert(existingDetail);

  // Basic business sanity checks: the nested report id should match, and
  // the article id should be the article we reported.
  TestValidator.equals(
    "existing detail: report id matches created report",
    existingDetail.report.id,
    report.id,
  );
  TestValidator.equals(
    "existing detail: article id matches created article",
    existingDetail.article.id,
    article.id,
  );

  // 6) Generate a non-existent reportId.
  const nonExistingReportId = typia.random<string & tags.Format<"uuid">>();

  // 7) As admin, attempt to fetch article report detail for a non-existent id
  // and assert that the call fails with an HttpError (e.g., not-found).
  await TestValidator.error(
    "non-existent reportId must cause not-found style error",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.article.at(
        connection,
        {
          reportId: nonExistingReportId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfArticle";

/**
 * Verify that the article-specific report detail endpoint rejects non-article
 * targets while succeeding for article-targeting reports.
 *
 * Business goal
 *
 * - Ensure GET /discussionBoard/adminUser/reports/{reportId}/article only works
 *   when the report actually targets an article, and fails when the report is
 *   for a comment or attachment.
 *
 * Steps
 *
 * 1. Admin joins and creates an article category.
 * 2. Member joins and creates an article in that category.
 * 3. Member adds a comment and an attachment to the article.
 * 4. Member files three reports: comment-targeting, attachment-targeting, and
 *    article-targeting.
 * 5. Admin logs in again and calls the article-detail report endpoint with each
 *    report id.
 * 6. Validate that:
 *
 *    - Article-targeting report returns IDiscussionBoardReportOfArticle whose ids
 *         match the created entities.
 *    - Comment-targeting and attachment-targeting reports cause errors when used
 *         with the article-detail endpoint.
 */
export async function test_api_admin_article_report_detail_for_non_article_target(
  connection: api.IConnection,
) {
  // 1) Admin joins (acquires adminUser tokens via SDK side effect)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> =
    "Admin!" + RandomGenerator.alphaNumeric(8);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2) Admin creates an article category
  const categoryBody = {
    code: "ECONOMY_" + RandomGenerator.alphaNumeric(6),
    name: "Economy " + RandomGenerator.name(1),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3) Member joins (memberUser actor) and becomes authenticated
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = "Member!" + RandomGenerator.alphaNumeric(8);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4) Member creates an article in the category
  const articleBody = {
    title: "Article about macro economy " + RandomGenerator.name(1),
    body: RandomGenerator.content({ paragraphs: 3 }),
    summary: RandomGenerator.paragraph({ sentences: 3 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5) Member adds a comment to the article
  const commentBody = {
    body: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  // 6) Member adds an attachment to the article
  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(12),
    file_name: "macro-economy-report.pdf",
    content_type: "application/pdf",
    file_size: 1024,
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 7) Member files three reports via /discussionBoard/memberUser/reports
  // 7-1) Comment-targeting report
  const commentReportBody = {
    category: "hate_abuse",
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    target_article_id: undefined,
    target_comment_id: comment.id,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const commentReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: commentReportBody,
    });
  typia.assert(commentReport);

  // 7-2) Attachment-targeting report
  const attachmentReportBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    target_article_id: undefined,
    target_comment_id: undefined,
    target_attachment_id: attachment.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const attachmentReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: attachmentReportBody,
    });
  typia.assert(attachmentReport);

  // 7-3) Article-targeting report
  const articleReportBody = {
    category: "off_topic",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: article.id,
    target_comment_id: undefined,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const articleReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: articleReportBody,
    });
  typia.assert(articleReport);

  // 8) Switch back to adminUser using login to restore admin auth context
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 9) Successful path: article-targeting report should return article details
  const articleDetail: IDiscussionBoardReportOfArticle =
    await api.functional.discussionBoard.adminUser.reports.article.at(
      connection,
      {
        reportId: articleReport.id,
      },
    );
  typia.assert(articleDetail);

  TestValidator.equals(
    "article-targeting report id must match",
    articleDetail.report.id,
    articleReport.id,
  );
  TestValidator.equals(
    "article-targeting article id must match",
    articleDetail.article.id,
    article.id,
  );

  // 10) Failure paths: comment- and attachment-targeting reports should fail
  await TestValidator.error(
    "comment-targeting report cannot be resolved by article detail endpoint",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.article.at(
        connection,
        {
          reportId: commentReport.id,
        },
      );
    },
  );

  await TestValidator.error(
    "attachment-targeting report cannot be resolved by article detail endpoint",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.article.at(
        connection,
        {
          reportId: attachmentReport.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that an authenticated adminUser can update basic mutable fields of a
 * discussion-board article category identified by its business code.
 *
 * Business flow covered:
 *
 * 1. Register a new adminUser with POST /auth/adminUser/join.
 * 2. As that adminUser, create an article category with POST
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Update the category’s name, description, and order via PUT
 *    /discussionBoard/adminUser/articleCategories/{categoryCode}, keeping the
 *    business code stable.
 * 4. Verify that mutable fields are changed, immutable identifiers are preserved,
 *    and audit fields behave correctly (created_at stable, updated_at
 *    refreshed, deleted_at still null/undefined).
 */
export async function test_api_article_category_update_basic_fields_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new adminUser and obtain authenticated context.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: RandomGenerator.alphabets(12),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create an initial article category as this adminUser.
  const initialCode: string = `CAT_${RandomGenerator.alphabets(8).toUpperCase()}`;
  const initialName: string = RandomGenerator.name(2);
  const initialDescription: string = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 4,
    wordMax: 10,
  });
  const initialOrder = typia.random<number & tags.Type<"int32">>();

  const createBody = {
    code: initialCode,
    name: initialName,
    description: initialDescription,
    order: initialOrder,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const createdCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: createBody,
      },
    );
  typia.assert(createdCategory);

  // Capture baseline values for comparison.
  const createdId = createdCategory.id;
  const createdCode = createdCategory.code;
  const createdName = createdCategory.name;
  const createdDescription = createdCategory.description ?? null;
  const createdOrder = createdCategory.order;
  const createdCreatedAt = createdCategory.created_at;
  const createdUpdatedAt = createdCategory.updated_at;
  const createdDeletedAt = createdCategory.deleted_at ?? null;

  // Sanity checks on creation.
  TestValidator.equals(
    "created category code matches requested code",
    createdCode,
    initialCode,
  );
  TestValidator.equals(
    "created category name matches requested name",
    createdName,
    initialName,
  );
  TestValidator.equals(
    "created category description matches requested description",
    createdDescription,
    initialDescription,
  );
  TestValidator.equals(
    "created category order matches requested order",
    createdOrder,
    initialOrder,
  );

  // 3. Update mutable fields via PUT using the category code as identifier.
  const updatedName: string = RandomGenerator.name(3);
  const updatedDescription: string = RandomGenerator.paragraph({
    sentences: 5,
    wordMin: 4,
    wordMax: 10,
  });
  const updatedOrder = typia.random<number & tags.Type<"int32">>();

  const updateBody = {
    name: updatedName,
    description: updatedDescription,
    order: updatedOrder,
  } satisfies IDiscussionBoardArticleCategory.IUpdate;

  const updatedCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.update(
      connection,
      {
        categoryCode: createdCode,
        body: updateBody,
      },
    );
  typia.assert(updatedCategory);

  // 4. Assertions: verify identifiers and fields after update.

  // Immutable identifiers should remain stable.
  TestValidator.equals(
    "category id is preserved after update",
    updatedCategory.id,
    createdId,
  );
  TestValidator.equals(
    "category code is preserved after update",
    updatedCategory.code,
    createdCode,
  );

  // Mutable fields should reflect updated values.
  TestValidator.equals(
    "category name is updated",
    updatedCategory.name,
    updatedName,
  );
  TestValidator.equals(
    "category description is updated",
    updatedCategory.description ?? null,
    updatedDescription,
  );
  TestValidator.equals(
    "category order is updated",
    updatedCategory.order,
    updatedOrder,
  );

  // Ensure at least one mutable field actually changed from original values.
  TestValidator.notEquals(
    "updated category name differs from original name",
    updatedCategory.name,
    createdName,
  );
  TestValidator.notEquals(
    "updated category order differs from original order",
    updatedCategory.order,
    createdOrder,
  );

  // Audit field behavior: created_at stable, updated_at refreshed, deleted_at unchanged.
  TestValidator.equals(
    "created_at is unchanged after update",
    updatedCategory.created_at,
    createdCreatedAt,
  );
  TestValidator.notEquals(
    "updated_at is refreshed after update",
    updatedCategory.updated_at,
    createdUpdatedAt,
  );

  const updatedDeletedAt = updatedCategory.deleted_at ?? null;
  TestValidator.equals(
    "deleted_at remains unchanged and nullish after update",
    updatedDeletedAt,
    createdDeletedAt,
  );
}

