import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate that updating a discussion board article category with a
 * non-existent business code fails and does not behave like an upsert.
 *
 * Business intent:
 *
 * - The PUT /discussionBoard/adminUser/articleCategories/:categoryCode operation
 *   is a pure update, not an upsert.
 * - When the target categoryCode does not exist in
 *   discussion_board_article_categories, the server must return an error
 *   instead of creating a new category.
 *
 * Test flow:
 *
 * 1. Join as an adminUser using POST /auth/adminUser/join to establish
 *    authenticated context (SDK: api.functional.auth.adminUser.join).
 * 2. Create at least one real category using POST
 *    /discussionBoard/adminUser/articleCategories (SDK:
 *    api.functional.discussionBoard.adminUser.articleCategories.create) so the
 *    table is non-empty and we know the set of real codes.
 * 3. Choose a deliberately non-existent categoryCode (e.g. "UNKNOWN_CODE") that
 *    differs from any created code.
 * 4. Call PUT /discussionBoard/adminUser/articleCategories/{categoryCode} (SDK:
 *    api.functional.discussionBoard.adminUser.articleCategories.update) with
 *    that fake code and a valid IDiscussionBoardArticleCategory.IUpdate body.
 * 5. Assert that the call results in an error (using TestValidator.error), proving
 *    that the endpoint does not accept non-existent codes and does not silently
 *    create new categories.
 *
 * Limitations:
 *
 * - No list/detail endpoint for categories is provided here, so we cannot
 *   directly re-query to prove absence of a new row. Instead, we rely on the
 *   fact that a failing update means no creation took place.
 */
export async function test_api_article_category_update_nonexistent_code_not_found(
  connection: api.IConnection,
) {
  // 1. Join as adminUser to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create a real category so that the table is known to be non-empty and
  //    we know at least one valid code.
  const realCategoryBody = {
    code: "ECONOMY",
    name: "Economy",
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const realCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: realCategoryBody,
      },
    );
  typia.assert(realCategory);

  // Confirm that our chosen fake code does not equal the real category code.
  const fakeCode = "UNKNOWN_CODE";
  TestValidator.notEquals(
    "fake code must differ from real category code",
    realCategory.code,
    fakeCode,
  );

  // 3 & 4. Attempt to update a non-existent categoryCode.
  const updateBody = {
    name: "Updated Nonexistent Category",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 999 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.IUpdate;

  await TestValidator.error(
    "updating non-existent category must fail",
    async () => {
      await api.functional.discussionBoard.adminUser.articleCategories.update(
        connection,
        {
          categoryCode: fakeCode,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate updating display order of discussion-board article categories.
 *
 * This test ensures that an authenticated adminUser can safely adjust the
 * `order` field of an existing discussion-board article category using the
 * update endpoint that targets categories by their `code`. It verifies that
 * changing the display order does not alter the category's identity (its stable
 * business `code` and primary key `id`) and that other mutable fields such as
 * `name` and `description` remain unchanged when omitted from the update
 * payload.
 *
 * Business context:
 *
 * - Categories like "ECONOMY" or "POLITICS" are master data used for
 *   classification and filtering of articles.
 * - Administrators need to reorder these categories in UIs without breaking
 *   references or accidentally changing labels or descriptions.
 * - The update endpoint identifies categories by their globally unique `code`
 *   (`categoryCode` path parameter) rather than UUID, so the test specifically
 *   validates this business identifier behavior.
 *
 * Steps:
 *
 * 1. Join as an adminUser via POST /auth/adminUser/join to obtain an authenticated
 *    admin session.
 * 2. As this adminUser, create two categories via POST
 *    /discussionBoard/adminUser/articleCategories with distinct codes, names,
 *    and initial `order` values (e.g. 1 and 2).
 * 3. Perform a first update using PUT
 *    /discussionBoard/adminUser/articleCategories/{categoryCode} on the second
 *    category, changing only its `order` (e.g. from 2 to 1) while omitting
 *    `name` and `description`.
 * 4. Assert that:
 *
 *    - The response `id` and `code` match the original category.
 *    - `name` and `description` are unchanged from the original.
 *    - `order` is updated to the new value.
 * 5. Perform a second update on the same category with another `order` change
 *    (e.g. from 1 to 3) again omitting other fields.
 * 6. Assert again that identity fields remain stable and non-updated fields are
 *    preserved, while `order` reflects the latest value.
 */
export async function test_api_article_category_update_conflicting_order_or_minor_reordering(
  connection: api.IConnection,
) {
  // 1. Join as an adminUser to establish authenticated admin session.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "127.0.0.1",
    href: "https://admin.discussion-board.local/join",
    referrer: "https://admin.discussion-board.local/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(adminAuthorized);

  // 2. Create two distinct categories with different codes and orders.
  const category1Create = {
    code: `ECONOMY_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category2Create = {
    code: `POLITICS_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 2 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category1 =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: category1Create },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category1);

  const category2 =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: category2Create },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category2);

  // Sanity checks: created categories reflect create payloads.
  TestValidator.equals(
    "category1 code matches create payload",
    category1.code,
    category1Create.code,
  );
  TestValidator.equals(
    "category2 code matches create payload",
    category2.code,
    category2Create.code,
  );

  // 3. First update: change only `order` of the second category (minor reorder).
  const firstNewOrder = 1 as number & tags.Type<"int32">;
  const firstUpdateBody = {
    order: firstNewOrder,
  } satisfies IDiscussionBoardArticleCategory.IUpdate;

  const updatedOnce =
    await api.functional.discussionBoard.adminUser.articleCategories.update(
      connection,
      {
        categoryCode: category2.code,
        body: firstUpdateBody,
      },
    );
  typia.assert<IDiscussionBoardArticleCategory>(updatedOnce);

  // 4. Assertions after first update.
  TestValidator.equals(
    "first update preserves id",
    updatedOnce.id,
    category2.id,
  );
  TestValidator.equals(
    "first update preserves code",
    updatedOnce.code,
    category2.code,
  );
  TestValidator.equals(
    "first update preserves name",
    updatedOnce.name,
    category2.name,
  );
  TestValidator.equals(
    "first update preserves description",
    updatedOnce.description ?? null,
    category2.description ?? null,
  );
  TestValidator.equals(
    "first update changes order to new value",
    updatedOnce.order,
    firstNewOrder,
  );

  // 5. Second update: change `order` again to another value.
  const secondNewOrder = 3 as number & tags.Type<"int32">;
  const secondUpdateBody = {
    order: secondNewOrder,
  } satisfies IDiscussionBoardArticleCategory.IUpdate;

  const updatedTwice =
    await api.functional.discussionBoard.adminUser.articleCategories.update(
      connection,
      {
        categoryCode: category2.code,
        body: secondUpdateBody,
      },
    );
  typia.assert<IDiscussionBoardArticleCategory>(updatedTwice);

  // 6. Assertions after second update.
  TestValidator.equals(
    "second update still preserves id",
    updatedTwice.id,
    category2.id,
  );
  TestValidator.equals(
    "second update still preserves code",
    updatedTwice.code,
    category2.code,
  );
  TestValidator.equals(
    "second update still preserves name",
    updatedTwice.name,
    category2.name,
  );
  TestValidator.equals(
    "second update still preserves description",
    updatedTwice.description ?? null,
    category2.description ?? null,
  );
  TestValidator.equals(
    "second update changes order to latest value",
    updatedTwice.order,
    secondNewOrder,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

export async function test_api_article_category_update_on_retired_category_behavior(
  connection: api.IConnection,
) {
  // 1. Join as adminUser to obtain authenticated context
  const joinBody = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create an initial active category
  const createBody = typia.random<IDiscussionBoardArticleCategory.ICreate>();
  const createdCategory: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: createBody,
      },
    );
  typia.assert(createdCategory);

  // 3. Retire the category via erase (logical delete)
  await api.functional.discussionBoard.adminUser.articleCategories.erase(
    connection,
    {
      categoryCode: createdCategory.code,
    },
  );

  // 4. Prepare deterministic update payload
  const updatedName = `${createdCategory.name} (updated after retire)`;
  const updatedDescription =
    (createdCategory.description ?? "") + " :: updated";
  const updatedOrder = createdCategory.order + 1;

  const updateBody = {
    name: updatedName,
    description: updatedDescription,
    order: updatedOrder,
  } satisfies IDiscussionBoardArticleCategory.IUpdate;

  // 5. Attempt to update the retired category.
  //    We don't know whether backend allows this or not, so we:
  //    - try once and see if it succeeds
  //    - if it throws, we assert that subsequent attempts continue to fail
  let updateSucceeded = false;
  let updatedCategory: IDiscussionBoardArticleCategory | null = null;

  try {
    updatedCategory =
      await api.functional.discussionBoard.adminUser.articleCategories.update(
        connection,
        {
          categoryCode: createdCategory.code,
          body: updateBody,
        },
      );
    typia.assert(updatedCategory);
    updateSucceeded = true;
  } catch {
    updateSucceeded = false;
  }

  if (updateSucceeded && updatedCategory !== null) {
    // 6A. Behavior: update on retired category is allowed (possibly reactivation)
    // Validate type and that updated fields match request body.
    TestValidator.equals(
      "updated category code should remain same as created",
      updatedCategory.code,
      createdCategory.code,
    );
    TestValidator.equals(
      "updated category name should match update payload",
      updatedCategory.name,
      updatedName,
    );
    TestValidator.equals(
      "updated category description should match update payload",
      updatedCategory.description,
      updatedDescription,
    );
    TestValidator.equals(
      "updated category order should match update payload",
      updatedCategory.order,
      updatedOrder,
    );
  } else {
    // 6B. Behavior: update on retired category is disallowed
    // We now assert that calling update on the retired code results in an error.
    await TestValidator.error(
      "updating a retired category should consistently fail",
      async () => {
        await api.functional.discussionBoard.adminUser.articleCategories.update(
          connection,
          {
            categoryCode: createdCategory.code,
            body: updateBody,
          },
        );
      },
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
