import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate idempotent deletion (retirement) of discussion-board article
 * categories.
 *
 * Business context: Administrative users (adminUser actor) manage
 * discussion-board article categories that live in
 * `discussion_board_article_categories`. Deletion is implemented as a
 * retirement via the `deleted_at` timestamp. This test ensures that deleting a
 * category by its business `code` is safe and well-defined even when invoked
 * multiple times for the same category.
 *
 * Test goal: Verify that calling DELETE
 * /discussionBoard/adminUser/articleCategories/{categoryCode} on an
 * already-retired category behaves idempotently from the client perspective:
 * the second call must not cause unexpected failures at the test level and must
 * be treated as a stable, well-defined operation.
 *
 * End-to-end workflow:
 *
 * 1. Register an adminUser via POST /auth/adminUser/join.
 *
 *    - Use a random but valid email, password, href, and referrer to obtain an
 *         authenticated admin session.
 * 2. As this adminUser, create an article category via POST
 *    /discussionBoard/adminUser/articleCategories.
 *
 *    - Construct an IDiscussionBoardArticleCategory.ICreate body with:
 *
 *         - Unique `code` (stable machine-friendly string)
 *         - Random human-friendly `name`
 *         - Optional `description` (random paragraph or null)
 *         - `order` as a reasonable int32 value.
 *    - Receive IDiscussionBoardArticleCategory and assert its shape with
 *         typia.assert.
 * 3. Retire the category via DELETE
 *    /discussionBoard/adminUser/articleCategories/{categoryCode}.
 *
 *    - Use the `code` from the created category as `categoryCode`.
 *    - The erase() function returns void; simply await it to ensure successful
 *         completion.
 * 4. Immediately call the same DELETE endpoint again with the identical
 *    `categoryCode`.
 *
 *    - Wrap the second call in TestValidator.error to validate that the backend
 *         exposes a well-defined behavior for already-retired categories. Since
 *         we are prohibited from checking exact HTTP status codes, we only
 *         assert that some error is thrown (e.g., not-found or business-rule
 *         violation), which still represents clear semantics from the
 *         perspective of this test.
 *
 * Assertions and validations:
 *
 * - Typia.assert on the admin join response
 *   (IDiscussionBoardAdminuser.IAuthorized).
 * - Typia.assert on the created category (IDiscussionBoardArticleCategory).
 * - For the first DELETE call, only await the promise to ensure it completes
 *   successfully without throwing.
 * - For the second DELETE, use `await TestValidator.error` with an async closure
 *   that calls erase(), asserting that the system does not silently succeed
 *   when attempting to delete an already-retired category. We do not validate
 *   specific HTTP status codes or error messages.
 */
export async function test_api_article_category_delete_idempotent_on_already_retired_category(
  connection: api.IConnection,
) {
  // 1. Register an adminUser to obtain an authenticated admin session.
  const joinBody = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();
  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Create a new article category with a unique code.
  const createBody = {
    code: RandomGenerator.alphaNumeric(12).toUpperCase(),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: createBody,
      },
    );
  typia.assert(category);

  // 3. First delete: retire the newly created category by its business code.
  await api.functional.discussionBoard.adminUser.articleCategories.erase(
    connection,
    {
      categoryCode: category.code,
    },
  );

  // 4. Second delete: attempt to delete the already-retired category again.
  //    We assert that some error is thrown, representing clear semantics
  //    (e.g., not-found or already-retired) without validating specific status.
  await TestValidator.error(
    "second delete on already-retired category should fail with a defined error",
    async () => {
      await api.functional.discussionBoard.adminUser.articleCategories.erase(
        connection,
        {
          categoryCode: category.code,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";

export async function test_api_admin_reports_search_by_status_and_target_type(
  connection: api.IConnection,
) {
  // 1. Admin join (auto-sets admin token on connection)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Member join (switches token to member user)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Switch back to admin to create a category
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 4. Switch to member to create article, comment, attachment, and reports
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://member.example.com/login",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  const commentBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: `${RandomGenerator.alphaNumeric(8)}.txt`,
    content_type: "text/plain",
    file_size: 1024,
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 5. Create three reports as member: article, comment, attachment
  const reportArticleBody = {
    category: "hate_abuse",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: article.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const reportCommentBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_comment_id: comment.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const reportAttachmentBody = {
    category: "off_topic",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_attachment_id: attachment.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const reportArticle: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportArticleBody,
    });
  typia.assert(reportArticle);

  const reportComment: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCommentBody,
    });
  typia.assert(reportComment);

  const reportAttachment: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportAttachmentBody,
    });
  typia.assert(reportAttachment);

  // 6. Switch back to admin to search reports
  const adminReLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminReLogin);

  // First, get baseline for article target_type without status filter
  const baselineRequest = {
    page: 1,
    limit: 50,
    status: undefined,
    target_type: "article",
    reporter_type: undefined,
    created_from: undefined,
    created_to: undefined,
    order_by: undefined,
    order_direction: undefined,
  } satisfies IDiscussionBoardReport.IRequest;

  const baselinePage: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.adminUser.reports.index(connection, {
      body: baselineRequest,
    });
  typia.assert(baselinePage);

  // Find the baseline summary for the article report
  const articleSummary = baselinePage.data.find(
    (summary) => summary.id === reportArticle.id,
  );

  await TestValidator.predicate(
    "article report should be present in baseline article-target list",
    async () => articleSummary !== undefined,
  );

  if (!articleSummary) return; // Defensive: nothing more to assert if not found

  const targetStatus: string = articleSummary.status;

  // 7. Execute combined filter query: status + target_type
  const filterLimit = 20;

  const filteredRequest = {
    page: 1,
    limit: filterLimit,
    status: targetStatus,
    target_type: "article",
    reporter_type: undefined,
    created_from: undefined,
    created_to: undefined,
    order_by: undefined,
    order_direction: undefined,
  } satisfies IDiscussionBoardReport.IRequest;

  const filteredPage: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.adminUser.reports.index(connection, {
      body: filteredRequest,
    });
  typia.assert(filteredPage);

  const pagination: IPage.IPagination = filteredPage.pagination;
  typia.assert(pagination);

  // 8. Pagination consistency assertions
  TestValidator.equals(
    "pagination.limit should equal requested limit",
    pagination.limit,
    filterLimit,
  );

  await TestValidator.predicate(
    "pagination.current must be non-negative",
    async () => pagination.current >= 0,
  );

  await TestValidator.predicate(
    "pagination.records must be >= data.length",
    async () => pagination.records >= filteredPage.data.length,
  );

  await TestValidator.predicate(
    "pagination.pages must be >= 0",
    async () => pagination.pages >= 0,
  );

  if (pagination.records === 0) {
    await TestValidator.predicate(
      "when records==0, data.length must be 0 and pages must be 0",
      async () => filteredPage.data.length === 0 && pagination.pages === 0,
    );
  } else if (pagination.records <= pagination.limit) {
    await TestValidator.predicate(
      "when records <= limit and records > 0, pages must be 1",
      async () => pagination.pages === 1,
    );
  }

  // 9. Business assertions: all results match status + target_type
  for (const summary of filteredPage.data) {
    TestValidator.equals(
      "summary.status should equal requested status",
      summary.status,
      targetStatus,
    );
    TestValidator.equals(
      "summary.target_type should be 'article'",
      summary.target_type,
      "article",
    );
  }

  // Ensure that the article report appears in filtered data
  const filteredHasArticle = filteredPage.data.some(
    (summary) => summary.id === reportArticle.id,
  );

  await TestValidator.predicate(
    "filtered result must contain the article report",
    async () => filteredHasArticle,
  );

  // Ensure that comment and attachment reports are excluded from article+status filter
  const filteredHasComment = filteredPage.data.some(
    (summary) => summary.id === reportComment.id,
  );
  const filteredHasAttachment = filteredPage.data.some(
    (summary) => summary.id === reportAttachment.id,
  );

  await TestValidator.predicate(
    "filtered result must NOT contain comment-targeting report",
    async () => filteredHasComment === false,
  );

  await TestValidator.predicate(
    "filtered result must NOT contain attachment-targeting report",
    async () => filteredHasAttachment === false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";

/**
 * Validate admin report search pagination boundaries and consistency.
 *
 * Business context: Admin users review discussion board reports through a
 * paginated listing API (PATCH /discussionBoard/adminUser/reports). This test
 * ensures that when there are more reports than a single page can hold,
 * pagination metadata in IPage.IPagination and the data slice of
 * IDiscussionBoardReport.ISummary behave consistently for first, middle, and
 * beyond-last page requests.
 *
 * Steps:
 *
 * 1. Register an adminUser (join) so we can create article categories and later
 *    call the admin reports index endpoint.
 * 2. Register a memberUser (join) who will create an article and file reports.
 * 3. As adminUser, create an article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Switch to memberUser, create a single article in that category.
 * 5. Still as memberUser, create N reports (N > pageLimit * 2, e.g. 13–15) all
 *    targeting the same article via /discussionBoard/memberUser/reports.
 * 6. Switch back to adminUser and query /discussionBoard/adminUser/reports with a
 *    small limit (e.g. 5) and different page values:
 *
 *    - First page: page=1
 *    - Middle page: page=2
 *    - Out-of-range page: page set to a very large number (e.g. 9999)
 * 7. For each response, assert that:
 *
 *    - Pagination.records equals the total records matching the query (we know it
 *         must be >= number of created reports, but due to pre-existing data in
 *         shared test DB we only assert lower bounds and consistency
 *         relationships rather than exact equality).
 *    - Pagination.pages == 0 iff records == 0.
 *    - If records > 0 then pages >= 1 and 0 <= current < pages.
 *    - Data.length <= pagination.limit.
 *    - If pages == 0, then data.length == 0.
 *    - For the first page call, current == 0 and data.length > 0 when records > 0.
 *    - For the middle page call, when pages >= 2, current == 1 and data.length <=
 *         limit.
 *    - For the out-of-range page call, either:
 *
 *         - Current is clamped to pages-1 (and data.length > 0), or
 *         - Pages == 0 && records == 0 && data.length == 0, or
 *         - Pages > 0 with current within range and data.length <= limit but potentially
 *                   empty if implementation chooses that semantics.
 *
 * Implementation notes:
 *
 * - Use RandomGenerator and typia.random to generate realistic test data,
 *   respecting DTO constraints (email format, URI formats, etc.).
 * - Use IDiscussionBoardAdminUserJoin.IRequest and
 *   IDiscussionBoardAdminUserLogin.IRequest for admin auth, and corresponding
 *   memberUser DTOs for member auth.
 * - Use IDiscussionBoardArticleCategory.ICreate and
 *   IDiscussionBoardArticle.ICreate for category/article creation.
 * - Use IDiscussionBoardReport.ICreate with target_article_id set to the created
 *   article ID when creating reports.
 * - Use IDiscussionBoardReport.IRequest for the admin reports index body, setting
 *   page and limit and a reporter_type filter of "memberuser" and target_type
 *   "article" to focus on the reports we just created.
 * - Always validate response types with typia.assert and use TestValidator for
 *   business-rule assertions.
 */
export async function test_api_admin_reports_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Register an adminUser via join
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // Extract admin email for later login (though join already authenticates)
  const adminEmail: string & tags.Format<"email"> = adminAuthorized.email;

  // 2. Register a memberUser via join
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberEmail: string & tags.Format<"email"> = memberAuthorized.email;

  // 3. As adminUser, create an article category
  // (join has already set admin token on connection)
  const categoryCreateBody = {
    code: `CAT-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Switch to memberUser and create an article in that category
  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const reloggedMember: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(reloggedMember);

  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. As memberUser, create multiple reports targeting this article
  const pageLimit = 5 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const reportCount = pageLimit * 3; // ensure multiple pages worth of reports

  await ArrayUtil.asyncRepeat(reportCount, async (index) => {
    const reportBody = {
      category: RandomGenerator.pick([
        "hate_abuse",
        "harassment",
        "spam",
        "off_topic",
        "dangerous_misleading",
        "other",
      ] as const),
      reason: RandomGenerator.paragraph({ sentences: 3 }),
      target_article_id: article.id,
      target_comment_id: undefined,
      target_attachment_id: undefined,
    } satisfies IDiscussionBoardReport.ICreate;

    const report: IDiscussionBoardReport =
      await api.functional.discussionBoard.memberUser.reports.create(
        connection,
        {
          body: reportBody,
        },
      );
    typia.assert(report);
  });

  // Helper to validate pagination consistency
  const assertPaginationConsistency = (
    title: string,
    page: IPage.IPagination,
    dataLength: number,
  ): void => {
    const { current, limit, records, pages } = page;

    TestValidator.predicate(
      `${title} - limit is non-negative`,
      () => limit >= 0,
    );
    TestValidator.predicate(
      `${title} - records is non-negative`,
      () => records >= 0,
    );
    TestValidator.predicate(
      `${title} - pages is non-negative`,
      () => pages >= 0,
    );

    // pages == 0 iff records == 0
    if (records === 0) {
      TestValidator.equals(
        `${title} - pages is zero when records zero`,
        pages,
        0,
      );
      TestValidator.equals(
        `${title} - data length is zero when no records`,
        dataLength,
        0,
      );
      TestValidator.equals(
        `${title} - current is zero when no records`,
        current,
        0,
      );
    } else {
      TestValidator.predicate(
        `${title} - pages positive when records > 0`,
        () => pages >= 1,
      );
      TestValidator.predicate(
        `${title} - current within [0, pages) when records > 0`,
        () => current >= 0 && current < pages,
      );
      TestValidator.predicate(
        `${title} - data length not exceeding limit`,
        () => dataLength <= limit,
      );
    }
  };

  // 6. Switch to adminUser to query reports
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const reloggedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(reloggedAdmin);

  // Base filter to focus on memberuser reports on articles
  const baseRequestFilter = {
    reporter_type: "memberuser",
    target_type: "article",
  } satisfies Partial<
    Pick<IDiscussionBoardReport.IRequest, "reporter_type" | "target_type">
  >;

  const makeRequestBody = (
    page: number & tags.Type<"int32"> & tags.Minimum<1>,
  ): IDiscussionBoardReport.IRequest => {
    return {
      ...baseRequestFilter,
      page,
      limit: pageLimit,
    } satisfies IDiscussionBoardReport.IRequest;
  };

  // 7-a. First page
  const firstPageBody = makeRequestBody(
    1 as number & tags.Type<"int32"> & tags.Minimum<1>,
  );
  const firstPageResult: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.adminUser.reports.index(connection, {
      body: firstPageBody,
    });
  typia.assert(firstPageResult);

  const firstPagination = firstPageResult.pagination;
  const firstData = firstPageResult.data;

  assertPaginationConsistency("first page", firstPagination, firstData.length);

  if (firstPagination.records > 0) {
    TestValidator.equals(
      "first page - current is 0 when there are records",
      firstPagination.current,
      0,
    );
    TestValidator.predicate(
      "first page - data length > 0 when there are records",
      () => firstData.length > 0,
    );
  }

  // 7-b. Middle page (page=2) – only meaningful if we have at least two pages
  const middlePageBody = makeRequestBody(
    2 as number & tags.Type<"int32"> & tags.Minimum<1>,
  );
  const middlePageResult: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.adminUser.reports.index(connection, {
      body: middlePageBody,
    });
  typia.assert(middlePageResult);

  const middlePagination = middlePageResult.pagination;
  const middleData = middlePageResult.data;

  assertPaginationConsistency(
    "middle page",
    middlePagination,
    middleData.length,
  );

  if (middlePagination.records > 0 && middlePagination.pages >= 2) {
    TestValidator.equals(
      "middle page - current is 1 for second page when pages >= 2",
      middlePagination.current,
      1,
    );
    TestValidator.predicate(
      "middle page - data length <= limit",
      () => middleData.length <= middlePagination.limit,
    );
  }

  // Capture total records/pages to design out-of-range request
  const totalRecords = firstPagination.records;
  const totalPages = firstPagination.pages;

  // 7-c. Out-of-range page (way beyond last page)
  const hugePageNumber = 9999 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const outOfRangeBody = makeRequestBody(hugePageNumber);
  const outOfRangeResult: IPageIDiscussionBoardReport.ISummary =
    await api.functional.discussionBoard.adminUser.reports.index(connection, {
      body: outOfRangeBody,
    });
  typia.assert(outOfRangeResult);

  const outPagination = outOfRangeResult.pagination;
  const outData = outOfRangeResult.data;

  assertPaginationConsistency(
    "out-of-range page",
    outPagination,
    outData.length,
  );

  if (totalRecords === 0) {
    TestValidator.equals(
      "out-of-range - when no records, pages must be 0",
      outPagination.pages,
      0,
    );
    TestValidator.equals(
      "out-of-range - when no records, current must be 0",
      outPagination.current,
      0,
    );
    TestValidator.equals(
      "out-of-range - when no records, data length must be 0",
      outData.length,
      0,
    );
  } else {
    // When there are records, we allow two main strategies:
    // - clamp: current == pages-1 (last page) and data.length > 0
    // - any other in-range current with data.length <= limit (may be 0)
    TestValidator.predicate(
      "out-of-range - current within [0, pages) when records > 0",
      () =>
        outPagination.pages >= 1 &&
        outPagination.current >= 0 &&
        outPagination.current < outPagination.pages,
    );

    if (outPagination.pages >= 1) {
      // If clamped to last page, we expect some data
      if (outPagination.current === outPagination.pages - 1) {
        TestValidator.predicate(
          "out-of-range - clamped last page has data",
          () => outData.length > 0,
        );
      } else {
        // Otherwise just ensure data length within limit (could be 0)
        TestValidator.predicate(
          "out-of-range - non-last page respects limit",
          () => outData.length <= outPagination.limit,
        );
      }
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
