/**
 * Validate admin report detail for comment-targeting reports.
 *
 * Business flow:
 *
 * 1. Register an admin user and obtain an authenticated admin session.
 * 2. As admin, create an article category to be used for article creation.
 * 3. Register a member user and authenticate as that member.
 * 4. As member, create an article under the created category.
 * 5. As member, create a comment on that article.
 * 6. As member, create a report targeting the created comment using POST
 *    /discussionBoard/memberUser/reports with target_comment_id.
 * 7. Switch authentication back to admin via admin login.
 * 8. As admin, fetch the report detail using GET
 *    /discussionBoard/adminUser/reports/{reportId}.
 * 9. Assert that the returned IDiscussionBoardReport:
 *
 *    - Has target_type equal to "comment" (comment-targeting report),
 *    - Has reason_code equal to the category used in creation,
 *    - Has non-empty status and action fields,
 *    - Has id equal to the id from the creation response,
 *    - Has created_at/updated_at present and in date-time format (ensured by
 *         typia.assert).
 */
export async function test_api_admin_report_detail_for_comment_target(
  connection: api.IConnection,
) {
  // 1) Admin registration (join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorizedFromJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorizedFromJoin);

  // 2) Create article category as admin
  const categoryCodeBase = "TEST_CATEGORY";
  const categoryCodeSuffix = RandomGenerator.alphaNumeric(8);
  const categoryCreateBody = {
    code: `${categoryCodeBase}_${categoryCodeSuffix}`,
    name: "Test Category for Comment Report",
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category);

  // 3) Member registration & login
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<IDiscussionBoardMemberuser.IAuthorized>(
    memberAuthorizedFromJoin,
  );

  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://member.example.com/login",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<IDiscussionBoardMemberuser.IAuthorized>(
    memberAuthorizedFromLogin,
  );

  // 4) Create article as member
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert<IDiscussionBoardArticle>(article);

  // 5) Create comment on the article as member
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert<IDiscussionBoardComment>(comment);

  // 6) Create a comment-targeting report as member
  const reportCategoryValue = "spam";
  const reportCreateBody = {
    category: reportCategoryValue,
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_comment_id: comment.id,
    target_article_id: undefined,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const createdReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert<IDiscussionBoardReport>(createdReport);

  // 7) Switch back to admin authentication
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedFromLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminAuthorizedFromLogin);

  // 8) Fetch report detail as admin
  const detailedReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.adminUser.reports.at(connection, {
      reportId: createdReport.id,
    });
  typia.assert<IDiscussionBoardReport>(detailedReport);

  // 9) Business assertions on admin detail payload
  TestValidator.equals(
    "report detail id matches created report id",
    detailedReport.id,
    createdReport.id,
  );

  TestValidator.equals(
    "report detail reason_code matches created reason_code",
    detailedReport.reason_code,
    createdReport.reason_code,
  );

  TestValidator.equals(
    "report detail reason_code matches input category",
    detailedReport.reason_code,
    reportCategoryValue,
  );

  TestValidator.equals(
    "report detail target_type should be comment",
    detailedReport.target_type,
    "comment",
  );

  TestValidator.predicate(
    "report status should be non-empty",
    detailedReport.status.length > 0,
  );

  TestValidator.predicate(
    "report action should be non-empty",
    detailedReport.action.length > 0,
  );

  TestValidator.equals(
    "report detail created_at matches created report created_at",
    detailedReport.created_at,
    createdReport.created_at,
  );

  TestValidator.predicate(
    "report detail has updated_at populated",
    detailedReport.updated_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate that an admin can retrieve detail of a report targeting an
 * attachment.
 *
 * Business flow:
 *
 * 1. Create an adminUser account via auth.adminUser.join.
 * 2. Create a discussion-board article category as adminUser.
 * 3. Create a memberUser account via auth.memberUser.join.
 * 4. As memberUser, create an article under the created category.
 * 5. As memberUser, create an attachment under that article.
 * 6. As memberUser, create a report whose target_attachment_id is the created
 *    attachment.
 * 7. As adminUser, call the admin report detail endpoint with that report id.
 * 8. Assert that the returned report matches the created one and has target_type
 *    "attachment" and core moderation fields populated.
 */
export async function test_api_admin_report_detail_for_attachment_target(
  connection: api.IConnection,
) {
  // 1. Create adminUser via join (also authenticates as adminUser)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create article category as adminUser
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Create memberUser via join (also authenticates as memberUser)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: "127.0.0.1",
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As memberUser, create an article
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. As memberUser, create an attachment under the article
  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: `file_${RandomGenerator.alphaNumeric(8)}.png`,
    content_type: "image/png",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 6. As memberUser, create a report targeting the attachment
  const reportCreateBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_attachment_id: attachment.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const createdReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(createdReport);

  TestValidator.equals(
    "created report target_type should be attachment",
    createdReport.target_type,
    "attachment",
  );

  // 7. Switch back to adminUser: login using admin email/password
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 8. As adminUser, fetch report detail by id
  const fetchedReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.adminUser.reports.at(connection, {
      reportId: createdReport.id,
    });
  typia.assert(fetchedReport);

  // Validate that ids match
  TestValidator.equals(
    "admin fetched report id matches created report id",
    fetchedReport.id,
    createdReport.id,
  );

  // target_type should be attachment
  TestValidator.equals(
    "admin fetched report target_type should be attachment",
    fetchedReport.target_type,
    "attachment",
  );

  // reason_code and description should reflect creation payload mapping
  TestValidator.equals(
    "reason_code equals creation category",
    fetchedReport.reason_code,
    reportCreateBody.category,
  );

  TestValidator.equals(
    "description equals creation reason",
    fetchedReport.description,
    reportCreateBody.reason,
  );

  // core moderation fields should be non-empty strings
  TestValidator.predicate(
    "status should be non-empty string",
    fetchedReport.status.length > 0,
  );

  TestValidator.predicate(
    "action should be non-empty string",
    fetchedReport.action.length > 0,
  );

  TestValidator.predicate(
    "created_at should be non-empty",
    fetchedReport.created_at.length > 0,
  );

  TestValidator.predicate(
    "updated_at should be non-empty",
    fetchedReport.updated_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

export async function test_api_admin_report_detail_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an adminUser so that we have proper adminUser context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Generate a UUID that is extremely unlikely to exist as a report id.
  const unknownReportId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. Call the detail endpoint with this unknown report id and expect an error.
  await TestValidator.error(
    "admin report detail should fail for unknown reportId",
    async () => {
      // If this call unexpectedly succeeds, typia.assert on the response would run
      // and the TestValidator.error will mark the test as failed.
      const _output: IDiscussionBoardReport =
        await api.functional.discussionBoard.adminUser.reports.at(connection, {
          reportId: unknownReportId,
        });
      typia.assert(_output);
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfComment";

export async function test_api_admin_report_comment_detail_happy_path(
  connection: api.IConnection,
) {
  // 1. Register admin user (join) and obtain admin authorization context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassw0rd!", // satisfies Format<"password"> by shape
    display_name: RandomGenerator.name(2),
    bio: null,
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const adminEmail: string = adminAuthorized.email;
  const adminPassword: string = adminJoinBody.password;

  // 2. As adminUser, create an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Register member user (join) and obtain member authorization
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassw0rd!",
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/home",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As memberUser, create an article under the created category
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 5 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. As same memberUser, create a comment on the article
  const commentBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  // 6. Create a report targeting this specific comment
  const reportBody = {
    category: "harassment", // valid non-empty category string
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_article_id: undefined,
    target_comment_id: comment.id,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportBody,
    });
  typia.assert(report);

  // Basic linkage checks between created report and input
  TestValidator.equals(
    "report id should be a valid uuid string",
    report.id,
    report.id,
  );
  TestValidator.equals(
    "report reason_code should reflect category for created report",
    report.reason_code,
    reportBody.category,
  );

  const reportId: string & tags.Format<"uuid"> = report.id as string &
    tags.Format<"uuid">;

  // 7. Switch back to adminUser via login to ensure admin auth context
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/dashboard",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminReAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminReAuthorized);

  // 8. As adminUser, retrieve the comment-targeting report detail
  const detail: IDiscussionBoardReportOfComment =
    await api.functional.discussionBoard.adminUser.reports.comment.at(
      connection,
      { reportId },
    );
  typia.assert(detail);

  // Business-level validations
  TestValidator.equals(
    "report detail id must equal created report id",
    detail.id,
    report.id,
  );

  TestValidator.equals(
    "report detail target_type must be 'comment'",
    detail.target_type,
    "comment",
  );

  TestValidator.equals(
    "report detail discussion_board_comment_id must equal created comment id",
    detail.discussion_board_comment_id,
    comment.id,
  );

  TestValidator.predicate(
    "report detail status must be non-empty string",
    detail.status.length > 0,
  );

  TestValidator.predicate(
    "report detail action must be non-empty string",
    detail.action.length > 0,
  );

  TestValidator.predicate(
    "report created_at must be a valid ISO date-time string",
    () => !Number.isNaN(Date.parse(detail.created_at)),
  );

  TestValidator.predicate(
    "report updated_at must be a valid ISO date-time string",
    () => !Number.isNaN(Date.parse(detail.updated_at)),
  );

  TestValidator.predicate(
    "comment_link_created_at must be a valid ISO date-time string",
    () => !Number.isNaN(Date.parse(detail.comment_link_created_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfComment";

export async function test_api_admin_report_comment_detail_for_non_comment_report(
  connection: api.IConnection,
) {
  // 1. Admin joins and becomes authenticated
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: null,
    href: "https://admin.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorizedFromJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Admin creates an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph(),
    order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0>
    >() satisfies number,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Member joins and becomes authenticated
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://board.example.com/join" as string & tags.Format<"uri">,
    referrer: "https://board.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 4. Member creates an article under the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. Member creates a report that targets the article (not a comment)
  const reportCreateBody = {
    category: "spam", // reason code string, non-empty
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    target_article_id: article.id,
    // target_comment_id and target_attachment_id intentionally omitted
  } satisfies IDiscussionBoardReport.ICreate;

  const articleReport: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(articleReport);

  // 6. Admin logs in again to ensure admin auth context for subsequent admin-only call
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/dashboard" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedFromLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 7. Attempt to fetch comment-targeting report detail with an article-targeting reportId
  //    Expect this to fail with an error (e.g., 404 or domain error), not succeed with 200.
  await TestValidator.error(
    "admin report comment detail must error for non-comment report",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.comment.at(
        connection,
        {
          reportId: articleReport.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfComment";

/**
 * Validate that admin report-comment detail endpoint fails when the report does
 * not have a comment link.
 *
 * Business context: Moderators review reports using admin-only endpoints that
 * join discussion_board_reports with type-specific link tables such as
 * discussion_board_report_of_comments. If a report is not associated with a
 * comment (for example because it targets an article instead), GET
 * /discussionBoard/adminUser/reports/{reportId}/comment must not return a
 * malformed or partially populated comment-report DTO. Instead it must clearly
 * fail so moderation tools can react properly.
 *
 * Scenario steps:
 *
 * 1. Admin joins the system, establishing an adminUser session.
 * 2. Admin creates an article category required for article creation.
 * 3. Member joins and logs in to establish a memberUser session.
 * 4. Member creates an article using the created category.
 * 5. Member creates a comment on that article.
 * 6. Member creates a comment-targeting report (sanity baseline).
 * 7. Member creates an article-targeting report against the same article.
 * 8. Admin logs in again to ensure admin Authorization context.
 * 9. Admin calls GET /discussionBoard/adminUser/reports/{reportId}/comment with
 *    the article-targeting reportId.
 *
 * Expected results:
 *
 * - All setup calls (join, category, article, comment, report creations) succeed
 *   and their responses conform to their DTOs.
 * - The final admin report-comment detail call using the article-targeting
 *   reportId throws an error, validated via TestValidator.error, rather than
 *   returning an IDiscussionBoardReportOfComment object.
 */
export async function test_api_admin_report_comment_detail_missing_link(
  connection: api.IConnection,
) {
  // 1. Admin joins
