import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfAttachment";

/**
 * Validate admin retrieval of attachment-targeting report detail (happy path).
 *
 * This scenario ensures that a report filed by a member user against an article
 * attachment can be inspected by an admin via the dedicated attachment-detail
 * endpoint. It builds all upstream entities (admin, category, member, article,
 * attachment, report) through real APIs and then asserts that GET
 * /discussionBoard/adminUser/reports/{reportId}/attachment returns an
 * IDiscussionBoardReportOfAttachment.IInvert object whose nested report and
 * attachment metadata exactly match the previously created entities.
 *
 * Steps:
 *
 * 1. Admin joins (auth.adminUser.join) to obtain initial admin session.
 * 2. Admin creates an article category
 *    (/discussionBoard/adminUser/articleCategories.create).
 * 3. Member joins (auth.memberUser.join) to obtain a member session.
 * 4. Member creates an article under the category
 *    (/discussionBoard/memberUser/articles.create).
 * 5. Member creates an attachment for that article
 *    (/discussionBoard/memberUser/articles/{articleId}/attachments.create).
 * 6. Member files a report targeting the attachment only
 *    (/discussionBoard/memberUser/reports.create).
 * 7. Admin logs in again (auth.adminUser.login) to ensure the admin context.
 * 8. Admin fetches attachment detail for the report via
 *    /discussionBoard/adminUser/reports/{reportId}/attachment.
 * 9. The test asserts that:
 *
 *    - The invert link connects the same report and attachment ids.
 *    - The nested report summary mirrors the created report.
 *    - The nested attachment summary mirrors the created attachment and points back
 *         to the correct article.
 */
export async function test_api_admin_report_attachment_detail_happy_path(
  connection: api.IConnection,
) {
  // 1. Admin joins to create an administrative user and start an admin session.
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: "AdminPassword123!",
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoinResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminJoinResult);

  const adminEmail: string = adminJoinResult.email;

  // 2. Admin creates a new article category for the discussion board.
  const articleCategoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: articleCategoryBody,
      },
    );
  typia.assert<IDiscussionBoardArticleCategory>(category);

  // 3. Member joins to create a member user session.
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@member.example.com`,
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 4 }),
    location: "Seoul, Korea",
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<IDiscussionBoardMemberuser.IAuthorized>(memberAuthorized);

  // 4. Member creates a discussion article under the created category.
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert<IDiscussionBoardArticle>(article);

  // 5. Member creates an attachment for that article.
  const attachmentBody = {
    file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(12)}`,
    file_name: `${RandomGenerator.alphabets(6)}.png`,
    content_type: "image/png",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: typia.random<number & tags.Type<"int32">>(),
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert<IDiscussionBoardAttachment>(attachment);

  TestValidator.equals(
    "attachment parent article id should match article.id",
    attachment.discussion_board_article_id,
    article.id,
  );

  // 6. Member files a report targeting the created attachment.
  const reportCreateBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    target_attachment_id: attachment.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert<IDiscussionBoardReport>(report);

  TestValidator.equals(
    "reason_code should mirror creation category",
    report.reason_code,
    reportCreateBody.category,
  );

  // 7. Switch back to admin context via admin login.
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/dashboard",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<IDiscussionBoardAdminuser.IAuthorized>(adminLoginResult);

  // 8. Admin fetches the attachment-detail view for this report.
  const invert: IDiscussionBoardReportOfAttachment.IInvert =
    await api.functional.discussionBoard.adminUser.reports.attachment.at(
      connection,
      {
        reportId: report.id,
      },
    );
  typia.assert<IDiscussionBoardReportOfAttachment.IInvert>(invert);

  // 9. Validate top-level link fields.
  TestValidator.equals(
    "invert.discussion_board_report_id matches report.id",
    invert.discussion_board_report_id,
    report.id,
  );
  TestValidator.equals(
    "invert.discussion_board_attachment_id matches attachment.id",
    invert.discussion_board_attachment_id,
    attachment.id,
  );

  // Validate nested report summary.
  const summaryReport: IDiscussionBoardReportOfAttachment.IReportSummary =
    invert.report;
  TestValidator.equals(
    "nested report.id matches report.id",
    summaryReport.id,
    report.id,
  );
  TestValidator.equals(
    "nested report.target_type matches base report.target_type",
    summaryReport.target_type,
    report.target_type,
  );
  TestValidator.equals(
    "nested report.reporter_type matches base report.reporter_type",
    summaryReport.reporter_type,
    report.reporter_type,
  );
  TestValidator.equals(
    "nested report.reason_code matches base report.reason_code",
    summaryReport.reason_code,
    report.reason_code,
  );
  TestValidator.equals(
    "nested report.description matches base report.description",
    summaryReport.description,
    report.description,
  );
  TestValidator.equals(
    "nested report.status matches base report.status",
    summaryReport.status,
    report.status,
  );
  TestValidator.equals(
    "nested report.action matches base report.action",
    summaryReport.action,
    report.action,
  );
  TestValidator.equals(
    "nested report.created_at matches base report.created_at",
    summaryReport.created_at,
    report.created_at,
  );
  TestValidator.equals(
    "nested report.updated_at matches base report.updated_at",
    summaryReport.updated_at,
    report.updated_at,
  );

  // Validate nested attachment summary.
  const summaryAttachment: IDiscussionBoardReportOfAttachment.IAttachmentSummary =
    invert.attachment;
  TestValidator.equals(
    "nested attachment.id matches attachment.id",
    summaryAttachment.id,
    attachment.id,
  );
  TestValidator.equals(
    "nested attachment.article id matches attachment.article id",
    summaryAttachment.discussion_board_article_id,
    attachment.discussion_board_article_id,
  );
  TestValidator.equals(
    "nested attachment.file_uri matches original",
    summaryAttachment.file_uri,
    attachment.file_uri,
  );
  TestValidator.equals(
    "nested attachment.file_name matches original",
    summaryAttachment.file_name,
    attachment.file_name,
  );
  TestValidator.equals(
    "nested attachment.content_type matches original",
    summaryAttachment.content_type,
    attachment.content_type,
  );
  TestValidator.equals(
    "nested attachment.file_size matches original",
    summaryAttachment.file_size,
    attachment.file_size,
  );
  TestValidator.equals(
    "nested attachment.order_in_article matches original",
    summaryAttachment.order_in_article,
    attachment.order_in_article,
  );
  TestValidator.equals(
    "nested attachment.status matches original",
    summaryAttachment.status,
    attachment.status,
  );
  TestValidator.equals(
    "nested attachment.created_at matches original",
    summaryAttachment.created_at,
    attachment.created_at,
  );
  TestValidator.equals(
    "nested attachment.updated_at matches original",
    summaryAttachment.updated_at,
    attachment.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfAttachment";

/**
 * Validate that the admin attachment-detail endpoint rejects non-attachment
 * reports.
 *
 * Business context:
 *
 * - Reports may target articles, comments, or attachments.
 * - The endpoint GET /discussionBoard/adminUser/reports/{reportId}/attachment is
 *   designed only for attachment-targeting reports and should fail when the
 *   reportId belongs to a comment-targeting report.
 *
 * Test workflow:
 *
 * 1. Register an admin user (adminUser actor) and obtain an authenticated admin
 *    session.
 * 2. As admin, create an article category master record.
 * 3. Register a member user (memberUser actor) and obtain a member session.
 * 4. As member, create an article under the created category.
 * 5. As member, create a comment on that article.
 * 6. As member, create a report targeting the comment (target_comment_id only).
 * 7. Switch back to the admin user session via admin login.
 * 8. As admin, call the attachment-detail endpoint with the comment-targeting
 *    reportId and assert that the call fails (throws an HttpError) instead of
 *    returning IDiscussionBoardReportOfAttachment.IInvert.
 */
export async function test_api_admin_report_attachment_detail_for_non_attachment_report(
  connection: api.IConnection,
) {
  // 1. Register admin user (join) and authenticate as adminUser
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "AdminPassword123!";

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: null,
    ip: null,
    href: "https://admin.test.local/join" as string & tags.Format<"uri">,
    referrer: "https://admin.test.local/landing" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoin);

  // 2. As admin, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Register member user and authenticate as memberUser
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "MemberPassword123!";

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://board.test.local/join" as string & tags.Format<"uri">,
    referrer: "https://board.test.local/landing" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberJoin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoin);

  // 4. As member, create an article in the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. As member, create a comment on that article
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);

  // 6. As member, create a report targeting the comment (not an attachment)
  const reportCreateBody = {
    category: "harassment" as string & tags.MinLength<1>,
    reason: RandomGenerator.paragraph({ sentences: 3 }) as string &
      tags.MinLength<1>,
    target_article_id: undefined,
    target_comment_id: comment.id,
    target_attachment_id: undefined,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportCreateBody,
    });
  typia.assert(report);

  // Sanity check: ensure target_type of the created report is not "attachment" (when available)
  TestValidator.predicate(
    "created report should not be attachment-targeting",
    report.target_type !== "attachment",
  );

  // 7. Switch back to admin user via login to ensure admin auth context
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://admin.test.local/login" as string & tags.Format<"uri">,
    referrer: "https://admin.test.local/landing" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  // 8. As admin, verify that attachment detail endpoint fails for comment-targeting reportId
  await TestValidator.error(
    "attachment-detail endpoint must fail for non-attachment reportId",
    async () => {
      await api.functional.discussionBoard.adminUser.reports.attachment.at(
        connection,
        {
          reportId: report.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportOfAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfAttachment";

/**
 * Validate attachment-report linkage and error handling for admin attachment
 * report detail.
 *
 * Business intent
 *
 * - Ensure that when a discussion-board report properly targets an attachment,
 *   the admin-only detail endpoint
 *   `/discussionBoard/adminUser/reports/{reportId}/attachment` returns a fully
 *   hydrated `IDiscussionBoardReportOfAttachment.IInvert` object with
 *   consistent IDs between the report and the attachment.
 * - Ensure that when the admin queries this endpoint with a non-existent
 *   reportId, the system raises an error instead of returning a malformed or
 *   partially populated DTO.
 *
 * Because the public API surface does not expose any direct way to delete or
 * corrupt link rows in `discussion_board_report_of_attachments`, this test
 * approximates the original "missing link row" scenario by asserting that an
 * unknown reportId yields an error, while a valid report with a legitimate link
 * succeeds and returns consistent linkage information.
 *
 * High-level steps
 *
 * 1. Admin join: create an adminUser using POST /auth/adminUser/join and rely on
 *    the SDK to set the Authorization header for adminUser.
 * 2. Admin creates category: call POST
 *    /discussionBoard/adminUser/articleCategories to get a usable article
 *    category id.
 * 3. Member join: create a memberUser using POST /auth/memberUser/join; the
 *    Authorization header now points to the member actor.
 * 4. Member creates article: call POST /discussionBoard/memberUser/articles with
 *    the category id from step 2 to get articleId.
 * 5. Member attaches file: call POST
 *    /discussionBoard/memberUser/articles/{articleId}/attachments to register
 *    an attachment under the article and capture attachmentId.
 * 6. Member reports attachment: call POST /discussionBoard/memberUser/reports with
 *    `target_attachment_id` set to attachmentId and no article/comment targets;
 *    capture report.id.
 * 7. Admin login: log back in as the same admin using POST /auth/adminUser/login
 *    so that the Authorization token is for adminUser when calling the admin
 *    endpoint.
 * 8. Happy path check: call GET
 *    /discussionBoard/adminUser/reports/{reportId}/attachment using the
 *    reportId from step 6, assert that:
 *
 *    - The response passes `typia.assert<...>()`.
 *    - `invert.discussion_board_report_id === report.id`.
 *    - `invert.report.id === report.id`.
 *    - `invert.attachment.id === attachment.id`.
 *    - `invert.attachment.discussion_board_article_id === article.id`.
 * 9. Error path check for unknown report: generate a new random UUID that differs
 *    from `report.id`, and wrap a call to the same endpoint in `await
 *    TestValidator.error(...)` to ensure an error is thrown instead of a
