  TestValidator.predicate(
    "adminB email should be contained in result list",
    emails.includes(adminB.email),
  );

  // 6. Verify default ordering is consistent (assume created_at descending)
  const createdAtList = summaries.map((s) => s.created_at);

  await TestValidator.predicate(
    "created_at should be ordered descending",
    async () => {
      for (let i = 1; i < createdAtList.length; i++) {
        const prev = new Date(createdAtList[i - 1]).getTime();
        const curr = new Date(createdAtList[i]).getTime();
        if (prev < curr) return false;
      }
      return true;
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuser";

/**
 * Verify admin user listing supports filtering by account status and role for
 * the authenticated administrator and returns correct pagination metadata.
 *
 * Business flow (rewritten to match available APIs):
 *
 * 1. Provision multiple administrator accounts using POST /auth/adminUser/join.
 *
 *    - Each join call creates a new admin user row and issues JWT tokens.
 *    - The SDK automatically updates `connection.headers.Authorization` to the newly
 *         created admin's access token.
 * 2. Treat the last created admin user as the "primary" authenticated actor for
 *    listing operations.
 *
 *    - Read its `status` and `role` fields from
 *         `IDiscussionBoardAdminuser.IAuthorized`.
 * 3. Call PATCH /discussionBoard/adminUser/adminUsers with
 *    `IDiscussionBoardAdminuser.IRequest` configured to:
 *
 *    - Filter by `status` equal to the primary admin's `status`.
 *    - Filter by `role` equal to the primary admin's `role`.
 *    - Apply a deterministic sort order (e.g., orderBy="createdAt",
 *         orderDirection="desc").
 *    - Request the first page (page=1) with a reasonable limit.
 * 4. Validate the listing response `IPageIDiscussionBoardAdminuser.ISummary`:
 *
 *    - `typia.assert()` the entire response for strict type conformance.
 *    - Assert pagination invariants:
 *
 *         - `records` and `pages` are non-negative.
 *         - If `records === 0` then `pages === 0` and `data.length === 0`.
 *         - If `records > 0` then `pages >= 1`, `data.length >= 1`, and `data.length <=
 *                   pagination.limit`.
 *         - `current` is zero-based and within valid range when pages > 0.
 * 5. Validate filtering semantics (within what the DTO exposes):
 *
 *    - For every returned `IDiscussionBoardAdminuser.ISummary`, `account_status`
 *         must equal the requested `status` filter.
 *    - Optionally, when the primary admin appears in the result set, verify that its
 *         `account_status` also matches the requested status, without requiring
 *         that it must be present on the first page (to remain robust in shared
 *         environments and large datasets).
 */
export async function test_api_admin_user_list_filtered_by_status_and_role(
  connection: api.IConnection,
) {
  // 1. Provision multiple administrator accounts via join
  const adminCount = 3;
  const authorizedAdmins: IDiscussionBoardAdminuser.IAuthorized[] = [];

  for (let index = 0; index < adminCount; index++) {
    const joinBody = {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardAdminUserJoin.IRequest;

    const joined = await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
    typia.assert(joined);
    authorizedAdmins.push(joined);
  }

  // 2. Use the last created admin as the primary authenticated actor
  const primaryAdmin = authorizedAdmins[authorizedAdmins.length - 1];

  // 3. Build listing request filtered by primary admin's status and role
  const page = 1 as number & tags.Type<"int32"> & tags.Minimum<1>;
  const limit = 20 as number & tags.Type<"int32"> & tags.Minimum<1>;

  const listRequestBody = {
    status: primaryAdmin.status,
    role: primaryAdmin.role,
    orderBy: "createdAt",
    orderDirection: "desc" as const,
    page,
    limit,
  } satisfies IDiscussionBoardAdminuser.IRequest;

  const pageResult =
    await api.functional.discussionBoard.adminUser.adminUsers.index(
      connection,
      {
        body: listRequestBody,
      },
    );
  typia.assert(pageResult);

  const { pagination, data } = pageResult;

  // 4. Pagination invariants
  TestValidator.predicate(
    "pagination.records must be non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages must be non-negative",
    pagination.pages >= 0,
  );
  TestValidator.predicate(
    "pagination.limit must be non-negative",
    pagination.limit >= 0,
  );

  if (pagination.records === 0) {
    TestValidator.equals("no records implies no pages", pagination.pages, 0);
    TestValidator.equals("no records implies empty data", data.length, 0);
  } else {
    TestValidator.predicate(
      "records > 0 implies at least one page",
      pagination.pages >= 1,
    );
    TestValidator.predicate(
      "records > 0 implies at least one row in data",
      data.length >= 1,
    );
    TestValidator.predicate(
      "page size constraint: data.length <= limit",
      data.length <= pagination.limit,
    );
  }

  if (pagination.pages > 0) {
    TestValidator.predicate(
      "current page index must be within [0, pages)",
      pagination.current >= 0 && pagination.current < pagination.pages,
    );
  }

  // 5. Filtering semantics: account_status must match requested status
  for (const summary of data) {
    TestValidator.equals(
      "each summary.account_status must equal requested status",
      summary.account_status,
      primaryAdmin.status,
    );
  }

  // When the primary admin appears in this page, verify its status too,
  // but do not require its presence (to avoid brittle assumptions about
  // global dataset size or ordering).
  if (data.length > 0) {
    const primarySummary = data.find((row) => row.email === primaryAdmin.email);

    if (primarySummary !== undefined) {
      typia.assert(primarySummary);
      TestValidator.equals(
        "primary summary.account_status matches filter status",
        primarySummary.account_status,
        primaryAdmin.status,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Validate admin profile retrieval by authenticated administrators.
 *
 * Business goal:
 *
 * - Ensure that when an adminUser signs up (join), their administrative profile
 *   is later retrievable via GET
 *   /discussionBoard/adminUser/adminUsers/{adminUserId} by both themselves and
 *   other authenticated admins.
 * - Confirm that the detailed profile matches core fields from the join-auth
 *   response, respects lifecycle semantics (createdAt/updatedAt, deletedAt),
 *   and does not expose sensitive credential internals.
 *
 * Steps:
 *
 * 1. Register Admin A using POST /auth/adminUser/join and capture the
 *    IDiscussionBoardAdminuser.IAuthorized response.
 * 2. Optionally create a discussion-board article category as Admin A using POST
 *    /discussionBoard/adminUser/articleCategories to simulate normal admin
 *    operations before profile lookup.
 * 3. As Admin A (current connection already holds Admin A token), call GET
 *    /discussionBoard/adminUser/adminUsers/{adminUserId} with adminUserId set
 *    to Admin A.id, and assert the returned IDiscussionBoardAdminuser is
 *    structurally valid and consistent with Admin A's authorized snapshot.
 * 4. Validate business invariants on the retrieved profile:
 *
 *    - Id equals Admin A.id.
 *    - DisplayName equals the display_name used at join (or at least equals the
 *         displayName from the authorized response).
 *    - Email equals Admin A.email from the authorized response.
 *    - EmailVerified and accountStatus are consistent with Admin A snapshot.
 *    - CreatedAt/updatedAt follow temporal rules (createdAt <= updatedAt).
 *    - DeletedAt is null or undefined for a fresh admin.
 *    - LastLoginAt, if present, is nullable/valid but not assumed to be set.
 * 5. Register Admin B via another POST /auth/adminUser/join; the SDK will update
 *    Authorization header to Admin B's token.
 * 6. As Admin B, call GET /discussionBoard/adminUser/adminUsers/{adminUserId} with
 *    adminUserId = Admin A.id, confirming cross-admin visibility of Admin A's
 *    profile with the same key profile invariants.
 */
export async function test_api_admin_user_detail_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register Admin A via join
  const joinRequestA = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();

  const adminAAuth: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinRequestA,
    });
  typia.assert(adminAAuth);

  // Basic sanity checks on Admin A authorized payload
  TestValidator.predicate(
    "admin A id should be a non-empty string",
    adminAAuth.id.length > 0,
  );
  TestValidator.predicate(
    "admin A email should be non-empty",
    adminAAuth.email.length > 0,
  );
  TestValidator.predicate(
    "admin A status should be non-empty",
    adminAAuth.status.length > 0,
  );

  // 2. Optionally create an article category as Admin A
  const categoryCreateBody =
    typia.random<IDiscussionBoardArticleCategory.ICreate>();
  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. As Admin A, fetch their own detailed profile
  const adminAProfile: IDiscussionBoardAdminuser =
    await api.functional.discussionBoard.adminUser.adminUsers.at(connection, {
      adminUserId: adminAAuth.id,
    });
  typia.assert(adminAProfile);

  // 4. Validate business invariants on Admin A profile
  TestValidator.equals(
    "admin profile id should match authorized id",
    adminAProfile.id,
    adminAAuth.id,
  );
  TestValidator.equals(
    "admin profile displayName should match authorized displayName",
    adminAProfile.displayName,
    adminAAuth.displayName,
  );
  TestValidator.equals(
    "admin profile email should match authorized email",
    adminAProfile.email,
    adminAAuth.email,
  );
  TestValidator.equals(
    "admin profile emailVerified should match authorized emailVerified",
    adminAProfile.emailVerified,
    adminAAuth.emailVerified,
  );
  TestValidator.equals(
    "admin profile accountStatus should match authorized status",
    adminAProfile.accountStatus,
    adminAAuth.status,
  );

  // createdAt/updatedAt temporal relations: createdAt <= updatedAt
  TestValidator.predicate(
    "admin profile createdAt should not be empty",
    adminAProfile.createdAt.length > 0,
  );
  TestValidator.predicate(
    "admin profile updatedAt should not be empty",
    adminAProfile.updatedAt.length > 0,
  );

  const createdAtTime = new Date(adminAProfile.createdAt).getTime();
  const updatedAtTime = new Date(adminAProfile.updatedAt).getTime();

  TestValidator.predicate(
    "admin profile createdAt should be a valid date-time",
    !Number.isNaN(createdAtTime),
  );
  TestValidator.predicate(
    "admin profile updatedAt should be a valid date-time",
    !Number.isNaN(updatedAtTime),
  );
  TestValidator.predicate(
    "admin profile createdAt should be earlier than or equal to updatedAt",
    createdAtTime <= updatedAtTime,
  );

  // deletedAt should be null or undefined for fresh account (no non-null expectations)
  TestValidator.predicate(
    "admin profile deletedAt should be null or undefined for new admin",
    adminAProfile.deletedAt === null || adminAProfile.deletedAt === undefined,
  );

  // lastLoginAt can be null/undefined/defined; just ensure no contradiction
  if (adminAProfile.lastLoginAt !== undefined) {
    // typia.assert already ensures correct type when defined; we only assert
    // that if it's non-null, it parses as a valid date-time string.
    if (adminAProfile.lastLoginAt !== null) {
      const lastLoginTime = new Date(adminAProfile.lastLoginAt).getTime();
      TestValidator.predicate(
        "admin profile lastLoginAt, when non-null, should be valid date-time",
        !Number.isNaN(lastLoginTime),
      );
    }
  }

  // 5. Register Admin B and switch context to Admin B (SDK updates Authorization)
  const joinRequestB = typia.random<IDiscussionBoardAdminUserJoin.IRequest>();

  const adminBAuth: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinRequestB,
    });
  typia.assert(adminBAuth);

  TestValidator.predicate(
    "admin B id should be non-empty",
    adminBAuth.id.length > 0,
  );

  // 6. As Admin B, fetch Admin A's profile again and verify invariants
  const adminAProfileByB: IDiscussionBoardAdminuser =
    await api.functional.discussionBoard.adminUser.adminUsers.at(connection, {
      adminUserId: adminAAuth.id,
    });
  typia.assert(adminAProfileByB);

  TestValidator.equals(
    "cross-admin read: id matches Admin A id",
    adminAProfileByB.id,
    adminAAuth.id,
  );
  TestValidator.equals(
    "cross-admin read: email matches Admin A email",
    adminAProfileByB.email,
    adminAAuth.email,
  );
  TestValidator.equals(
    "cross-admin read: displayName matches Admin A displayName",
    adminAProfileByB.displayName,
    adminAAuth.displayName,
  );
  TestValidator.equals(
    "cross-admin read: accountStatus matches Admin A status",
    adminAProfileByB.accountStatus,
    adminAAuth.status,
  );

  // Ensure no sensitive credential fields are present beyond the DTO contract
  // (typia.assert already enforces the exact shape of IDiscussionBoardAdminuser).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";

/**
 * Ensure that an authenticated adminUser receives an error when requesting an
 * administrator profile by a random, non-existent id.
 *
 * Business context:
 *
 * - Only authenticated adminUser actors may call the adminUsers.at endpoint.
 * - When an admin requests a profile by id, the backend must either return a
 *   valid IDiscussionBoardAdminuser profile or an error if no such admin exists
 *   for the given identifier.
 * - This test ensures that the system does not accidentally return some default
 *   or unrelated profile for unknown ids and correctly fails instead.
 *
 * Steps:
 *
 * 1. Join as a new adminUser via POST /auth/adminUser/join to establish an
 *    authenticated admin session (token wiring is handled by the SDK).
 * 2. Optionally create a single discussion-board article category via POST
 *    /discussionBoard/adminUser/articleCategories to mimic realistic admin
 *    usage before profile lookup.
 * 3. Generate a random UUID that is guaranteed to differ from the newly created
 *    administrator's id.
 * 4. Call GET /discussionBoard/adminUser/adminUsers/{adminUserId} with this
 *    unknown adminUserId while authenticated.
 * 5. Verify that the call fails by asserting that an error is thrown using
 *    TestValidator.error, without asserting any concrete HTTP status code.
 * 6. Ensure that the success path of IDiscussionBoardAdminuser is not taken for
 *    the unknown id case.
 */
export async function test_api_admin_user_detail_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Join as a new adminUser to obtain an authenticated session.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph(),
    ip: "127.0.0.1",
    href: "https://admin.discussion-board.local/join",
    referrer: "https://admin.discussion-board.local/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const authorizedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(authorizedAdmin);

  // 2. Optionally create one article category for contextual completeness.
  const categoryCreateBody = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Generate a random UUID different from the real admin id.
  const realAdminId: string = authorizedAdmin.id;
  let unknownAdminId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  if (unknownAdminId === realAdminId) {
    unknownAdminId = typia.random<string & tags.Format<"uuid">>();
  }

  // 4 & 5. Call adminUsers.at with the unknown id and verify an error occurs.
  await TestValidator.error(
    "requesting unknown adminUserId should result in an error",
    async () => {
      await api.functional.discussionBoard.adminUser.adminUsers.at(connection, {
        adminUserId: unknownAdminId,
      });
    },
  );
}

