import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportByReasonStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportByReasonStatistics";

export async function test_api_report_statistics_by_reason_time_and_status_filters(
  connection: api.IConnection,
) {
  // 1. Bootstrap: create adminUser and memberUser accounts
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const baseHref: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const baseReferrer: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "AdminPassword!123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: baseHref,
    referrer: baseReferrer,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const memberJoinBody = {
    email: memberEmail,
    password: "MemberPassword!123",
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: null,
    ip: null,
    href: baseHref,
    referrer: baseReferrer,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. As adminUser, create an article category
  // (connection already carries admin auth token from admin join)
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 1 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Switch to memberUser and create an article under that category
  await api.functional.auth.memberUser.login(connection, {
    body: {
      email: memberEmail,
      password: "MemberPassword!123",
      ip: null,
      href: baseHref,
      referrer: baseReferrer,
    } satisfies IDiscussionBoardMemberUserLogin.IRequest,
  });

  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 1 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 4. Create two cohorts of reports on the same article
  // Cohort A: earlier reports
  const reasonCodes = ["spam", "hate_abuse"] as const;

  const cohortAReports: IDiscussionBoardReport[] = [];
  for (let i = 0; i < 3; i += 1) {
    const categoryCode = RandomGenerator.pick(reasonCodes);
    const reportBodyA = {
      category: categoryCode,
      reason: RandomGenerator.paragraph({ sentences: 2 }),
      target_article_id: article.id,
      target_comment_id: undefined,
      target_attachment_id: undefined,
    } satisfies IDiscussionBoardReport.ICreate;

    const reportA: IDiscussionBoardReport =
      await api.functional.discussionBoard.memberUser.reports.create(
        connection,
        {
          body: reportBodyA,
        },
      );
    typia.assert(reportA);
    cohortAReports.push(reportA);
  }

  // Capture a timestamp after cohort A creation
  const middleBoundary: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;

  // Cohort B: later reports
  const cohortBReports: IDiscussionBoardReport[] = [];
  for (let i = 0; i < 5; i += 1) {
    const categoryCode = RandomGenerator.pick(reasonCodes);
    const reportBodyB = {
      category: categoryCode,
      reason: RandomGenerator.paragraph({ sentences: 2 }),
      target_article_id: article.id,
      target_comment_id: undefined,
      target_attachment_id: undefined,
    } satisfies IDiscussionBoardReport.ICreate;

    const reportB: IDiscussionBoardReport =
      await api.functional.discussionBoard.memberUser.reports.create(
        connection,
        {
          body: reportBodyB,
        },
      );
    typia.assert(reportB);
    cohortBReports.push(reportB);
  }

  // Capture a timestamp after cohort B; used as upper bound
  const endBoundary: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;

  // 5. Switch back to adminUser to call statistics endpoint
  await api.functional.auth.adminUser.login(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword!123",
      ip: null,
      href: baseHref,
      referrer: baseReferrer,
    } satisfies IDiscussionBoardAdminUserLogin.IRequest,
  });

  // Build helper to aggregate expected counts by reason for each cohort,
  // based only on reason_code of reports this test created.
  type ReasonCountMap = Record<string, number>;

  const cohortAReasonCounts: ReasonCountMap = {};
  for (const report of cohortAReports) {
    const key = report.reason_code;
    cohortAReasonCounts[key] = (cohortAReasonCounts[key] ?? 0) + 1;
  }

  const cohortBReasonCounts: ReasonCountMap = {};
  for (const report of cohortBReports) {
    const key = report.reason_code;
    cohortBReasonCounts[key] = (cohortBReasonCounts[key] ?? 0) + 1;
  }

  const combinedReasonCounts: ReasonCountMap = {};
  for (const key of Object.keys(cohortAReasonCounts)) {
    combinedReasonCounts[key] =
      (combinedReasonCounts[key] ?? 0) + cohortAReasonCounts[key];
  }
  for (const key of Object.keys(cohortBReasonCounts)) {
    combinedReasonCounts[key] =
      (combinedReasonCounts[key] ?? 0) + cohortBReasonCounts[key];
  }

  // 6. Narrow window: only include reports created after middleBoundary
  const narrowRequestBody = {
    created_at_from: middleBoundary,
    created_at_to: endBoundary,
    updated_at_from: null,
    updated_at_to: null,
    target_types: undefined,
    reporter_types: undefined,
    reason_codes: undefined,
    statuses: undefined,
    actions: undefined,
  } satisfies IDiscussionBoardReportByReasonStatistics.IRequest;

  const narrowStats: IDiscussionBoardReportByReasonStatistics =
    await api.functional.discussionBoard.adminUser.reports.statistics.byReason.index(
      connection,
      {
        body: narrowRequestBody,
      },
    );
  typia.assert(narrowStats);

  // 7. Broad window: include everything up to endBoundary
  const broadRequestBody = {
    created_at_from: null,
    created_at_to: endBoundary,
    updated_at_from: null,
    updated_at_to: null,
    target_types: undefined,
    reporter_types: undefined,
    reason_codes: undefined,
    statuses: undefined,
    actions: undefined,
  } satisfies IDiscussionBoardReportByReasonStatistics.IRequest;

  const broadStats: IDiscussionBoardReportByReasonStatistics =
    await api.functional.discussionBoard.adminUser.reports.statistics.byReason.index(
      connection,
      {
        body: broadRequestBody,
      },
    );
  typia.assert(broadStats);

  // 8. Convert statistics arrays to maps for easier comparison
  const toRowMap = (
    stats: IDiscussionBoardReportByReasonStatistics,
  ): Record<string, IDiscussionBoardReportByReasonStatistics.IRow> => {
    const map: Record<string, IDiscussionBoardReportByReasonStatistics.IRow> =
      {};
    for (const row of stats.items) {
      map[row.reason_code] = row;
    }
    return map;
  };

  const narrowRowMap = toRowMap(narrowStats);
  const broadRowMap = toRowMap(broadStats);

  // 9. Validate that narrow stats include at least the B-cohort counts per reason
  for (const reasonCode of Object.keys(cohortBReasonCounts)) {
    const expectedBCount = cohortBReasonCounts[reasonCode];
    const narrowRow = narrowRowMap[reasonCode];

    TestValidator.predicate(
      `narrow window should have row for reason_code ${reasonCode}`,
      narrowRow !== undefined,
    );

    if (narrowRow !== undefined) {
      TestValidator.predicate(
        `narrow total_count should be at least B-cohort count for reason_code ${reasonCode}`,
        narrowRow.total_count >= expectedBCount,
      );
    }
  }

  // 10. Validate that broad stats include at least combined cohort counts per reason
  for (const reasonCode of Object.keys(combinedReasonCounts)) {
    const expectedTotal = combinedReasonCounts[reasonCode];
    const broadRow = broadRowMap[reasonCode];

    TestValidator.predicate(
      `broad window should have row for reason_code ${reasonCode}`,
      broadRow !== undefined,
    );

    if (broadRow !== undefined) {
      TestValidator.predicate(
        `broad total_count should be at least combined cohort count for reason_code ${reasonCode}`,
        broadRow.total_count >= expectedTotal,
      );
    }
  }

  // 11. Validate that broad totals and action counts are >= narrow per reason
  for (const [reasonCode, narrowRow] of Object.entries(narrowRowMap)) {
    const broadRow = broadRowMap[reasonCode];

    if (broadRow !== undefined) {
      TestValidator.predicate(
        `broad total_count should be >= narrow for reason_code ${reasonCode}`,
        broadRow.total_count >= narrowRow.total_count,
      );

      TestValidator.predicate(
        `broad action_none_count >= narrow for reason_code ${reasonCode}`,
        broadRow.action_none_count >= narrowRow.action_none_count,
      );
      TestValidator.predicate(
        `broad action_keep_count >= narrow for reason_code ${reasonCode}`,
        broadRow.action_keep_count >= narrowRow.action_keep_count,
      );
      TestValidator.predicate(
        `broad action_hide_content_count >= narrow for reason_code ${reasonCode}`,
        broadRow.action_hide_content_count >=
          narrowRow.action_hide_content_count,
      );
      TestValidator.predicate(
        `broad action_delete_content_count >= narrow for reason_code ${reasonCode}`,
        broadRow.action_delete_content_count >=
          narrowRow.action_delete_content_count,
      );
      TestValidator.predicate(
        `broad action_restrict_user_count >= narrow for reason_code ${reasonCode}`,
        broadRow.action_restrict_user_count >=
          narrowRow.action_restrict_user_count,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportByReasonStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportByReasonStatistics";

/**
 * Verify that by-reason report statistics return an empty items array when
 * filters exclude all existing reports.
 *
 * Business flow
 *
 * 1. Register an adminUser via POST /auth/adminUser/join.
 * 2. Register a memberUser via POST /auth/memberUser/join.
 * 3. Log in as adminUser and create an article category via POST
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Log in as memberUser and create one or more articles in that category via
 *    POST /discussionBoard/memberUser/articles.
 * 5. As memberUser, create at least one report targeting one of the articles via
 *    POST /discussionBoard/memberUser/reports, so that the system has baseline
 *    report data.
 * 6. Log in again as adminUser and call PATCH
 *    /discussionBoard/adminUser/reports/statistics/byReason with broad filters,
 *    asserting that the statistics items array is non-empty (sanity check that
 *    data exists).
 * 7. Call the same statistics endpoint with a very old created_at time range
 *    (e.g., year 2000) that cannot include the just-created report data.
 * 8. Confirm that the response is successful and that items is an empty array,
 *    proving that the endpoint expresses "no data for given filters" via an
 *    empty items list rather than errors or partial aggregates.
 */
export async function test_api_report_statistics_by_reason_no_matching_data(
  connection: api.IConnection,
) {
  // 1. Register adminUser (join) and obtain initial tokens.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register memberUser (join) and obtain initial tokens.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: "127.0.0.1",
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Log in as adminUser to simulate real-world admin session.
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/login-form",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  // 4. Create an article category as adminUser.
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 5. Log in as memberUser to create articles and reports.
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://member.example.com/login",
    referrer: "https://member.example.com/login-form",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);

  // 6. Create one or more articles in the created category.
  const articleBodies: IDiscussionBoardArticle.ICreate[] = ArrayUtil.repeat(
    2,
    () =>
      ({
        title: RandomGenerator.paragraph({ sentences: 3 }),
        body: RandomGenerator.content({ paragraphs: 2 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        categoryId: category.id,
      }) satisfies IDiscussionBoardArticle.ICreate,
  );

  const articles: IDiscussionBoardArticle[] = [];
  for (const articleBody of articleBodies) {
    const article: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        {
          body: articleBody,
        },
      );
    typia.assert(article);
    articles.push(article);
  }

  // 7. Create at least one report against one of the articles as memberUser.
  const targetArticle: IDiscussionBoardArticle = articles[0];

  const reportBody = {
    category: "spam",
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    target_article_id: targetArticle.id,
  } satisfies IDiscussionBoardReport.ICreate;

  const report: IDiscussionBoardReport =
    await api.functional.discussionBoard.memberUser.reports.create(connection, {
      body: reportBody,
    });
  typia.assert(report);

  // 8. Switch back to adminUser for statistics calls.
  const adminLoginAgain: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAgain);

  // 9. Broad statistics request: expect non-empty items when baseline data exists.
  const broadRequestBody = {
    created_at_from: null,
    created_at_to: null,
    updated_at_from: null,
    updated_at_to: null,
    target_types: undefined,
    reporter_types: undefined,
    reason_codes: undefined,
    statuses: undefined,
    actions: undefined,
  } satisfies IDiscussionBoardReportByReasonStatistics.IRequest;

  const broadStats: IDiscussionBoardReportByReasonStatistics =
    await api.functional.discussionBoard.adminUser.reports.statistics.byReason.index(
      connection,
      {
        body: broadRequestBody,
      },
    );
  typia.assert(broadStats);

  TestValidator.predicate(
    "broad statistics should contain at least one row when baseline reports exist",
    () => broadStats.items.length >= 1,
  );

  // 10. Statistics request with a time range far in the past to exclude all reports.
  const noMatchTimeFilterBody = {
    created_at_from: "2000-01-01T00:00:00.000Z" as string &
      tags.Format<"date-time">,
    created_at_to: "2000-01-02T00:00:00.000Z" as string &
      tags.Format<"date-time">,
    updated_at_from: null,
    updated_at_to: null,
    target_types: undefined,
    reporter_types: undefined,
    reason_codes: undefined,
    statuses: undefined,
    actions: undefined,
  } satisfies IDiscussionBoardReportByReasonStatistics.IRequest;

  const noMatchStats: IDiscussionBoardReportByReasonStatistics =
    await api.functional.discussionBoard.adminUser.reports.statistics.byReason.index(
      connection,
      {
        body: noMatchTimeFilterBody,
      },
    );
  typia.assert(noMatchStats);

  // 11. Main assertion: items must be empty when filters exclude all reports.
  TestValidator.equals(
    "statistics items must be empty when filters exclude all reports",
    noMatchStats.items,
    [],
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMemberuser";

export async function test_api_admin_member_user_search_basic_filters(
  connection: api.IConnection,
) {
  // 1) Admin bootstrap (adminUser join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminJoinResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoinResult);

  // 2) Admin creates an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3) Member bootstrap (memberUser join)
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberJoinBody = {
    email: memberEmail,
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberJoinResult: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoinResult);

  // Member creates an article under the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 4) Switch back to admin actor via login (member join overwrote Authorization)
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginResult: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginResult);

  // 5) Execute memberUsers search with basic filters as adminUser
  const searchRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    page_size: 20 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    email_verified: null,
    account_statuses: ["active"],
    created_from: null,
    created_to: null,
    last_login_from: null,
    last_login_to: null,
    search: "",
    order_by: "created_at",
    order_direction: "desc" as const,
  } satisfies IDiscussionBoardMemberuser.IRequest;

  const pageResult: IPageIDiscussionBoardMemberuser.ISummary =
    await api.functional.discussionBoard.adminUser.memberUsers.index(
      connection,
      {
        body: searchRequestBody,
      },
    );
  typia.assert(pageResult);

  const pagination: IPage.IPagination = pageResult.pagination;
  typia.assert(pagination);

  // 6) Validate pagination invariants
  TestValidator.predicate(
    "pagination.current is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination.limit is within 0..100",
    pagination.limit >= 0 && pagination.limit <= 100,
  );
  TestValidator.predicate(
    "pagination.records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages is non-negative",
    pagination.pages >= 0,
  );

  if (pageResult.data.length === 0) {
    TestValidator.equals("when no data, records is 0", pagination.records, 0);
    TestValidator.equals("when no data, pages is 0", pagination.pages, 0);
  } else {
    TestValidator.predicate(
      "when data exists, records >= data.length",
      pagination.records >= pageResult.data.length,
    );
  }

  // 7) Validate each member summary
  for (const summary of pageResult.data) {
    typia.assert<IDiscussionBoardMemberuser.ISummary>(summary);

    TestValidator.predicate(
      "member summary account_status is active",
      summary.account_status === "active",
    );
  }

  // 8) Optional existence assertion: at least one active member likely exists
  if (pageResult.data.length > 0) {
    TestValidator.predicate(
      "search returns at least one active member",
      pageResult.data.some(
        (it: IDiscussionBoardMemberuser.ISummary) =>
          it.account_status === "active",
      ),
    );
  }
}

