    password: member2JoinBody.password,
    ip: null,
    href: memberHref,
    referrer: memberReferrer,
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const member2LoginAuth1: IDiscussionBoardMemberuser.IAuthorized =
