import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMemberuser";

/**
 * Validate that admin free-text member search filters by profile fields.
 *
 * Business goal: Ensure PATCH /discussionBoard/adminUser/memberUsers applies
 * the `search` field from IDiscussionBoardMemberuser.IRequest to member profile
 * fields (such as display_name) so that only accounts whose profile contains
 * the search term are returned.
 *
 * High level steps:
 *
 * 1. Create an admin user and authenticate as that admin.
 * 2. As admin, create an article category to support article creation.
 * 3. Create one target member with a unique keyword in displayName and at least
 *    one article, and one or more noise members without that keyword who also
 *    create articles.
 * 4. Switch back to the admin user context.
 * 5. Call the administrative member search endpoint with `search` set to the
 *    unique keyword and broad filters.
 * 6. Verify that only the target member appears in the paginated results and noise
 *    members are excluded.
 */
export async function test_api_admin_member_user_search_by_free_text(
  connection: api.IConnection,
) {
  // Helper to generate common href/referrer used for join/login
  const href: string & tags.Format<"uri"> =
    "https://discussion-board.example.com/" as string & tags.Format<"uri">;
  const referrer: string & tags.Format<"uri"> =
    "https://discussion-board.example.com/landing" as string &
      tags.Format<"uri">;

  // 1. Register an admin user (also authenticates as that admin)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: "AdminP@ssw0rd!", // satisfies Format<"password">
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href,
    referrer,
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Create member users
  const searchKeyword = "unique_keyword";

  // 3-1. Target member: displayName contains the keyword
  const targetMemberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const targetJoinBody = {
    email: targetMemberEmail,
    password: "MemberP@ssw0rd!",
    displayName: `Target ${searchKeyword} User`,
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: null,
    href,
    referrer,
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const targetAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: targetJoinBody,
    });
  typia.assert(targetAuthorized);

  // MemberUser article creation requires memberUser auth token which join set.
  const targetArticleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const targetArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: targetArticleBody },
    );
  typia.assert(targetArticle);

  // 3-2. Noise members without the keyword in any profile field
  const noiseMembers: IDiscussionBoardMemberuser.IAuthorized[] = [];

  const noiseCount: number = 2;
  for (let i = 0; i < noiseCount; i++) {
    const noiseEmail: string & tags.Format<"email"> = typia.random<
      string & tags.Format<"email">
    >();

    const noiseJoinBody = {
      email: noiseEmail,
      password: "MemberP@ssw0rd!",
      displayName: `Noise User ${i + 1}`,
      bio: RandomGenerator.paragraph({ sentences: 2 }),
      location: "Busan",
      ip: null,
      href,
      referrer,
    } satisfies IDiscussionBoardMemberUserJoin.IRequest;

    const noiseAuthorized: IDiscussionBoardMemberuser.IAuthorized =
      await api.functional.auth.memberUser.join(connection, {
        body: noiseJoinBody,
      });
    typia.assert(noiseAuthorized);
    noiseMembers.push(noiseAuthorized);

    const noiseArticleBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      body: RandomGenerator.content({ paragraphs: 2 }),
      summary: RandomGenerator.paragraph({ sentences: 2 }),
      categoryId: category.id,
    } satisfies IDiscussionBoardArticle.ICreate;

    const noiseArticle: IDiscussionBoardArticle =
      await api.functional.discussionBoard.memberUser.articles.create(
        connection,
        { body: noiseArticleBody },
      );
    typia.assert(noiseArticle);
  }

  // 4. Switch back to admin user context with explicit login
  const adminLoginBody = {
    email: adminEmail,
    password: "AdminP@ssw0rd!",
    ip: null,
    href,
    referrer,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 5. Perform member search with free-text keyword
  const searchRequestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    page_size: 20 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    email_verified: null,
    account_statuses: undefined,
    created_from: null,
    created_to: null,
    last_login_from: null,
    last_login_to: null,
    search: searchKeyword,
    order_by: undefined,
    order_direction: undefined,
  } satisfies IDiscussionBoardMemberuser.IRequest;

  const pageResult: IPageIDiscussionBoardMemberuser.ISummary =
    await api.functional.discussionBoard.adminUser.memberUsers.index(
      connection,
      { body: searchRequestBody },
    );
  typia.assert(pageResult);

  const summaries = pageResult.data;

  // Ensure at least one result contains the keyword and matches target member
  const targetSummary = summaries.find((s) => s.id === targetAuthorized.id);

  TestValidator.predicate(
    "search results should include the target member with keyword in display_name",
    targetSummary !== undefined &&
      targetSummary.display_name.includes(searchKeyword),
  );

  // Ensure noise members are not returned (no false positives)
  for (const noise of noiseMembers) {
    const foundNoise = summaries.find((s) => s.id === noise.id);
    TestValidator.predicate(
      "search results should not include noise members without keyword",
      foundNoise === undefined,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that an authenticated adminUser can view a member user's full
 * detail.
 *
 * Business context:
 *
 * - Support staff and moderators use
 *   /discussionBoard/adminUser/memberUsers/{memberUserId} to inspect a member
 *   account: identity, profile, and lifecycle flags.
 * - The API must return a complete IDiscussionBoardMemberuser payload while never
 *   exposing sensitive internals like password_hash.
 *
 * Scenario covered by this test:
 *
 * 1. Register a new member user (join) and capture its id.
 * 2. Register a new adminUser and obtain an admin session (token in
 *    connection.headers).
 * 3. As adminUser, create at least one article category so that the board has a
 *    valid category for member articles.
 * 4. Switch back to the member user and create an article under that category so
 *    the target memberUserId is an "engaged" account.
 * 5. Switch back to adminUser and call GET
 *    /discussionBoard/adminUser/memberUsers/{memberUserId}.
 * 6. Verify response type and important business fields.
 */
export async function test_api_admin_member_user_detail_basic(
  connection: api.IConnection,
) {
  // 1. Member user joins the discussion board
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(1),
    bio: null,
    location: null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberUserId = memberAuthorized.id;

  // 2. Admin user joins to obtain admin session
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1), // adjust to DTO naming below
    bio: null,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As adminUser, create an article category
  const categoryCreateBody = {
    code: `CAT-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(category);

  // 4. Switch back to member user via login, then create an article
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoginAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleCreateBody },
    );
  typia.assert(article);

  // 5. Switch back to adminUser via login to ensure we call admin endpoint as admin
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoginAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 6. Admin retrieves the member user's detail
  const detail: IDiscussionBoardMemberuser =
    await api.functional.discussionBoard.adminUser.memberUsers.at(connection, {
      memberUserId,
    });
  typia.assert(detail);

  // 7. Business-level assertions on returned member detail
  TestValidator.equals(
    "member id must match the originally joined member",
    detail.id,
    memberUserId,
  );

  TestValidator.equals(
    "member email must match join email",
    detail.email,
    memberJoinBody.email,
  );

  TestValidator.equals(
    "display_name must match join displayName",
    detail.display_name,
    memberJoinBody.displayName,
  );

  TestValidator.predicate(
    "freshly joined account should not be closed by admin",
    detail.closed_by_admin === false,
  );

  TestValidator.predicate(
    "freshly joined account should not be soft-deleted",
    detail.deleted_at === null || detail.deleted_at === undefined,
  );

  TestValidator.predicate(
    "freshly joined account should not be closed",
    detail.closed_at === null || detail.closed_at === undefined,
  );

  // We do not explicitly check password_hash absence beyond relying on the
  // DTO type and typia.assert, which already guarantees that only documented
  // properties are present.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

export async function test_api_admin_member_user_detail_for_restricted_account(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.example.com/register",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Login as that member user to simulate activity and update last_login_at
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.example.com/login",
    referrer: "https://frontend.example.com/register",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberAuthorizedAfterLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedAfterLogin);

  // 3. Register an admin user (join) to create categories
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(18),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.example.com/admin/register",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 4. As adminUser, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 5. Switch back to memberUser context via login (connection headers auto managed)
  const memberAuthorizedForArticle: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedForArticle);

  // 6. As memberUser, create an article using the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
      wordMin: 3,
      wordMax: 10,
    }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  TestValidator.equals(
    "article category should match created category",
    article.category.id,
    category.id,
  );

  // 7. Ensure we are authenticated as adminUser again before calling admin endpoint
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.example.com/admin/login",
    referrer: "https://frontend.example.com/admin/register",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminAuthorizedAfterLogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedAfterLogin);

  // Helper for optional date-time validation
  const checkOptionalDateTime = (
    title: string,
    value: string | null | undefined,
  ) => {
    if (value === null || value === undefined) return;
    typia.assert<string & tags.Format<"date-time">>(value);
    TestValidator.predicate(title, value.length > 0);
  };

  // 8. As adminUser, retrieve member user details by memberUserId
  const memberDetail: IDiscussionBoardMemberuser =
    await api.functional.discussionBoard.adminUser.memberUsers.at(connection, {
      memberUserId: memberAuthorized.id,
    });
  typia.assert(memberDetail);

  // 9. Validate essential identity fields
  TestValidator.equals(
    "member id from detail should match joined member id",
    memberDetail.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "member email from detail should match joined member email",
    memberDetail.email,
    memberAuthorized.email,
  );

  // 10. Validate lifecycle and restriction-related fields shape
  TestValidator.predicate(
    "account_status should be a non-empty string",
    memberDetail.account_status.length > 0,
  );

  checkOptionalDateTime(
    "deleted_at, when present, must be a valid date-time",
    memberDetail.deleted_at ?? null,
  );
  checkOptionalDateTime(
    "closed_at, when present, must be a valid date-time",
    memberDetail.closed_at ?? null,
  );
  checkOptionalDateTime(
    "last_login_at, when present, must be a valid date-time",
    memberDetail.last_login_at ?? null,
  );

  TestValidator.predicate(
    "closed_by_admin should be a boolean flag (always defined)",
    typeof memberDetail.closed_by_admin === "boolean",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate safe not-found behavior when admin requests details for a
 * non-existent member user.
 *
 * Business goal
 *
 * - When an administrator calls the member user detail endpoint with a
 *   non-existent memberUserId, the backend must fail safely (not-found style
 *   behavior) without returning any member profile object or leaking which IDs
 *   are valid.
 *
 * Test flow
 *
 * 1. Register an adminUser via /auth/adminUser/join so that we have permissions to
 *    call admin-only memberUsers.at endpoint.
 * 2. With that admin session, create at least one article category via
 *    /discussionBoard/adminUser/articleCategories.create so that the board is
 *    not empty.
 * 3. Register a memberUser via /auth/memberUser/join and, as that member, create
 *    an article via /discussionBoard/memberUser/articles.create so the
 *    environment contains realistic content and we have one known valid member
 *    id that we must _not_ use for the negative case.
 * 4. Generate a random UUID that is different from this existing member id.
 * 5. Re-authenticate as adminUser (to ensure admin context) and invoke
 *    api.functional.discussionBoard.adminUser.memberUsers.at with the
 *    non-existent memberUserId.
 * 6. Use TestValidator.error to assert that the call results in an error and no
 *    IDiscussionBoardMemberuser object is returned. We do not assert a specific
 *    HTTP status code or error body, only that an error occurs for the
 *    non-existent id.
 */
export async function test_api_admin_member_user_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Register an admin user (adminUser.join) to gain admin privileges
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Create at least one article category as admin
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryCreateBody },
    );
  typia.assert(category);

  // 3. Create a member user and let them create an article
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(10),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
