import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportByStatusStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportByStatusStatistics";

export async function test_api_report_statistics_by_status_empty_result_for_unmatched_filters(
  connection: api.IConnection,
) {
  // 1. Admin and member bootstrap
  // 1-1. Register admin user (join)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 1-2. Register member user (join)
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul",
    ip: null,
    href: "https://board.example.com/join",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Admin creates an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 3. Member creates article, comment, attachment, and reports
  // After admin join, the last auth header belongs to admin.
  // Switch to member explicitly to avoid ambiguity (even though join already set it when called).
  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://board.example.com/login",
    referrer: "https://board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  // 3-1. Create article
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 3-2. Create a comment on the article
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);

  // 3-3. Create an attachment on the article
  const attachmentCreateBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: `${RandomGenerator.alphabets(8)}.txt`,
    content_type: "text/plain",
    file_size: 1024,
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachment);

  // 3-4. Create several reports that WILL NOT match the later filter
  const baseReasonCategory = "hate_abuse";

  const reportBodies: IDiscussionBoardReport.ICreate[] = [
    {
      category: baseReasonCategory,
      reason: RandomGenerator.paragraph({ sentences: 2 }),
      target_article_id: article.id,
    },
    {
      category: "spam",
      reason: RandomGenerator.paragraph({ sentences: 2 }),
      target_comment_id: comment.id,
    },
    {
      category: "off_topic",
      reason: RandomGenerator.paragraph({ sentences: 2 }),
      target_attachment_id: attachment.id,
    },
  ];

  const reports: IDiscussionBoardReport[] = [];
  for (const body of reportBodies) {
    const report: IDiscussionBoardReport =
      await api.functional.discussionBoard.memberUser.reports.create(
        connection,
        {
          body,
        },
      );
    typia.assert(report);
    reports.push(report);
  }

  // 4. Switch back to admin user for statistics call
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 5. Call statistics endpoint with unmatched filters
  // Use a future time range and reasonCodes/actions that do not exist.
  const farFutureFrom = new Date(
    Date.now() + 365 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const farFutureTo = new Date(
    Date.now() + 366 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const statsRequestBody = {
    createdAtFrom: farFutureFrom,
    createdAtTo: farFutureTo,
    reasonCodes: ["non_existing_reason_code"],
    actions: ["non_existing_action_code"],
  } satisfies IDiscussionBoardReportByStatusStatistics.IRequest;

  const stats: IDiscussionBoardReportByStatusStatistics =
    await api.functional.discussionBoard.adminUser.reports.statistics.byStatus.indexByStatus(
      connection,
      {
        body: statsRequestBody,
      },
    );
  typia.assert(stats);

  // 6. Validate that items is an empty array
  TestValidator.equals(
    "statistics items must be empty when filters match no reports",
    stats.items.length,
    0,
  );

  TestValidator.equals(
    "statistics items array object must be an empty array",
    stats.items,
    [],
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserNotificationPreference";

/**
 * Validate retrieval of default notification preferences for a new member user.
 *
 * Business goals:
 *
 * - A newly joined member user must be able to fetch their notification
 *   preferences even if they have never adjusted the settings.
 * - The system should either create or expose a consistent default preferences
 *   record bound to that member.
 * - Defaults are expected to enable activity and digest notifications while
 *   disabling marketing notifications.
 *
 * Scenario steps:
 *
 * 1. Create and authenticate an admin user via POST /auth/adminUser/join.
 * 2. As the admin, create an article category via POST
 *    /discussionBoard/adminUser/articleCategories.
 * 3. Create and authenticate a member user via POST /auth/memberUser/join.
 * 4. As that member, create an article within the category via POST
 *    /discussionBoard/memberUser/articles.
 * 5. As the same member, create a comment on the article via POST
 *    /discussionBoard/memberUser/articles/{articleId}/comments.
 * 6. As the same member, create an attachment on the article via POST
 *    /discussionBoard/memberUser/articles/{articleId}/attachments.
 * 7. Finally, as the same member, call GET
 *    /discussionBoard/memberUser/notifications/memberUser/preferences.
 * 8. Assert that:
 *
 *    - The response type is IDiscussionBoardMemberuserNotificationPreference.
 *    - Discussion_board_memberuser_id matches the authenticated member's id.
 *    - Activity_notifications_enabled === true.
 *    - Digest_notifications_enabled === true.
 *    - Marketing_notifications_enabled === false.
 *    - Created_at and updated_at are well-formed date-time strings (covered by
 *         typia.assert).
 */
export async function test_api_member_notification_preferences_default_retrieval(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin user.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As admin, create an article category.
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 satisfies number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Register and authenticate a member user.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/home",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. As member, create an article in the created category.
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBody },
    );
  typia.assert(article);

  // 5. As same member, create a comment on the article.
  const commentBody = {
    body: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentBody,
      },
    );
  typia.assert(comment);

  // 6. As same member, create an attachment on the article.
  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: "attachment-" + RandomGenerator.alphaNumeric(6) + ".txt",
    content_type: "text/plain",
    file_size: 1024 satisfies number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 satisfies number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 7. Retrieve notification preferences for the current member.
  const preferences: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.at(
      connection,
    );
  typia.assert(preferences);

  // 8. Business validations for default preferences.
  TestValidator.equals(
    "notification preferences are bound to the authenticated member",
    preferences.discussion_board_memberuser_id,
    memberAuthorized.id,
  );

  TestValidator.equals(
    "activity notifications should be enabled by default",
    preferences.activity_notifications_enabled,
    true,
  );

  TestValidator.equals(
    "digest notifications should be enabled by default",
    preferences.digest_notifications_enabled,
    true,
  );

  TestValidator.equals(
    "marketing notifications should be disabled by default",
    preferences.marketing_notifications_enabled,
    false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserNotificationPreference";
import type { IDiscussionBoardMemberuserRestriction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserRestriction";

/**
 * Validate that a restricted member user can still read their own notification
 * preferences.
 *
 * Business context
 *
 * - Discussion_board_memberuser_notification_preferences stores per-member
 *   notification flags.
 * - Discussion_board_memberuser_restrictions controls posting/participation
 *   capabilities but should not block read-only inspection of preferences.
 *
 * Scenario steps
 *
 * 1. Register a member user (join) and capture their id; SDK sets member JWT.
 * 2. Register an admin user (join); SDK switches Authorization to admin.
 * 3. As admin, create an article category for later article creation.
 * 4. Log back in as the member user so subsequent calls run under memberUser.
 * 5. As member, create an article in the created category.
 * 6. As member, add a comment and an attachment to that article.
 *
 *    - This step creates realistic activity but is not strictly required for the
 *         core assertion; it helps ensure restriction logic has context.
 * 7. Log in as admin again and apply a posting restriction to the member via POST
 *    /discussionBoard/adminUser/memberUsers/{memberUserId}/restriction.
 * 8. Finally, log back in as the restricted member and call GET
 *    /discussionBoard/memberUser/notifications/memberUser/preferences.
 * 9. Assert that the preferences are successfully returned and belong to the
 *    restricted member, demonstrating that restriction does not block this
 *    read-only endpoint.
 */
export async function test_api_member_notification_preferences_reflect_restriction_state(
  connection: api.IConnection,
) {
  // 1. Register a member user and capture id (member context)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://discussion-board.example.com/signup",
    referrer: "https://discussion-board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberId = memberAuthorized.id;

  // 2. Register an admin user (admin context)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://discussion-board.example.com/admin/signup",
    referrer: "https://discussion-board.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const adminId = adminAuthorized.id;
  void adminId; // not used further, but kept for clarity that admin exists

  // 3. As admin, create an article category
  const categoryCreateBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Log back in as the member user (switch Authorization to member)
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://discussion-board.example.com/login",
    referrer: "https://discussion-board.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const reauthorizedMember: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(reauthorizedMember);
  TestValidator.equals(
    "reauthorized member id matches joined member",
    reauthorizedMember.id,
    memberId,
  );

  // 5. As member, create an article in the created category
  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 6. As member, add a comment on that article
  const commentCreateBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: commentCreateBody,
      },
    );
  typia.assert(comment);
  TestValidator.equals(
    "comment belongs to the created article",
    comment.article.id,
    article.id,
  );

  // 7. As member, add an attachment to the article
  const attachmentCreateBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(12),
    file_name: `attachment_${RandomGenerator.alphaNumeric(6)}.txt`,
    content_type: "text/plain",
    file_size: 1024 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachment);
  TestValidator.equals(
    "attachment belongs to the created article",
    attachment.discussion_board_article_id,
    article.id,
  );

  // 8. Log in as admin again (switch Authorization back to admin)
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://discussion-board.example.com/admin/login",
    referrer: "https://discussion-board.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const reauthorizedAdmin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(reauthorizedAdmin);
  TestValidator.equals(
    "reauthorized admin id matches joined admin",
    reauthorizedAdmin.id,
    adminId,
  );

  // 9. As admin, apply a restriction to the member
  const nowIso = new Date().toISOString();
  const restrictionCreateBody = {
    restriction_level: "posting_restriction",
    reason_category: "test_restriction_for_notification_preferences",
    started_at: nowIso,
    ended_at: null,
  } satisfies IDiscussionBoardMemberuserRestriction.ICreate;

  const restriction: IDiscussionBoardMemberuserRestriction =
    await api.functional.discussionBoard.adminUser.memberUsers.restriction.create(
      connection,
      {
        memberUserId: memberId,
        body: restrictionCreateBody,
      },
    );
  typia.assert(restriction);
  TestValidator.equals(
    "restriction targets the correct member",
    restriction.memberUser.id,
    memberId,
  );

  // 10. Switch back to member context after restriction
  const restrictedMember: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(restrictedMember);
  TestValidator.equals(
    "restricted member id still matches original member",
    restrictedMember.id,
    memberId,
  );

  // 11. As restricted member, fetch notification preferences
  const preferences: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.at(
      connection,
    );
  typia.assert(preferences);

  // 12. Business assertions: restriction does not block reading preferences
  TestValidator.equals(
    "preferences belong to the restricted member",
    preferences.discussion_board_memberuser_id,
    memberId,
  );

  // Flags must be booleans — typia.assert already guarantees types, but we
  // add simple business-level predicates for clarity.
  TestValidator.predicate(
    "activity notifications flag is boolean",
    typeof preferences.activity_notifications_enabled === "boolean",
  );
  TestValidator.predicate(
    "digest notifications flag is boolean",
    typeof preferences.digest_notifications_enabled === "boolean",
  );
  TestValidator.predicate(
    "marketing notifications flag is boolean",
    typeof preferences.marketing_notifications_enabled === "boolean",
  );

  // Ensure created_at <= updated_at chronologically as a soft sanity check.
  const createdAtTime = Date.parse(preferences.created_at);
  const updatedAtTime = Date.parse(preferences.updated_at);
  TestValidator.predicate(
    "preferences timestamps are in chronological order",
    !Number.isNaN(createdAtTime) &&
      !Number.isNaN(updatedAtTime) &&
      createdAtTime <= updatedAtTime,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import type { IDiscussionBoardMemberuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuserNotificationPreference";

/**
 * Ensure notification preferences are isolated per member user and bound to the
 * authenticated identity.
 *
 * Business goals:
 *
 * - A member user can retrieve only their own notification preferences via GET
 *   /discussionBoard/memberUser/notifications/memberUser/preferences.
 * - The returned IDiscussionBoardMemberuserNotificationPreference must reference
 *   the authenticated member’s id in discussion_board_memberuser_id.
 * - Different members must see their own preference records, not each other’s,
 *   even when both are active in the same discussion board context.
 *
 * Steps:
 *
 * 1. Register Member A (join) and obtain their authorized session (memberA).
 * 2. As Member A, fetch preferences.at and assert the owner id matches memberA.id.
 * 3. Register Member B (join) and obtain memberB.
 * 4. As Member B, fetch preferences.at and assert the owner id matches memberB.id.
 * 5. Assert Member A and Member B preference owner IDs differ, demonstrating
 *    isolation.
 * 6. (Realism) Join an admin and create a category; then have both members create
 *    articles/comments/attachments under that category to simulate independent
 *    activity contexts.
 * 7. After activity, re-fetch preferences for each member to confirm they still
 *    receive their own preference row bound by discussion_board_memberuser_id.
 */
export async function test_api_member_notification_preferences_isolated_per_member(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://frontend.example.com/join",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberA: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberA);

  // 2. Member A fetches their notification preferences
  const prefA: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.at(
      connection,
    );
  typia.assert(prefA);

  TestValidator.equals(
    "member A preference owner should match member A id",
    prefA.discussion_board_memberuser_id,
    memberA.id,
  );

  // 3. Register Member B
  const memberBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(2),
    bio: null,
    location: null,
    ip: null,
    href: "https://frontend.example.com/join",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberB: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberB);

  // 4. Member B fetches their notification preferences
  const prefB: IDiscussionBoardMemberuserNotificationPreference =
    await api.functional.discussionBoard.memberUser.notifications.memberUser.preferences.at(
      connection,
    );
  typia.assert(prefB);

  TestValidator.equals(
    "member B preference owner should match member B id",
    prefB.discussion_board_memberuser_id,
    memberB.id,
  );

  // 5. Ensure isolation between member A and member B
  TestValidator.notEquals(
    "preference owner ids must differ between members",
    prefA.discussion_board_memberuser_id,
    prefB.discussion_board_memberuser_id,
  );

  // 6. Admin joins and creates a category for realistic activity context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(20),
    display_name: RandomGenerator.name(2),
    bio: null,
    ip: null,
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const admin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(6)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 7. Switch to Member A via login and create article, comment, attachment
  const memberALoginBody = {
    email: memberA.email,
    password: memberAJoinBody.password,
    ip: null,
    href: "https://frontend.example.com/login",
    referrer: "https://frontend.example.com",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberALogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALogin);

  const articleABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 5 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleA: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleABody },
    );
  typia.assert(articleA);

  const commentABody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const commentA: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: articleA.id,
        body: commentABody,
      },
    );
  typia.assert(commentA);

  const attachmentABody = {
    file_uri: "https://cdn.example.com/files/attachment-a.bin",
    file_name: "attachment-a.bin",
    content_type: "application/octet-stream",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachmentA: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: articleA.id,
        body: attachmentABody,
      },
    );
  typia.assert(attachmentA);

  // 8. Switch to Member B via login and create article, comment, attachment
  const memberBLoginBody = {
    email: memberB.email,
    password: memberBJoinBody.password,
    ip: null,
    href: "https://frontend.example.com/login",
    referrer: "https://frontend.example.com",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberBLogin: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberBLoginBody,
    });
  typia.assert(memberBLogin);

  const articleBBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 5 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleB: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBBody },
    );
  typia.assert(articleB);

  const commentBBody = {
    body: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IDiscussionBoardComment.ICreate;

  const commentB: IDiscussionBoardComment =
    await api.functional.discussionBoard.memberUser.articles.comments.create(
      connection,
      {
        articleId: articleB.id,
        body: commentBBody,
      },
    );
  typia.assert(commentB);

  const attachmentBBody = {
    file_uri: "https://cdn.example.com/files/attachment-b.bin",
    file_name: "attachment-b.bin",
    content_type: "application/octet-stream",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachmentB: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: articleB.id,
        body: attachmentBBody,
      },
    );
  typia.assert(attachmentB);

  // 9. Re-fetch preferences as Member A after activity
  const memberALoginAgain: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberALoginBody,
    });
  typia.assert(memberALoginAgain);

  const prefAAfter: IDiscussionBoardMemberuserNotificationPreference =
