    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryCreateBody,
      },
    );
  typia.assert(category);

  // 4. Switch to memberUser and create an article in that category.
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://board.example.com/login" as string & tags.Format<"uri">,
    referrer: "https://board.example.com/home" as string & tags.Format<"uri">,
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;
  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  const articleCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleCreateBody,
      },
    );
  typia.assert(article);

  // 5. As memberUser, create an attachment for that article.
  const attachmentCreateBody = {
    file_uri: "https://cdn.example.com/files/".concat(
      RandomGenerator.alphaNumeric(16),
    ) as string & tags.Format<"uri">,
    file_name: `${RandomGenerator.alphabets(8)}.png`,
    content_type: "image/png",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0>
    >(),
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;
  const createdAttachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(createdAttachment);

  // 6. Switch back to adminUser and update the attachment to hidden.
  const adminLoginAgainBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login" as string & tags.Format<"uri">,
    referrer: "https://admin.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;
  const adminLoggedInAgain: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginAgainBody,
    });
  typia.assert(adminLoggedInAgain);

  const updateBody = {
    status: "hidden",
  } satisfies IDiscussionBoardAttachment.IUpdate;
  const updatedAttachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.adminUser.articles.attachments.update(
      connection,
      {
        articleId: article.id,
        attachmentId: createdAttachment.id,
        body: updateBody,
      },
    );
  typia.assert(updatedAttachment);

  // 7. Validate that the attachment was updated correctly.
  TestValidator.equals(
    "attachment id remains the same after moderation update",
    updatedAttachment.id,
    createdAttachment.id,
  );
  TestValidator.equals(
    "attachment remains linked to the same article",
    updatedAttachment.discussion_board_article_id,
    createdAttachment.discussion_board_article_id,
  );
  TestValidator.equals(
    "attachment status is updated to hidden",
    updatedAttachment.status,
    "hidden",
  );

  // 8. Verify that memberUser cannot call the admin-only update endpoint.
  // Create a non-admin connection by dropping auth headers.
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "memberUser (or unauthenticated) cannot invoke admin attachment update",
    async () => {
      await api.functional.discussionBoard.adminUser.articles.attachments.update(
        unauthConnection,
        {
          articleId: article.id,
          attachmentId: createdAttachment.id,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Ensure adminUser attachment update enforces article-attachment consistency.
 *
 * Business flow:
 *
 * 1. Create an adminUser and memberUser and establish authentication contexts.
 * 2. As adminUser, create an article category.
 * 3. As memberUser, create two articles (A and B) under that category.
 * 4. As memberUser, create an attachment under article A.
 * 5. Switch back to adminUser and attempt to update the attachment while using
 *    article B's id in the path; expect an error.
 * 6. Then update the same attachment under its real owning article A; expect
 *    success and verify the returned attachment.
 */
export async function test_api_admin_attachment_update_prohibits_cross_article_mislink(
  connection: api.IConnection,
) {
  // 1. Join adminUser (also logs in as that admin)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: null,
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Join memberUser (also logs in as that member)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    displayName: RandomGenerator.name(),
    bio: null,
    location: null,
    ip: null,
    href: "https://app.example.com/join",
    referrer: "https://app.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Switch back to adminUser explicitly (exercise login path)
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserLogin.IRequest;

  const adminLoggedIn: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 4. Create an article category as adminUser
  const categoryBody = {
    code: `CAT-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 5. Switch to memberUser for article and attachment creation
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://app.example.com/login",
    referrer: "https://app.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoggedIn: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoggedIn);

  // 6. Create two articles (A and B) under the same category as memberUser
  const articleABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleA: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleABody,
      },
    );
  typia.assert(articleA);

  const articleBBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleB: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBBody,
      },
    );
  typia.assert(articleB);

  // 7. Create an attachment under article A as memberUser
  const attachmentCreateBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(12),
    file_name: "attachment-A1.txt",
    content_type: "text/plain",
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachmentA1: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: articleA.id,
        body: attachmentCreateBody,
      },
    );
  typia.assert(attachmentA1);

  // Snapshot some original fields for later comparison
  const originalFileName = attachmentA1.file_name;
  const originalContentType = attachmentA1.content_type;
  const originalOrder = attachmentA1.order_in_article;
  const originalStatus = attachmentA1.status;

  // 8. Switch back to adminUser for privileged update attempts
  const adminRelogin: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminRelogin);

  // 9. Attempt cross-article update: use articleB.id with attachment from articleA
  const crossUpdateBody = {
    file_name: originalFileName + "-cross",
    content_type: originalContentType,
    order_in_article: (originalOrder + 1) as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    status: originalStatus,
  } satisfies IDiscussionBoardAttachment.IUpdate;

  await TestValidator.error(
    "cross-article admin update must fail when articleId does not own attachment",
    async () => {
      await api.functional.discussionBoard.adminUser.articles.attachments.update(
        connection,
        {
          articleId: articleB.id,
          attachmentId: attachmentA1.id,
          body: crossUpdateBody,
        },
      );
    },
  );

  // 10. Perform a valid update for the same attachment under its correct article A
  const validFileName = `${originalFileName}-valid`;
  const validContentType = originalContentType;
  const validOrder = (originalOrder + 1) as number &
    tags.Type<"int32"> &
    tags.Minimum<0>;
  const validStatus = "hidden";

  const validUpdateBody = {
    file_name: validFileName,
    content_type: validContentType,
    order_in_article: validOrder,
    status: validStatus,
  } satisfies IDiscussionBoardAttachment.IUpdate;

  const updatedAttachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.adminUser.articles.attachments.update(
      connection,
      {
        articleId: articleA.id,
        attachmentId: attachmentA1.id,
        body: validUpdateBody,
      },
    );
  typia.assert(updatedAttachment);

  // 11. Verify that the successful update actually changed the attachment
  TestValidator.equals(
    "updated attachment should keep the same id",
    updatedAttachment.id,
    attachmentA1.id,
  );
  TestValidator.equals(
    "updated attachment should remain bound to article A",
    updatedAttachment.discussion_board_article_id,
    articleA.id,
  );
  TestValidator.equals(
    "file_name should be updated only in the valid update scenario",
    updatedAttachment.file_name,
    validFileName,
  );
  TestValidator.equals(
    "content_type should reflect the last valid update value",
    updatedAttachment.content_type,
    validContentType,
  );
  TestValidator.equals(
    "order_in_article should reflect the new order from valid update",
    updatedAttachment.order_in_article,
    validOrder,
  );
  TestValidator.equals(
    "status should be updated to hidden by the valid update",
    updatedAttachment.status,
    validStatus,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

export async function test_api_member_attachment_delete_soft_deletion_flow(
  connection: api.IConnection,
) {
  // 1. Register a member user, which also authenticates as that memberUser
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/join/member",
    referrer: "https://frontend.local/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Register an admin user, which authenticates as adminUser
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16) as string &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: "127.0.0.1",
    href: "https://frontend.local/join/admin",
    referrer: "https://frontend.local/admin-landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. Create an article category as adminUser
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    order: 1 as number & tags.Type<"int32">,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 4. Switch back to memberUser by explicit login
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: "127.0.0.1",
    href: "https://frontend.local/login/member",
    referrer: "https://frontend.local/login",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const memberLoginAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 5. Create an article in the created category as the memberUser
  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  TestValidator.predicate(
    "article should reference created category",
    () => article.category.id === category.id,
  );

  // 6. Create an attachment under the article as the memberUser
  const attachmentBody = {
    file_uri: "https://files.local/uploads/" + RandomGenerator.alphaNumeric(16),
    file_name: `spec-${RandomGenerator.alphaNumeric(6)}.pdf`,
    content_type: "application/pdf",
    file_size: 1024 as number & tags.Type<"int32"> & tags.Minimum<0>,
    order_in_article: 1 as number & tags.Type<"int32">,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  TestValidator.predicate(
    "attachment should belong to the created article",
    () => attachment.discussion_board_article_id === article.id,
  );

  TestValidator.predicate(
    "attachment should not be soft-deleted initially",
    () => attachment.deleted_at === null || attachment.deleted_at === undefined,
  );

  // 7. Delete (soft-delete) the attachment once
  await api.functional.discussionBoard.memberUser.articles.attachments.erase(
    connection,
    {
      articleId: article.id,
      attachmentId: attachment.id,
    },
  );

  // 8. Attempt to delete again and expect an error (already deleted / not found)
  await TestValidator.error(
    "re-deleting same attachment should fail",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.erase(
        connection,
        {
          articleId: article.id,
          attachmentId: attachment.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

/**
 * Validate that memberUser attachment deletion respects article ownership.
 *
 * Business goal:
 *
 * - Ensure only the owning member user of an article (or a properly authenticated
 *   role) can delete its attachments through the memberUser attachment erase
 *   endpoint.
 *
 * High-level flow:
 *
 * 1. Create two member users: ownerMember and otherMember via
 *    /auth/memberUser/join.
 * 2. Create an adminUser via /auth/adminUser/join for category management.
 * 3. As adminUser, create an article category via
 *    /discussionBoard/adminUser/articleCategories.
 * 4. Switch to ownerMember and create an article under that category via
 *    /discussionBoard/memberUser/articles.
 * 5. As ownerMember, create an attachment under the article via
 *    /discussionBoard/memberUser/articles/{articleId}/attachments.
 * 6. Switch to otherMember and attempt to delete the attachment via the memberUser
 *    erase endpoint, expecting an authorization/permission error.
 * 7. Switch back to ownerMember and successfully delete the same attachment.
 * 8. Since no attachment "list" API exists, we treat successful owner delete after
 *    failed other delete as proof of ownership-based enforcement.
 */
export async function test_api_member_attachment_delete_respects_article_ownership(
  connection: api.IConnection,
) {
  // 1. Register owner member user
  const ownerEmail: string = typia.random<string & tags.Format<"email">>();
  const ownerPassword: string = RandomGenerator.alphaNumeric(12);

  const ownerJoinBody = {
    email: ownerEmail,
    password: ownerPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    location: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://frontend.example.com/join/owner",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const ownerAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: ownerJoinBody,
    });
  typia.assert(ownerAuthorized);

  // 2. Register other member user
  const otherEmail: string = typia.random<string & tags.Format<"email">>();
  const otherPassword: string = RandomGenerator.alphaNumeric(12);

  const otherJoinBody = {
    email: otherEmail,
    password: otherPassword,
    displayName: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    ip: null,
    href: "https://frontend.example.com/join/other",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const otherAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: otherJoinBody,
    });
  typia.assert(otherAuthorized);

  // 3. Register admin user for category creation
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16);

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    ip: null,
    href: "https://frontend.example.com/admin/join",
    referrer: "https://frontend.example.com/admin/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 4. Create an article category as admin
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      {
        body: categoryBody,
      },
    );
  typia.assert(category);

  // 5. Login as ownerMember to create article
  const ownerLoginBody = {
    email: ownerEmail,
    password: ownerPassword,
    ip: null,
    href: "https://frontend.example.com/login/owner",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const ownerLoginResult: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: ownerLoginBody,
    });
  typia.assert(ownerLoginResult);

  const articleBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      {
        body: articleBody,
      },
    );
  typia.assert(article);

  // 6. As ownerMember, create an attachment for the article
  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: `${RandomGenerator.name(1)}.txt`,
    content_type: "text/plain",
    file_size: 1024,
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: article.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 7. Switch to otherMember and attempt to delete the attachment (expect error).
  const otherLoginBody = {
    email: otherEmail,
    password: otherPassword,
    ip: null,
    href: "https://frontend.example.com/login/other",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const otherLoginResult: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: otherLoginBody,
    });
  typia.assert(otherLoginResult);

  await TestValidator.error(
    "other member cannot delete another member's article attachment",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.erase(
        connection,
        {
          articleId: article.id,
          attachmentId: attachment.id,
        },
      );
    },
  );

  // 8. Switch back to ownerMember and delete the attachment successfully.
  const ownerReloginBody = {
    email: ownerEmail,
    password: ownerPassword,
    ip: null,
    href: "https://frontend.example.com/login/owner",
    referrer: "https://frontend.example.com/landing",
  } satisfies IDiscussionBoardMemberUserLogin.IRequest;

  const ownerReloginResult: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: ownerReloginBody,
    });
  typia.assert(ownerReloginResult);

  await api.functional.discussionBoard.memberUser.articles.attachments.erase(
    connection,
    {
      articleId: article.id,
      attachmentId: attachment.id,
    },
  );

  // Logical post-conditions: if we reached here, authorization rules behaved as expected.
  TestValidator.predicate(
    "owner member successfully deletes their own attachment after other member is denied",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import type { IDiscussionBoardAdminUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserLogin";
import type { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import type { IDiscussionBoardMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserJoin";
import type { IDiscussionBoardMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberUserLogin";
import type { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";

export async function test_api_member_attachment_delete_on_nonexistent_or_mismatched_article(
  connection: api.IConnection,
) {
  // 1. Admin joins to create a category for articles
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminPassw0rd!", // any string is allowed; Format<"password"> is type-level only
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 3 }),
    ip: "127.0.0.1",
    href: "https://admin.example.com/join",
    referrer: "https://admin.example.com/landing",
  } satisfies IDiscussionBoardAdminUserJoin.IRequest;

  const adminAuthorized: IDiscussionBoardAdminuser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Admin creates an article category
  const categoryBody = {
    code: `CAT_${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    order: 1,
  } satisfies IDiscussionBoardArticleCategory.ICreate;

  const category: IDiscussionBoardArticleCategory =
    await api.functional.discussionBoard.adminUser.articleCategories.create(
      connection,
      { body: categoryBody },
    );
  typia.assert(category);

  // 3. Member joins
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassw0rd!",
    displayName: RandomGenerator.name(),
    bio: RandomGenerator.paragraph({ sentences: 2 }),
    location: "Seoul, Korea",
    ip: "127.0.0.1",
    href: "https://member.example.com/join",
    referrer: "https://member.example.com/landing",
  } satisfies IDiscussionBoardMemberUserJoin.IRequest;

  const memberAuthorized: IDiscussionBoardMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 4. Member creates Article A
  const articleABody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleA: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleABody },
    );
  typia.assert(articleA);

  // 5. Member creates Article B
  const articleBBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    body: RandomGenerator.content({ paragraphs: 2 }),
    summary: RandomGenerator.paragraph({ sentences: 2 }),
    categoryId: category.id,
  } satisfies IDiscussionBoardArticle.ICreate;

  const articleB: IDiscussionBoardArticle =
    await api.functional.discussionBoard.memberUser.articles.create(
      connection,
      { body: articleBBody },
    );
  typia.assert(articleB);

  // 6. Member creates an attachment under Article A
  const attachmentBody = {
    file_uri:
      "https://cdn.example.com/files/" + RandomGenerator.alphaNumeric(16),
    file_name: RandomGenerator.paragraph({ sentences: 1 }),
    content_type: RandomGenerator.pick([
      "image/png",
      "image/jpeg",
      "application/pdf",
    ] as const),
    file_size: 1024,
    order_in_article: 1,
    status: "active",
  } satisfies IDiscussionBoardAttachment.ICreate;

  const attachment: IDiscussionBoardAttachment =
    await api.functional.discussionBoard.memberUser.articles.attachments.create(
      connection,
      {
        articleId: articleA.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);

  // 7. Attempt to delete the attachment using mismatched article (Article B)
  await TestValidator.error(
    "delete with mismatched articleId should fail",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.erase(
        connection,
        {
          articleId: articleB.id,
          attachmentId: attachment.id,
        },
      );
    },
  );

  // 8. Delete with the correct article (Article A) should succeed
  await api.functional.discussionBoard.memberUser.articles.attachments.erase(
    connection,
    {
      articleId: articleA.id,
      attachmentId: attachment.id,
    },
  );

  // 9. Optional: second delete should fail as not found (idempotent not-found semantics)
  await TestValidator.error(
    "second delete on same attachment under correct article should fail",
    async () => {
      await api.functional.discussionBoard.memberUser.articles.attachments.erase(
        connection,
        {
          articleId: articleA.id,
          attachmentId: attachment.id,
        },
      );
    },
  );
}

