import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { IPageIDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardArticleCategory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchDiscussionBoardArticleCategories(props: {
  body: IDiscussionBoardArticleCategory.IRequest;
}): Promise<IPageIDiscussionBoardArticleCategory.ISummary> {
  const body = props.body;

  const requestedPage = body.page ?? 1;
  const requestedLimit = body.limit ?? 20;

  const normalizedPage = requestedPage < 1 ? 1 : requestedPage;
  const effectiveLimit = requestedLimit < 0 ? 0 : requestedLimit;

  const where = {
    deleted_at: null,
    ...(body.search !== undefined && body.search !== null && body.search !== ""
      ? {
          OR: [
            { name: { contains: body.search, mode: "insensitive" as const } },
            {
              description: {
                contains: body.search,
                mode: "insensitive" as const,
              },
            },
          ],
        }
      : {}),
    ...(Array.isArray(body.codes) && body.codes.length > 0
      ? { code: { in: body.codes } }
      : {}),
  } satisfies Prisma.discussion_board_article_categoriesWhereInput;

  const orderByFieldRaw = body.order_by ?? "order";
  const orderDirectionRaw = body.order_direction ?? "asc";

  const loweredDirection =
    typeof orderDirectionRaw === "string"
      ? orderDirectionRaw.toLowerCase()
      : "asc";

  const normalizedDirection =
    loweredDirection === "asc" || loweredDirection === "desc"
      ? loweredDirection
      : "asc";

  // Ensure the value is typed as Prisma.SortOrder ("asc" | "desc")
  const sortDirection: Prisma.SortOrder =
    normalizedDirection === "desc" ? "desc" : "asc";

  const orderByField =
    orderByFieldRaw === "created_at" || orderByFieldRaw === "order"
      ? orderByFieldRaw
      : "order";

  const orderBy: Prisma.discussion_board_article_categoriesOrderByWithRelationInput[] =
    orderByField === "order"
      ? [{ order: sortDirection }, { created_at: sortDirection }]
      : [{ created_at: sortDirection }];

  const skip = effectiveLimit > 0 ? (normalizedPage - 1) * effectiveLimit : 0;

  const [rows, totalCount] = await Promise.all([
    MyGlobal.prisma.discussion_board_article_categories.findMany({
      where,
      orderBy,
      skip,
      take: effectiveLimit,
      select: {
        id: true,
        code: true,
        name: true,
        description: true,
      },
    }),
    MyGlobal.prisma.discussion_board_article_categories.count({
      where,
    }),
  ]);

  const records = totalCount;
  const pages = effectiveLimit > 0 ? Math.ceil(records / effectiveLimit) : 0;

  const clampedCurrent =
    pages === 0
      ? 0
      : (() => {
          const requestedZeroBased = normalizedPage - 1;
          if (requestedZeroBased < 0) return 0;
          if (requestedZeroBased >= pages) return pages - 1;
          return requestedZeroBased;
        })();

  const data: IDiscussionBoardArticleCategory.ISummary[] = rows.map((row) => ({
    id: row.id,
    code: row.code,
    name: row.name,
    description: row.description ?? null,
  }));

  const pagination: IPage.IPagination = {
    current: clampedCurrent,
    limit: effectiveLimit,
    records,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAttachment";
import { IPageIDiscussionBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchDiscussionBoardArticlesArticleIdAttachments(props: {
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardAttachment.IRequest;
}): Promise<IPageIDiscussionBoardAttachment.ISummary> {
  const requestedPage = props.body.page ?? 1;
  const requestedLimit = props.body.limit ?? 20;

  const safePage = requestedPage < 1 ? 1 : requestedPage;
  const safeLimit = requestedLimit < 0 ? 0 : requestedLimit;

  const skip = safeLimit > 0 ? (safePage - 1) * safeLimit : 0;
  const take = safeLimit > 0 ? safeLimit : undefined;

  const sortField = props.body.sortField;
  const sortOrder = props.body.sortOrder;

  const effectiveSortField = (() => {
    if (
      sortField === "fileName" ||
      sortField === "fileSize" ||
      sortField === "uploadedAt"
    ) {
      return sortField;
    }
    return "uploadedAt";
  })();

  const effectiveSortOrder: "asc" | "desc" = (() => {
    if (sortOrder === "asc" || sortOrder === "ASC") return "asc";
    if (sortOrder === "desc" || sortOrder === "DESC") return "desc";
    return "desc";
  })();

  const orderBy = (() => {
    if (effectiveSortField === "fileName") {
      return { file_name: effectiveSortOrder } as const;
    }
    if (effectiveSortField === "fileSize") {
      return { file_size: effectiveSortOrder } as const;
    }
    // Default: uploadedAt
    return { created_at: effectiveSortOrder } as const;
  })();

  const whereBase = {
    article_id: props.articleId,
    deleted_at: null,
  } as const;

  const whereWithExtension = props.body.fileExtension
    ? { ...whereBase, file_extension: props.body.fileExtension }
    : whereBase;

  const where = props.body.contentType
    ? { ...whereWithExtension, content_type: props.body.contentType }
    : whereWithExtension;

  const [rows, totalCount] = await Promise.all([
    MyGlobal.prisma.discussion_board_attachments.findMany({
      where,
      skip,
      take,
      orderBy,
    }),
    MyGlobal.prisma.discussion_board_attachments.count({
      where,
    }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    name: row.file_name,
    extension: (row as any).file_extension,
    size_bytes: row.file_size,
    url: row.file_uri,
    status: row.status,
  }));

  const currentPageIndex = safePage - 1;

  const pages =
    safeLimit > 0 && totalCount > 0 ? Math.ceil(totalCount / safeLimit) : 0;

  const pagination: IPage.IPagination = {
    current: currentPageIndex as number & tags.Type<"int32"> & tags.Minimum<0>,
    limit: safeLimit satisfies number as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
    records: totalCount as number & tags.Type<"int32"> & tags.Minimum<0>,
    pages: pages satisfies number as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
