import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function putDiscussionBoardAdminUserReportsReportId(props: {
  adminUser: AdminuserPayload;
  reportId: string & tags.Format<"uuid">;
  body: IDiscussionBoardReport.IUpdate;
}): Promise<IDiscussionBoardReport> {
  // 1. Load existing report by id
  const existing = await MyGlobal.prisma.discussion_board_reports.findUnique({
    where: { id: props.reportId },
  });

  if (existing === null) {
    throw new HttpException("Report not found", 404);
  }

  // 2. Enforce basic workflow transition rules
  const currentStatus = existing.status;
  const requestedStatus = props.body.status;

  if (requestedStatus !== undefined) {
    // Terminal states that cannot move back to an initial-like state
    const terminalStatuses = ["resolved"];
    const initialLikeStatuses = ["submitted"];

    const isCurrentlyTerminal = terminalStatuses.indexOf(currentStatus) !== -1;
    const isRequestedInitialLike =
      initialLikeStatuses.indexOf(requestedStatus) !== -1;

    if (isCurrentlyTerminal && isRequestedInitialLike) {
      throw new HttpException(
        "Cannot transition a resolved report back to an initial submitted state",
        400,
      );
    }
  }

  // 3. Determine if there is any mutable field to update
  const hasStatusUpdate = props.body.status !== undefined;
  const hasActionUpdate = props.body.action !== undefined;

  // If nothing to update, simply return current state as DTO snapshot
  if (!hasStatusUpdate && !hasActionUpdate) {
    return {
      id: existing.id,
      target_type: existing.target_type,
      reporter_type: existing.reporter_type,
      reason_code: existing.reason_code,
      description: existing.description,
      status: existing.status,
      action: existing.action,
      created_at: toISOStringSafe(existing.created_at),
      updated_at: toISOStringSafe(existing.updated_at),
    };
  }

  // 4. Persist update with only provided mutable fields
  const updated = await MyGlobal.prisma.discussion_board_reports.update({
    where: { id: props.reportId },
    data: {
      ...(hasStatusUpdate ? { status: props.body.status } : {}),
      ...(hasActionUpdate ? { action: props.body.action } : {}),
    },
  });

  // 5. Map updated record back to DTO
  return {
    id: updated.id,
    target_type: updated.target_type,
    reporter_type: updated.reporter_type,
    reason_code: updated.reason_code,
    description: updated.description,
    status: updated.status,
    action: updated.action,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function deleteDiscussionBoardMemberUserArticlesArticleIdAttachmentsAttachmentId(props: {
  memberUser: MemberuserPayload;
  articleId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Locate the attachment scoped to the given article
  const attachment =
    await MyGlobal.prisma.discussion_board_attachments.findFirst({
      where: {
        id: props.attachmentId,
        discussion_board_article_id: props.articleId,
      },
    });

  if (attachment === null) {
    // No attachment for this article/attachment combination
    throw new HttpException("Attachment not found", 404);
  }

  if (attachment.deleted_at !== null) {
    // Already soft-deleted: treat as not found for member-facing API
    throw new HttpException("Attachment not found", 404);
  }

  // 2. Ensure the parent article exists and is not deleted
  const article = await MyGlobal.prisma.discussion_board_articles.findFirst({
    where: {
      id: props.articleId,
      deleted_at: null,
    },
  });

  if (article === null) {
    throw new HttpException("Article not found", 404);
  }

  // 3. Ensure the authenticated member user owns the article.
  // Ownership is modeled via a separate subtype table linking articles to member users
  const memberArticle =
    await MyGlobal.prisma.discussion_board_article_of_memberusers.findFirst({
      where: {
        discussion_board_article_id: article.id,
        discussion_board_memberuser_id: props.memberUser.id,
      },
    });

  if (memberArticle === null) {
    // The current member does not own this article
    throw new HttpException(
      "You do not have permission to delete this attachment",
      403,
    );
  }

  // 4. Perform soft deletion by setting deleted_at and updating status
  const now: string = toISOStringSafe(new Date());

  await MyGlobal.prisma.discussion_board_attachments.update({
    where: {
      id: props.attachmentId,
    },
    data: {
      deleted_at: now,
      status: "deleted",
      updated_at: now,
    },
  });

  return;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReportOfArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportOfArticle";
import { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function getDiscussionBoardAdminUserReportsReportIdArticle(props: {
  adminUser: AdminuserPayload;
  reportId: string & tags.Format<"uuid">;
}): Promise<IDiscussionBoardReportOfArticle> {
  const report = await MyGlobal.prisma.discussion_board_reports.findUnique({
    where: { id: props.reportId },
  });

  if (report === null) {
    throw new HttpException("Report not found", 404);
  }

  if (report.target_type !== "article") {
    throw new HttpException("Report does not target an article", 404);
  }

  const reportOfArticle =
    await MyGlobal.prisma.discussion_board_report_of_articles.findFirst({
      where: { discussion_board_report_id: report.id },
    });

  if (reportOfArticle === null) {
    throw new HttpException("Article association for report not found", 404);
  }

  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: reportOfArticle.discussion_board_article_id },
  });

  if (article === null) {
    throw new HttpException("Article not found for report", 404);
  }

  const category =
    await MyGlobal.prisma.discussion_board_article_categories.findUnique({
      where: { id: article.discussion_board_article_category_id },
    });

  if (category === null) {
    throw new HttpException("Article category not found", 500);
  }

  const categorySummary: IDiscussionBoardArticleCategory.ISummary = {
    id: category.id,
    code: category.code,
    name: category.name,
    description:
      category.description === null ? undefined : category.description,
  };

  const articleOfMemberuser =
    await MyGlobal.prisma.discussion_board_article_of_memberusers.findFirst({
      where: { discussion_board_article_id: article.id },
    });

  const articleOfAdminuser =
    await MyGlobal.prisma.discussion_board_article_of_adminusers.findFirst({
      where: { discussion_board_article_id: article.id },
    });

  let author:
    | IDiscussionBoardMemberuser.ISummary
    | IDiscussionBoardAdminuser.ISummary;

  if (articleOfMemberuser !== null) {
    const member =
      await MyGlobal.prisma.discussion_board_memberusers.findUnique({
        where: { id: articleOfMemberuser.discussion_board_memberuser_id },
      });

    if (member === null) {
      throw new HttpException("Article author (memberuser) not found", 500);
    }

    author = {
      id: member.id,
      display_name: member.display_name,
      account_status: member.account_status,
      created_at: toISOStringSafe(member.created_at),
    };
  } else if (articleOfAdminuser !== null) {
    const admin = await MyGlobal.prisma.discussion_board_adminusers.findUnique({
      where: { id: articleOfAdminuser.discussion_board_adminuser_id },
    });

    if (admin === null) {
      throw new HttpException("Article author (adminuser) not found", 500);
    }

    author = {
      id: admin.id,
      email: admin.email,
      display_name: admin.display_name,
      // DB does not have profile_image_url column; expose as undefined in summary
      profile_image_url: undefined,
      email_verified: admin.email_verified,
      account_status: admin.account_status,
      created_at: toISOStringSafe(admin.created_at),
      last_login_at: admin.last_login_at
        ? toISOStringSafe(admin.last_login_at)
        : undefined,
    };
  } else {
    throw new HttpException("Article author not found", 500);
  }

  const [likeCount, commentCount] = await Promise.all([
    MyGlobal.prisma.discussion_board_article_likes.count({
      where: { discussion_board_article_id: article.id },
    }),
    MyGlobal.prisma.discussion_board_comments.count({
      where: { discussion_board_article_id: article.id },
    }),
  ]);

  const articleSummary: IDiscussionBoardArticle.ISummary = {
    id: article.id,
    title: article.title,
    excerpt: article.summary === null ? undefined : article.summary,
    category: categorySummary,
    author,
    createdAt: toISOStringSafe(article.created_at),
    likeCount: likeCount as number & tags.Type<"int32"> & tags.Minimum<0>,
    commentCount: commentCount as number & tags.Type<"int32"> & tags.Minimum<0>,
  };

  const reportDto: IDiscussionBoardReport = {
    id: report.id,
    target_type: report.target_type,
    reporter_type: report.reporter_type,
    reason_code: report.reason_code,
    description: report.description,
    status: report.status,
    action: report.action,
    created_at: toISOStringSafe(report.created_at),
    updated_at: toISOStringSafe(report.updated_at),
  };

  const result: IDiscussionBoardReportOfArticle = {
    report: reportDto,
    article: articleSummary,
    created_at: toISOStringSafe(reportOfArticle.created_at),
  };

  return result;
}

