import { IDiscussionBoardAdminuserNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuserNotificationPreference";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function getDiscussionBoardAdminUserNotificationsAdminUserPreferences(props: {
  adminUser: AdminuserPayload;
}): Promise<IDiscussionBoardAdminuserNotificationPreference> {
  // Attempt to load existing notification preferences for this admin user
  const existing =
    await MyGlobal.prisma.discussion_board_adminuser_notification_preferences.findFirst(
      {
        where: {
          discussion_board_adminuser_id: props.adminUser.id,
        },
      },
    );

  if (existing !== null) {
    return {
      id: existing.id,
      activity_notifications_enabled: existing.activity_notifications_enabled,
      digest_notifications_enabled: existing.digest_notifications_enabled,
      marketing_notifications_enabled: existing.marketing_notifications_enabled,
      created_at: toISOStringSafe(existing.created_at),
      updated_at: toISOStringSafe(existing.updated_at),
    };
  }

  // Lazily create a default preference record when none exists yet.
  // Defaults: enable all notification categories so that admins receive updates
  // unless they explicitly opt out via the update endpoint.
  const now = new Date();
  const created =
    await MyGlobal.prisma.discussion_board_adminuser_notification_preferences.create(
      {
        data: {
          id: v4(),
          discussion_board_adminuser_id: props.adminUser.id,
          activity_notifications_enabled: true,
          digest_notifications_enabled: true,
          marketing_notifications_enabled: true,
          created_at: toISOStringSafe(now),
          updated_at: toISOStringSafe(now),
        },
      },
    );

  return {
    id: created.id,
    activity_notifications_enabled: created.activity_notifications_enabled,
    digest_notifications_enabled: created.digest_notifications_enabled,
    marketing_notifications_enabled: created.marketing_notifications_enabled,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import { IPageIDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdminuser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchDiscussionBoardAdminUserAdminUsers(props: {
  adminUser: AdminuserPayload;
  body: IDiscussionBoardAdminuser.IRequest;
}): Promise<IPageIDiscussionBoardAdminuser.ISummary> {
  const pageInput = props.body.page;
  const limitInput = props.body.limit;

  const page = pageInput === undefined ? 1 : pageInput;
  const limit = limitInput === undefined ? 20 : limitInput;

  const skip = (page - 1) * limit;

  const where: Prisma.discussion_board_adminusersWhereInput = {
    deleted_at: null,
    ...(props.body.status !== undefined && {
      account_status: props.body.status,
    }),
    ...(props.body.role !== undefined && {
      role: props.body.role,
    }),
    ...(props.body.search !== undefined &&
      props.body.search !== "" && {
        OR: [
          {
            email: {
              contains: props.body.search,
              mode: Prisma.QueryMode.insensitive,
            },
          },
          {
            display_name: {
              contains: props.body.search,
              mode: Prisma.QueryMode.insensitive,
            },
          },
        ],
      }),
  };

  const orderByField = props.body.orderBy;
  const direction: Prisma.SortOrder =
    props.body.orderDirection === undefined
      ? "desc"
      : props.body.orderDirection;

  const orderBy: Prisma.discussion_board_adminusersOrderByWithRelationInput =
    orderByField === "createdAt"
      ? { created_at: direction }
      : orderByField === "email"
        ? { email: direction }
        : { created_at: "desc" };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_adminusers.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        email: true,
        display_name: true,
        // profile_image_url does not exist on the Prisma model, so we don't select it
        email_verified: true,
        account_status: true,
        created_at: true,
        last_login_at: true,
      },
    }),
    MyGlobal.prisma.discussion_board_adminusers.count({
      where,
    }),
  ]);

  const data: IDiscussionBoardAdminuser.ISummary[] = rows.map((row) => {
    const lastLoginAtValue = row.last_login_at;

    return {
      id: row.id,
      email: row.email,
      display_name: row.display_name,
      // Prisma row has no profile_image_url column; expose undefined to satisfy summary type
      profile_image_url: undefined,
      email_verified: row.email_verified,
      account_status: row.account_status,
      created_at: toISOStringSafe(row.created_at),
      last_login_at:
        lastLoginAtValue === null
          ? undefined
          : toISOStringSafe(lastLoginAtValue),
    };
  });

  const records = total;
  const pages = records === 0 ? 0 : Math.ceil(records / limit);

  const pagination: IPage.IPagination = {
    current: page - 1,
    limit,
    records,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticleLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleLike";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postDiscussionBoardMemberUserArticlesArticleIdLikes(props: {
  memberUser: MemberuserPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardArticleLike.ICreate;
}): Promise<IDiscussionBoardArticleLike> {
  const result = await MyGlobal.prisma.$transaction(async (tx) => {
    const article = await tx.discussion_board_articles.findFirst({
      where: {
        id: props.articleId,
      },
    });

    if (article === null) {
      throw new HttpException("Article not found", 404);
    }

    const existingLike = await tx.discussion_board_article_likes.findFirst({
      where: {
        discussion_board_article_id: props.articleId,
        discussion_board_memberuser_id: props.memberUser.id,
      },
    });

    if (existingLike === null) {
      await tx.discussion_board_article_likes.create({
        data: {
          id: v4(),
          discussion_board_article_id: props.articleId,
          discussion_board_memberuser_id: props.memberUser.id,
          created_at: new Date(),
        },
      });
    }

    const totalLikeCount = await tx.discussion_board_article_likes.count({
      where: {
        discussion_board_article_id: props.articleId,
      },
    });

    const commentCount = await tx.discussion_board_comments.count({
      where: {
        discussion_board_article_id: props.articleId,
      },
    });

    const category = await tx.discussion_board_article_categories.findFirst({
      where: {
        id: article.discussion_board_article_category_id,
      },
    });

    if (category === null) {
      throw new HttpException("Article category not found", 500);
    }

    const articleOfMember =
      await tx.discussion_board_article_of_memberusers.findFirst({
        where: {
          discussion_board_article_id: article.id,
        },
      });

    let authorSummary:
      | IDiscussionBoardMemberuser.ISummary
      | IDiscussionBoardAdminuser.ISummary;

    if (articleOfMember !== null) {
      const member = await tx.discussion_board_memberusers.findFirst({
        where: {
          id: articleOfMember.discussion_board_memberuser_id,
        },
      });

      if (member === null) {
        throw new HttpException("Article author (member) not found", 500);
      }

      authorSummary = {
        id: member.id,
        display_name: member.display_name,
        account_status: member.account_status,
        created_at: toISOStringSafe(member.created_at),
      };
    } else {
      const articleOfAdmin =
        await tx.discussion_board_article_of_adminusers.findFirst({
          where: {
            discussion_board_article_id: article.id,
          },
        });

      if (articleOfAdmin === null) {
        throw new HttpException("Article author not found", 500);
      }

      const admin = await tx.discussion_board_adminusers.findFirst({
        where: {
          id: articleOfAdmin.discussion_board_adminuser_id,
        },
      });

      if (admin === null) {
        throw new HttpException("Article author (admin) not found", 500);
      }

      authorSummary = {
        id: admin.id,
        email: admin.email,
        display_name: admin.display_name,
        // profile_image_url field does not exist on admin Prisma type per error
        email_verified: admin.email_verified,
        account_status: admin.account_status,
        created_at: toISOStringSafe(admin.created_at),
        last_login_at:
          admin.last_login_at !== null
            ? toISOStringSafe(admin.last_login_at)
            : undefined,
      };
    }

    const articleSummary: IDiscussionBoardArticle.ISummary = {
      id: article.id,
      title: article.title,
      excerpt:
        article.summary !== null && article.summary !== undefined
          ? article.summary
          : undefined,
      category: {
        id: category.id,
        code: category.code,
        name: category.name,
        description:
          category.description !== null && category.description !== undefined
            ? category.description
            : undefined,
      },
      author: authorSummary,
      createdAt: toISOStringSafe(article.created_at),
      likeCount: totalLikeCount,
      commentCount: commentCount,
    };

    const likeDto: IDiscussionBoardArticleLike = {
      article: articleSummary,
      totalLikeCount: totalLikeCount,
      likedByCurrentMember: true,
    };

    return likeDto;
  });

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function putDiscussionBoardMemberUserArticlesArticleId(props: {
  memberUser: MemberuserPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardArticle.IUpdate;
}): Promise<IDiscussionBoardArticle> {
  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: {
      id: props.articleId,
    },
    include: {
      // Prisma include property issue is out of casting scope
      discussion_board_article_of_memberusers: true,
    },
  });

  if (article === null) {
    throw new HttpException("Article not found", 404);
  }

  if (article.deleted_at !== undefined && article.deleted_at !== null) {
    throw new HttpException("Article has been deleted", 404);
  }

  const memberAuthorLinks = Array.isArray(
    (article as any).discussion_board_article_of_memberusers,
  )
    ? (article as any).discussion_board_article_of_memberusers
    : [];

  const isAuthor = (
    memberAuthorLinks as Array<{ discussion_board_memberuser_id: string }>
  ).some((link) => link.discussion_board_memberuser_id === props.memberUser.id);

  if (!isAuthor) {
    throw new HttpException("You are not the author of this article", 403);
  }

  const updateData: Record<string, unknown> = {};

  if (props.body.title !== undefined) {
    updateData.title = props.body.title;
  }

  if (props.body.body !== undefined) {
    updateData.body = props.body.body;
  }

  if (props.body.summary !== undefined) {
    updateData.summary = props.body.summary;
  }

  if (props.body.discussion_board_article_category_id !== undefined) {
    const categoryForUpdate =
      await MyGlobal.prisma.discussion_board_article_categories.findFirst({
        where: {
          id: props.body.discussion_board_article_category_id,
          deleted_at: null,
        },
      });

    if (categoryForUpdate === null) {
      throw new HttpException("Category not found", 400);
    }

    updateData.discussion_board_article_category_id =
      props.body.discussion_board_article_category_id;
  }

  const updatedArticle = await MyGlobal.prisma.discussion_board_articles.update(
    {
      where: {
        id: props.articleId,
      },
      data: updateData,
      include: {
        // Prisma include property issue is out of casting scope
      },
    },
  );

  // We cannot reliably access discussion_board_article_categories without proper include,
  // but this is a structural/Prisma issue, not a casting one.
  const category = (updatedArticle as any)
    .discussion_board_article_categories as IDiscussionBoardArticleCategory;

  const response: IDiscussionBoardArticle = {
    id: updatedArticle.id as string & tags.Format<"uuid">,
    title: updatedArticle.title,
    body: updatedArticle.body,
    summary:
      updatedArticle.summary === null
        ? null
        : (updatedArticle.summary ?? undefined),
    category: {
      id: category.id as string & tags.Format<"uuid">,
      code: category.code,
      name: category.name,
      description:
        category.description === null
          ? null
          : (category.description ?? undefined),
    },
    moderationState:
      updatedArticle.moderation_state as IDiscussionBoardArticle["moderationState"],
    createdAt: toISOStringSafe(updatedArticle.created_at as any),
    updatedAt: toISOStringSafe(updatedArticle.updated_at as any),
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
