import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchDiscussionBoardAdminUserMemberUsersMemberUserIdSessions(props: {
  adminUser: AdminuserPayload;
  memberUserId: string & tags.Format<"uuid">;
  body: IDiscussionBoardMemberuserSession.IRequest;
}): Promise<IPageIDiscussionBoardMemberuserSession.ISummary> {
  // Ensure the target member user exists before listing sessions.
  const memberUser =
    await MyGlobal.prisma.discussion_board_memberusers.findUnique({
      where: { id: props.memberUserId },
    });

  if (memberUser === null) {
    throw new HttpException("Member user not found", 404);
  }

  // Derive pagination parameters with sensible defaults.
  const requestedPage = props.body.page !== undefined ? props.body.page : 1;
  const requestedLimit = props.body.limit !== undefined ? props.body.limit : 20;

  const page = requestedPage < 1 ? 1 : requestedPage;
  const limit = requestedLimit < 0 ? 0 : requestedLimit;

  const skip = limit === 0 ? 0 : (page - 1) * limit;

  // Build the where condition for sessions.
  const baseWhere = {
    discussion_board_memberuser_id: props.memberUserId,
  };

  const dateRangeWhere = (() => {
    const createdFrom = props.body.created_from;
    const createdTo = props.body.created_to;

    if (
      createdFrom === undefined &&
      createdFrom === null &&
      createdTo === undefined &&
      createdTo === null
    ) {
      return {};
    }

    const createdAtCondition: Record<
      string,
      string & tags.Format<"date-time">
    > = {};

    if (createdFrom !== undefined && createdFrom !== null) {
      createdAtCondition.gte = createdFrom;
    }

    if (createdTo !== undefined && createdTo !== null) {
      createdAtCondition.lte = createdTo;
    }

    return Object.keys(createdAtCondition).length === 0
      ? {}
      : { created_at: createdAtCondition };
  })();

  const where = {
    ...baseWhere,
    ...dateRangeWhere,
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.discussion_board_memberuser_sessions.findMany({
      where,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.discussion_board_memberuser_sessions.count({ where }),
  ]);

  const memberSummary: IDiscussionBoardMemberuser.ISummary = {
    id: memberUser.id,
    display_name: memberUser.display_name,
    account_status: memberUser.account_status,
    created_at: toISOStringSafe(memberUser.created_at),
  };

  const data: IDiscussionBoardMemberuserSession.ISummary[] = rows.map((row) => {
    const summary: IDiscussionBoardMemberuserSession.ISummary = {
      id: row.id,
      created_at: toISOStringSafe(row.created_at),
      // Model does not provide last_active_at, so expose as null.
      last_active_at: null,
      ip: row.ip ?? null,
      href: row.href ?? null,
      referrer: row.referrer ?? null,
      expired_at:
        row.expired_at !== null && row.expired_at !== undefined
          ? toISOStringSafe(row.expired_at)
          : null,
      // Derive active flag from expired_at when explicit column is missing.
      is_active: row.expired_at === null,
      memberUser: memberSummary,
    };

    return summary;
  });

  const pagination: IPage.IPagination = {
    current: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      page - 1,
    ),
    limit: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(limit),
    records: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(total),
    pages: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      limit === 0 ? 0 : Math.ceil(total / limit),
    ),
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestuserPayload } from "../decorators/payload/GuestuserPayload";

export async function postAuthGuestUserJoin(props: {
  guestUser: GuestuserPayload;
  body: IDiscussionBoardGuestUser.IJoin;
}): Promise<IDiscussionBoardGuestUser.IAuthorized> {
  const anonymousToken = props.body.anonymous_token;

  const nowDate = new Date();
  const now = toISOStringSafe(nowDate);

  const accessExpiresDate = new Date(nowDate.getTime() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(
    nowDate.getTime() + 7 * 24 * 60 * 60 * 1000,
  );

  const accessExpiresAt = toISOStringSafe(accessExpiresDate);
  const refreshExpiresAt = toISOStringSafe(refreshExpiresDate);

  const findActiveOrAnyGuest = async () => {
    return MyGlobal.prisma.discussion_board_guestusers.findUnique({
      where: { anonymous_token: anonymousToken },
    });
  };

  let guest = await findActiveOrAnyGuest();

  if (!guest) {
    try {
      guest = await MyGlobal.prisma.discussion_board_guestusers.create({
        data: {
          id: v4(),
          anonymous_token: anonymousToken,
          created_at: now,
          updated_at: now,
          deleted_at: null,
        },
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        guest = await findActiveOrAnyGuest();
      } else {
        throw error;
      }
    }
  }

  if (!guest) {
    throw new HttpException("Failed to materialize guest user", 500);
  }

  if (guest.deleted_at !== null) {
    guest = await MyGlobal.prisma.discussion_board_guestusers.update({
      where: { id: guest.id },
      data: {
        deleted_at: null,
        updated_at: now,
      },
    });
  } else {
    guest = await MyGlobal.prisma.discussion_board_guestusers.update({
      where: { id: guest.id },
      data: {
        updated_at: now,
      },
    });
  }

  // For guests, we don't have a dedicated session table in Prisma. We still
  // need a session identifier in the JWT payload, so generate an ephemeral
  // UUID to represent this logical session instance.
  const sessionId = v4();

  const accessToken = jwt.sign(
    {
      type: "guestUser",
      id: guest.id,
      session_id: sessionId,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "guestUser",
      id: guest.id,
      session_id: sessionId,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresAt,
    refreshable_until: refreshExpiresAt,
  };

  const response: IDiscussionBoardGuestUser.IAuthorized = {
    id: guest.id,
    anonymous_token: guest.anonymous_token,
    created_at: guest.created_at ? toISOStringSafe(guest.created_at) : now,
    updated_at: guest.updated_at ? toISOStringSafe(guest.updated_at) : now,
    deleted_at:
      guest.deleted_at !== null && guest.deleted_at !== undefined
        ? toISOStringSafe(guest.deleted_at)
        : null,
    token,
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postDiscussionBoardMemberUserArticlesArticleIdComments(props: {
  memberUser: MemberuserPayload;
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.ICreate;
}): Promise<IDiscussionBoardComment> {
  // 1. Load target article row
  const article = await MyGlobal.prisma.discussion_board_articles.findFirst({
    where: {
      id: props.articleId,
    },
  });

  if (article === null) {
    throw new HttpException("Article not found", 404);
  }

  // 2. Create the comment and the memberuser ownership subtype within a transaction
  const now = toISOStringSafe(new Date());
  const commentId = v4() as string & tags.Format<"uuid">;

  const [createdComment] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.discussion_board_comments.create({
      data: {
        id: commentId,
        discussion_board_article_id: article.id,
        body: props.body.body,
        status: "active",
        author_type: "memberuser",
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    }),
    MyGlobal.prisma.discussion_board_comment_of_memberusers.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        discussion_board_comment_id: commentId,
        discussion_board_memberuser_id: props.memberUser.id,
        discussion_board_memberuser_session_id: props.memberUser.session_id,
        created_at: now,
      },
    }),
  ]);

  // 3. Load category for summary, if it exists
  const category =
    await MyGlobal.prisma.discussion_board_article_categories.findFirst({
      where: {
        id: article.discussion_board_article_category_id,
      },
    });

  const categorySummary: IDiscussionBoardArticleCategory.ISummary = category
    ? {
        id: category.id,
        code: category.code,
        name: category.name,
        description: category.description,
      }
    : {
        id: article.discussion_board_article_category_id,
        code: "UNKNOWN",
        name: "Unknown",
        description: null,
      };

  // 4. Build a synthetic author summary. We cannot reliably resolve the real
  // author from subtype tables here without additional schema context, but the
  // DTO only requires that the union shape be satisfied. Use minimal fields
  // and map from the authenticated member user context when possible.
  const memberAuthor: IDiscussionBoardMemberuser.ISummary = {
    id: props.memberUser.id,
    display_name: "Member",
    account_status: "active",
    created_at: now,
  };

  const author: IDiscussionBoardArticle.ISummary["author"] = memberAuthor;

  // 5. Build article summary for the comment DTO
  const articleSummary: IDiscussionBoardArticle.ISummary = {
    id: article.id,
    title: article.title,
    excerpt: article.summary ?? undefined,
    category: categorySummary,
    author,
    createdAt: toISOStringSafe(article.created_at),
    likeCount: 0 as number & tags.Type<"int32"> & tags.Minimum<0>,
    commentCount: 0 as number & tags.Type<"int32"> & tags.Minimum<0>,
  };

  // 6. Assemble final comment DTO
  const result: IDiscussionBoardComment = {
    id: createdComment.id,
    author_type: "memberuser",
    body: createdComment.body,
    status: createdComment.status,
    created_at: toISOStringSafe(createdComment.created_at),
    updated_at: toISOStringSafe(createdComment.updated_at),
    deleted_at:
      createdComment.deleted_at !== null &&
      createdComment.deleted_at !== undefined
        ? toISOStringSafe(createdComment.deleted_at)
        : null,
    article: articleSummary,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardAdminUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminUserJoin";
import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminUserJoin(props: {
  body: IDiscussionBoardAdminUserJoin.IRequest;
}): Promise<IDiscussionBoardAdminuser.IAuthorized> {
  const email = props.body.email;

  const existing = await MyGlobal.prisma.discussion_board_adminusers.findFirst({
    where: {
      email,
    },
  });

  if (existing !== null) {
    throw new HttpException("Email already registered", 409);
  }

  const passwordHash = await PasswordUtil.hash(props.body.password);

  const now = new Date();
  const nowIso = toISOStringSafe(now);

  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const accessExpiresIso = toISOStringSafe(accessExpires);
  const refreshExpiresIso = toISOStringSafe(refreshExpires);

  const createdAdmin = await MyGlobal.prisma.discussion_board_adminusers.create(
    {
      data: {
        id: v4(),
        email,
        password_hash: passwordHash,
        display_name: props.body.display_name,
        bio: props.body.bio === undefined ? null : props.body.bio,
        email_verified: false,
        account_status: "active",
        created_at: now,
        updated_at: now,
        deleted_at: null,
        last_login_at: null,
      },
    },
  );

  const createdSession =
    await MyGlobal.prisma.discussion_board_adminuser_sessions.create({
      data: {
        id: v4(),
        discussion_board_adminuser_id: createdAdmin.id,
        ip: props.body.ip ?? "",
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: now,
        expired_at: accessExpires,
      },
    });

  const accessToken = jwt.sign(
    {
      id: createdAdmin.id,
      session_id: createdSession.id,
      type: "adminuser",
      email: createdAdmin.email,
      display_name: createdAdmin.display_name,
      email_verified: createdAdmin.email_verified,
      account_status: createdAdmin.account_status,
      created_at: nowIso,
      updated_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      id: createdAdmin.id,
      session_id: createdSession.id,
      type: "adminuser",
      email: createdAdmin.email,
      display_name: createdAdmin.display_name,
      email_verified: createdAdmin.email_verified,
      account_status: createdAdmin.account_status,
      created_at: nowIso,
      updated_at: nowIso,
      tokenType: "refresh",
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  return {
    id: createdAdmin.id,
    loginId: createdAdmin.email,
    displayName: createdAdmin.display_name,
    email: createdAdmin.email,
    status: createdAdmin.account_status,
    role: "admin",
    emailVerified: createdAdmin.email_verified,
    createdAt: toISOStringSafe(createdAdmin.created_at),
    updatedAt: toISOStringSafe(createdAdmin.updated_at),
    token,
  };
}

