import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { IDiscussionBoardMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMemberuser";
import { IDiscussionBoardAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminuser";

export async function patchDiscussionBoardArticlesArticleIdComments(props: {
  articleId: string & tags.Format<"uuid">;
  body: IDiscussionBoardComment.IRequest;
}): Promise<IPageIDiscussionBoardComment.ISummary> {
  const pageRaw = props.body.page ?? 1;
  const limitRaw = props.body.limit ?? 20;

  const effectivePage = pageRaw < 1 ? 1 : pageRaw;
  const effectiveLimit = limitRaw < 1 ? 20 : limitRaw;
  const skip = (effectivePage - 1) * effectiveLimit;

  const orderByField =
    props.body.orderBy === "created_at" ? "created_at" : "created_at";
  const orderDirection: "asc" | "desc" =
    props.body.orderDirection === "asc" ? "asc" : "desc";

  const article = await MyGlobal.prisma.discussion_board_articles.findUnique({
    where: { id: props.articleId },
  });

  if (article === null) {
    throw new HttpException("Article not found", 404);
  }

  const baseWhere: Record<string, unknown> = {
    discussion_board_article_id: props.articleId,
  };

  if (props.body.search !== undefined) {
    baseWhere.body = {
      contains: props.body.search,
      mode: "insensitive",
    };
  }

  if (props.body.status !== undefined) {
    baseWhere.status = props.body.status;
  }

  const whereCondition = baseWhere;

  const [comments, total, likeCount] = await Promise.all([
    MyGlobal.prisma.discussion_board_comments.findMany({
      where: whereCondition,
      skip,
      take: effectiveLimit,
      orderBy: {
        [orderByField]: orderDirection,
      },
    }),
    MyGlobal.prisma.discussion_board_comments.count({
      where: whereCondition,
    }),
    MyGlobal.prisma.discussion_board_article_likes.count({
      where: {
        discussion_board_article_id: props.articleId,
      },
    }),
  ]);

  const articleCategory =
    await MyGlobal.prisma.discussion_board_article_categories.findUnique({
      where: { id: article.discussion_board_article_category_id },
    });

  if (articleCategory === null) {
    throw new HttpException("Article category not found", 500);
  }

  // Resolve article author via subtype link tables
  const articleMemberAuthor =
    await MyGlobal.prisma.discussion_board_article_of_memberusers.findUnique({
      where: {
        discussion_board_article_id: article.id,
      },
    });

  const articleAdminAuthor =
    articleMemberAuthor === null
      ? await MyGlobal.prisma.discussion_board_article_of_adminusers.findUnique(
          {
            where: {
              discussion_board_article_id: article.id,
            },
          },
        )
      : null;

  if (articleMemberAuthor === null && articleAdminAuthor === null) {
    throw new HttpException("Article author not resolvable", 500);
  }

  let articleAuthorSummary:
    | IDiscussionBoardMemberuser.ISummary
    | IDiscussionBoardAdminuser.ISummary;

  if (articleMemberAuthor !== null) {
    const member =
      await MyGlobal.prisma.discussion_board_memberusers.findUnique({
        where: { id: articleMemberAuthor.discussion_board_memberuser_id },
      });

    if (member === null) {
      throw new HttpException("Article member author not found", 500);
    }

    articleAuthorSummary = {
      id: member.id,
      display_name: member.display_name,
      account_status: member.account_status,
      created_at: toISOStringSafe(member.created_at),
    };
  } else {
    const adminLink = articleAdminAuthor!;
    const admin = await MyGlobal.prisma.discussion_board_adminusers.findUnique({
      where: { id: adminLink.discussion_board_adminuser_id },
    });

    if (admin === null) {
      throw new HttpException("Article admin author not found", 500);
    }

    articleAuthorSummary = {
      id: admin.id,
      email: admin.email,
      display_name: admin.display_name,
      email_verified: admin.email_verified,
      account_status: admin.account_status,
      created_at: toISOStringSafe(admin.created_at),
      last_login_at: admin.last_login_at
        ? toISOStringSafe(admin.last_login_at)
        : undefined,
    };
  }

  const articleSummary: IDiscussionBoardArticle.ISummary = {
    id: article.id,
    title: article.title,
    excerpt: article.summary ?? null,
    category: {
      id: articleCategory.id,
      code: articleCategory.code,
      name: articleCategory.name,
      description: articleCategory.description ?? null,
    },
    author: articleAuthorSummary,
    createdAt: toISOStringSafe(article.created_at),
    likeCount,
    commentCount: total,
  };

  // Collect author link rows for comments
  const commentIds = comments.map((c) => c.id);

  const [commentMemberLinks, commentAdminLinks] = await Promise.all([
    MyGlobal.prisma.discussion_board_comment_of_memberusers.findMany({
      where: {
        discussion_board_comment_id: { in: commentIds },
      },
    }),
    MyGlobal.prisma.discussion_board_comment_of_adminusers.findMany({
      where: {
        discussion_board_comment_id: { in: commentIds },
      },
    }),
  ]);

  const memberUserIds = commentMemberLinks.map(
    (l) => l.discussion_board_memberuser_id,
  );
  const adminUserIds = commentAdminLinks.map(
    (l) => l.discussion_board_adminuser_id,
  );

  const [memberUsers, adminUsers] = await Promise.all([
    memberUserIds.length
      ? MyGlobal.prisma.discussion_board_memberusers.findMany({
          where: { id: { in: memberUserIds } },
        })
      : Promise.resolve([] as any[]),
    adminUserIds.length
      ? MyGlobal.prisma.discussion_board_adminusers.findMany({
          where: { id: { in: adminUserIds } },
        })
      : Promise.resolve([] as any[]),
  ]);

  const memberUserMap = new Map<string, (typeof memberUsers)[number]>();
  for (const m of memberUsers) memberUserMap.set(m.id, m);

  const adminUserMap = new Map<string, (typeof adminUsers)[number]>();
  for (const a of adminUsers) adminUserMap.set(a.id, a);

  const commentMemberMap = new Map<
    string,
    (typeof commentMemberLinks)[number]
  >();
  for (const link of commentMemberLinks)
    commentMemberMap.set(link.discussion_board_comment_id, link);

  const commentAdminMap = new Map<string, (typeof commentAdminLinks)[number]>();
  for (const link of commentAdminLinks)
    commentAdminMap.set(link.discussion_board_comment_id, link);

  const data = comments.map((comment) => {
    const memberLink = commentMemberMap.get(comment.id) ?? null;
    const adminLink =
      memberLink === null ? (commentAdminMap.get(comment.id) ?? null) : null;

    let author:
      | IDiscussionBoardMemberuser.ISummary
      | IDiscussionBoardAdminuser.ISummary;

    if (memberLink !== null) {
      const member =
        memberUserMap.get(memberLink.discussion_board_memberuser_id) ?? null;
      if (member === null) {
        throw new HttpException("Comment member author not found", 500);
      }

      author = {
        id: member.id,
        display_name: member.display_name,
        account_status: member.account_status,
        created_at: toISOStringSafe(member.created_at),
      };
    } else if (adminLink !== null) {
      const admin =
        adminUserMap.get(adminLink.discussion_board_adminuser_id) ?? null;
      if (admin === null) {
        throw new HttpException("Comment admin author not found", 500);
      }

      author = {
        id: admin.id,
        email: admin.email,
        display_name: admin.display_name,
        email_verified: admin.email_verified,
        account_status: admin.account_status,
        created_at: toISOStringSafe(admin.created_at),
        last_login_at: admin.last_login_at
          ? toISOStringSafe(admin.last_login_at)
          : undefined,
      };
    } else {
      throw new HttpException("Comment author not resolvable", 500);
    }

    const bodyText = comment.body;
    const contentPreview =
      bodyText.length > 120 ? `${bodyText.slice(0, 117)}...` : bodyText;

    return {
      id: comment.id,
      content_preview: contentPreview,
      createdAt: toISOStringSafe(comment.created_at),
      article: articleSummary,
      author,
    };
  });

  const pagesNumber =
    effectiveLimit === 0 ? 0 : Math.ceil(total / effectiveLimit);

  const pagination: IPage.IPagination = {
    current: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      effectivePage - 1,
    ),
    limit: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      effectiveLimit,
    ),
    records: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(total),
    pages: typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      pagesNumber,
    ),
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postDiscussionBoardMemberUserArticles(props: {
  memberUser: MemberuserPayload;
  body: IDiscussionBoardArticle.ICreate;
}): Promise<IDiscussionBoardArticle> {
  const { memberUser, body } = props;

  // Validate that the referenced category exists and is not deleted.
  const category =
    await MyGlobal.prisma.discussion_board_article_categories.findFirst({
      where: {
        id: body.categoryId,
        deleted_at: null,
      },
    });

  if (category === null) {
    throw new HttpException("Category not found", 400);
  }

  // Server-managed timestamps
  const now = new Date();

  // Create the core article row. Prisma error indicated that created_at and updated_at
  // are required fields in the unchecked create input, so we set them explicitly.
  const createdArticle = await MyGlobal.prisma.discussion_board_articles.create(
    {
      data: {
        id: v4(),
        title: body.title,
        body: body.body,
        summary: body.summary === undefined ? null : body.summary,
        discussion_board_article_category_id: body.categoryId,
        moderation_state: "active",
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    },
  );

  // Create authorship subtype linking article to the member user.
  // Compilation error shows that created_at is required in the unchecked create input,
  // so we provide it here as well.
  await MyGlobal.prisma.discussion_board_article_of_memberusers.create({
    data: {
      id: v4(),
      discussion_board_article_id: createdArticle.id,
      discussion_board_memberuser_id: memberUser.id,
      created_at: now,
    },
  });

  // Reload the article to ensure we have persisted timestamps as Date objects.
  const reloadedArticle =
    await MyGlobal.prisma.discussion_board_articles.findFirst({
      where: { id: createdArticle.id },
    });

  if (reloadedArticle === null) {
    throw new HttpException("Failed to load created article", 500);
  }

  // Build the response DTO using the article row and the already-fetched category entity.
  const result: IDiscussionBoardArticle = {
    id: reloadedArticle.id as string & tags.Format<"uuid">,
    title: reloadedArticle.title,
    body: reloadedArticle.body,
    summary: reloadedArticle.summary,
    category: {
      id: category.id as string & tags.Format<"uuid">,
      code: category.code,
      name: category.name,
      description: category.description,
    },
    moderationState: reloadedArticle.moderation_state,
    createdAt: toISOStringSafe(reloadedArticle.created_at),
    updatedAt: toISOStringSafe(reloadedArticle.updated_at),
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuestUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestuserPayload } from "../decorators/payload/GuestuserPayload";

export async function postAuthGuestUserRefresh(props: {
  guestUser: GuestuserPayload;
  body: IDiscussionBoardGuestUser.IRefresh;
}): Promise<IDiscussionBoardGuestUser.IAuthorized> {
  // 1. Verify and decode the refresh token
  let rawDecoded: unknown;
  try {
    rawDecoded = jwt.verify(
      props.body.refreshToken,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    );
  } catch (_error) {
    // Do not leak cryptographic details
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // 2. Narrow the decoded payload structurally (JWT payload, not API DTO)
  const isObject = typeof rawDecoded === "object" && rawDecoded !== null;
  if (!isObject) {
    throw new HttpException("Invalid token payload", 401);
  }

  const maybeDecoded = rawDecoded as {
    id?: unknown;
    session_id?: unknown;
    type?: unknown;
  };

  if (
    typeof maybeDecoded.id !== "string" ||
    typeof maybeDecoded.session_id !== "string" ||
    typeof maybeDecoded.type !== "string"
  ) {
    throw new HttpException("Invalid token payload", 401);
  }

  if (maybeDecoded.type !== "guestUser") {
    throw new HttpException("Invalid token type for guestUser refresh", 403);
  }

  const guestId: string = maybeDecoded.id;
  const sessionId: string = maybeDecoded.session_id;

  // 3. Load guest record and ensure it is active (not deleted)
  const guest = await MyGlobal.prisma.discussion_board_guestusers.findFirst({
    where: {
      id: guestId,
    },
  });

  if (!guest) {
    // Guest referenced by token no longer exists
    throw new HttpException("Guest identity does not exist", 401);
  }

  if (guest.deleted_at !== null) {
    // Logically closed guest identity
    throw new HttpException("Guest identity is not active", 403);
  }

  // 4. Compute new expiration timestamps
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  // 5. Generate new JWT tokens preserving the same session
  const nowIso = new Date().toISOString();

  const accessToken = jwt.sign(
    {
      id: guest.id,
      session_id: sessionId,
      type: "guestUser",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      id: guest.id,
      session_id: sessionId,
      type: "guestUser",
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // 6. Update guest's updated_at timestamp to reflect recent activity
  const updatedGuest = await MyGlobal.prisma.discussion_board_guestusers.update(
    {
      where: {
        id: guest.id,
      },
      data: {
        updated_at: new Date(),
      },
    },
  );

  // 7. Build authorization token DTO
  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // 8. Map database record to IAuthorized DTO
  const result: IDiscussionBoardGuestUser.IAuthorized = {
    id: updatedGuest.id,
    anonymous_token: updatedGuest.anonymous_token,
    created_at: toISOStringSafe(updatedGuest.created_at),
    updated_at: toISOStringSafe(updatedGuest.updated_at),
    deleted_at:
      updatedGuest.deleted_at !== null
        ? toISOStringSafe(updatedGuest.deleted_at)
        : undefined,
    token,
  };

  return result;
}

