import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReportStatisticsByTarget } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatisticsByTarget";
import { IDiscussionBoardReportStatisticsByTargetBucket } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportStatisticsByTargetBucket";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchDiscussionBoardAdminUserReportsStatisticsByTarget(props: {
  adminUser: AdminuserPayload;
  body: IDiscussionBoardReportStatisticsByTarget.IRequest;
}): Promise<IDiscussionBoardReportStatisticsByTarget> {
  const baseWhere = (() => {
    const body = props.body;

    const createdAtCondition = (() => {
      if (body.createdAtFrom === undefined && body.createdAtTo === undefined) {
        return {};
      }

      const range: {
        gte?: string;
        lt?: string;
      } = {};

      if (body.createdAtFrom !== undefined) {
        range.gte = body.createdAtFrom;
      }

      if (body.createdAtTo !== undefined) {
        range.lt = body.createdAtTo;
      }

      return { created_at: range };
    })();

    const statusCondition =
      body.statusList !== undefined && body.statusList.length > 0
        ? { status: { in: body.statusList } }
        : {};

    const actionCondition =
      body.actionList !== undefined && body.actionList.length > 0
        ? { action: { in: body.actionList } }
        : {};

    const reasonCodeCondition =
      body.reasonCodeList !== undefined && body.reasonCodeList.length > 0
        ? { reason_code: { in: body.reasonCodeList } }
        : {};

    return {
      ...createdAtCondition,
      ...statusCondition,
      ...actionCondition,
      ...reasonCodeCondition,
    };
  })();

  const [totalByTarget, resolvedByTarget, openByTarget] = await Promise.all([
    MyGlobal.prisma.discussion_board_reports.groupBy({
      by: ["target_type"],
      where: baseWhere,
      _count: { _all: true },
    }),
    MyGlobal.prisma.discussion_board_reports.groupBy({
      by: ["target_type"],
      where: {
        ...baseWhere,
        status: {
          equals: "resolved",
        },
      },
      _count: { _all: true },
    }),
    MyGlobal.prisma.discussion_board_reports.groupBy({
      by: ["target_type"],
      where: {
        ...baseWhere,
        status: {
          not: "resolved",
        },
      },
      _count: { _all: true },
    }),
  ]);

  const resolvedMap = resolvedByTarget.reduce(
    (acc, row) => {
      const next: { [targetType: string]: number } = {};

      for (const key in acc) {
        next[key] = acc[key];
      }

      next[row.target_type] = row._count._all;
      return next;
    },
    {} as { [targetType: string]: number },
  );

  const openMap = openByTarget.reduce(
    (acc, row) => {
      const next: { [targetType: string]: number } = {};

      for (const key in acc) {
        next[key] = acc[key];
      }

      next[row.target_type] = row._count._all;
      return next;
    },
    {} as { [targetType: string]: number },
  );

  const buckets: IDiscussionBoardReportStatisticsByTargetBucket[] =
    totalByTarget.map((row) => {
      const targetType = row.target_type;
      const totalReportCount = row._count._all;
      const resolvedReportCount =
        resolvedMap[targetType] !== undefined ? resolvedMap[targetType] : 0;
      const openReportCount =
        openMap[targetType] !== undefined ? openMap[targetType] : 0;

      return {
        targetType,
        totalReportCount,
        openReportCount,
        resolvedReportCount,
      };
    });

  return { buckets };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardReportByReasonStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportByReasonStatistics";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchDiscussionBoardAdminUserReportsStatisticsByReason(props: {
  adminUser: AdminuserPayload;
  body: IDiscussionBoardReportByReasonStatistics.IRequest;
}): Promise<IDiscussionBoardReportByReasonStatistics> {
  const requestBody = props.body;

  const andConditions: Prisma.discussion_board_reportsWhereInput[] = [];

  if (
    requestBody.created_at_from !== undefined &&
    requestBody.created_at_from !== null
  ) {
    andConditions.push({
      created_at: {
        gte: requestBody.created_at_from,
      },
    });
  }

  if (
    requestBody.created_at_to !== undefined &&
    requestBody.created_at_to !== null
  ) {
    andConditions.push({
      created_at: {
        lte: requestBody.created_at_to,
      },
    });
  }

  if (
    requestBody.updated_at_from !== undefined &&
    requestBody.updated_at_from !== null
  ) {
    andConditions.push({
      updated_at: {
        gte: requestBody.updated_at_from,
      },
    });
  }

  if (
    requestBody.updated_at_to !== undefined &&
    requestBody.updated_at_to !== null
  ) {
    andConditions.push({
      updated_at: {
        lte: requestBody.updated_at_to,
      },
    });
  }

  if (
    requestBody.target_types !== undefined &&
    requestBody.target_types.length > 0
  ) {
    andConditions.push({
      target_type: {
        in: requestBody.target_types,
      },
    });
  }

  if (
    requestBody.reporter_types !== undefined &&
    requestBody.reporter_types.length > 0
  ) {
    andConditions.push({
      reporter_type: {
        in: requestBody.reporter_types,
      },
    });
  }

  if (
    requestBody.reason_codes !== undefined &&
    requestBody.reason_codes.length > 0
  ) {
    andConditions.push({
      reason_code: {
        in: requestBody.reason_codes,
      },
    });
  }

  if (requestBody.statuses !== undefined && requestBody.statuses.length > 0) {
    andConditions.push({
      status: {
        in: requestBody.statuses,
      },
    });
  }

  if (requestBody.actions !== undefined && requestBody.actions.length > 0) {
    andConditions.push({
      action: {
        in: requestBody.actions,
      },
    });
  }

  const where: Prisma.discussion_board_reportsWhereInput =
    andConditions.length > 0
      ? {
          AND: andConditions,
        }
      : {};

  const rows = await MyGlobal.prisma.discussion_board_reports.findMany({
    where,
    select: {
      reason_code: true,
      status: true,
      action: true,
    },
  });

  const grouped: Record<string, IDiscussionBoardReportByReasonStatistics.IRow> =
    {};

  for (const row of rows) {
    const reason = row.reason_code;

    if (grouped[reason] === undefined) {
      grouped[reason] = {
        reason_code: reason,
        total_count: 0,
        submitted_count: 0,
        in_review_count: 0,
        resolved_count: 0,
        action_none_count: 0,
        action_keep_count: 0,
        action_hide_content_count: 0,
        action_delete_content_count: 0,
        action_restrict_user_count: 0,
      };
    }

    const statsRow = grouped[reason];

    statsRow.total_count += 1;

    if (row.status === "submitted") {
      statsRow.submitted_count += 1;
    } else if (row.status === "in_review") {
      statsRow.in_review_count += 1;
    } else if (row.status === "resolved") {
      statsRow.resolved_count += 1;
    }

    if (row.action === "none") {
      statsRow.action_none_count += 1;
    } else if (row.action === "keep") {
      statsRow.action_keep_count += 1;
    } else if (row.action === "hide_content") {
      statsRow.action_hide_content_count += 1;
    } else if (row.action === "delete_content") {
      statsRow.action_delete_content_count += 1;
    } else if (row.action === "restrict_user") {
      statsRow.action_restrict_user_count += 1;
    }
  }

  const items: IDiscussionBoardReportByReasonStatistics.IRow[] =
    Object.values(grouped);

  return {
    items,
  };
}

